INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stripe/ai/upgrade-stripe', 'official', 'stripe', 'ai', 'stripe/ai', 'upgrade-stripe', 1335, 216, 86, '2026-03-05T20:34:42Z', '2026-03-06T05:29:35.070Z', '1138f35352f4b2d0bad615cc88f9cfe7db4712ef639874f1cd04f319e07832f0', '{"id":"stripe/ai/upgrade-stripe","name":"upgrade-stripe","description":{"en":"The upgrade-stripe skill guides developers through upgrading Stripe API versions, server-side SDKs, Stripe.js, and mobile SDKs, ensuring a smooth transition to the latest version, such as 2026-02-25.clover","zh":"本指南介绍如何升级 Stripe API 版本和 SDK，包括服务器端 SDK、Stripe.js 和移动 SDK","ja":"このガイドでは、Stripe API と SDK のアップグレード方法について説明します。サーバーサイド SDK、Stripe.js、モバイル SDK が含まれます","ko":"이 가이드는 Stripe API 및 SDK 업그레이드 방법을 다룹니다. 서버 측 SDK, Stripe.js 및 모바일 SDK가 포함되어 있습니다","es":"Esta guía cubre la actualización de versiones de la API de Stripe, SDK de servidor, Stripe.js y SDK móviles para desarrolladores de AI Agents","fr":"Ce guide couvre la mise à niveau des versions de l''API Stripe, des SDK serveur, de Stripe.js et des SDK mobiles pour les développeurs d''outils d''IA","de":"Dieser Leitfaden behandelt das Upgrade von Stripe-API- und SDK-Versionen, Server-SDKs, Stripe.js und mobilen SDKs für Entwickler von KI-Agents","pt":"Este guia fornece orientação sobre como atualizar as versões da API do Stripe, incluindo SDKs e Stripe.js. Aprenda a usar a versão mais recente da API do Stripe, 2026-02-25.clover.","ru":"Это руководство предоставляет рекомендации по обновлению версий API Stripe, включая SDK и Stripe.js. Узнайте, как использовать последнюю версию API Stripe, 2026-02-25.clover.","ar":"يوفر هذا الدليل إرشادات حول كيفية ترقية إصدارات API سترايب، بما في ذلك SDK و Stripe.js. تعلم كيفية استخدام أحدث إصدار من API سترايب، 2026-02-25.clover."},"owner":"stripe","repo":"ai","repoPath":"stripe/ai","stars":1335,"forks":216,"updatedAt":"2026-03-05T20:34:42Z","topics":["ai","llm","llm-agents","mcp","python","typescript","workflows"],"skillMd":{"name":"upgrade-stripe","description":"Guide for upgrading Stripe API versions and SDKs","bodyPreview":"The latest Stripe API version is 2026-02-25.clover - use this version when upgrading unless the user specifies a different target version.\n\n# Upgrading Stripe Versions\n\nThis guide covers upgrading Stripe API versions, server-side SDKs, Stripe.js, and mobile SDKs.\n\n## Understanding Stripe API Versioning\n\nStripe uses date-based API versions (e.g., `2026-02-25.clover`, `2025-08-27.basil`, `2024-12-18.acacia`). Your account''s API version determines request/response behavior.\n\n### Types of Changes\n\n*","body":"The latest Stripe API version is 2026-02-25.clover - use this version when upgrading unless the user specifies a different target version.\n\n# Upgrading Stripe Versions\n\nThis guide covers upgrading Stripe API versions, server-side SDKs, Stripe.js, and mobile SDKs.\n\n## Understanding Stripe API Versioning\n\nStripe uses date-based API versions (e.g., `2026-02-25.clover`, `2025-08-27.basil`, `2024-12-18.acacia`). Your account''s API version determines request/response behavior.\n\n### Types of Changes\n\n**Backward-Compatible Changes** (do not require code updates):\n- New API resources\n- New optional request parameters\n- New properties in existing responses\n- Changes to opaque string lengths (e.g., object IDs)\n- New webhook event types\n\n**Breaking Changes** (require code updates):\n- Field renames or removals\n- Behavioral modifications\n- Removed endpoints or parameters\n\nReview the [API Changelog](https://docs.stripe.com/changelog.md) for all changes between versions.\n\n## Server-Side SDK Versioning\n\nSee [SDK Version Management](https://docs.stripe.com/sdks/set-version.md) for details.\n\n### Dynamically-Typed Languages (Ruby, Python, PHP, Node.js)\n\nThese SDKs offer flexible version control:\n\n**Global Configuration:**\n```python\nimport stripe\nstripe.api_version = ''2026-02-25.clover''\n```\n\n```ruby\nStripe.api_version = ''2026-02-25.clover''\n```\n\n```javascript\nconst stripe = require(''stripe'')(''sk_test_xxx'', {\n  apiVersion: ''2026-02-25.clover''\n});\n```\n\n**Per-Request Override:**\n```python\nstripe.Customer.create(\n  email=\"customer@example.com\",\n  stripe_version=''2026-02-25.clover''\n)\n```\n\n### Strongly-Typed Languages (Java, Go, .NET)\n\nThese use a fixed API version matching the SDK release date. Do not set a different API version for strongly-typed languages because response objects might not match the strong types in the SDK. Instead, update the SDK to target a new API version.\n\n### Best Practice\n\nAlways specify the API version you''re integrating against in your code instead of relying on your account''s default API version:\n\n```javascript\n// Good: Explicit version\nconst stripe = require(''stripe'')(''sk_test_xxx'', {\n  apiVersion: ''2026-02-25.clover''\n});\n\n// Avoid: Relying on account default\nconst stripe = require(''stripe'')(''sk_test_xxx'');\n```\n\n## Stripe.js Versioning\n\nSee [Stripe.js Versioning](https://docs.stripe.com/sdks/stripejs-versioning.md) for details.\n\nStripe.js uses an evergreen model with major releases (Acacia, Basil, Clover) on a biannual basis.\n\n### Loading Versioned Stripe.js\n\n**Via Script Tag:**\n```html\n<script src=\"https://js.stripe.com/clover/stripe.js\"></script>\n```\n\n**Via npm:**\n```bash\nnpm install @stripe/stripe-js\n```\n\nMajor npm versions correspond to specific Stripe.js versions.\n\n### API Version Pairing\n\nEach Stripe.js version automatically pairs with its corresponding API version. For instance:\n- Clover Stripe.js uses `2026-02-25.clover` API\n- Acacia Stripe.js uses `2024-12-18.acacia` API\n\nYou cannot override this association.\n\n### Migrating from v3\n\n1. Identify your current API version in code\n2. Review the changelog for relevant changes\n3. Consider gradually updating your API version before switching Stripe.js versions\n4. Stripe continues supporting v3 indefinitely\n\n## Mobile SDK Versioning\n\nSee [Mobile SDK Versioning](https://docs.stripe.com/sdks/mobile-sdk-versioning.md) for details.\n\n### iOS and Android SDKs\n\nBoth platforms follow **semantic versioning** (MAJOR.MINOR.PATCH):\n- **MAJOR**: Breaking API changes\n- **MINOR**: New functionality (backward-compatible)\n- **PATCH**: Bug fixes (backward-compatible)\n\nNew features and fixes release only on the latest major version. Upgrade regularly to access improvements.\n\n### React Native SDK\n\nUses a different model (0.x.y schema):\n- **Minor version changes** (x): Breaking changes AND new features\n- **Patch updates** (y): Critical bug fixes only\n\n### Backend Compatibility\n\nAll mobile SDKs work with any Stripe API version you use on your backend unless documentation specifies otherwise.\n\n## Upgrade Checklist\n\n1. Review the [API Changelog](https://docs.stripe.com/changelog.md) for changes between your current and target versions\n2. Check [Upgrades Guide](https://docs.stripe.com/upgrades.md) for migration guidance\n3. Update server-side SDK package version (e.g., `npm update stripe`, `pip install --upgrade stripe`)\n4. Update the `apiVersion` parameter in your Stripe client initialization\n5. Test your integration against the new API version using the `Stripe-Version` header\n6. Update webhook handlers to handle new event structures\n7. Update Stripe.js script tag or npm package version if needed\n8. Update mobile SDK versions in your package manager if needed\n9. Store Stripe object IDs in databases that accommodate up to 255 characters (case-sensitive collation)\n\n## Testing API Version Changes\n\nUse the `Stripe-Version` header to test your code against a new version without changing your default:\n\n```bash\ncurl https://api.stripe.com/v1/customers \\\n  -u sk_test_xxx: \\\n  -H \"Stripe-Version: 2026-02-25.clover\"\n```\n\nOr in code:\n\n```javascript\nconst stripe = require(''stripe'')(''sk_test_xxx'', {\n  apiVersion: ''2026-02-25.clover''  // Test with new version\n});\n```\n\n## Important Notes\n\n- Your webhook listener should handle unfamiliar event types gracefully\n- Test webhooks with the new version structure before upgrading\n- Breaking changes are tagged by affected product areas (Payments, Billing, Connect, etc.)\n- Multiple API versions coexist simultaneously, enabling staged adoption\n\n"},"category":"official","lastSynced":"2026-03-06T05:29:35.070Z","seo":{"title":{"en":"upgrade-stripe: Stripe API Upgrade Guide for AI Agents","zh":"升级 Stripe API 版本和 SDK 的最佳实践","ja":"Stripe API と SDK をアップグレードするためのガイド","ko":"Stripe API 및 SDK 업그레이드 설정 가이드","es":"Guía de actualización de Stripe API","fr":"Mise à niveau de l''API Stripe : Guide de configuration","de":"Stripe API Upgrade-Setup-Anleitung","pt":"Guia de Upgrade do Stripe: Melhores Práticas para Atualiz...","ru":"Обновление Stripe: Руководство по ИИ Агентам для обновлен...","ar":"دليل ترقية سترايب: إرشادات لترقية إصدارات API باستخدام أد..."},"description":{"en":"Discover how to seamlessly upgrade Stripe API versions and SDKs with our expert guide, tailored for AI agents and developers","zh":"了解如何升级 Stripe API 版本和 SDK，以利用最新功能和安全更新，包括 Python 和 TypeScript 支持","ja":"最新の機能とセキュリティ更新を利用するために、Stripe API と SDK をアップグレードする方法を学びましょう。Python と TypeScript を含む","ko":"최신 기능과 보안 업데이트를 활용하려면 Stripe API 및 SDK 업그레이드 방법을 알아보세요. Python 및 TypeScript 지원 포함","es":"Aprende a actualizar las versiones de la API de Stripe y SDK con nuestra guía paso a paso para desarrolladores de AI Agents","fr":"Découvrez comment mettre à niveau les versions de l''API Stripe et des SDK avec notre guide étape par étape pour les développeurs d''outils d''IA","de":"Erfahren Sie, wie Sie die Stripe-API- und SDK-Versionen mit unserem Schritt-für-Schritt-Leitfaden für Entwickler von KI-Agents aktualisieren","pt":"Aprenda a atualizar as versões da API do Stripe, SDKs e Stripe.js com este guia passo a passo para desenvolvedores","ru":"Узнайте, как обновить версии API Stripe, SDK и Stripe.js с помощью этого пошагового руководства для разработчиков и ИИ Агентов","ar":"تعرف على كيفية ترقية إصدارات API سترايب و SDK و Stripe.js باستخدام هذا الدليل المتدرج للdevelopers و أدوات الذكاء الاصطناعي"},"definition":{"en":"upgrade-stripe is a technical guide for upgrading Stripe API versions and SDKs, including server-side and mobile implementations","zh":"升级 Stripe API 版本和 SDK 是指将 Stripe API 和 SDK 更新到最新版本，以利用新功能和安全更新","ja":"Stripe API と SDK のアップグレードとは、最新の機能とセキュリティ更新を利用するために、Stripe API と SDK を最新バージョンに更新することを指します","ko":"Stripe API 및 SDK 업그레이드는 최신 기능과 보안 업데이트를 활용하기 위해 Stripe API 및 SDK를 최신 버전으로 업데이트하는 것을 의미합니다","es":"Actualización de Stripe es una guía para desarrolladores de AI Agents que necesitan actualizar sus versiones de API y SDK","fr":"La mise à niveau de Stripe est un guide pour les développeurs d''outils d''IA qui doivent mettre à niveau leurs versions d''API et de SDK","de":"Das Upgrade von Stripe ist ein Leitfaden für Entwickler von KI-Agents, die ihre API- und SDK-Versionen aktualisieren müssen","pt":"O upgrade-stripe é uma ferramenta que ajuda desenvolvedores a atualizar as versões da API do Stripe para garantir a compatibilidade e a segurança","ru":"Обновление Stripe - это инструмент, который помогает разработчикам обновить версии API Stripe для обеспечения совместимости и безопасности","ar":"ترقية سترايب هي أداة تساعد المطورين على ترقية إصدارات API سترايب لضمان التوافق والأمان"},"features":{"en":["Upgrades Stripe API versions, such as 2026-02-25.clover, for improved request/response behavior","Supports server-side SDK upgrades for Python and TypeScript","Provides guidance on upgrading Stripe.js for web applications","Covers mobile SDK upgrades for seamless integration","Explains date-based API versioning, such as 2025-08-27.basil and 2024-12-18.acacia","Outlines types of changes, including request/response behavior modifications"],"zh":["支持最新的 Stripe API 版本（2026-02-25.clover）","升级服务器端 SDK、Stripe.js 和移动 SDK","支持 Python 和 TypeScript","了解 Stripe API 版本控制和更改类型","升级 Stripe API 版本以利用最新功能和安全更新"],"ja":["最新の Stripe API バージョン（2026-02-25.clover）をサポート","サーバーサイド SDK、Stripe.js、モバイル SDK をアップグレード","Python と TypeScript をサポート","Stripe API のバージョン管理と変更タイプについて学びます","Stripe API バージョンをアップグレードして最新の機能とセキュリティ更新を利用"],"ko":["최신 Stripe API 버전（2026-02-25.clover） 지원","서버 측 SDK, Stripe.js 및 모바일 SDK 업그레이드","Python 및 TypeScript 지원","Stripe API 버전 관리 및 변경 유형에 대해 알아보기","Stripe API 버전 업그레이드하여 최신 기능 및 보안 업데이트를 활용"],"es":["Actualización de versiones de la API de Stripe","Compatibilidad con SDK de servidor y Stripe.js","Soporte para SDK móviles","Uso de la versión de API 2026-02-25.clover","Understanding de la versión de API basada en fechas de Stripe"],"fr":["Mise à niveau des versions de l''API Stripe","Compatibilité avec les SDK serveur et Stripe.js","Prise en charge des SDK mobiles","Utilisation de la version d''API 2026-02-25.clover","Compréhension de la version d''API basée sur les dates de Stripe"],"de":["Aktualisierung von Stripe-API-Versionen","Kompatibilität mit Server-SDKs und Stripe.js","Unterstützung für mobile SDKs","Verwendung der API-Version 2026-02-25.clover","Verständnis der datumsbasierten API-Version von Stripe"],"pt":["Atualização da versão da API do Stripe para 2026-02-25.clover","Compatibilidade com SDKs e Stripe.js","Suporte a mudanças de comportamento de requisição e resposta","Guia passo a passo para desenvolvedores","Integração com tecnologias como Python e TypeScript"],"ru":["Обновление версии API Stripe до 2026-02-25.clover","Совместимость с SDK и Stripe.js","Поддержка изменений поведения запросов и ответов","Пошаговое руководство для разработчиков","Интеграция с технологиями seperti Python и TypeScript"],"ar":["ترقية إصدار API سترايب إلى 2026-02-25.clover","التوافق مع SDK و Stripe.js","دعم تغييرات سلوك الطلبات والاستجابات","دليل متدرج للمطورين","التكامل مع تقنيات مثل Python و TypeScript"]},"keywords":{"en":["how to upgrade Stripe API","upgrade-stripe alternative","Stripe API versioning guide","upgrade-stripe setup guide","what is upgrade-stripe","upgrade-stripe vs Stripe API","upgrade-stripe install","Stripe.js upgrade tutorial","mobile SDK upgrade best practices","upgrade-stripe for AI agents"],"zh":["升级 Stripe API","Stripe SDK 升级","Python Stripe","TypeScript Stripe","Stripe API 版本控制","Stripe.js 升级","移动 SDK 升级","AIエージェント"," Stripe API Setup"],"ja":["Stripe API アップグレード","Stripe SDK アップグレード","Python Stripe","TypeScript Stripe","Stripe API バージョン管理","Stripe.js アップグレード","モバイル SDK アップグレード","AIエージェント","Stripe API Setup"],"ko":["Stripe API 업그레이드","Stripe SDK 업그레이드","Python Stripe","TypeScript Stripe","Stripe API 버전 관리","Stripe.js 업그레이드","모바일 SDK 업그레이드","AI 에이전트","Stripe API Setup"],"es":["actualización de Stripe","API de Stripe","SDK de Stripe","AI Agents","desarrollo de AI","integración de Stripe","versiones de API","Stripe.js","SDK móviles"],"fr":["mise à niveau de Stripe","API Stripe","SDK Stripe","outils d''IA","développement d''IA","intégration de Stripe","versions d''API","Stripe.js","SDK mobiles"],"de":["Aktualisierung von Stripe","Stripe-API","Stripe-SDK","KI-Agents","KI-Entwicklung","Stripe-Integration","API-Versionen","Stripe.js","mobile SDKs"],"pt":["upgrade stripe","atualizar api stripe","stripe api versão 2026-02-25.clover","sdk stripe","stripe.js","python","typescript","desenvolvedores"],"ru":["обновление stripe","обновить api stripe","stripe api версия 2026-02-25.clover","sdk stripe","stripe.js","python","typescript","разработчики"],"ar":["ترقية سترايب","ترقية api سترايب","إصدار api سترايب 2026-02-25.clover","sdk سترايب","stripe.js","python","typescript","مطورين"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Payment Processing Agents needing seamless Stripe API version upgrades and SDK management.","zh":"非常适合需要无缝升级Stripe API版本和管理SDK的支付处理代理。","ja":"Stripe APIバージョンの無停止アップグレードとSDK管理が必要な決済処理エージェントに最適。","ko":"무정지 스트라이프 API 버전 업그레이드와 SDK 관리가 필요한 결제 처리 에이전트에게 완벽합니다.","es":"Perfecto para agentes de procesamiento de pagos que necesitan actualizaciones de versión de API de Stripe y administración de SDK sin problemas.","fr":"Parfait pour les agents de traitement de paiement ayant besoin de mises à jour de version d''API Stripe et de gestion de SDK sans interruption.","de":"Perfekt für Zahlungsabwicklungsagenten, die eine nahtlose Stripe API-Version und SDK-Verwaltung benötigen.","pt":"Perfeito para Agentes de Processamento de Pagamento que necessitam de atualizações de versão da API Stripe sem interrupções e gestão de SDK.","ru":"Идеально для агентов обработки платежей, которым необходимы бесшовные обновления версий API Stripe и управление SDK.","ar":"مثالي للوكلاء الذين يحتاجون إلى ترقية نسخة API Stripe بأمان دون انقطاع وإدارة SDK."},"recommendation":{"en":"Empowers agents to upgrade Stripe API versions, server-side SDKs, Stripe.js, and mobile SDKs, ensuring compatibility with the latest Stripe API version, such as 2026-02-25.clover, and handling date-based API versioning.","zh":"赋予代理升级Stripe API版本、服务器端SDK、Stripe.js和移动SDK的能力，确保与最新的Stripe API版本（如2026-02-25.clover）兼容，并处理基于日期的API版本控制。","ja":"エージェントがStripe APIバージョン、アプリケーションサーバー側のSDK、Stripe.js、モバイルSDKをアップグレードできるようにし、最新のStripe APIバージョン（2026-02-25.cloverなど）と互換性を保ち、日付ベースのAPIバージョニングを処理する。","ko":"에이전트가 스트라이프 API 버전, 서버 측 SDK, 스트라이프.js, 모바일 SDK를 업그레이드 할 수 있도록 하여 최신 스트라이프 API 버전(2026-02-25.clover 등)과 호환되며 날짜 기반 API 버전 관리를 처리합니다.","es":"Habilita a los agentes a actualizar versiones de API de Stripe, SDK del lado del servidor, Stripe.js y SDK móviles, garantizando la compatibilidad con la última versión de API de Stripe, como 2026-02-25.clover, y manejo de versiones de API basadas en fechas.","fr":"Permet aux agents de mettre à jour les versions d''API Stripe, les SDK côté serveur, Stripe.js et les SDK mobiles, en garantissant la compatibilité avec la dernière version d''API Stripe, telle que 2026-02-25.clover, et en gérant les versions d''API basées sur les dates.","de":"Ermächtigt Agenten, Stripe API-Versionen, serverseitige SDKs, Stripe.js und mobile SDKs zu aktualisieren, um die Kompatibilität mit der neuesten Stripe API-Version, wie z.B. 2026-02-25.clover, sicherzustellen und datenbasierte API-Versionen zu verwalten.","pt":"Permite que os agentes atualizem as versões da API Stripe, SDKs lado servidor, Stripe.js e SDKs móveis, garantindo a compatibilidade com a versão mais recente da API Stripe, como 2026-02-25.clover, e lidando com a versão da API com base em data.","ru":"Позволяет агентам обновлять версии API Stripe, SDK с серверной стороны, Stripe.js и мобильные SDK, обеспечивая совместимость с последней версией API Stripe, такой как 2026-02-25.clover, и обрабатывая версию API на основе даты.","ar":"تمكن الوكلاء من ترقية إصدارات API Stripe و SDKKhaddم الخادم و Stripe.js و SDK الموبايل، وضمان التوافق مع أحدث إصدار من API Stripe، مثل 2026-02-25.clover، ومعالجة إصدار API المستندة إلى التاريخ."},"useCases":{"en":["Upgrading Stripe API versions for improved security and features","Migrating server-side SDKs for enhanced payment processing","Updating Stripe.js and mobile SDKs for consistent user experience"],"zh":["为改善安全性和功能而升级Stripe API版本","迁移服务器端SDK以增强支付处理","更新Stripe.js和移动SDK以提供一致的用户体验"],"ja":["セキュリティと機能の向上のためStripe APIバージョンをアップグレードする","決済処理の強化のためにアプリケーションサーバー側のSDKを移行する","一貫したユーザーエクスペリエンスを提供するためにStripe.jsとモバイルSDKを更新する"],"ko":["보안 및 기능 개선을 위해 스트라이프 API 버전을 업그레이드하는 것","결제 처리를 강화하기 위해 서버 측 SDK를 마이그레이션하는 것","일관된 사용자 경험을 제공하기 위해 스트라이프.js 및 모바일 SDK를 업데이트하는 것"],"es":["Actualización de versiones de API de Stripe para mejorar la seguridad y las características","Migración de SDK del lado del servidor para mejorar el procesamiento de pagos","Actualización de Stripe.js y SDK móviles para una experiencia del usuario coherente"],"fr":["Mise à jour des versions d''API Stripe pour améliorer la sécurité et les fonctionnalités","Migration des SDK côté serveur pour améliorer le traitement des paiements","Mise à jour de Stripe.js et des SDK mobiles pour une expérience utilisateur cohérente"],"de":["Aktualisierung von Stripe API-Versionen für verbesserte Sicherheit und Funktionen","Migration von serverseitigen SDKs für verbessertes Zahlungsverarbeitung","Aktualisierung von Stripe.js und mobilen SDKs für eine konsistente Benutzeroberfläche"],"pt":["Atualizar versões da API Stripe para melhorar a segurança e os recursos","Migrar SDKs lado servidor para processamento de pagamento melhorado","Atualizar Stripe.js e SDKs móveis para experiência do usuário consistente"],"ru":["Обновление версий API Stripe для улучшения безопасности и функций","Миграция SDK с серверной стороны для улучшения обработки платежей","Обновление Stripe.js и мобильных SDK для согласованного пользовательского опыта"],"ar":["ترقية إصدارات API Stripe لتحسين الأمان والميزات","نقل SDKs الخادم إلى معالجة الدفع المحسنة","تحديث Stripe.js و SDK الموبايل لتجربة مستخدم متسقة"]},"limitations":{"en":["Requires knowledge of Stripe API versioning and SDK management","Specific target version must be specified if not using the latest version"],"zh":["需要了解Stripe API版本控制和SDK管理知识","如果不使用最新版本，必须指定特定的目标版本"],"ja":["Stripe APIバージョニングとSDK管理の知識が必要","最新バージョン以外のバージョンを使用する場合、特定のターゲットバージョンを指定する必要がある"],"ko":["스트라이프 API 버전 관리 및 SDK 관리 지식이 필요합니다","최신 버전이 아닌 경우 특정 대상 버전을 지정해야 합니다"],"es":["Requiere conocimiento de la versión de API de Stripe y la administración de SDK","Deberá especificarse la versión de destino específica si no se utiliza la versión más reciente"],"fr":["Nécessite des connaissances en matière de version d''API Stripe et de gestion de SDK","La version cible spécifique doit être spécifiée si la version la plus récente n''est pas utilisée"],"de":["Benötigt Kenntnisse über Stripe API-Versionen und SDK-Verwaltung","Das spezifische Ziel muss angegeben werden, wenn nicht die neueste Version verwendet wird"],"pt":["Requer conhecimento de versionamento da API Stripe e gestão de SDK","A versão de destino específica deve ser especificada se não estiver usando a versão mais recente"],"ru":["Требует знания версионности API Stripe и управления SDK","Конкретная целевая версия должна быть указана, если не используется последняя версия"],"ar":["يتطلب معرفة إصدار API Stripe وإدارة SDK","يجب تحديد الإصدار المستهدف المحدد إذا لم يتم استخدام الإصدار الأحدث"]},"version":4},"contentHash":"1138f35352f4b2d0bad615cc88f9cfe7db4712ef639874f1cd04f319e07832f0","repoEtag":"W/\"b3f6b0c2730a4e4fbf8dcd674c5948fe05a665c063a0a23a0793e879680cfdae\"","qualityScore":86}');
