INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stripe/ai/upgrade-stripe', 'upgrade-stripe', 'stripe', 'ai', 'official', 'upgrade-stripe stripe ai official ai llm llm-agents mcp python typescript workflows The upgrade-stripe skill guides developers through upgrading Stripe API versions, server-side SDKs, Stripe.js, and mobile SDKs, ensuring a smooth transition to the latest version, such as 2026-02-25.clover 本指南介绍如何升级 Stripe API 版本和 SDK，包括服务器端 SDK、Stripe.js 和移动 SDK このガイドでは、Stripe API と SDK のアップグレード方法について説明します。サーバーサイド SDK、Stripe.js、モバイル SDK が含まれます 이 가이드는 Stripe API 및 SDK 업그레이드 방법을 다룹니다. 서버 측 SDK, Stripe.js 및 모바일 SDK가 포함되어 있습니다 Esta guía cubre la actualización de versiones de la API de Stripe, SDK de servidor, Stripe.js y SDK móviles para desarrolladores de AI Agents Ce guide couvre la mise à niveau des versions de l''API Stripe, des SDK serveur, de Stripe.js et des SDK mobiles pour les développeurs d''outils d''IA Dieser Leitfaden behandelt das Upgrade von Stripe-API- und SDK-Versionen, Server-SDKs, Stripe.js und mobilen SDKs für Entwickler von KI-Agents Este guia fornece orientação sobre como atualizar as versões da API do Stripe, incluindo SDKs e Stripe.js. Aprenda a usar a versão mais recente da API do Stripe, 2026-02-25.clover. Это руководство предоставляет рекомендации по обновлению версий API Stripe, включая SDK и Stripe.js. Узнайте, как использовать последнюю версию API Stripe, 2026-02-25.clover. يوفر هذا الدليل إرشادات حول كيفية ترقية إصدارات API سترايب، بما في ذلك SDK و Stripe.js. تعلم كيفية استخدام أحدث إصدار من API سترايب، 2026-02-25.clover. how to upgrade Stripe API upgrade-stripe alternative Stripe API versioning guide upgrade-stripe setup guide what is upgrade-stripe upgrade-stripe vs Stripe API upgrade-stripe install Stripe.js upgrade tutorial mobile SDK upgrade best practices upgrade-stripe for AI agents 升级 Stripe API Stripe SDK 升级 Python Stripe TypeScript Stripe Stripe API 版本控制 Stripe.js 升级 移动 SDK 升级 AIエージェント Stripe API Setup Upgrades Stripe API versions, such as 2026-02-25.clover, for improved request/response behavior Supports server-side SDK upgrades for Python and TypeScript Provides guidance on upgrading Stripe.js for web applications Covers mobile SDK upgrades for seamless integration Explains date-based API versioning, such as 2025-08-27.basil and 2024-12-18.acacia Outlines types of changes, including request/response behavior modifications upgrade-stripe is a technical guide for upgrading Stripe API versions and SDKs, including server-side and mobile implementations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langgenius/dify/component-refactoring', 'community', 'langgenius', 'dify', 'langgenius/dify', 'component-refactoring', 0, 0, 85, '2026-03-08T01:57:15.461Z', '2026-03-08T02:09:13.192Z', '996349b0b799095aeaa7781bc9646d032f054edd85a7c90ea67b49f3334c98ad', '{"id":"langgenius/dify/component-refactoring","name":"component-refactoring","description":{"en":"The component-refactoring skill automates the refactoring of complex React components within the Dify frontend codebase. It is triggered by specific complexity metrics from `pnpm analyze-component` and is designed for developers and AI agents managing large-scale React applications.","zh":"专为Dify前端设计的AI驱动组件重构技能，当pnpm analyze-component检测到复杂度>50或行数>300时自动触发重构流程，支持代码拆分、Hook提取和复杂度降低，确保组件在测试前达到最佳结构。","ja":"Difyフロントエンド向けAI駆動コンポーネントリファクタリングスキル。pnpm analyze-componentで複雑度>50または行数>300を検出すると自動的にリファクタリングを実行し、コード分割やフック抽出による最適化を実現。","ko":"Dify 프론트엔드를 위한 AI 기반 컴포넌트 리팩토링 스킬. pnpm analyze-component에서 복잡도>50 또는 라인수>300 감지 시 자동 리팩토링 실행, 코드 분할 및 훅 추출을 통한 최적화 지원.","es":"Refactoriza componentes React complejos en Dify frontend con umbrales de complejidad y línea de comando personalizados","fr":"Refactorez des composants React complexes dans Dify frontend avec des seuils de complexité et des commandes personnalisées","de":"Refaktorieren Sie komplexe React-Komponenten in Dify-Frontend mit benutzerdefinierten Komplexitätsschwellen und Befehlszeilen","pt":"Skill de agente IA para refatorar componentes React de alta complexidade no frontend Dify. Automatiza a redução de complexidade ciclomática (>50) e contagem de linhas (>300) usando pnpm analyze-component --json.","ru":"Навык ИИ Агента для рефакторинга высокосложных React компонентов во фронтенде Dify. Автоматизирует снижение цикломатической сложности (>50) и подсчета строк (>300) с помощью pnpm analyze-component --json.","ar":"مهارة أداة الذكاء الاصطناعي لإعادة هيكلة مكونات React عالية التعقيد في واجهة Dify. تمكن أتمتة تقليل التعقيد الدوري (>50) وعدد الأسطر (>300) باستخدام pnpm analyze-component --json."},"seo":{"title":{"en":"component-refactoring: Automate React Complexity Reductio...","zh":"Dify组件重构技能：自动化React代码拆分与复杂度降低指南","ja":"DifyコンポーネントリファクタリングAIエージェント：複雑度分析と自動最適化","ko":"Dify 컴포넌트 리팩토링 AI 에이전트: React 복잡도 분석 및 자동 최적화 가이드","es":"Guía de refactorización de componentes para React","fr":"Référencement de composants React avec refactorisation","de":"Leitfaden zur Refaktorierung von React-Komponenten","pt":"Guia de Refatoração de Componentes React com Agentes IA","ru":"Руководство по рефакторингу React компонентов с ИИ Агентами","ar":"دليل إعادة هيكلة مكونات React باستخدام أدوات الذكاء الاصط..."},"description":{"en":"Automate refactoring of high-complexity React components in Dify''s frontend. This AI agent skill uses `pnpm analyze-component` metrics to trigger code splitt...","zh":"使用Dify component-refactoring技能自动化重构高复杂度React组件。当pnpm analyze-component显示复杂度>50或行数>300时自动触发，支持代码拆分、Hook提取和复杂度降低，专为Dify前端优化设计。","ja":"Difyのcomponent-refactoring AIエージェントで高複雑度Reactコンポーネントを自動リファクタリング。pnpm analyze-componentで複雑度>50または行数>300の場合に自動発動し、コード分割やフック抽出を実行。","ko":"Dify component-refactoring AI 에이전트로 고복잡도 React 컴포넌트 자동 리팩토링. pnpm analyze-component에서 복잡도>50 또는 라인수>300 시 자동 실행, 코드 분할 및 훅 추출 지원.","es":"Mejora la complejidad de tus componentes React con nuestra guía de refactorización y optimiza tu código","fr":"Améliorez la complexité de vos composants React avec notre guide de refactorisation et optimisez votre code","de":"Verbessern Sie die Komplexität Ihrer React-Komponenten mit unserem Refaktorierungsleitfaden und optimieren Sie Ihren Code","pt":"Automatize a refatoração de componentes React complexos no Dify usando pnpm analyze-component. Reduza complexidade ciclomática e extraia hooks com agentes IA.","ru":"Автоматизируйте рефакторинг сложных React компонентов в Dify с помощью pnpm analyze-component. Снижайте цикломатическую сложность и извлекайте хуки с ИИ Аген...","ar":"أتمتة إعادة هيكلة مكونات React المعقدة في Dify باستخدام pnpm analyze-component. تقليل التعقيد الدوري واستخراج Hooks باستخدام أدوات الذكاء الاصطناعي."},"definition":{"en":"component-refactoring is an AI agent skill that refactors high-complexity React components in the Dify frontend. It is activated when `pnpm analyze-component --json` shows a complexity score over 50 or a line count exceeding 300, or upon direct user request for code splitting.","zh":"component-refactoring是Dify平台上的AI代理技能，专门用于自动化重构高复杂度React组件。它通过pnpm analyze-component命令监测组件复杂度（>50）和代码行数（>300），自动执行代码拆分、Hook提取和复杂度降低操作。","ja":"component-refactoringはDifyプラットフォームのAIエージェントスキルで、高複雑度Reactコンポーネントの自動リファクタリングを専門とします。pnpm analyze-componentで複雑度（>50）と行数（>300）を監視し、コード分割やフック抽出を自動実行します。","ko":"component-refactoring은 Dify 플랫폼의 AI 에이전트 스킬로, 고복잡도 React 컴포넌트의 자동 리팩토링을 전문으로 합니다. pnpm analyze-component로 복잡도(>50)와 라인수(>300)를 모니터링하며 코드 분할 및 훅 추출을 자동 수행합니다.","es":"La refactorización de componentes es una técnica para simplificar componentes React complejos","fr":"La refactorisation de composants est une technique pour simplifier les composants React complexes","de":"Die Refaktorierung von Komponenten ist eine Technik zur Vereinfachung komplexer React-Komponenten","pt":"Skill de agente IA que automatiza a refatoração de componentes React complexos no Dify baseada em métricas de pnpm analyze-component. Atua quando complexidade >50 ou lineCount >300, extraindo hooks e dividindo código.","ru":"Навык ИИ Агента, автоматизирующий рефакторинг сложных React компонентов в Dify на основе метрик pnpm analyze-component. Срабатывает при сложности >50 или lineCount >300, извлекая хуки и разделяя код.","ar":"مهارة أداة الذكاء الاصطناعي التي تؤتمت إعادة هيكلة مكونات React المعقدة في Dify بناءً على مقاييس pnpm analyze-component. تعمل عندما يكون التعقيد >50 أو عدد الأسطر >300، لاستخراج Hooks وتقسيم الكود."},"features":{"en":["Triggers refactoring based on `pnpm analyze-component` complexity metrics (>50) and line count (>300)","Executes code splitting and custom hook extraction for React components","Operates on component paths relative to the `web/` directory (e.g., `app/components/...`)","Uses the `refactor-component` command for refactoring prompts","Integrates with the `analyze-component` command for testing and metrics"],"zh":["基于pnpm analyze-component的自动化复杂度检测（阈值>50）","代码行数监控（300行以上自动触发重构）","React组件代码拆分自动化实现","自定义Hook提取与逻辑分离","Dify前端特定工作流集成","测试前重构验证保障代码质量"],"ja":["pnpm analyze-componentに基づく自動複雑度検出（しきい値>50）","コード行数モニタリング（300行以上で自動リファクタリング発動）","Reactコンポーネントの自動コード分割","カスタムフック抽出とロジック分離","Difyフロントエンド特化ワークフロー統合","テスト前リファクタリング検証による品質保証"],"ko":["pnpm analyze-component 기반 자동 복잡도 감지（기준값>50）","코드 라인수 모니터링（300줄 이상 시 자동 리팩토링 실행）","React 컴포넌트 자동 코드 분할","커스텀 훅 추출 및 로직 분리","Dify 프론트엔드 특화 워크플로우 통합","테스트 전 리팩토링 검증을 통한 품질 보증"],"es":["Análisis de complejidad con `pnpm analyze-component`","Refactorización de componentes con umbrales de complejidad personalizados","Soporte para código dividido y extracción de hooks","Integración con Dify frontend y React","Uso de `refactor-component` y `analyze-component` para refactorización y pruebas"],"fr":["Analyse de complexité avec `pnpm analyze-component`","Réfactoration de composants avec des seuils de complexité personnalisés","Prise en charge du code divisé et de l''extraction de hooks","Intégration avec Dify frontend et React","Utilisation de `refactor-component` et `analyze-component` pour la réfactoration et les tests"],"de":["Komplexitätsanalyse mit `pnpm analyze-component`","Refaktorierung von Komponenten mit benutzerdefinierten Komplexitätsschwellen","Unterstützung für getrennten Code und Hook-Extraktion","Integration mit Dify-Frontend und React","Verwendung von `refactor-component` und `analyze-component` für Refaktorierung und Tests"],"pt":["Refatoração automática baseada em complexidade ciclomática >50","Análise de componentes via pnpm analyze-component --json","Extração automática de React Hooks personalizados","Code splitting para componentes com >300 linhas","Integração com workflow de testes do Dify","Suporte a caminhos relativos do diretório web/"],"ru":["Автоматический рефакторинг на основе цикломатической сложности >50","Анализ компонентов через pnpm analyze-component --json","Автоматическое извлечение пользовательских React хуков","Разделение кода для компонентов с >300 строками","Интеграция с рабочим процессом тестирования Dify","Поддержка относительных путей из директории web/"],"ar":["إعادة هيكلة تلقائية بناءً على التعقيد الدوري >50","تحليل المكونات عبر pnpm analyze-component --json","استخراج تلقائي لـ React Hooks المخصصة","تقسيم الكود للمكونات ذات >300 سطر","التكامل مع سير عمل اختبارات Dify","دعم المسارات النسبية من مجلد web/"]},"keywords":{"en":["what is component-refactoring","how to use component-refactoring skill","component-refactoring vs manual refactoring","component-refactoring setup guide","pnpm analyze-component complexity","Dify React component refactoring","automate React code splitting","AI agent for component refactoring"],"zh":["Dify组件重构","React代码拆分","pnpm analyze-component","Hook提取","复杂度降低","AI代理重构","Dify前端优化","自动化重构工具"],"ja":["Difyコンポーネントリファクタリング","Reactコード分割","pnpm analyze-component","フック抽出","複雑度削減","AIエージェントリファクタリング","Difyフロントエンド最適化","自動リファクタリングツール"],"ko":["Dify 컴포넌트 리팩토링","React 코드 분할","pnpm analyze-component","훅 추출","복잡도 감소","AI 에이전트 리팩토링","Dify 프론트엔드 최적화","자동 리팩토링 도구"],"es":["refactorización de componentes","React","Dify frontend","complexidad de componentes","código dividido","extracción de hooks","pnpm analyze-component","refactor-component","Herramientas de AI para desarrolladores"],"fr":["réfactoration de composants","React","Dify frontend","complexité de composants","code divisé","extraction de hooks","pnpm analyze-component","refactor-component","Outils IA pour développeurs"],"de":["Refaktorierung von Komponenten","React","Dify-Frontend","Komplexität von Komponenten","getrennter Code","Hook-Extraktion","pnpm analyze-component","refactor-component","KI-Tools für Entwickler"],"pt":["refatoração componentes React","pnpm analyze-component complexidade","agentes IA para desenvolvimento","extração hooks React","code splitting Dify","redução complexidade ciclomática","automação refatoração frontend","workflow agentic ai"],"ru":["рефакторинг React компонентов","pnpm analyze-component сложность","ИИ Агенты для разработки","извлечение React хуков","разделение кода Dify","снижение цикломатической сложности","автоматизация рефакторинга фронтенда","agentic workflow ИИ"],"ar":["إعادة هيكلة مكونات React","pnpm analyze-component التعقيد","أدوات الذكاء الاصطناعي للتطوير","استخراج React Hooks","تقسيم الكود Dify","تقليل التعقيد الدوري","أتمتة إعادة هيكلة الواجهة","سير عمل أدوات الذكاء الاصطناعي"]}},"owner":"langgenius","repo":"dify","repoPath":"langgenius/dify","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.461Z","topics":[],"category":"community","skillMd":{"name":"component-refactoring","description":"Refactor high-complexity React components in Dify frontend. Use when `pnpm analyze-component --json` shows complexity > 50 or lineCount > 300, when the user asks for code splitting, hook extraction, or complexity reduction, or when `pnpm analyze-component` warns to refactor before testing; avoid for simple/well-structured components, third-party wrappers, or when the user explicitly wants testing without refactoring.","bodyPreview":"# Dify Component Refactoring Skill\n\nRefactor high-complexity React components in the Dify frontend codebase with the patterns and workflow below.\n\n> **Complexity Threshold**: Components with complexity > 50 (measured by `pnpm analyze-component`) should be refactored before testing.\n\n## Quick Reference\n\n### Commands (run from `web/`)\n\nUse paths relative to `web/` (e.g., `app/components/...`).\nUse `refactor-component` for refactoring prompts and `analyze-component` for testing prompts and metrics.","body":"# Dify Component Refactoring Skill\n\nRefactor high-complexity React components in the Dify frontend codebase with the patterns and workflow below.\n\n> **Complexity Threshold**: Components with complexity > 50 (measured by `pnpm analyze-component`) should be refactored before testing.\n\n## Quick Reference\n\n### Commands (run from `web/`)\n\nUse paths relative to `web/` (e.g., `app/components/...`).\nUse `refactor-component` for refactoring prompts and `analyze-component` for testing prompts and metrics.\n\n```bash\ncd web\n\n# Generate refactoring prompt\npnpm refactor-component <path>\n\n# Output refactoring analysis as JSON\npnpm refactor-component <path> --json\n\n# Generate testing prompt (after refactoring)\npnpm analyze-component <path>\n\n# Output testing analysis as JSON\npnpm analyze-component <path> --json\n```\n\n### Complexity Analysis\n\n```bash\n# Analyze component complexity\npnpm analyze-component <path> --json\n\n# Key metrics to check:\n# - complexity: normalized score 0-100 (target < 50)\n# - maxComplexity: highest single function complexity\n# - lineCount: total lines (target < 300)\n```\n\n### Complexity Score Interpretation\n\n| Score | Level | Action |\n|-------|-------|--------|\n| 0-25 | 🟢 Simple | Ready for testing |\n| 26-50 | 🟡 Medium | Consider minor refactoring |\n| 51-75 | 🟠 Complex | **Refactor before testing** |\n| 76-100 | 🔴 Very Complex | **Must refactor** |\n\n## Core Refactoring Patterns\n\n### Pattern 1: Extract Custom Hooks\n\n**When**: Component has complex state management, multiple `useState`/`useEffect`, or business logic mixed with UI.\n\n**Dify Convention**: Place hooks in a `hooks/` subdirectory or alongside the component as `use-<feature>.ts`.\n\n```typescript\n// ❌ Before: Complex state logic in component\nconst Configuration: FC = () => {\n  const [modelConfig, setModelConfig] = useState<ModelConfig>(...)\n  const [datasetConfigs, setDatasetConfigs] = useState<DatasetConfigs>(...)\n  const [completionParams, setCompletionParams] = useState<FormValue>({})\n  \n  // 50+ lines of state management logic...\n  \n  return <div>...</div>\n}\n\n// ✅ After: Extract to custom hook\n// hooks/use-model-config.ts\nexport const useModelConfig = (appId: string) => {\n  const [modelConfig, setModelConfig] = useState<ModelConfig>(...)\n  const [completionParams, setCompletionParams] = useState<FormValue>({})\n  \n  // Related state management logic here\n  \n  return { modelConfig, setModelConfig, completionParams, setCompletionParams }\n}\n\n// Component becomes cleaner\nconst Configuration: FC = () => {\n  const { modelConfig, setModelConfig } = useModelConfig(appId)\n  return <div>...</div>\n}\n```\n\n**Dify Examples**:\n- `web/app/components/app/configuration/hooks/use-advanced-prompt-config.ts`\n- `web/app/components/app/configuration/debug/hooks.tsx`\n- `web/app/components/workflow/hooks/use-workflow.ts`\n\n### Pattern 2: Extract Sub-Components\n\n**When**: Single component has multiple UI sections, conditional rendering blocks, or repeated patterns.\n\n**Dify Convention**: Place sub-components in subdirectories or as separate files in the same directory.\n\n```typescript\n// ❌ Before: Monolithic JSX with multiple sections\nconst AppInfo = () => {\n  return (\n    <div>\n      {/* 100 lines of header UI */}\n      {/* 100 lines of operations UI */}\n      {/* 100 lines of modals */}\n    </div>\n  )\n}\n\n// ✅ After: Split into focused components\n// app-info/\n//   ├── index.tsx           (orchestration only)\n//   ├── app-header.tsx      (header UI)\n//   ├── app-operations.tsx  (operations UI)\n//   └── app-modals.tsx      (modal management)\n\nconst AppInfo = () => {\n  const { showModal, setShowModal } = useAppInfoModals()\n  \n  return (\n    <div>\n      <AppHeader appDetail={appDetail} />\n      <AppOperations onAction={handleAction} />\n      <AppModals show={showModal} onClose={() => setShowModal(null)} />\n    </div>\n  )\n}\n```\n\n**Dify Examples**:\n- `web/app/components/app/configuration/` directory structure\n- `web/app/components/workflow/nodes/` per-node organization\n\n### Pattern 3: Simplify Conditional Logic\n\n**When**: Deep nesting (> 3 levels), complex ternaries, or multiple `if/else` chains.\n\n```typescript\n// ❌ Before: Deeply nested conditionals\nconst Template = useMemo(() => {\n  if (appDetail?.mode === AppModeEnum.CHAT) {\n    switch (locale) {\n      case LanguagesSupported[1]:\n        return <TemplateChatZh />\n      case LanguagesSupported[7]:\n        return <TemplateChatJa />\n      default:\n        return <TemplateChatEn />\n    }\n  }\n  if (appDetail?.mode === AppModeEnum.ADVANCED_CHAT) {\n    // Another 15 lines...\n  }\n  // More conditions...\n}, [appDetail, locale])\n\n// ✅ After: Use lookup tables + early returns\nconst TEMPLATE_MAP = {\n  [AppModeEnum.CHAT]: {\n    [LanguagesSupported[1]]: TemplateChatZh,\n    [LanguagesSupported[7]]: TemplateChatJa,\n    default: TemplateChatEn,\n  },\n  [AppModeEnum.ADVANCED_CHAT]: {\n    [LanguagesSupported[1]]: TemplateAdvancedChatZh,\n    // ...\n  },\n}\n\nconst Template = useMemo(() => {\n  const modeTemplates = TEMPLATE_MAP[appDetail?.mode]\n  if (!modeTemplates) return null\n  \n  const TemplateComponent = modeTemplates[locale] || modeTemplates.default\n  return <TemplateComponent appDetail={appDetail} />\n}, [appDetail, locale])\n```\n\n### Pattern 4: Extract API/Data Logic\n\n**When**: Component directly handles API calls, data transformation, or complex async operations.\n\n**Dify Convention**: Use `@tanstack/react-query` hooks from `web/service/use-*.ts` or create custom data hooks.\n\n```typescript\n// ❌ Before: API logic in component\nconst MCPServiceCard = () => {\n  const [basicAppConfig, setBasicAppConfig] = useState({})\n  \n  useEffect(() => {\n    if (isBasicApp && appId) {\n      (async () => {\n        const res = await fetchAppDetail({ url: ''/apps'', id: appId })\n        setBasicAppConfig(res?.model_config || {})\n      })()\n    }\n  }, [appId, isBasicApp])\n  \n  // More API-related logic...\n}\n\n// ✅ After: Extract to data hook using React Query\n// use-app-config.ts\nimport { useQuery } from ''@tanstack/react-query''\nimport { get } from ''@/service/base''\n\nconst NAME_SPACE = ''appConfig''\n\nexport const useAppConfig = (appId: string, isBasicApp: boolean) => {\n  return useQuery({\n    enabled: isBasicApp && !!appId,\n    queryKey: [NAME_SPACE, ''detail'', appId],\n    queryFn: () => get<AppDetailResponse>(`/apps/${appId}`),\n    select: data => data?.model_config || {},\n  })\n}\n\n// Component becomes cleaner\nconst MCPServiceCard = () => {\n  const { data: config, isLoading } = useAppConfig(appId, isBasicApp)\n  // UI only\n}\n```\n\n**React Query Best Practices in Dify**:\n- Define `NAME_SPACE` for query key organization\n- Use `enabled` option for conditional fetching\n- Use `select` for data transformation\n- Export invalidation hooks: `useInvalidXxx`\n\n**Dify Examples**:\n- `web/service/use-workflow.ts`\n- `web/service/use-common.ts`\n- `web/service/knowledge/use-dataset.ts`\n- `web/service/knowledge/use-document.ts`\n\n### Pattern 5: Extract Modal/Dialog Management\n\n**When**: Component manages multiple modals with complex open/close states.\n\n**Dify Convention**: Modals should be extracted with their state management.\n\n```typescript\n// ❌ Before: Multiple modal states in component\nconst AppInfo = () => {\n  const [showEditModal, setShowEditModal] = useState(false)\n  const [showDuplicateModal, setShowDuplicateModal] = useState(false)\n  const [showConfirmDelete, setShowConfirmDelete] = useState(false)\n  const [showSwitchModal, setShowSwitchModal] = useState(false)\n  const [showImportDSLModal, setShowImportDSLModal] = useState(false)\n  // 5+ more modal states...\n}\n\n// ✅ After: Extract to modal management hook\ntype ModalType = ''edit'' | ''duplicate'' | ''delete'' | ''switch'' | ''import'' | null\n\nconst useAppInfoModals = () => {\n  const [activeModal, setActiveModal] = useState<ModalType>(null)\n  \n  const openModal = useCallback((type: ModalType) => setActiveModal(type), [])\n  const closeModal = useCallback(() => setActiveModal(null), [])\n  \n  return {\n    activeModal,\n    openModal,\n    closeModal,\n    isOpen: (type: ModalType) => activeModal === type,\n  }\n}\n```\n\n### Pattern 6: Extract Form Logic\n\n**When**: Complex form validation, submission handling, or field transformation.\n\n**Dify Convention**: Use `@tanstack/react-form` patterns from `web/app/components/base/form/`.\n\n```typescript\n// ✅ Use existing form infrastructure\nimport { useAppForm } from ''@/app/components/base/form''\n\nconst ConfigForm = () => {\n  const form = useAppForm({\n    defaultValues: { name: '''', description: '''' },\n    onSubmit: handleSubmit,\n  })\n  \n  return <form.Provider>...</form.Provider>\n}\n```\n\n## Dify-Specific Refactoring Guidelines\n\n### 1. Context Provider Extraction\n\n**When**: Component provides complex context values with multiple states.\n\n```typescript\n// ❌ Before: Large context value object\nconst value = {\n  appId, isAPIKeySet, isTrailFinished, mode, modelModeType,\n  promptMode, isAdvancedMode, isAgent, isOpenAI, isFunctionCall,\n  // 50+ more properties...\n}\nreturn <ConfigContext.Provider value={value}>...</ConfigContext.Provider>\n\n// ✅ After: Split into domain-specific contexts\n<ModelConfigProvider value={modelConfigValue}>\n  <DatasetConfigProvider value={datasetConfigValue}>\n    <UIConfigProvider value={uiConfigValue}>\n      {children}\n    </UIConfigProvider>\n  </DatasetConfigProvider>\n</ModelConfigProvider>\n```\n\n**Dify Reference**: `web/context/` directory structure\n\n### 2. Workflow Node Components\n\n**When**: Refactoring workflow node components (`web/app/components/workflow/nodes/`).\n\n**Conventions**:\n- Keep node logic in `use-interactions.ts`\n- Extract panel UI to separate files\n- Use `_base` components for common patterns\n\n```\nnodes/<node-type>/\n  ├── index.tsx              # Node registration\n  ├── node.tsx               # Node visual component\n  ├── panel.tsx              # Configuration panel\n  ├── use-interactions.ts    # Node-specific hooks\n  └── types.ts               # Type definitions\n```\n\n### 3. Configuration Components\n\n**When**: Refactoring app configuration components.\n\n**Conventions**:\n- Separate config sections into subdirectories\n- Use existing patterns from `web/app/components/app/configuration/`\n- Keep feature toggles in dedicated components\n\n### 4. Tool/Plugin Components\n\n**When**: Refactoring tool-related components (`web/app/components/tools/`).\n\n**Conventions**:\n- Follow existing modal patterns\n- Use service hooks from `web/service/use-tools.ts`\n- Keep provider-specific logic isolated\n\n## Refactoring Workflow\n\n### Step 1: Generate Refactoring Prompt\n\n```bash\npnpm refactor-component <path>\n```\n\nThis command will:\n- Analyze component complexity and features\n- Identify specific refactoring actions needed\n- Generate a prompt for AI assistant (auto-copied to clipboard on macOS)\n- Provide detailed requirements based on detected patterns\n\n### Step 2: Analyze Details\n\n```bash\npnpm analyze-component <path> --json\n```\n\nIdentify:\n- Total complexity score\n- Max function complexity\n- Line count\n- Features detected (state, effects, API, etc.)\n\n### Step 3: Plan\n\nCreate a refactoring plan based on detected features:\n\n| Detected Feature | Refactoring Action |\n|------------------|-------------------|\n| `hasState: true` + `hasEffects: true` | Extract custom hook |\n| `hasAPI: true` | Extract data/service hook |\n| `hasEvents: true` (many) | Extract event handlers |\n| `lineCount > 300` | Split into sub-components |\n| `maxComplexity > 50` | Simplify conditional logic |\n\n### Step 4: Execute Incrementally\n\n1. **Extract one piece at a time**\n2. **Run lint, type-check, and tests after each extraction**\n3. **Verify functionality before next step**\n\n```\nFor each extraction:\n  ┌────────────────────────────────────────┐\n  │ 1. Extract code                        │\n  │ 2. Run: pnpm lint:fix                  │\n  │ 3. Run: pnpm type-check:tsgo           │\n  │ 4. Run: pnpm test                      │\n  │ 5. Test functionality manually         │\n  │ 6. PASS? → Next extraction             │\n  │    FAIL? → Fix before continuing       │\n  └────────────────────────────────────────┘\n```\n\n### Step 5: Verify\n\nAfter refactoring:\n\n```bash\n# Re-run refactor command to verify improvements\npnpm refactor-component <path>\n\n# If complexity < 25 and lines < 200, you''ll see:\n# ✅ COMPONENT IS WELL-STRUCTURED\n\n# For detailed metrics:\npnpm analyze-component <path> --json\n\n# Target metrics:\n# - complexity < 50\n# - lineCount < 300\n# - maxComplexity < 30\n```\n\n## Common Mistakes to Avoid\n\n### ❌ Over-Engineering\n\n```typescript\n// ❌ Too many tiny hooks\nconst useButtonText = () => useState(''Click'')\nconst useButtonDisabled = () => useState(false)\nconst useButtonLoading = () => useState(false)\n\n// ✅ Cohesive hook with related state\nconst useButtonState = () => {\n  const [text, setText] = useState(''Click'')\n  const [disabled, setDisabled] = useState(false)\n  const [loading, setLoading] = useState(false)\n  return { text, setText, disabled, setDisabled, loading, setLoading }\n}\n```\n\n### ❌ Breaking Existing Patterns\n\n- Follow existing directory structures\n- Maintain naming conventions\n- Preserve export patterns for compatibility\n\n### ❌ Premature Abstraction\n\n- Only extract when there''s clear complexity benefit\n- Don''t create abstractions for single-use code\n- Keep refactored code in the same domain area\n\n## References\n\n### Dify Codebase Examples\n\n- **Hook extraction**: `web/app/components/app/configuration/hooks/`\n- **Component splitting**: `web/app/components/app/configuration/`\n- **Service hooks**: `web/service/use-*.ts`\n- **Workflow patterns**: `web/app/components/workflow/hooks/`\n- **Form patterns**: `web/app/components/base/form/`\n\n### Related Skills\n\n- `frontend-testing` - For testing refactored components\n- `web/docs/test.md` - Testing specification\n"},"lastSynced":"2026-03-08T02:09:13.192Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents specializing in React component optimization and technical debt reduction.","zh":"非常适合专注于 React 组件优化和技术债务削减的代码重构 Agent。","ja":"Reactコンポーネントの最適化と技術的負債の削減に特化したコードリファクタリングエージェントに最適です。","ko":"React 컴포넌트 최적화 및 기술 부채 감소에 특화된 코드 리팩토링 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Refactorización de Código especializados en la optimización de componentes de React y la reducción de deuda técnica.","fr":"Parfait pour les Agents de Réfactoration de Code spécialisés dans l''optimisation des composants React et la réduction de la dette technique.","de":"Perfekt für Code-Refactoring-Agenten, die auf die Optimierung von React-Komponenten und die Reduzierung von technischer Schulden spezialisiert sind.","pt":"Perfeito para Agentes de Refatoração de Código especializados em otimização de componentes React e redução de dívida técnica.","ru":"Идеально подходит для Агентов рефакторинга кода, специализирующихся на оптимизации компонентов React и сокращении технического долга.","ar":"مثالي لوكلاء إعادة هيكلة التعليمات البرمجية المتخصصين في تحسين مكونات React وتقليل الديون التقنية."},"recommendation":{"en":"Enables automated refactoring of high-complexity React components in Dify frontend using pnpm analyze-component metrics. Provides intelligent component splitting, hook extraction, and complexity reduction based on concrete thresholds (>50 complexity or >300 lines).","zh":"支持使用 pnpm analyze-component 指标对 Dify 前端中的高复杂度 React 组件进行自动化重构。基于具体阈值（>50 复杂度或 >300 行），提供智能的组件拆分、Hook 提取和复杂度降低功能。","ja":"pnpm analyze-component メトリクスを使用して、Difyフロントエンドの高複雑度Reactコンポーネントの自動リファクタリングを可能にします。具体的なしきい値（複雑度>50または行数>300）に基づいて、インテリジェントなコンポーネント分割、フックの抽出、複雑度の削減を提供します。","ko":"pnpm analyze-component 메트릭스를 사용하여 Dify 프론트엔드의 고복잡도 React 컴포넌트 자동 리팩토링을 가능하게 합니다. 구체적인 임계값(>50 복잡도 또는 >300 라인)을 기반으로 지능적인 컴포넌트 분할, 훅 추출 및 복잡도 감소를 제공합니다.","es":"Permite la refactorización automatizada de componentes de React de alta complejidad en Dify frontend utilizando las métricas de pnpm analyze-component. Proporciona una división de componentes inteligente, extracción de hooks y reducción de complejidad basada en umbrales concretos (>50 complejidad o >300 líneas).","fr":"Permet la refactorisation automatique de composants React à haute complexité dans Dify frontend en utilisant les métriques de pnpm analyze-component. Fournit un splitting de composants intelligent, une extraction de hooks et une réduction de complexité basée sur des seuils concrets (>50 complexité ou >300 lignes).","de":"Ermöglicht die automatisierte Refaktorierung von React-Komponenten mit hoher Komplexität in Dify frontend unter Verwendung der pnpm analyze-component-Metriken. Bietet eine intelligente Komponentenaufteilung, Hook-Extraktion und Komplexitätsreduzierung basierend auf konkreten Schwellenwerten (>50 Komplexität oder >300 Zeilen).","pt":"Permite a refatoração automatizada de componentes React de alta complexidade no frontend do Dify usando métricas do pnpm analyze-component. Fornece divisão inteligente de componentes, extração de hooks e redução de complexidade com base em limites concretos (>50 de complexidade ou >300 linhas).","ru":"Позволяет автоматизировать рефакторинг высокосложных компонентов React во фронтенде Dify с использованием метрик инструмента pnpm analyze-component. Обеспечивает интеллектуальное разделение компонентов, извлечение хуков и снижение сложности на основе конкретных пороговых значений (>50 по сложности или >300 строк).","ar":"يتيح إعادة هيكلة آلية لمكونات React عالية التعقيد في واجهة Dify الأمامية باستخدام مقاييس أداة pnpm analyze-component. يوفر تقسيمًا ذكيًا للمكونات، واستخراج الـ hooks، وتقليل التعقيد بناءً على حدود ملموسة (>50 تعقيدًا أو >300 سطر)."},"useCases":{"en":["Refactoring components flagged by pnpm analyze-component warnings","Extracting custom hooks from complex components","Splitting large components before testing","Reducing cognitive complexity in React codebases"],"zh":["重构被 pnpm analyze-component 警告标记的组件","从复杂组件中提取自定义 Hook","测试前拆分大型组件","降低 React 代码库的认知复杂度"],"ja":["pnpm analyze-component の警告でフラグが立てられたコンポーネントのリファクタリング","複雑なコンポーネントからのカスタムフックの抽出","テスト前の大型コンポーネントの分割","Reactコードベースの認知的複雑さの軽減"],"ko":["pnpm analyze-component 경고로 플래그 지정된 컴포넌트 리팩토링","복잡한 컴포넌트로부터 커스텀 훅 추출","테스트 전 대형 컴포넌트 분할","React 코드베이스의 인지적 복잡성 감소"],"es":["Refactorización de componentes marcados por las advertencias de pnpm analyze-component","Extracción de hooks personalizados de componentes complejos","División de componentes grandes antes de las pruebas","Reducción de la complejidad cognitiva en las bases de código de React"],"fr":["Réfactoration de composants signalés par les avertissements de pnpm analyze-component","Extraction de hooks personnalisés à partir de composants complexes","Splitting de composants importants avant les tests","Réduction de la complexité cognitive dans les bases de code React"],"de":["Refaktorierung von Komponenten, die durch pnpm analyze-component-Warnungen gekennzeichnet sind","Extraktion von benutzerdefinierten Hooks aus komplexen Komponenten","Aufteilung großer Komponenten vor dem Testen","Reduzierung der kognitiven Komplexität in React-Codebasen"],"pt":["Refatoração de componentes sinalizados por avisos do pnpm analyze-component","Extração de hooks personalizados de componentes complexos","Divisão de componentes grandes antes dos testes","Redução da complexidade cognitiva em bases de código React"],"ru":["Рефакторинг компонентов, отмеченных предупреждениями pnpm analyze-component","Извлечение пользовательских хуков из сложных компонентов","Разделение крупных компонентов перед тестированием","Снижение когнитивной сложности в кодовых базах React"],"ar":["إعادة هيكلة المكونات التي تم وضع علامة عليها بواسطة تحذيرات أداة pnpm analyze-component","استخراج الـ hooks المخصصة من المكونات المعقدة","تقسيم المكونات الكبيرة قبل الاختبار","تقليل التعقيد المعرفي في قواعد تعليمات React البرمجية"]},"limitations":{"en":["Dify frontend specific (web/ directory)","Requires pnpm analyze-component tool","Avoids third-party wrapper components","Not for simple/well-structured components"],"zh":["特定于 Dify 前端（web/ 目录）","需要 pnpm analyze-component 工具","避免处理第三方包装组件","不适用于简单/结构良好的组件"],"ja":["Difyフロントエンド固有（web/ディレクトリ）","pnpm analyze-component ツールが必要","サードパーティのラッパーコンポーネントは対象外","シンプル/構造化されたコンポーネントには不向き"],"ko":["Dify 프론트엔드 전용 (web/ 디렉토리)","pnpm analyze-component 도구 필요","제3자 래퍼 컴포넌트 제외","단순/잘 구조화된 컴포넌트에는 해당되지 않음"],"es":["Específico de Dify frontend (directorio web/)","Requiere la herramienta pnpm analyze-component","Evita componentes de terceros con envoltura","No para componentes simples/bien estructurados"],"fr":["Spécifique à Dify frontend (répertoire web/)","Nécessite l''outil pnpm analyze-component","Évite les composants de tiers avec wrapper","Pas pour les composants simples/bien structurés"],"de":["Spezifisch für Dify frontend (web/-Verzeichnis)","Benötigt das Tool pnpm analyze-component","Meidet Wrapper-Komponenten von Drittanbietern","Nicht für einfache/gut strukturierte Komponenten"],"pt":["Específico para o frontend do Dify (diretório web/)","Requer a ferramenta pnpm analyze-component","Evita componentes wrapper de terceiros","Não é para componentes simples/bem estruturados"],"ru":["Специфично для фронтенда Dify (директория web/)","Требует инструмент pnpm analyze-component","Избегает сторонних компонентов-обёрток","Не для простых/хорошо структурированных компонентов"],"ar":["مخصص لواجهة Dify الأمامية (دليل web/)","يتطلب أداة pnpm analyze-component","يتجنب مكونات الـ wrapper التابعة لجهات خارجية","ليس للمكونات البسيطة/جيدة الهيكلة"]},"version":4},"contentHash":"996349b0b799095aeaa7781bc9646d032f054edd85a7c90ea67b49f3334c98ad","qualityScore":85}');
