INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('langgenius/dify/component-refactoring', 'component-refactoring', 'langgenius', 'dify', 'community', 'component-refactoring langgenius dify community The component-refactoring skill automates the refactoring of complex React components within the Dify frontend codebase. It is triggered by specific complexity metrics from `pnpm analyze-component` and is designed for developers and AI agents managing large-scale React applications. 专为Dify前端设计的AI驱动组件重构技能，当pnpm analyze-component检测到复杂度>50或行数>300时自动触发重构流程，支持代码拆分、Hook提取和复杂度降低，确保组件在测试前达到最佳结构。 Difyフロントエンド向けAI駆動コンポーネントリファクタリングスキル。pnpm analyze-componentで複雑度>50または行数>300を検出すると自動的にリファクタリングを実行し、コード分割やフック抽出による最適化を実現。 Dify 프론트엔드를 위한 AI 기반 컴포넌트 리팩토링 스킬. pnpm analyze-component에서 복잡도>50 또는 라인수>300 감지 시 자동 리팩토링 실행, 코드 분할 및 훅 추출을 통한 최적화 지원. Refactoriza componentes React complejos en Dify frontend con umbrales de complejidad y línea de comando personalizados Refactorez des composants React complexes dans Dify frontend avec des seuils de complexité et des commandes personnalisées Refaktorieren Sie komplexe React-Komponenten in Dify-Frontend mit benutzerdefinierten Komplexitätsschwellen und Befehlszeilen Skill de agente IA para refatorar componentes React de alta complexidade no frontend Dify. Automatiza a redução de complexidade ciclomática (>50) e contagem de linhas (>300) usando pnpm analyze-component --json. Навык ИИ Агента для рефакторинга высокосложных React компонентов во фронтенде Dify. Автоматизирует снижение цикломатической сложности (>50) и подсчета строк (>300) с помощью pnpm analyze-component --json. مهارة أداة الذكاء الاصطناعي لإعادة هيكلة مكونات React عالية التعقيد في واجهة Dify. تمكن أتمتة تقليل التعقيد الدوري (>50) وعدد الأسطر (>300) باستخدام pnpm analyze-component --json. what is component-refactoring how to use component-refactoring skill component-refactoring vs manual refactoring component-refactoring setup guide pnpm analyze-component complexity Dify React component refactoring automate React code splitting AI agent for component refactoring Dify组件重构 React代码拆分 pnpm analyze-component Hook提取 复杂度降低 AI代理重构 Dify前端优化 自动化重构工具 Triggers refactoring based on `pnpm analyze-component` complexity metrics (>50) and line count (>300) Executes code splitting and custom hook extraction for React components Operates on component paths relative to the `web/` directory (e.g., `app/components/...`) Uses the `refactor-component` command for refactoring prompts Integrates with the `analyze-component` command for testing and metrics component-refactoring is an AI agent skill that refactors high-complexity React components in the Dify frontend. It is activated when `pnpm analyze-component --json` shows a complexity score over 50 or a line count exceeding 300, or upon direct user request for code splitting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/continuous-learning-v2', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'continuous-learning-v2', 61988, 7678, 85, '2026-03-06T03:39:20Z', '2026-03-06T03:54:21.413Z', 'b0a7efabaef654921a7871807cd81ea10fb50c0890ffb496668e48840a157508', '{"id":"affaan-m/everything-claude-code/continuous-learning-v2","name":"continuous-learning-v2","description":{"en":"Continuous-learning-v2 is an instinct-based learning system that observes sessions via hooks, creating atomic instincts with confidence scoring for AI agents and developers. It benefits developers by turning Claude Code sessions into reusable knowledge.","es":"Continuous-learning-v2 es un sistema de aprendizaje basado en instintos que observa sesiones y crea comportamientos reutilizables. La versión 2.1 agrega instintos con ámbito de proyecto.","fr":"Continuous-learning-v2 est un système d''apprentissage basé sur des instincts qui observe les sessions et crée des comportements réutilisables. La version 2.1 ajoute des instincts avec portée de projet.","de":"Continuous-learning-v2 ist ein instinktbasierendes Lernsystem, das Sitzungen beobachtet und wiederverwendbare Verhaltensweisen erstellt. Die Version 2.1 fügt projektspezifische Instinkte hinzu."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"continuous-learning-v2","description":"Instinct-based learning system that observes sessions via hooks, creates atomic instincts with confidence scoring, and evolves them into skills/commands/agents. v2.1 adds project-scoped instincts to prevent cross-project contamination.","version":"2.1.0","bodyPreview":"# Continuous Learning v2.1 - Instinct\n-Based Architecture\n\nAn advanced learning system that turns your Claude Code sessions into reusable knowledge through atomic \"instincts\" - small learned behaviors with confidence scoring.\n\n**v2.1** adds **project-scoped instincts** — React patterns stay in your React project, Python conventions stay in your Python project, and universal patterns (like \"always validate input\") are shared globally.\n\n## When to Activate\n\n- Setting up automatic learning from Cla","body":"# Continuous Learning v2.1 - Instinct\n-Based Architecture\n\nAn advanced learning system that turns your Claude Code sessions into reusable knowledge through atomic \"instincts\" - small learned behaviors with confidence scoring.\n\n**v2.1** adds **project-scoped instincts** — React patterns stay in your React project, Python conventions stay in your Python project, and universal patterns (like \"always validate input\") are shared globally.\n\n## When to Activate\n\n- Setting up automatic learning from Claude Code sessions\n- Configuring instinct-based behavior extraction via hooks\n- Tuning confidence thresholds for learned behaviors\n- Reviewing, exporting, or importing instinct libraries\n- Evolving instincts into full skills, commands, or agents\n- Managing project-scoped vs global instincts\n- Promoting instincts from project to global scope\n\n## What''s New in v2.1\n\n| Feature | v2.0 | v2.1 |\n|---------|------|------|\n| Storage | Global (~/.claude/homunculus/) | Project-scoped (projects/<hash>/) |\n| Scope | All instincts apply everywhere | Project-scoped + global |\n| Detection | None | git remote URL / repo path |\n| Promotion | N/A | Project → global when seen in 2+ projects |\n| Commands | 4 (status/evolve/export/import) | 6 (+promote/projects) |\n| Cross-project | Contamination risk | Isolated by default |\n\n## What''s New in v2 (vs v1)\n\n| Feature | v1 | v2 |\n|---------|----|----|\n| Observation | Stop hook (session end) | PreToolUse/PostToolUse (100% reliable) |\n| Analysis | Main context | Background agent (Haiku) |\n| Granularity | Full skills | Atomic \"instincts\" |\n| Confidence | None | 0.3-0.9 weighted |\n| Evolution | Direct to skill | Instincts -> cluster -> skill/command/agent |\n| Sharing | None | Export/import instincts |\n\n## The Instinct Model\n\nAn instinct is a small learned behavior:\n\n```yaml\n---\nid: prefer-functional-style\ntrigger: \"when writing new functions\"\nconfidence: 0.7\ndomain: \"code-style\"\nsource: \"session-observation\"\nscope: project\nproject_id: \"a1b2c3d4e5f6\"\nproject_name: \"my-react-app\"\n---\n\n# Prefer Functional Style\n\n## Action\nUse functional patterns over classes when appropriate.\n\n## Evidence\n- Observed 5 instances of functional pattern preference\n- User corrected class-based approach to functional on 2025-01-15\n```\n\n**Properties:**\n- **Atomic** -- one trigger, one action\n- **Confidence-weighted** -- 0.3 = tentative, 0.9 = near certain\n- **Domain-tagged** -- code-style, testing, git, debugging, workflow, etc.\n- **Evidence-backed** -- tracks what observations created it\n- **Scope-aware** -- `project` (default) or `global`\n\n## How It Works\n\n```\nSession Activity (in a git repo)\n      |\n      | Hooks capture prompts + tool use (100% reliable)\n      | + detect project context (git remote / repo path)\n      v\n+---------------------------------------------+\n|  projects/<project-hash>/observations.jsonl  |\n|   (prompts, tool calls, outcomes, project)   |\n+---------------------------------------------+\n      |\n      | Observer agent reads (background, Haiku)\n      v\n+---------------------------------------------+\n|          PATTERN DETECTION                   |\n|   * User corrections -> instinct             |\n|   * Error resolutions -> instinct            |\n|   * Repeated workflows -> instinct           |\n|   * Scope decision: project or global?       |\n+---------------------------------------------+\n      |\n      | Creates/updates\n      v\n+---------------------------------------------+\n|  projects/<project-hash>/instincts/personal/ |\n|   * prefer-functional.yaml (0.7) [project]   |\n|   * use-react-hooks.yaml (0.9) [project]     |\n+---------------------------------------------+\n|  instincts/personal/  (GLOBAL)               |\n|   * always-validate-input.yaml (0.85) [global]|\n|   * grep-before-edit.yaml (0.6) [global]     |\n+---------------------------------------------+\n      |\n      | /evolve clusters + /promote\n      v\n+---------------------------------------------+\n|  projects/<hash>/evolved/ (project-scoped)   |\n|  evolved/ (global)                           |\n|   * commands/new-feature.md                  |\n|   * skills/testing-workflow.md               |\n|   * agents/refactor-specialist.md            |\n+---------------------------------------------+\n```\n\n## Project Detection\n\nThe system automatically detects your current project:\n\n1. **`CLAUDE_PROJECT_DIR` env var** (highest priority)\n2. **`git remote get-url origin`** -- hashed to create a portable project ID (same repo on different machines gets the same ID)\n3. **`git rev-parse --show-toplevel`** -- fallback using repo path (machine-specific)\n4. **Global fallback** -- if no project is detected, instincts go to global scope\n\nEach project gets a 12-character hash ID (e.g., `a1b2c3d4e5f6`). A registry file at `~/.claude/homunculus/projects.json` maps IDs to human-readable names.\n\n## Quick Start\n\n### 1. Enable Observation Hooks\n\nAdd to your `~/.claude/settings.json`.\n\n**If installed as a plugin** (recommended):\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"${CLAUDE_PLUGIN_ROOT}/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }],\n    \"PostToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"${CLAUDE_PLUGIN_ROOT}/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }]\n  }\n}\n```\n\n**If installed manually** to `~/.claude/skills`:\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }],\n    \"PostToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }]\n  }\n}\n```\n\n### 2. Initialize Directory Structure\n\nThe system creates directories automatically on first use, but you can also create them manually:\n\n```bash\n# Global directories\nmkdir -p ~/.claude/homunculus/{instincts/{personal,inherited},evolved/{agents,skills,commands},projects}\n\n# Project directories are auto-created when the hook first runs in a git repo\n```\n\n### 3. Use the Instinct Commands\n\n```bash\n/instinct-status     # Show learned instincts (project + global)\n/evolve              # Cluster related instincts into skills/commands\n/instinct-export     # Export instincts to file\n/instinct-import     # Import instincts from others\n/promote             # Promote project instincts to global scope\n/projects            # List all known projects and their instinct counts\n```\n\n## Commands\n\n| Command | Description |\n|---------|-------------|\n| `/instinct-status` | Show all instincts (project-scoped + global) with confidence |\n| `/evolve` | Cluster related instincts into skills/commands, suggest promotions |\n| `/instinct-export` | Export instincts (filterable by scope/domain) |\n| `/instinct-import <file>` | Import instincts with scope control |\n| `/promote [id]` | Promote project instincts to global scope |\n| `/projects` | List all known projects and their instinct counts |\n\n## Configuration\n\nEdit `config.json` to control the background observer:\n\n```json\n{\n  \"version\": \"2.1\",\n  \"observer\": {\n    \"enabled\": false,\n    \"run_interval_minutes\": 5,\n    \"min_observations_to_analyze\": 20\n  }\n}\n```\n\n| Key | Default | Description |\n|-----|---------|-------------|\n| `observer.enabled` | `false` | Enable the background observer agent |\n| `observer.run_interval_minutes` | `5` | How often the observer analyzes observations |\n| `observer.min_observations_to_analyze` | `20` | Minimum observations before analysis runs |\n\nOther behavior (observation capture, instinct thresholds, project scoping, promotion criteria) is configured via code defaults in `instinct-cli.py` and `observe.sh`.\n\n## File Structure\n\n```\n~/.claude/homunculus/\n+-- identity.json           # Your profile, technical level\n+-- projects.json           # Registry: project hash -> name/path/remote\n+-- observations.jsonl      # Global observations (fallback)\n+-- instincts/\n|   +-- personal/           # Global auto-learned instincts\n|   +-- inherited/          # Global imported instincts\n+-- evolved/\n|   +-- agents/             # Global generated agents\n|   +-- skills/             # Global generated skills\n|   +-- commands/           # Global generated commands\n+-- projects/\n    +-- a1b2c3d4e5f6/       # Project hash (from git remote URL)\n    |   +-- observations.jsonl\n    |   +-- observations.archive/\n    |   +-- instincts/\n    |   |   +-- personal/   # Project-specific auto-learned\n    |   |   +-- inherited/  # Project-specific imported\n    |   +-- evolved/\n    |       +-- skills/\n    |       +-- commands/\n    |       +-- agents/\n    +-- f6e5d4c3b2a1/       # Another project\n        +-- ...\n```\n\n## Scope Decision Guide\n\n| Pattern Type | Scope | Examples |\n|-------------|-------|---------|\n| Language/framework conventions | **project** | \"Use React hooks\", \"Follow Django REST patterns\" |\n| File structure preferences | **project** | \"Tests in `__tests__`/\", \"Components in src/components/\" |\n| Code style | **project** | \"Use functional style\", \"Prefer dataclasses\" |\n| Error handling strategies | **project** | \"Use Result type for errors\" |\n| Security practices | **global** | \"Validate user input\", \"Sanitize SQL\" |\n| General best practices | **global** | \"Write tests first\", \"Always handle errors\" |\n| Tool workflow preferences | **global** | \"Grep before Edit\", \"Read before Write\" |\n| Git practices | **global** | \"Conventional commits\", \"Small focused commits\" |\n\n## Instinct Promotion (Project -> Global)\n\nWhen the same instinct appears in multiple projects with high confidence, it''s a candidate for promotion to global scope.\n\n**Auto-promotion criteria:**\n- Same instinct ID in 2+ projects\n- Average confidence >= 0.8\n\n**How to promote:**\n\n```bash\n# Promote a specific instinct\npython3 instinct-cli.py promote prefer-explicit-errors\n\n# Auto-promote all qualifying instincts\npython3 instinct-cli.py promote\n\n# Preview without changes\npython3 instinct-cli.py promote --dry-run\n```\n\nThe `/evolve` command also suggests promotion candidates.\n\n## Confidence Scoring\n\nConfidence evolves over time:\n\n| Score | Meaning | Behavior |\n|-------|---------|----------|\n| 0.3 | Tentative | Suggested but not enforced |\n| 0.5 | Moderate | Applied when relevant |\n| 0.7 | Strong | Auto-approved for application |\n| 0.9 | Near-certain | Core behavior |\n\n**Confidence increases** when:\n- Pattern is repeatedly observed\n- User doesn''t correct the suggested behavior\n- Similar instincts from other sources agree\n\n**Confidence decreases** when:\n- User explicitly corrects the behavior\n- Pattern isn''t observed for extended periods\n- Contradicting evidence appears\n\n## Why Hooks vs Skills for Observation?\n\n> \"v1 relied on skills to observe. Skills are probabilistic -- they fire ~50-80% of the time based on Claude''s judgment.\"\n\nHooks fire **100% of the time**, deterministically. This means:\n- Every tool call is observed\n- No patterns are missed\n- Learning is comprehensive\n\n## Backward Compatibility\n\nv2.1 is fully compatible with v2.0 and v1:\n- Existing global instincts in `~/.claude/homunculus/instincts/` still work as global instincts\n- Existing `~/.claude/skills/learned/` skills from v1 still work\n- Stop hook still runs (but now also feeds into v2)\n- Gradual migration: run both in parallel\n\n## Privacy\n\n- Observations stay **local** on your machine\n- Project-scoped instincts are isolated per project\n- Only **instincts** (patterns) can be exported — not raw observations\n- No actual code or conversation content is shared\n- You control what gets exported and promoted\n\n## Related\n\n- [Skill Creator](https://skill-creator.app) - Generate instincts from repo history\n- Homunculus - Community project that inspired the v2 instinct-based architecture (atomic observations, confidence scoring, instinct evolution pipeline)\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) - Continuous learning section\n\n---\n\n*Instinct-based learning: teaching Claude your patterns, one project at a time.*\n"},"category":"official","lastSynced":"2026-03-06T03:54:21.413Z","seo":{"title":{"en":"continuous-learning-v2: Advanced AI Agent Setup Guide | A...","es":"Guía de configuración de continuous-learning-v2 para agen...","fr":"Guide de mise en place de continuous-learning-v2 pour les...","de":"Einrichtungsleitfaden für continuous-learning-v2 für KI-A..."},"description":{"en":"Unlock the full potential of continuous-learning-v2! Discover how to activate project-scoped instincts and evolve atomic behaviors into reusable knowledge","es":"Aprende a configurar continuous-learning-v2 para mejorar la productividad con agentes de IA y patrones de React y Python","fr":"Découvrez comment configurer continuous-learning-v2 pour améliorer la productivité avec des agents d''IA et des modèles React et Python","de":"Erfahren Sie, wie Sie continuous-learning-v2 einrichten, um die Produktivität mit KI-Agents und React- und Python-Mustern zu verbessern"},"definition":{"en":"continuous-learning-v2 is an advanced learning system that turns Claude Code sessions into reusable knowledge through atomic instincts with confidence scoring","es":"Continuous-learning-v2 es un sistema de aprendizaje de inteligencia artificial que crea instintos reutilizables a partir de sesiones","fr":"Continuous-learning-v2 est un système d''apprentissage d''intelligence artificielle qui crée des instincts réutilisables à partir de sessions","de":"Continuous-learning-v2 ist ein KI-Lernsystem, das wiederverwendbare Instinkte aus Sitzungen erstellt"},"features":{"en":["Creates atomic instincts with confidence scoring","Evolves instincts into skills, commands, and agents","Supports project-scoped instincts to prevent cross-project contamination","Integrates with Claude Code for seamless learning","Enables React patterns to stay within React projects","Allows universal patterns to be shared globally"],"es":["Sistema de aprendizaje basado en instintos","Creación de comportamientos reutilizables","Instintos con ámbito de proyecto (versión 2.1)","Compatibilidad con patrones de React y Python","Puntuación de confianza para los instintos","Integración con Claude Code"],"fr":["Système d''apprentissage basé sur des instincts","Création de comportements réutilisables","Instincts avec portée de projet (version 2.1)","Compatibilité avec des modèles React et Python","Score de confiance pour les instincts","Intégration avec Claude Code"],"de":["Instinktbasierendes Lernsystem","Erstellung wiederverwendbarer Verhaltensweisen","Projektspezifische Instinkte (Version 2.1)","Kompatibilität mit React- und Python-Mustern","Vertrauenswertung für Instinkte","Integration mit Claude Code"]},"keywords":{"en":["how to use continuous-learning-v2","continuous-learning-v2 alternative","continuous-learning-v2 setup guide","what is continuous-learning-v2","continuous-learning-v2 vs claude","installing continuous-learning-v2 for AI agents","continuous-learning-v2 for developer tools","project-scoped instincts in continuous-learning-v2","continuous-learning-v2 and anthropic integration"],"es":["agentes de inteligencia artificial","herramientas de IA","continuous learning","aprendizaje basado en instintos","patrones de React","patrones de Python","Claude Code","productividad con IA"],"fr":["agents d''intelligence artificielle","outils d''IA","apprentissage continu","apprentissage basé sur des instincts","modèles React","modèles Python","Claude Code","productivité avec IA"],"de":["KI-Agents","KI-Tools","kontinuierliches Lernen","instinktbasierendes Lernen","React-Muster","Python-Muster","Claude Code","Produktivität mit KI"]}},"agentAnalysis":{"suitability":{"en":"Essential for AI Agents like Claude Code that evolve through session-based learning and need to prevent cross-project knowledge contamination.","zh":"对于像Claude Code这样通过基于会话的学习进化的AI代理至关重要，需要防止跨项目知识污染。","ja":"Claude Codeのようなセッションベースの学習を通じて進化するAIエージェントにとって必須であり、プロジェクト間の知識汚染を防止する必要があります。","ko":"Claude Code와 같이 세션 기반 학습을 통해 진화하는 AI 에이전트에게 필수적이며, 프로젝트 간 지식 오염을 방지해야 합니다.","es":"Esencial para Agentes de IA como Claude Code que evolucionan a través del aprendizaje basado en sesiones y necesitan prevenir la contaminación de conocimiento entre proyectos.","fr":"Essentiel pour les agents IA comme Claude Code qui évoluent à travers l''apprentissage basé sur les sessions et doivent prévenir la contamination des connaissances entre les projets.","de":"Wesentlich für KI-Agents wie Claude Code, die durch sessionsbasiertes Lernen evolvieren und eine Kontaminierung von Projektwissen verhindern müssen.","pt":"Essencial para Agentes de IA como Claude Code que evoluem por meio do aprendizado baseado em sessões e precisam prevenir a contaminação de conhecimento entre projetos.","ru":"Необходимо для ИИ-агентов, таких как Claude Code, которые развиваются через обучение на основе сессий и нуждаются в предотвращении перекрестного загрязнения знаний между проектами.","ar":"ضروري للوكلاء الذكيين مثل Claude Code الذين يتقدمون من خلال التعلم القائم على الجلسات ويهتمون بمنع تلوث المعرفة بين المشاريع."},"recommendation":{"en":"Enables agents to automatically capture atomic instincts from session hooks with confidence scoring, then evolve them into reusable skills, commands, or specialized agents while maintaining project-scoped isolation for domain-specific patterns.","zh":"使代理能够自动从会话钩子中捕获原子本能并给出置信度评分，然后将其进化为可重用的技能、命令或专用代理，同时为领域特定模式保持项目范围隔离。","ja":"エージェントがセッションフックから信頼度スコア付きで原子的本能を自動的にキャプチャし、それらを再利用可能なスキル、コマンド、または専門エージェントに進化させながら、ドメイン固有パターンのためにプロジェクトスコープの分離を維持できるようにします。","ko":"에이전트가 세션 후크에서 신뢰도 점수와 함께 원자적 본능을 자동으로 캡처하고, 이를 재사용 가능한 스킬, 명령 또는 전문 에이전트로 진화시키면서 도메인 특정 패턴을 위해 프로젝트 범위 격리를 유지할 수 있게 합니다.","es":"Permite a los agentes capturar automáticamente instintos atómicos desde ganchos de sesión con puntuación de confianza, luego evolucionarlos en habilidades, comandos o agentes especializados reutilizables, manteniendo al mismo tiempo el aislamiento con alcance de proyecto para patrones específicos de dominio.","fr":"Permet aux agents de capturer automatiquement des instincts atomiques à partir de crochets de session avec un score de confiance, puis de les faire évoluer en compétences, commandes ou agents spécialisés réutilisables, tout en maintenant l''isolement à portée de projet pour les modèles spécifiques de domaine.","de":"Ermöglicht es Agents, atomare Instinkte aus Sitzungshooks mit Vertrauensbewertung automatisch zu erfassen, sie dann in wiederverwendbare Fähigkeiten, Befehle oder spezialisierte Agents zu entwickeln, während gleichzeitig die projektspezifische Isolation für domänenpezifische Muster aufrechterhalten wird.","pt":"Permite que os agentes capturem automaticamente instintos atômicos a partir de ganchos de sessão com pontuação de confiança, em seguida os evoluem em habilidades reutilizáveis, comandos ou agentes especializados, mantendo o isolamento com escopo de projeto para padrões específicos de domínio.","ru":"Позволяет агентам автоматически захватывать атомарные инстинкты из сессионных крючков с оценкой уверенности, а затем развивать их в многоразовые навыки, команды или специализированные агенты, сохраняя изоляцию в рамках проекта для домен-специфических шаблонов.","ar":"يسمح للوكلاء بتقاطب الصدف الذرية تلقائيًا من مشابك الجلسة مع تسجيل درجات الثقة، ثم يطورونها إلى مهارات قابلة لإعادة الاستخدام أو أوامر أو وكلاء متخصصين مع الحفاظ على عزل نطاق المشروع لأنماط محددة النطاق."},"useCases":{"en":["Automating instinct capture from Claude Code sessions","Generating project-specific skills from learned behaviors","Evolving atomic instincts into full agent capabilities","Preventing cross-project pattern contamination","Scoring confidence levels for learned behaviors"],"zh":["从Claude Code会话自动捕获本能","从学习行为生成项目特定技能","将原子本能进化为完整代理能力","防止跨项目模式污染","对学习行为进行置信度评分"],"ja":["Claude Codeセッションからの本能の自動キャプチャ","学習された動作からプロジェクト固有のスキルを生成","原子的本能を完全なエージェント機能に進化","プロジェクト間のパターン汚染の防止","学習された動作の信頼度レベルの評価"],"ko":["Claude Code 세션에서 본능 자동 캡처","학습된 행동에서 프로젝트별 스킬 생성","원자적 본능을 완전한 에이전트 기능으로 진화","프로젝트 간 패턴 오염 방지","학습된 행동에 대한 신뢰도 수준 점수화"],"es":["Automatizar la captura de instintos de sesiones de Claude Code","Generar habilidades específicas de proyecto a partir de comportamientos aprendidos","Evolucionar instintos atómicos en capacidades de agente completas","Prevenir la contaminación de patrones entre proyectos","Puntuar niveles de confianza para comportamientos aprendidos"],"fr":["Automatiser la capture d''instincts de sessions Claude Code","Générer des compétences spécifiques au projet à partir de comportements appris","Faire évoluer les instincts atomiques en capacités d''agent complet","Prévenir la contamination de modèles entre les projets","Noter les niveaux de confiance pour les comportements appris"],"de":["Automatisieren der Erfassung von Instinkten aus Claude-Code-Sitzungen","Erzeugen projektspezifischer Fähigkeiten aus gelernten Verhaltensweisen","Weiterentwicklung atomarer Instinkte in vollständige Agentenfähigkeiten","Verhindern der Kontaminierung von Mustern zwischen Projekten","Bewerten von Vertrauensniveaus für gelernte Verhaltensweisen"],"pt":["Automatizar a captura de instintos de sessões do Claude Code","Gerar habilidades específicas do projeto a partir de comportamentos aprendidos","Evoluir instintos atômicos em capacidades de agente completo","Prevenir a contaminação de padrões entre projetos","Avaliar níveis de confiança para comportamentos aprendidos"],"ru":["Автоматизировать захват инстинктов из сессий Claude Code","Генерировать проект-специфические навыки из изученных поведений","Развивать атомарные инстинкты в полные возможности агента","Предотвратить перекрестное загрязнение шаблонов между проектами","Оценить уровни уверенности для изученных поведений"],"ar":["توفير التقاط التلقائي للصدف من جلسات Claude Code","توليد مهارات محددة للمشروع من السلوكيات المكتسبة","تطوير الصدف الذرية إلى قدرات وكلاء كاملة","منع تلوث الأنماط بين المشاريع","تقييم مستويات الثقة للسلوكيات المكتسبة"]},"limitations":{"en":["Requires session hook integration","Depends on Claude Code environment","Needs project-scoping configuration"],"zh":["需要会话钩子集成","依赖Claude Code环境","需要项目范围配置"],"ja":["セッションフックの統合が必要","Claude Code環境に依存","プロジェクトスコープの設定が必要"],"ko":["세션 후크 통합 필요","Claude Code 환경에 의존","프로젝트 범위 구성 필요"],"es":["Requiere integración con ganchos de sesión","Depende del entorno de Claude Code","Necesita configuración de alcance de proyecto"],"fr":["Nécessite une intégration avec des crochets de session","Dépend de l''environnement Claude Code","Nécessite une configuration à portée de projet"],"de":["Benötigt Integration mit Sitzungshooks","Hängt von der Claude-Code-Umgebung ab","Benötigt projektspezifische Konfiguration"],"pt":["Requer integração de ganchos de sessão","Depende do ambiente Claude Code","Necessita de configuração de escopo de projeto"],"ru":["Требует интеграции сессионных крючков","Зависит от среды Claude Code","Требует конфигурации проектного объема"],"ar":["يتطلب تكامل مشابك الجلسة","يعتمد على بيئة Claude Code","يحتاج إلى تكوين نطاق المشروع"]},"version":4},"contentHash":"b0a7efabaef654921a7871807cd81ea10fb50c0890ffb496668e48840a157508","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":85}');
