INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/continuous-learning-v2', 'continuous-learning-v2', 'affaan-m', 'everything-claude-code', 'official', 'continuous-learning-v2 affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity Continuous-learning-v2 is an instinct-based learning system that observes sessions via hooks, creating atomic instincts with confidence scoring for AI agents and developers. It benefits developers by turning Claude Code sessions into reusable knowledge. Continuous-learning-v2 es un sistema de aprendizaje basado en instintos que observa sesiones y crea comportamientos reutilizables. La versión 2.1 agrega instintos con ámbito de proyecto. Continuous-learning-v2 est un système d''apprentissage basé sur des instincts qui observe les sessions et crée des comportements réutilisables. La version 2.1 ajoute des instincts avec portée de projet. Continuous-learning-v2 ist ein instinktbasierendes Lernsystem, das Sitzungen beobachtet und wiederverwendbare Verhaltensweisen erstellt. Die Version 2.1 fügt projektspezifische Instinkte hinzu. how to use continuous-learning-v2 continuous-learning-v2 alternative continuous-learning-v2 setup guide what is continuous-learning-v2 continuous-learning-v2 vs claude installing continuous-learning-v2 for AI agents continuous-learning-v2 for developer tools project-scoped instincts in continuous-learning-v2 continuous-learning-v2 and anthropic integration Creates atomic instincts with confidence scoring Evolves instincts into skills, commands, and agents Supports project-scoped instincts to prevent cross-project contamination Integrates with Claude Code for seamless learning Enables React patterns to stay within React projects Allows universal patterns to be shared globally continuous-learning-v2 is an advanced learning system that turns Claude Code sessions into reusable knowledge through atomic instincts with confidence scoring');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-skills/react-native-best-practices', 'official', 'callstackincubator', 'agent-skills', 'callstackincubator/agent-skills', 'react-native-best-practices', 969, 57, 85, '2026-03-06T00:34:35Z', '2026-03-06T04:52:06.514Z', 'a725ff928e058c1dd9c5dae34fc53e0ea0442e65559158de64ae1e902ab59da8', '{"id":"callstackincubator/agent-skills/react-native-best-practices","name":"react-native-best-practices","description":{"en":"This AI agent skill provides developers with concrete React Native performance optimization guidelines. It delivers actionable patterns for improving FPS, TTI, bundle size, and debugging memory leaks or re-renders, directly applicable to tasks involving Hermes or native modules.","zh":"react-native-best-practices 提供 React Native 性能优化指南，涵盖 JavaScript/React、Native（iOS/Android）和 bundling 优化","ja":"react-native-best-practices は、JavaScript/React、Native（iOS/Android）およびバンドリングの最適化をカバーする React Native パフォーマンス最適化ガイドを提供します","ko":"react-native-best-practices는 JavaScript/React, 네이티브(ios/안드로이드) 및 번들링 최적화를 포함하는 React Native 성능 최적화 가이드를 제공합니다","es":"Guía de optimización de React Native para mejorar el rendimiento de tus aplicaciones","fr":"Guide d''optimisation de React Native pour améliorer les performances de vos applications","de":"Leitfaden zur Optimierung von React Native für die Verbesserung der Leistung Ihrer Anwendungen","pt":"Otimização de desempenho para aplicativos React Native, incluindo JavaScript, React e otimização de bundles","ru":"Оптимизация производительности для приложений React Native, включая JavaScript, React и оптимизацию пакетов","ar":"تحسين الأداء لتطبيقات React Native، بما في ذلك JavaScript و React و تحسين الحزم"},"owner":"callstackincubator","repo":"agent-skills","repoPath":"callstackincubator/agent-skills","stars":969,"forks":57,"updatedAt":"2026-03-06T00:34:35Z","topics":[],"skillMd":{"name":"react-native-best-practices","description":"Provides React Native performance optimization guidelines for FPS, TTI, bundle size, memory leaks, re-renders, and animations. Applies to tasks involving Hermes optimization, JS thread blocking, bridge overhead, FlashList, native modules, or debugging jank and frame drops.","tags":"react-native, expo, performance, optimization, profiling","bodyPreview":"# React Native Best Practices\n\n## Overview\n\nPerformance optimization guide for React Native applications, covering JavaScript/React, Native (iOS/Android), and bundling optimizations. Based on Callstack''s \"Ultimate Guide to React Native Optimization\".\n\n## Skill Format\n\nEach reference file follows a hybrid format for fast lookup and deep understanding:\n\n- **Quick Pattern**: Incorrect/Correct code snippets for immediate pattern matching\n- **Quick Command**: Shell commands for process/measurement sk","body":"# React Native Best Practices\n\n## Overview\n\nPerformance optimization guide for React Native applications, covering JavaScript/React, Native (iOS/Android), and bundling optimizations. Based on Callstack''s \"Ultimate Guide to React Native Optimization\".\n\n## Skill Format\n\nEach reference file follows a hybrid format for fast lookup and deep understanding:\n\n- **Quick Pattern**: Incorrect/Correct code snippets for immediate pattern matching\n- **Quick Command**: Shell commands for process/measurement skills\n- **Quick Config**: Configuration snippets for setup-focused skills\n- **Quick Reference**: Summary tables for conceptual skills\n- **Deep Dive**: Full context with When to Use, Prerequisites, Step-by-Step, Common Pitfalls\n\n**Impact ratings**: CRITICAL (fix immediately), HIGH (significant improvement), MEDIUM (worthwhile optimization)\n\n## When to Apply\n\nReference these guidelines when:\n- Debugging slow/janky UI or animations\n- Investigating memory leaks (JS or native)\n- Optimizing app startup time (TTI)\n- Reducing bundle or app size\n- Writing native modules (Turbo Modules)\n- Profiling React Native performance\n- Reviewing React Native code for performance\n\n## Priority-Ordered Guidelines\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | FPS & Re-renders | CRITICAL | `js-*` |\n| 2 | Bundle Size | CRITICAL | `bundle-*` |\n| 3 | TTI Optimization | HIGH | `native-*`, `bundle-*` |\n| 4 | Native Performance | HIGH | `native-*` |\n| 5 | Memory Management | MEDIUM-HIGH | `js-*`, `native-*` |\n| 6 | Animations | MEDIUM | `js-*` |\n\n## Quick Reference\n\n### Optimization Workflow\n\nFollow this cycle for any performance issue: **Measure → Optimize → Re-measure → Validate**\n\n1. **Measure**: Capture baseline metrics (FPS, TTI, bundle size) before changes\n2. **Optimize**: Apply the targeted fix from the relevant reference\n3. **Re-measure**: Run the same measurement to get updated metrics\n4. **Validate**: Confirm improvement (e.g., FPS 45→60, TTI 3.2s→1.8s, bundle 2.1MB→1.6MB)\n\nIf metrics did not improve, revert and try the next suggested fix.\n\n### Critical: FPS & Re-renders\n\n**Profile first:**\n```bash\n# Open React Native DevTools\n# Press ''j'' in Metro, or shake device → \"Open DevTools\"\n```\n\n**Common fixes:**\n- Replace ScrollView with FlatList/FlashList for lists\n- Use React Compiler for automatic memoization\n- Use atomic state (Jotai/Zustand) to reduce re-renders\n- Use `useDeferredValue` for expensive computations\n\n### Critical: Bundle Size\n\n**Analyze bundle:**\n```bash\nnpx react-native bundle \\\n  --entry-file index.js \\\n  --bundle-output output.js \\\n  --platform ios \\\n  --sourcemap-output output.js.map \\\n  --dev false --minify true\n\nnpx source-map-explorer output.js --no-border-checks\n```\n\n**Verify improvement after optimization:**\n```bash\n# Record baseline size before changes\nls -lh output.js  # e.g., Before: 2.1 MB\n\n# After applying fixes, re-bundle and compare\nnpx react-native bundle --entry-file index.js --bundle-output output.js \\\n  --platform ios --dev false --minify true\nls -lh output.js  # e.g., After: 1.6 MB  (24% reduction)\n```\n\n**Common fixes:**\n- Avoid barrel imports (import directly from source)\n- Remove unnecessary Intl polyfills (Hermes has native support)\n- Enable tree shaking (Expo SDK 52+ or Re.Pack)\n- Enable R8 for Android native code shrinking\n\n### High: TTI Optimization\n\n**Measure TTI:**\n- Use `react-native-performance` for markers\n- Only measure cold starts (exclude warm/hot/prewarm)\n\n**Common fixes:**\n- Disable JS bundle compression on Android (enables Hermes mmap)\n- Use native navigation (react-native-screens)\n- Preload commonly-used expensive screens before navigating to them\n\n### High: Native Performance\n\n**Profile native:**\n- iOS: Xcode Instruments → Time Profiler\n- Android: Android Studio → CPU Profiler\n\n**Common fixes:**\n- Use background threads for heavy native work\n- Prefer async over sync Turbo Module methods\n- Use C++ for cross-platform performance-critical code\n\n## References\n\nFull documentation with code examples in [references/][references]:\n\n### JavaScript/React (`js-*`)\n\n| File | Impact | Description |\n|------|--------|-------------|\n| [js-lists-flatlist-flashlist.md][js-lists-flatlist-flashlist] | CRITICAL | Replace ScrollView with virtualized lists |\n| [js-profile-react.md][js-profile-react] | MEDIUM | React DevTools profiling |\n| [js-measure-fps.md][js-measure-fps] | HIGH | FPS monitoring and measurement |\n| [js-memory-leaks.md][js-memory-leaks] | MEDIUM | JS memory leak hunting |\n| [js-atomic-state.md][js-atomic-state] | HIGH | Jotai/Zustand patterns |\n| [js-concurrent-react.md][js-concurrent-react] | HIGH | useDeferredValue, useTransition |\n| [js-react-compiler.md][js-react-compiler] | HIGH | Automatic memoization |\n| [js-animations-reanimated.md][js-animations-reanimated] | MEDIUM | Reanimated worklets |\n| [js-uncontrolled-components.md][js-uncontrolled-components] | HIGH | TextInput optimization |\n\n### Native (`native-*`)\n\n| File | Impact | Description |\n|------|--------|-------------|\n| [native-turbo-modules.md][native-turbo-modules] | HIGH | Building fast native modules |\n| [native-sdks-over-polyfills.md][native-sdks-over-polyfills] | HIGH | Native vs JS libraries |\n| [native-measure-tti.md][native-measure-tti] | HIGH | TTI measurement setup |\n| [native-threading-model.md][native-threading-model] | HIGH | Turbo Module threads |\n| [native-profiling.md][native-profiling] | MEDIUM | Xcode/Android Studio profiling |\n| [native-platform-setup.md][native-platform-setup] | MEDIUM | iOS/Android tooling guide |\n| [native-view-flattening.md][native-view-flattening] | MEDIUM | View hierarchy debugging |\n| [native-memory-patterns.md][native-memory-patterns] | MEDIUM | C++/Swift/Kotlin memory |\n| [native-memory-leaks.md][native-memory-leaks] | MEDIUM | Native memory leak hunting |\n| [native-android-16kb-alignment.md][native-android-16kb-alignment] | CRITICAL | Third-party library alignment for Google Play |\n\n### Bundling (`bundle-*`)\n\n| File | Impact | Description |\n|------|--------|-------------|\n| [bundle-barrel-exports.md][bundle-barrel-exports] | CRITICAL | Avoid barrel imports |\n| [bundle-analyze-js.md][bundle-analyze-js] | CRITICAL | JS bundle visualization |\n| [bundle-tree-shaking.md][bundle-tree-shaking] | HIGH | Dead code elimination |\n| [bundle-analyze-app.md][bundle-analyze-app] | HIGH | App size analysis |\n| [bundle-r8-android.md][bundle-r8-android] | HIGH | Android code shrinking |\n| [bundle-hermes-mmap.md][bundle-hermes-mmap] | HIGH | Disable bundle compression |\n| [bundle-native-assets.md][bundle-native-assets] | HIGH | Asset catalog setup |\n| [bundle-library-size.md][bundle-library-size] | MEDIUM | Evaluate dependencies |\n| [bundle-code-splitting.md][bundle-code-splitting] | MEDIUM | Re.Pack code splitting |\n\n\n## Searching References\n\n```bash\n# Find patterns by keyword\ngrep -l \"reanimated\" references/\ngrep -l \"flatlist\" references/\ngrep -l \"memory\" references/\ngrep -l \"profil\" references/\ngrep -l \"tti\" references/\ngrep -l \"bundle\" references/\n```\n\n## Problem → Skill Mapping\n\n| Problem | Start With |\n|---------|------------|\n| App feels slow/janky | [js-measure-fps.md][js-measure-fps] → [js-profile-react.md][js-profile-react] |\n| Too many re-renders | [js-profile-react.md][js-profile-react] → [js-react-compiler.md][js-react-compiler] |\n| Slow startup (TTI) | [native-measure-tti.md][native-measure-tti] → [bundle-analyze-js.md][bundle-analyze-js] |\n| Large app size | [bundle-analyze-app.md][bundle-analyze-app] → [bundle-r8-android.md][bundle-r8-android] |\n| Memory growing | [js-memory-leaks.md][js-memory-leaks] or [native-memory-leaks.md][native-memory-leaks] |\n| Animation drops frames | [js-animations-reanimated.md][js-animations-reanimated] |\n| List scroll jank | [js-lists-flatlist-flashlist.md][js-lists-flatlist-flashlist] |\n| TextInput lag | [js-uncontrolled-components.md][js-uncontrolled-components] |\n| Native module slow | [native-turbo-modules.md][native-turbo-modules] → [native-threading-model.md][native-threading-model] |\n| Native library alignment issue | [native-android-16kb-alignment.md][native-android-16kb-alignment] |\n\n[references]: references/\n[js-lists-flatlist-flashlist]: references/js-lists-flatlist-flashlist.md\n[js-profile-react]: references/js-profile-react.md\n[js-measure-fps]: references/js-measure-fps.md\n[js-memory-leaks]: references/js-memory-leaks.md\n[js-atomic-state]: references/js-atomic-state.md\n[js-concurrent-react]: references/js-concurrent-react.md\n[js-react-compiler]: references/js-react-compiler.md\n[js-animations-reanimated]: references/js-animations-reanimated.md\n[js-uncontrolled-components]: references/js-uncontrolled-components.md\n[native-turbo-modules]: references/native-turbo-modules.md\n[native-sdks-over-polyfills]: references/native-sdks-over-polyfills.md\n[native-measure-tti]: references/native-measure-tti.md\n[native-threading-model]: references/native-threading-model.md\n[native-profiling]: references/native-profiling.md\n[native-platform-setup]: references/native-platform-setup.md\n[native-view-flattening]: references/native-view-flattening.md\n[native-memory-patterns]: references/native-memory-patterns.md\n[native-memory-leaks]: references/native-memory-leaks.md\n[native-android-16kb-alignment]: references/native-android-16kb-alignment.md\n[bundle-barrel-exports]: references/bundle-barrel-exports.md\n[bundle-analyze-js]: references/bundle-analyze-js.md\n[bundle-tree-shaking]: references/bundle-tree-shaking.md\n[bundle-analyze-app]: references/bundle-analyze-app.md\n[bundle-r8-android]: references/bundle-r8-android.md\n[bundle-hermes-mmap]: references/bundle-hermes-mmap.md\n[bundle-native-assets]: references/bundle-native-assets.md\n[bundle-library-size]: references/bundle-library-size.md\n[bundle-code-splitting]: references/bundle-code-splitting.md\n\n## Attribution\n\nBased on \"The Ultimate Guide to React Native Optimization\" by Callstack.\n"},"category":"official","lastSynced":"2026-03-06T04:52:06.514Z","seo":{"title":{"en":"React Native Best Practices: Performance Optimization Gui...","zh":"React Native 优化设置指南 - react-native-best-practices","ja":"React Native 最適化ガイド - react-native-best-practices AIエージェント","ko":"React Native 최적화 설정 가이드 - react-native-best-practices","es":"Guía de Optimización de React Native","fr":"Meilleures Pratiques de React Native","de":"React Native Leistungsoptimierung","pt":"Guia de Otimização para React Native","ru":"Лучшие практики для React Native: ИИ Агенты","ar":"دليل احترافي لتحسين أداء React Native"},"description":{"en":"An AI agent skill delivering React Native performance optimization patterns for FPS, TTI, and bundle size. Includes Hermes optimization, FlashList implementa...","zh":"提高 React Native 应用的性能，优化 FPS、TTI、包大小、内存泄漏等，使用 react-native-best-practices AI 工具","ja":"React Native アプリのパフォーマンスを向上させる - FPS、TTI、バンドルサイズ、メモリーリークなどを最適化する react-native-best-practices AIエージェント","ko":"React Native 애플리케이션의 성능을 개선합니다. FPS, TTI, 번들 크기, 메모리 누수 등을 최적화하는 react-native-best-practices","es":"Aprende a mejorar el rendimiento de tus aplicaciones React Native con nuestras guías de optimización de FPS, TTI y más","fr":"Améliorez les performances de vos applications React Native avec nos guides d''optimisation de FPS, TTI et plus","de":"Erfahren Sie, wie Sie die Leistung Ihrer React Native-Anwendungen mit unseren Optimierungsleitfäden für FPS, TTI und mehr verbessern können","pt":"Aprenda a otimizar o desempenho do seu aplicativo React Native com dicas sobre FPS, TTI e Hermes","ru":"Узнайте, как оптимизировать производительность вашего приложения React Native с помощью ИИ Агентов и Hermes","ar":"تعلم كيف تحسن أداء تطبيق React Native الخاص بك باستخدام نصائح حول FPS و TTI و Hermes"},"definition":{"en":"react-native-best-practices is an AI agent skill that provides a performance optimization guide for React Native applications. It offers a hybrid format with quick code patterns and shell commands for optimizing JavaScript, Native iOS/Android, and bundling processes, based on industry best practices.","zh":"react-native-best-practices 是一种提供 React Native 性能优化指南的 AI 工具","ja":"react-native-best-practices は、React Native パフォーマンス最適化ガイドを提供する AIエージェントです","ko":"react-native-best-practices는 React Native 성능 최적화 가이드를 제공하는 AI 도구입니다","es":"Herramienta de optimización de React Native para mejorar el rendimiento de aplicaciones móviles","fr":"Outil d''optimisation de React Native pour améliorer les performances des applications mobiles","de":"Werkzeug zur Optimierung von React Native für die Verbesserung der Leistung mobiler Anwendungen","pt":"O que é React Native Best Practices? É um guia de otimização de desempenho para aplicativos React Native","ru":"Что такое лучшие практики для React Native? Это руководство по оптимизации производительности для приложений React Native","ar":"ما هي أفضل ممارسات React Native؟ إنه دليل لتحسين الأداء لتطبيقات React Native"},"features":{"en":["Provides incorrect/correct code snippets for immediate pattern matching","Includes shell commands for process measurement and optimization","Offers guidelines for Hermes engine optimization","Covers optimizations for JavaScript thread blocking and bridge overhead","Delivers best practices for implementing FlashList","Provides debugging techniques for jank and frame drops"],"zh":["Hermes 优化","JS 线程阻塞优化","桥接开销优化","FlashList 优化","原生模块优化","调试 jank 和 frame drops"],"ja":["Hermes 最適化","JS スレッドブロッキング最適化","ブリッジオーバーヘッド最適化","FlashList 最適化","ネイティブモジュール最適化","ジャンクとフレームドロップのデバッグ"],"ko":["Hermes 최적화","JS 스레드 블록 최적화","브릿지 오버헤드 최적화","FlashList 최적화","네이티브 모듈 최적화","장크 및 프레임 드롭 디버깅"],"es":["Optimización de FPS y TTI","Reducción del tamaño del paquete","Eliminación de fugas de memoria","Mejora de la eficiencia de los módulos nativos","Optimización de Hermes","Depuración de problemas de renderizado"],"fr":["Optimisation de FPS et TTI","Réduction de la taille du paquet","Élimination des fuites de mémoire","Amélioration de l''efficacité des modules natifs","Optimisation de Hermes","Débogage des problèmes de rendu"],"de":["Optimierung von FPS und TTI","Reduzierung der Paketgröße","Beseitigung von Speicherlecks","Verbesserung der Effizienz von Native-Modulen","Optimierung von Hermes","Fehlersuche bei Renderproblemen"],"pt":["Otimização de FPS e TTI","Uso de Hermes para melhorar o desempenho","Redução do tamanho do bundle","Prevenção de vazamentos de memória","Otimização de re-renders e animações"],"ru":["Оптимизация FPS и TTI","Использование Hermes для улучшения производительности","Сокращение размера пакета","Предотвращение утечек памяти","Оптимизация повторного рендеринга и анимаций"],"ar":["تحسين FPS و TTI","استخدام Hermes لتحسين الأداء","تقليل حجم الحزمة","منع تسربات الذاكرة","تحسين إعادة الرسم والحركات"]},"keywords":{"en":["how to optimize React Native FPS","React Native Hermes optimization guide","debug React Native jank and frame drops","react-native-best-practices vs ultimate guide","implement FlashList React Native","react-native-best-practices install","reduce React Native bundle size","fix React Native memory leaks","React Native JS thread blocking solutions","React Native bridge overhead reduction"],"zh":["React Native 优化","React Native 性能优化","Hermes 优化","JS 线程阻塞优化","React Native 调试","React Native 最佳实践","React Native AI 工具"],"ja":["React Native 最適化","React Native パフォーマンス最適化","Hermes 最適化","JS スレッドブロッキング最適化","React Native デバッグ","React Native ベストプラクティス","React Native AIエージェント"],"ko":["React Native 최적화","React Native 성능 최적화","Hermes 최적화","JS 스레드 블록 최적화","React Native 디버깅","React Native 최적화 가이드","React Native AI 도구"],"es":["optimización de React Native","mejora del rendimiento","FPS","TTI","tamaño del paquete","fugas de memoria","módulos nativos","Hermes","depuración de problemas de renderizado"],"fr":["optimisation de React Native","amélioration des performances","FPS","TTI","taille du paquet","fuites de mémoire","modules natifs","Hermes","débogage des problèmes de rendu"],"de":["Optimierung von React Native","Leistungsverbesserung","FPS","TTI","Paketgröße","Speicherlecks","Native-Module","Hermes","Fehlersuche bei Renderproblemen"],"pt":["React Native otimização","Guia de otimização React Native","Melhorar desempenho React Native","Otimização de bundles React Native","Prevenção de vazamentos de memória React Native","React Native performance optimization"],"ru":["Оптимизация React Native","Руководство по оптимизации React Native","Улучшение производительности React Native","Оптимизация пакетов React Native","Предотвращение утечек памяти React Native","React Native производительность оптимизация"],"ar":["تحسين أداء React Native","دليل تحسين React Native","تحسين أداء تطبيقات React Native","تحسين حزم React Native","منع تسربات الذاكرة في React Native","React Native تحسين الأداء"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Development Agents needing advanced React Native performance optimization capabilities.","zh":"适用于需要高级 React Native 性能优化能力的移动应用开发代理。","ja":"React Native のパフォーマンス最適化機能が必要なモバイルアプリ開発エージェントに最適。","ko":"고급 React Native 성능 최적화 기능이 필요한 모바일 앱 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de aplicaciones móviles que necesitan capacidades avanzadas de optimización de rendimiento de React Native.","fr":"Parfait pour les agents de développement d''applications mobiles ayant besoin de capacités avancées d''optimisation de performance de React Native.","de":"Perfekt für Mobile App Development Agents, die erweiterte React Native-Leistungsoptimierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Aplicativos Móveis que necessitam de capacidades avançadas de otimização de desempenho em React Native.","ru":"Идеально подходит для агентов разработки мобильных приложений, которым требуются расширенные возможности оптимизации производительности React Native.","ar":"مثالي لوكلاء تطوير التطبيقات المحمولة الذين يحتاجون إلى قدرات متقدمة لتحسين أداء React Native."},"recommendation":{"en":"Empowers agents to optimize React Native applications for better FPS, TTI, and bundle size, leveraging techniques like Hermes optimization, JS thread blocking reduction, and native module debugging, while also addressing memory leaks, re-renders, and animation issues using FlashList and other optimized components.","zh":"赋予代理优化 React Native 应用程序以获得更好的 FPS、TTI 和包大小的能力，利用诸如 Hermes 优化、JS 线程阻塞减少和本机模块调试等技术，同时使用 FlashList 和其他优化组件解决内存泄漏、重新渲染和动画问题。","ja":"エージェントが React Native アプリケーションを FPS、TTI、バンドルサイズの向上のために最適化できるようにすることで、Hermes 最適化、JS スレッドブロッキング削減、ネイティブモジュールデバッグなどのテクニックを利用し、FlashList やその他の最適化コンポーネントを使用してメモリーリーク、再描画、アニメーションの問題に対処する。","ko":"에이전트가 React Native 애플리케이션을 더 나은 FPS, TTI 및 번들 크기의 향상을 위해 최적화할 수 있도록하여 Hermes 최적화, JS 스레드 블로킹 감소, 네이티브 모듈 디버깅 등의 기술을 활용하며 FlashList 및 기타 최적화된 컴포넌트를 사용하여 메모리 누수, 재렌더링 및 애니메이션 문제를 해결할 수 있다.","es":"Habilita a los agentes a optimizar aplicaciones React Native para un mejor FPS, TTI y tamaño de paquete, aprovechando técnicas como la optimización de Hermes, la reducción de bloqueo de subprocesos JS y la depuración de módulos nativos, y también abordando las fugas de memoria, las re-renders y los problemas de animación mediante FlashList y otros componentes optimizados.","fr":"Permet aux agents d''optimiser les applications React Native pour un meilleur FPS, TTI et taille de bundle, en exploitant des techniques telles que l''optimisation de Hermes, la réduction du blocage du thread JS et le débogage de modules natifs, tout en abordant les fuites de mémoire, les re-renders et les problèmes d''animation à l''aide de FlashList et d''autres composants optimisés.","de":"Ermöglicht es Agents, React Native-Anwendungen für ein besseres FPS, TTI und Bundle-Größe zu optimieren, indem Techniken wie Hermes-Optimierung, JS-Thread-Blockierung-Reduktion und native Modul-Debugging eingesetzt werden, und geht auch auf Speicherlecks, Re-Render und Animationsprobleme mithilfe von FlashList und anderen optimierten Komponenten ein.","pt":"Capacita os agentes a otimizar aplicações React Native para melhorar FPS, TTI e tamanho do bundle, aproveitando técnicas como otimização Hermes, redução de bloqueio da thread JS e depuração de módulos nativos, além de abordar vazamentos de memória, re-renderizações e problemas de animação usando FlashList e outros componentes otimizados.","ru":"Позволяет агентам оптимизировать приложения React Native для улучшения FPS, TTI и размера бандла, используя такие методы, как оптимизация Hermes, сокращение блокировки потока JS и отладка нативных модулей, а также решая проблемы с утечками памяти, повторными рендерингами и анимацией с помощью FlashList и других оптимизированных компонентов.","ar":"يمكّن الوكلاء من تحسين تطبيقات React Native للحصول على معدل أطر أفضل (FPS)، وقت التفاعل الأولي (TTI)، وحجم الحزمة، مستفيدين من تقنيات مثل تحسين Hermes، تقليل انسداد خيط JS، وتصحيح أخطاء الوحدات الأصلية، مع معالجة تسريبات الذاكرة، إعادة التصيير، ومشاكل الرسوم المتحركة باستخدام FlashList ومكونات محسّنة أخرى."},"useCases":{"en":["Debugging jank and frame drops in React Native applications","Optimizing bundle size and reducing bridge overhead for improved performance","Improving animations and reducing re-renders for smoother user experiences"],"zh":["调试 React Native 应用程序中的 jank 和帧丢失","优化包大小并减少桥接开销以提高性能","改进动画并减少重新渲染以获得更流畅的用户体验"],"ja":["React Native アプリケーションの jank とフレームドロップをデバッグする","バンドルサイズを最適化し、ブリッジオーバーヘッドを削減してパフォーマンスを向上させる","アニメーションを改善し、再描画を削減してよりスムーズなユーザーエクスペリエンスを実現する"],"ko":["React Native 애플리케이션의 잔렉과 프레임 드롭을 디버깅하는 것","번들 크기 최적화 및 브릿지 오버헤드 감소를 통해 성능 개선","애니메이션 개선 및 재렌더링 감소를 통해 더 나은 사용자 경험을 제공하는 것"],"es":["Depuración de problemas de jank y caídas de frames en aplicaciones React Native","Optimización del tamaño de paquete y reducción de la sobrecarga del puente para un mejor rendimiento","Mejora de las animaciones y reducción de las re-renders para experiencias de usuario más suaves"],"fr":["Débogage des problèmes de jank et de chute de frames dans les applications React Native","Optimisation de la taille de bundle et réduction de la surcharge du pont pour de meilleures performances","Amélioration des animations et réduction des re-renders pour des expériences utilisateur plus fluides"],"de":["Debugging von Jank- und Frame-Drop-Problemen in React Native-Anwendungen","Optimierung der Bundle-Größe und Reduzierung der Bridge-Overhead für bessere Leistung","Verbesserung der Animationen und Reduzierung der Re-Render für flüssigere Benutzeroberflächen"],"pt":["Depuração de engasgos e quedas de frames em aplicações React Native","Otimização do tamanho do bundle e redução da sobrecarga da ponte para melhorar o desempenho","Melhoria de animações e redução de re-renderizações para experiências de usuário mais suaves"],"ru":["Отладка задержек и падений кадров в приложениях React Native","Оптимизация размера бандла и снижение накладных расходов моста для повышения производительности","Улучшение анимаций и сокращение повторных рендеров для более плавного пользовательского опыта"],"ar":["تصحيح الاهتزازات وانخفاض الإطارات في تطبيقات React Native","تحسين حجم الحزمة وتقليل عبء الجسر لتحسين الأداء","تحسين الرسوم المتحركة وتقليل إعادة التصيير لتجارب مستخدم أكثر سلاسة"]},"limitations":{"en":["Requires knowledge of React Native and JavaScript","Limited to React Native applications only","May require additional setup for Hermes optimization and native module debugging"],"zh":["需要 React Native 和 JavaScript 的知识","仅限 React Native 应用程序","可能需要额外的设置来进行 Hermes 优化和本机模块调试"],"ja":["React Native と JavaScript の知識が必要","React Native アプリケーションのみに限定される","Hermes 最適化とネイティブモジュールデバッグを行うために追加の設定が必要になる可能性がある"],"ko":["React Native 및 JavaScript에 대한 지식이 필요함","React Native 애플리케이션만 해당함","Hermes 최적화 및 네이티브 모듈 디버깅을 위해 추가 설정이 필요할 수 있음"],"es":["Requiere conocimiento de React Native y JavaScript","Limitado a aplicaciones React Native solamente","Puede requerir configuración adicional para la optimización de Hermes y la depuración de módulos nativos"],"fr":["Nécessite des connaissances en React Native et JavaScript","Limité aux applications React Native uniquement","Peut nécessiter une configuration supplémentaire pour l''optimisation de Hermes et le débogage de modules natifs"],"de":["Benötigt Kenntnisse von React Native und JavaScript","Begrenzt auf React Native-Anwendungen","Kann eine zusätzliche Einrichtung für Hermes-Optimierung und native Modul-Debugging erfordern"],"pt":["Requer conhecimento de React Native e JavaScript","Limitado apenas a aplicações React Native","Pode exigir configuração adicional para otimização Hermes e depuração de módulos nativos"],"ru":["Требует знания React Native и JavaScript","Ограничено только приложениями React Native","Может потребовать дополнительной настройки для оптимизации Hermes и отладки нативных модулей"],"ar":["يتطلب معرفة بـ React Native و JavaScript","مقتصر على تطبيقات React Native فقط","قد يتطلب إعدادًا إضافيًا لتحسين Hermes وتصحيح أخطاء الوحدات الأصلية"]},"version":4},"contentHash":"a725ff928e058c1dd9c5dae34fc53e0ea0442e65559158de64ae1e902ab59da8","repoEtag":"W/\"cde3f79b6c913438993afe18fdb53c1f5dcf7c814f31b8ef5104f2d45f6ca3dc\"","qualityScore":85}');
