INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-skills/react-native-best-practices', 'react-native-best-practices', 'callstackincubator', 'agent-skills', 'official', 'react-native-best-practices callstackincubator agent-skills official This AI agent skill provides developers with concrete React Native performance optimization guidelines. It delivers actionable patterns for improving FPS, TTI, bundle size, and debugging memory leaks or re-renders, directly applicable to tasks involving Hermes or native modules. react-native-best-practices 提供 React Native 性能优化指南，涵盖 JavaScript/React、Native（iOS/Android）和 bundling 优化 react-native-best-practices は、JavaScript/React、Native（iOS/Android）およびバンドリングの最適化をカバーする React Native パフォーマンス最適化ガイドを提供します react-native-best-practices는 JavaScript/React, 네이티브(ios/안드로이드) 및 번들링 최적화를 포함하는 React Native 성능 최적화 가이드를 제공합니다 Guía de optimización de React Native para mejorar el rendimiento de tus aplicaciones Guide d''optimisation de React Native pour améliorer les performances de vos applications Leitfaden zur Optimierung von React Native für die Verbesserung der Leistung Ihrer Anwendungen Otimização de desempenho para aplicativos React Native, incluindo JavaScript, React e otimização de bundles Оптимизация производительности для приложений React Native, включая JavaScript, React и оптимизацию пакетов تحسين الأداء لتطبيقات React Native، بما في ذلك JavaScript و React و تحسين الحزم how to optimize React Native FPS React Native Hermes optimization guide debug React Native jank and frame drops react-native-best-practices vs ultimate guide implement FlashList React Native react-native-best-practices install reduce React Native bundle size fix React Native memory leaks React Native JS thread blocking solutions React Native bridge overhead reduction React Native 优化 React Native 性能优化 Hermes 优化 JS 线程阻塞优化 React Native 调试 React Native 最佳实践 React Native AI 工具 Provides incorrect/correct code snippets for immediate pattern matching Includes shell commands for process measurement and optimization Offers guidelines for Hermes engine optimization Covers optimizations for JavaScript thread blocking and bridge overhead Delivers best practices for implementing FlashList Provides debugging techniques for jank and frame drops react-native-best-practices is an AI agent skill that provides a performance optimization guide for React Native applications. It offers a hybrid format with quick code patterns and shell commands for optimizing JavaScript, Native iOS/Android, and bundling processes, based on industry best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/building-native-ui', 'official', 'expo', 'skills', 'expo/skills', 'building-native-ui', 1349, 59, 85, '2026-03-06T04:04:30Z', '2026-03-06T05:20:29.445Z', 'dc9c08d2601ea0f3df25656da2c6bff4f28fbc164901fabf7c8b504f5c833c19', '{"id":"expo/skills/building-native-ui","name":"building-native-ui","description":{"en":"The building-native-ui skill provides a complete guide for building beautiful apps with Expo Router, covering fundamentals, styling, and navigation. It benefits developers looking to create native-like UI experiences.","zh":"Expo Router 是一个用于构建原生 UI 应用的框架，本指南涵盖了其基础、样式、组件、导航、动画等方面的内容","ja":"Expo Router はネイティブ UI アプリケーションを構築するためのフレームワークです。このガイドでは、その基礎、スタイル、コンポーネント、ナビゲーション、アニメーションなどについて説明します","ko":"Expo Router는 네이티브 UI 애플리케이션을 구축하기 위한 프레임워크입니다. 이 가이드에서는 기본, 스타일, 구성 요소, 네비게이션, 애니메이션 등에 대한 내용을 다룹니다","es":"Guía completa para crear aplicaciones con Expo Router, cubriendo fundamentos, estilos y componentes","fr":"Guide complet pour créer des applications avec Expo Router, couvrant les fondamentaux, les styles et les composants","de":"Kompletter Leitfaden für die Erstellung von Apps mit Expo Router, einschließlich Grundlagen, Stilen und Komponenten","pt":"Construa aplicações nativas com Expo Router. Aprenda sobre fundamentos, estilização, componentes, navegação, animações e padrões","ru":"Создайте родные приложения с Expo Router. Узнайте о основах, стилизации, компонентах, навигации, анимациях и паттернах","ar":"ابني تطبيقات أصلية مع Expo Router. تعلم عن الأساسيات والتخصيص والمكونات والتنقل والرسوم المتحركة والأنماط"},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"building-native-ui","description":"Complete guide for building beautiful apps with Expo Router. Covers fundamentals, styling, components, navigation, animations, patterns, and native tabs.","version":"1.0.1","bodyPreview":"# Expo UI Guidelines\n\n## References\n\nConsult these resources as needed:\n\n```\nreferences/\n  animations.md          Reanimated: entering, exiting, layout, scroll-driven, gestures\n  controls.md            Native iOS: Switch, Slider, SegmentedControl, DateTimePicker, Picker\n  form-sheet.md          Form sheets in expo-router: configuration, footers and background interaction. \n  gradients.md           CSS gradients via experimental_backgroundImage (New Arch only)\n  icons.md               SF Symbols","body":"# Expo UI Guidelines\n\n## References\n\nConsult these resources as needed:\n\n```\nreferences/\n  animations.md          Reanimated: entering, exiting, layout, scroll-driven, gestures\n  controls.md            Native iOS: Switch, Slider, SegmentedControl, DateTimePicker, Picker\n  form-sheet.md          Form sheets in expo-router: configuration, footers and background interaction. \n  gradients.md           CSS gradients via experimental_backgroundImage (New Arch only)\n  icons.md               SF Symbols via expo-image (sf: source), names, animations, weights\n  media.md               Camera, audio, video, and file saving\n  route-structure.md     Route conventions, dynamic routes, groups, folder organization\n  search.md              Search bar with headers, useSearch hook, filtering patterns\n  storage.md             SQLite, AsyncStorage, SecureStore\n  tabs.md                NativeTabs, migration from JS tabs, iOS 26 features\n  toolbar-and-headers.md Stack headers and toolbar buttons, menus, search (iOS only)\n  visual-effects.md      Blur (expo-blur) and liquid glass (expo-glass-effect)\n  webgpu-three.md        3D graphics, games, GPU visualizations with WebGPU and Three.js\n  zoom-transitions.md    Apple Zoom: fluid zoom transitions with Link.AppleZoom (iOS 18+)\n```\n\n## Running the App\n\n**CRITICAL: Always try Expo Go first before creating custom builds.**\n\nMost Expo apps work in Expo Go without any custom native code. Before running `npx expo run:ios` or `npx expo run:android`:\n\n1. **Start with Expo Go**: Run `npx expo start` and scan the QR code with Expo Go\n2. **Check if features work**: Test your app thoroughly in Expo Go\n3. **Only create custom builds when required** - see below\n\n### When Custom Builds Are Required\n\nYou need `npx expo run:ios/android` or `eas build` ONLY when using:\n\n- **Local Expo modules** (custom native code in `modules/`)\n- **Apple targets** (widgets, app clips, extensions via `@bacons/apple-targets`)\n- **Third-party native modules** not included in Expo Go\n- **Custom native configuration** that can''t be expressed in `app.json`\n\n### When Expo Go Works\n\nExpo Go supports a huge range of features out of the box:\n\n- All `expo-*` packages (camera, location, notifications, etc.)\n- Expo Router navigation\n- Most UI libraries (reanimated, gesture handler, etc.)\n- Push notifications, deep links, and more\n\n**If you''re unsure, try Expo Go first.** Creating custom builds adds complexity, slower iteration, and requires Xcode/Android Studio setup.\n\n## Code Style\n\n- Be cautious of unterminated strings. Ensure nested backticks are escaped; never forget to escape quotes correctly.\n- Always use import statements at the top of the file.\n- Always use kebab-case for file names, e.g. `comment-card.tsx`\n- Always remove old route files when moving or restructuring navigation\n- Never use special characters in file names\n- Configure tsconfig.json with path aliases, and prefer aliases over relative imports for refactors.\n\n## Routes\n\nSee `./references/route-structure.md` for detailed route conventions.\n\n- Routes belong in the `app` directory.\n- Never co-locate components, types, or utilities in the app directory. This is an anti-pattern.\n- Ensure the app always has a route that matches \"/\", it may be inside a group route.\n\n## Library Preferences\n\n- Never use modules removed from React Native such as Picker, WebView, SafeAreaView, or AsyncStorage\n- Never use legacy expo-permissions\n- `expo-audio` not `expo-av`\n- `expo-video` not `expo-av`\n- `expo-image` with `source=\"sf:name\"` for SF Symbols, not `expo-symbols` or `@expo/vector-icons`\n- `react-native-safe-area-context` not react-native SafeAreaView\n- `process.env.EXPO_OS` not `Platform.OS`\n- `React.use` not `React.useContext`\n- `expo-image` Image component instead of intrinsic element `img`\n- `expo-glass-effect` for liquid glass backdrops\n\n## Responsiveness\n\n- Always wrap root component in a scroll view for responsiveness\n- Use `<ScrollView contentInsetAdjustmentBehavior=\"automatic\" />` instead of `<SafeAreaView>` for smarter safe area insets\n- `contentInsetAdjustmentBehavior=\"automatic\"` should be applied to FlatList and SectionList as well\n- Use flexbox instead of Dimensions API\n- ALWAYS prefer `useWindowDimensions` over `Dimensions.get()` to measure screen size\n\n## Behavior\n\n- Use expo-haptics conditionally on iOS to make more delightful experiences\n- Use views with built-in haptics like `<Switch />` from React Native and `@react-native-community/datetimepicker`\n- When a route belongs to a Stack, its first child should almost always be a ScrollView with `contentInsetAdjustmentBehavior=\"automatic\"` set\n- When adding a `ScrollView` to the page it should almost always be the first component inside the route component\n- Prefer `headerSearchBarOptions` in Stack.Screen options to add a search bar\n- Use the `<Text selectable />` prop on text containing data that could be copied\n- Consider formatting large numbers like 1.4M or 38k\n- Never use intrinsic elements like ''img'' or ''div'' unless in a webview or Expo DOM component\n\n# Styling\n\nFollow Apple Human Interface Guidelines.\n\n## General Styling Rules\n\n- Prefer flex gap over margin and padding styles\n- Prefer padding over margin where possible\n- Always account for safe area, either with stack headers, tabs, or ScrollView/FlatList `contentInsetAdjustmentBehavior=\"automatic\"`\n- Ensure both top and bottom safe area insets are accounted for\n- Inline styles not StyleSheet.create unless reusing styles is faster\n- Add entering and exiting animations for state changes\n- Use `{ borderCurve: ''continuous'' }` for rounded corners unless creating a capsule shape\n- ALWAYS use a navigation stack title instead of a custom text element on the page\n- When padding a ScrollView, use `contentContainerStyle` padding and gap instead of padding on the ScrollView itself (reduces clipping)\n- CSS and Tailwind are not supported - use inline styles\n\n## Text Styling\n\n- Add the `selectable` prop to every `<Text/>` element displaying important data or error messages\n- Counters should use `{ fontVariant: ''tabular-nums'' }` for alignment\n\n## Shadows\n\nUse CSS `boxShadow` style prop. NEVER use legacy React Native shadow or elevation styles.\n\n```tsx\n<View style={{ boxShadow: \"0 1px 2px rgba(0, 0, 0, 0.05)\" }} />\n```\n\n''inset'' shadows are supported.\n\n# Navigation\n\n## Link\n\nUse `<Link href=\"/path\" />` from ''expo-router'' for navigation between routes.\n\n```tsx\nimport { Link } from ''expo-router'';\n\n// Basic link\n<Link href=\"/path\" />\n\n// Wrapping custom components\n<Link href=\"/path\" asChild>\n  <Pressable>...</Pressable>\n</Link>\n```\n\nWhenever possible, include a `<Link.Preview>` to follow iOS conventions. Add context menus and previews frequently to enhance navigation.\n\n## Stack\n\n- ALWAYS use `_layout.tsx` files to define stacks\n- Use Stack from ''expo-router/stack'' for native navigation stacks\n\n### Page Title\n\nSet the page title in Stack.Screen options:\n\n```tsx\n<Stack.Screen options={{ title: \"Home\" }} />\n```\n\n## Context Menus\n\nAdd long press context menus to Link components:\n\n```tsx\nimport { Link } from \"expo-router\";\n\n<Link href=\"/settings\" asChild>\n  <Link.Trigger>\n    <Pressable>\n      <Card />\n    </Pressable>\n  </Link.Trigger>\n  <Link.Menu>\n    <Link.MenuAction\n      title=\"Share\"\n      icon=\"square.and.arrow.up\"\n      onPress={handleSharePress}\n    />\n    <Link.MenuAction\n      title=\"Block\"\n      icon=\"nosign\"\n      destructive\n      onPress={handleBlockPress}\n    />\n    <Link.Menu title=\"More\" icon=\"ellipsis\">\n      <Link.MenuAction title=\"Copy\" icon=\"doc.on.doc\" onPress={() => {}} />\n      <Link.MenuAction\n        title=\"Delete\"\n        icon=\"trash\"\n        destructive\n        onPress={() => {}}\n      />\n    </Link.Menu>\n  </Link.Menu>\n</Link>;\n```\n\n## Link Previews\n\nUse link previews frequently to enhance navigation:\n\n```tsx\n<Link href=\"/settings\">\n  <Link.Trigger>\n    <Pressable>\n      <Card />\n    </Pressable>\n  </Link.Trigger>\n  <Link.Preview />\n</Link>\n```\n\nLink preview can be used with context menus.\n\n## Modal\n\nPresent a screen as a modal:\n\n```tsx\n<Stack.Screen name=\"modal\" options={{ presentation: \"modal\" }} />\n```\n\nPrefer this to building a custom modal component.\n\n## Sheet\n\nPresent a screen as a dynamic form sheet:\n\n```tsx\n<Stack.Screen\n  name=\"sheet\"\n  options={{\n    presentation: \"formSheet\",\n    sheetGrabberVisible: true,\n    sheetAllowedDetents: [0.5, 1.0],\n    contentStyle: { backgroundColor: \"transparent\" },\n  }}\n/>\n```\n\n- Using `contentStyle: { backgroundColor: \"transparent\" }` makes the background liquid glass on iOS 26+.\n\n## Common route structure\n\nA standard app layout with tabs and stacks inside each tab:\n\n```\napp/\n  _layout.tsx — <NativeTabs />\n  (index,search)/\n    _layout.tsx — <Stack />\n    index.tsx — Main list\n    search.tsx — Search view\n```\n\n```tsx\n// app/_layout.tsx\nimport { NativeTabs, Icon, Label } from \"expo-router/unstable-native-tabs\";\nimport { Theme } from \"../components/theme\";\n\nexport default function Layout() {\n  return (\n    <Theme>\n      <NativeTabs>\n        <NativeTabs.Trigger name=\"(index)\">\n          <Icon sf=\"list.dash\" />\n          <Label>Items</Label>\n        </NativeTabs.Trigger>\n        <NativeTabs.Trigger name=\"(search)\" role=\"search\" />\n      </NativeTabs>\n    </Theme>\n  );\n}\n```\n\nCreate a shared group route so both tabs can push common screens:\n\n```tsx\n// app/(index,search)/_layout.tsx\nimport { Stack } from \"expo-router/stack\";\nimport { PlatformColor } from \"react-native\";\n\nexport default function Layout({ segment }) {\n  const screen = segment.match(/\\((.*)\\)/)?.[1]!;\n  const titles: Record<string, string> = { index: \"Items\", search: \"Search\" };\n\n  return (\n    <Stack\n      screenOptions={{\n        headerTransparent: true,\n        headerShadowVisible: false,\n        headerLargeTitleShadowVisible: false,\n        headerLargeStyle: { backgroundColor: \"transparent\" },\n        headerTitleStyle: { color: PlatformColor(\"label\") },\n        headerLargeTitle: true,\n        headerBlurEffect: \"none\",\n        headerBackButtonDisplayMode: \"minimal\",\n      }}\n    >\n      <Stack.Screen name={screen} options={{ title: titles[screen] }} />\n      <Stack.Screen name=\"i/[id]\" options={{ headerLargeTitle: false }} />\n    </Stack>\n  );\n}\n```\n"},"category":"official","lastSynced":"2026-03-06T05:20:29.445Z","seo":{"title":{"en":"building-native-ui: Expo Router Setup Guide | AI Agent Skill","zh":"使用 Expo Router 搭建原生 UI 应用 Setup Guide","ja":"Expo Router を使用したネイティブ UI アプリケーションの構築方法 - AIエージェント","ko":"Expo Router로 네이티브 UI 애플리케이션 구축 가이드 - AI 도구","es":"Guía de configuración para interfaces de usuario nativas ...","fr":"Guide de mise en place d''interfaces utilisateur natives a...","de":"Einrichtungsleitfaden für native Benutzeroberflächen mit ...","pt":"Guia de Configuração para building-native-ui com Expo Router","ru":"ИИ Агенты: Руководство по настройке building-native-ui с ...","ar":"دليل الإعداد للواجهة الأصلية مع Expo Router"},"description":{"en":"Unlock native UI capabilities with Expo Router. Get started with our comprehensive guide and master animations, styling, and navigation.","zh":"学习使用 Expo Router 搭建美丽的原生 UI 应用，涵盖基础、样式、组件、导航、动画等","ja":"Expo Router を使用して美しいネイティブ UI アプリケーションを構築する方法を学びましょう。基礎、スタイル、コンポーネント、ナビゲーション、アニメーションなどをカバー","ko":"Expo Router로 아름다운 네이티브 UI 애플리케이션을 구축하는 방법을 배우세요. 기본, 스타일, 구성 요소, 네비게이션, 애니메이션 등","es":"Aprende a crear aplicaciones hermosas con Expo Router. Descubre fundamentos, estilos, componentes y más","fr":"Découvrez comment créer des applications magnifiques avec Expo Router. Consultez les fondamentaux, les styles, les composants et plus","de":"Erfahren Sie, wie Sie mit Expo Router schöne Apps erstellen. Entdecken Sie Grundlagen, Stile, Komponenten und mehr","pt":"Aprenda a criar aplicações bonitas com Expo Router. Descubra os fundamentos, estilização, componentes e navegação","ru":"Изучите основы создания красивых приложений с Expo Router. Узнайте о стилизации, компонентах и навигации","ar":"تعلم كيفية إنشاء تطبيقات جميلة مع Expo Router. اكتشف الأساسيات والتخصيص والمكونات والتنقل"},"definition":{"en":"building-native-ui is a skill that provides a comprehensive guide for building native user interfaces with Expo Router, covering topics such as animations, styling, and navigation.","zh":"Expo Router 是一个用于构建原生 UI 应用的框架，提供了基础、样式、组件、导航、动画等功能","ja":"Expo Router はネイティブ UI アプリケーションを構築するためのフレームワークで、基礎、スタイル、コンポーネント、ナビゲーション、アニメーションなどの機能を提供します","ko":"Expo Router는 네이티브 UI 애플리케이션을 구축하기 위한 프레임워크로 기본, 스타일, 구성 요소, 네비게이션, 애니메이션 등을 제공합니다","es":"La creación de interfaces de usuario nativas es el proceso de diseñar y desarrollar aplicaciones con una experiencia de usuario nativa","fr":"La création d''interfaces utilisateur natives est le processus de conception et de développement d''applications avec une expérience utilisateur native","de":"Die Erstellung von nativen Benutzeroberflächen ist der Prozess des Entwurfs und der Entwicklung von Apps mit einer nativen Benutzererfahrung","pt":"building-native-ui é uma habilidade para criar aplicações móveis com interface do usuário nativa usando Expo Router","ru":"building-native-ui - это навык для создания мобильных приложений с родным пользовательским интерфейсом, используя Expo Router","ar":"building-native-ui هي مهارة لإنشاء تطبيقات الهاتف المحمول مع واجهة المستخدم الأصلية باستخدام Expo Router"},"features":{"en":["Covers Expo Router fundamentals for building native-like UI experiences","Supports styling with CSS gradients via experimental_backgroundImage","Includes navigation and animation capabilities with Reanimated","Provides components for native iOS controls, such as Switch and Slider","Offers patterns for form sheets, including configuration and background interaction","Features native tabs for a seamless user experience"],"zh":["使用 Reanimated 实现进入、退出、布局、滚动驱动和手势动画","支持 Native iOS 控件，如 Switch、Slider、SegmentedControl、DateTimePicker 和 Picker","提供表单表格配置、页脚和背景交互功能","支持 CSS 渐变和实验性背景图像","提供 SF Symbols 图标支持"],"ja":["Reanimated を使用してエンタリング、エクシット、レイアウト、スクロール駆動、アニメーションを実現","Native iOS コントロールをサポート、Switch、Slider、SegmentedControl、DateTimePicker、Picker など","フォーム シートの構成、フッター、背景のインタラクション機能を提供","CSS グラデーションと実験的背景画像をサポート","SF Symbols アイコンのサポートを提供"],"ko":["Reanimated를 사용하여 들어가기, 나가기, 레이아웃, 스크롤驱动, 제스처 애니메이션을 구현","Native iOS 컨트롤을 지원, Switch, Slider, SegmentedControl, DateTimePicker, Picker 등","폼 시트 구성, 푸터, 배경 상호 작용 기능을 제공","CSS 그라데이션과 실험적 배경 이미지를 지원","SF Symbols 아이콘 지원을 제공"],"es":["Estilos y componentes de Expo Router","Navegación y animaciones con Reanimated","Patrones y pestañas nativas","Integración con SF Symbols y CSS gradients","Compatibilidad con Form sheets y DateTimePicker"],"fr":["Styles et composants d''Expo Router","Navigation et animations avec Reanimated","Modèles et onglets natifs","Intégration avec SF Symbols et CSS gradients","Compatibilité avec Form sheets et DateTimePicker"],"de":["Stile und Komponenten von Expo Router","Navigation und Animationen mit Reanimated","Muster und native Registerkarten","Integration mit SF Symbols und CSS-Gradienten","Kompatibilität mit Form sheets und DateTimePicker"],"pt":["Criação de aplicações com Expo Router","Estilização de componentes e layouts","Implementação de navegação e animações","Uso de padrões de design para interfaces do usuário","Integração com Reanimated para animações avançadas"],"ru":["Создание приложений с Expo Router","Стилизация компонентов и макетов","Реализация навигации и анимаций","Использование паттернов дизайна для интерфейсов пользователя","Интеграция с Reanimated для продвинутых анимаций"],"ar":["إنشاء تطبيقات مع Expo Router","تخصيص المكونات والتصاميم","تنفيذ التنقل والرسوم المتحركة","استخدام أنماط التصميم لواجهات المستخدم","التكامل مع Reanimated للرسوم المتحركة المتقدمة"]},"keywords":{"en":["how to use building-native-ui","what is building-native-ui","building-native-ui alternative","building-native-ui vs React Native","building-native-ui install","building-native-ui setup guide","Expo Router tutorial","native UI design patterns","Reanimated animations"],"zh":["Expo Router","原生 UI 应用","Reanimated","Native iOS 控件","CSS 渐变","SF Symbols","Expo Router 教程","原生 UI 应用开发"],"ja":["Expo Router","ネイティブ UI アプリケーション","Reanimated","Native iOS コントロール","CSS グラデーション","SF Symbols","Expo Router ガイド","ネイティブ UI アプリケーション開発"],"ko":["Expo Router","네이티브 UI 애플리케이션","Reanimated","Native iOS 컨트롤","CSS 그라데이션","SF Symbols","Expo Router 가이드","네이티브 UI 애플리케이션 개발"],"es":["Expo Router","interfaces de usuario nativas","desarrollo de aplicaciones móviles","Reanimated","SF Symbols","CSS gradients","Form sheets","DateTimePicker"],"fr":["Expo Router","interfaces utilisateur natives","développement d''applications mobiles","Reanimated","SF Symbols","CSS gradients","Form sheets","DateTimePicker"],"de":["Expo Router","native Benutzeroberflächen","Entwicklung von mobilen Anwendungen","Reanimated","SF Symbols","CSS-Gradienten","Form sheets","DateTimePicker"],"pt":["building-native-ui","Expo Router","aplicações móveis","interface do usuário nativa","estilização de componentes","navegação e animações","padrões de design","Reanimated"],"ru":["building-native-ui","Expo Router","мобильные приложения","родной пользовательский интерфейс","стилизация компонентов","навигация и анимации","паттерны дизайна","Reanimated","ИИ Агенты"],"ar":["building-native-ui","Expo Router","تطبيقات الهاتف المحمول","واجهة المستخدم الأصلية","تخصيص المكونات","التنقل والرسوم المتحركة","أنماط التصميم","Reanimated","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Mobile Agents needing native UI development capabilities with Expo Router.","zh":"非常适合需要使用 Expo Router 进行本地 UI 开发的移动代理。","ja":"Expo Router を使用したネイティブ UI 開発機能を必要とするモバイル エージェントに最適です。","ko":"Expo Router를 사용하여 네이티브 UI 개발 기능이 필요한 모바일 에이전트에 적합합니다.","es":"Perfecto para agentes móviles que necesitan capacidades de desarrollo de UI nativo con Expo Router.","fr":"Parfait pour les agents mobiles nécessitant des capacités de développement d''UI native avec Expo Router.","de":"Perfekt für Mobile Agents, die native UI-Entwicklungsfähigkeiten mit Expo Router benötigen.","pt":"Perfeito para Agentes Móveis que necessitam de capacidades de desenvolvimento de UI nativo com Expo Router.","ru":"Идеально для мобильных агентов, которым необходимы возможности разработки родного UI с помощью Expo Router.","ar":"مثالي للوكلاء المحمولين الذين يحتاجون إلى قدرات تطوير واجهة المستخدم الأصلية مع Expo Router."},"recommendation":{"en":"Empowers agents to build beautiful, native apps with Expo Router, leveraging Reanimated animations, CSS gradients, and SF Symbols, while following Expo UI Guidelines for styling, components, and navigation.","zh":"赋予代理构建美丽、原生应用的能力，利用 Expo Router、Reanimated 动画、CSS 渐变和 SF Symbols，同时遵循 Expo UI 指南进行样式、组件和导航设置。","ja":"Expo Router、Reanimated アニメーション、CSS グラデーション、SF シンボルを利用して、美しいネイティブ アプリを構築するエージェントの能力を付与し、Expo UI ガイドラインに従ってスタイリング、コンポーネント、ナビゲーションを設定します。","ko":"Expo Router, Reanimated 애니메이션, CSS 그라데이션 및 SF 심볼을 활용하여 아름다운 네이티브 앱을 구축할 수 있는 에이전트의 능력을 부여하며, Expo UI 가이드라인을 따라 스타일, 구성 요소 및 네비게이션을 설정합니다.","es":"Habilita a los agentes a crear aplicaciones hermosas y nativas con Expo Router, aprovechando animaciones Reanimated, gradientes CSS y símbolos SF, siguiendo las pautas de UI de Expo para el estilo, los componentes y la navegación.","fr":"Permet aux agents de créer des applications natives et magnifiques avec Expo Router, en exploitant les animations Reanimated, les dégradés CSS et les symboles SF, tout en suivant les directives de l''UI d''Expo pour le style, les composants et la navigation.","de":"Ermöglich es den Agenten, schöne, native Apps mit Expo Router zu erstellen, indem sie Reanimated-Animationen, CSS-Gradienten und SF-Symbole nutzen und dabei die Expo-UI-Richtlinien für Stil, Komponenten und Navigation befolgen.","pt":"Habilita os agentes a construir aplicativos nativos bonitos com Expo Router, aproveitando animações Reanimated, gradientes CSS e SF Symbols, seguindo as Diretrizes de UI do Expo para estilização, componentes e navegação.","ru":"Наделяет агентов возможностью создавать красивые родные приложения с помощью Expo Router, используя анимации Reanimated, градиенты CSS и SF Symbols, при этом следуя Руководящим принципам UI Expo для стилизации, компонентов и навигации.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات أصلية جميلة مع Expo Router، باستخدام رسوميات حركية Reanimated وتنقيطات CSS وأشكال SF، مع اتباع إرشادات واجهة المستخدم في Expo للأسلوب والمكونات والتنقل."},"useCases":{"en":["Building custom native tabs with Expo Router","Implementing scroll-driven animations using Reanimated","Designing form sheets with configuration, footers, and background interaction"],"zh":["使用 Expo Router 构建自定义本地选项卡","使用 Reanimated 实现滚动驱动动画","设计带有配置、页脚和背景交互的表单表单"],"ja":["Expo Router を使用してカスタム ネイティブ タブを構築する","Reanimated を使用してスクロール駆動アニメーションを実装する","設定、フッター、背景のインタラクションを備えたフォーム シートを設計する"],"ko":["Expo Router를 사용하여 커스텀 네이티브 탭을 구축하는 것","Reanimated를 사용하여 스크롤 구동 애니메이션을 구현하는 것","설정, 푸터 및 배경 상호 작용을 갖춘 폼 시트를 설계하는 것"],"es":["Creación de pestañas personalizadas nativas con Expo Router","Implementación de animaciones impulsadas por desplazamiento con Reanimated","Diseño de hojas de formulario con configuración, pies de página y interacción con el fondo"],"fr":["Création de onglets natifs personnalisés avec Expo Router","Mise en œuvre d''animations à défilement avec Reanimated","Conception de feuilles de formulaire avec configuration, pieds de page et interaction avec l''arrière-plan"],"de":["Erstellung von benutzerdefinierten nativen Reitern mit Expo Router","Implementierung von scrollgesteuerten Animationen mit Reanimated","Entwurf von Formulareinblättern mit Konfiguration, Fußzeilen und Hintergrundinteraktion"],"pt":["Construir guias personalizadas nativas com Expo Router","Implementar animações impulsionadas por rolagem usando Reanimated","Projetar folhas de formulário com configuração, rodapés e interação de fundo"],"ru":["Создание пользовательских родных вкладок с помощью Expo Router","Реализация анимаций, управляемых прокруткой, с помощью Reanimated","Разработка листов форм с конфигурацией, подвалами и взаимодействием фона"],"ar":["بناء علامات التبويب الأصلية المخصصة مع Expo Router","تنفيذ الرسوم المتحركة التي تدفعها الإزاحة باستخدام Reanimated","تصميم أوراق الاستمارة مع التكوين والتذييلات والتفاعل الخلفي"]},"limitations":{"en":["Requires Expo Router setup","Limited to native iOS controls (e.g., Switch, Slider, SegmentedControl)","Experimental features (e.g., gradients) require New Arch only"],"zh":["需要 Expo Router 设置","仅限于本地 iOS 控件（例如 Switch、Slider、SegmentedControl）","实验功能（例如渐变）需要 New Archのみ"],"ja":["Expo Router の設定が必要","ネイティブ iOS コントロール (例: Switch、Slider、SegmentedControl) のみ","実験機能 (例: グラデーション) には New Archのみが必要"],"ko":["Expo Router 설정이 필요합니다","네이티브 iOS 컨트롤(예: 스위치, 슬라이더, 세그먼트 컨트롤)만 해당","실험 기능(예: 그라데이션)은 New Arch만 해당"],"es":["Requiere configuración de Expo Router","Limitado a controles nativos de iOS (por ejemplo, Switch, Slider, SegmentedControl)","Características experimentales (por ejemplo, gradientes) requieren solo Nueva Arquitectura"],"fr":["Nécessite une configuration d''Expo Router","Limité aux contrôles natifs d''iOS (par exemple, Switch, Slider, SegmentedControl)","Fonctionnalités expérimentales (par exemple, dégradés) nécessitent uniquement la Nouvelle Architecture"],"de":["Benötigt Expo Router-Setup","Begrenzt auf native iOS-Steuerlemente (z. B. Switch, Slider, SegmentedControl)","Experimentelle Funktionen (z. B. Gradienten) erfordern nur die neue Architektur"],"pt":["Requer configuração do Expo Router","Limitado aos controles nativos do iOS (por exemplo, Switch, Slider, SegmentedControl)","Recursos experimentais (por exemplo, gradientes) requerem apenas Nova Arquitetura"],"ru":["Требует настройки Expo Router","Ограничен родными элементами управления iOS (например, Switch, Slider, SegmentedControl)","Экспериментальные функции (например, градиенты) требуют только Новой Архитектуры"],"ar":["يتطلب إعداد Expo Router","محدود بالتحكم الأصلي في iOS (على سبيل المثال، Switch و Slider و SegmentedControl)","السمات التجريبية (على سبيل المثال، التدرج) تتطلب فقط الهندسة المعمارية الجديدة"]},"version":4},"contentHash":"dc9c08d2601ea0f3df25656da2c6bff4f28fbc164901fabf7c8b504f5c833c19","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":85}');
