INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/building-native-ui', 'building-native-ui', 'expo', 'skills', 'official', 'building-native-ui expo skills official The building-native-ui skill provides a complete guide for building beautiful apps with Expo Router, covering fundamentals, styling, and navigation. It benefits developers looking to create native-like UI experiences. Expo Router 是一个用于构建原生 UI 应用的框架，本指南涵盖了其基础、样式、组件、导航、动画等方面的内容 Expo Router はネイティブ UI アプリケーションを構築するためのフレームワークです。このガイドでは、その基礎、スタイル、コンポーネント、ナビゲーション、アニメーションなどについて説明します Expo Router는 네이티브 UI 애플리케이션을 구축하기 위한 프레임워크입니다. 이 가이드에서는 기본, 스타일, 구성 요소, 네비게이션, 애니메이션 등에 대한 내용을 다룹니다 Guía completa para crear aplicaciones con Expo Router, cubriendo fundamentos, estilos y componentes Guide complet pour créer des applications avec Expo Router, couvrant les fondamentaux, les styles et les composants Kompletter Leitfaden für die Erstellung von Apps mit Expo Router, einschließlich Grundlagen, Stilen und Komponenten Construa aplicações nativas com Expo Router. Aprenda sobre fundamentos, estilização, componentes, navegação, animações e padrões Создайте родные приложения с Expo Router. Узнайте о основах, стилизации, компонентах, навигации, анимациях и паттернах ابني تطبيقات أصلية مع Expo Router. تعلم عن الأساسيات والتخصيص والمكونات والتنقل والرسوم المتحركة والأنماط how to use building-native-ui what is building-native-ui building-native-ui alternative building-native-ui vs React Native building-native-ui install building-native-ui setup guide Expo Router tutorial native UI design patterns Reanimated animations Expo Router 原生 UI 应用 Reanimated Native iOS 控件 CSS 渐变 SF Symbols Expo Router 教程 原生 UI 应用开发 Covers Expo Router fundamentals for building native-like UI experiences Supports styling with CSS gradients via experimental_backgroundImage Includes navigation and animation capabilities with Reanimated Provides components for native iOS controls, such as Switch and Slider Offers patterns for form sheets, including configuration and background interaction Features native tabs for a seamless user experience building-native-ui is a skill that provides a comprehensive guide for building native user interfaces with Expo Router, covering topics such as animations, styling, and navigation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('n8n-io/n8n/reproduce-bug', 'official', 'n8n-io', 'n8n', 'n8n-io/n8n', 'reproduce-bug', 177792, 55472, 85, '2026-03-06T06:12:37Z', '2026-03-06T06:23:00.081Z', '3bd0e16cdf07eca0de32aac67a10f37578e1027fbac57fd80f1a4e82ff303a40', '{"id":"n8n-io/n8n/reproduce-bug","name":"reproduce-bug","description":{"en":"The reproduce-bug skill enables developers to reproduce bugs from Linear tickets with failing tests, using a systematic approach to parse signals and route to test strategies.","zh":"Reproduce-Bug AIエージェント可自动化故障复现，支持Linear ticket上下文解析、错误消息提取和工作流JSON分析。通过该功能，开发者可以快速定位和解决问题","ja":"Reproduce-Bug AIエージェントはバグを自動再現することができます。Linear ticketのコンテキスト解析、エラーメッセージの抽出、ワークフローJSONの分析をサポートします。開発者はこの機能を使用して問題を迅速に特定し解決できます","ko":"Reproduce-Bug AI 에이전트는 오류를 자동으로 재현할 수 있습니다. Linear 티켓 컨텍스트 파싱, 오류 메시지 추출 및 워크플ロー JSON 분석을 지원합니다. 개발자는 이 기능을 사용하여 문제를 빠르게 식별하고 해결할 수 있습니다","es":"Reproduce errores de forma sistemática con nuestra herramienta de AI, que utiliza tecnologías como Linear y n8n para analizar y reproducir errores","fr":"Reproduisez les bogues de manière systématique avec notre outil d''IA, qui utilise des technologies comme Linear et n8n pour analyser et reproduire les bogues","de":"Reproduzieren Sie Fehler systematisch mit unserem AI-Tool, das Technologien wie Linear und n8n verwendet, um Fehler zu analysieren und zu reproduzieren","pt":"O Reproduce-Bug é uma ferramenta de automação que reproduce erros a partir de tickets do Linear com testes de regressão falhos. Ele extrai informações como mensagens de erro e passos de reprodução.","ru":"Reproduce-Bug - это инструмент автоматизации, который воспроизводит ошибки из тикетов Linear с неудачными тестами регрессии. Он извлекает информацию, такую как сообщения об ошибках и шаги воспроизведения.","ar":"إعادة إنتاج الخطأ هي أداة تلقائية تعيد إنتاج الأخطاء من تذاكر Linear مع اختبارات回归 فاشلة. أنها تستخرج المعلومات مثل رسائل الخطأ وخطوات الإعادة"},"owner":"n8n-io","repo":"n8n","repoPath":"n8n-io/n8n","stars":177792,"forks":55472,"updatedAt":"2026-03-06T06:12:37Z","topics":["ai","apis","automation","cli","data-flow","development","integration-framework","integrations","ipaas","low-code","low-code-platform","mcp","mcp-client","mcp-server","n8n","no-code","self-hosted","typescript","workflow","workflow-automation"],"skillMd":{"name":"reproduce-bug","description":"Reproduce a bug from a Linear ticket with a failing test. Expects the full ticket context (title, description, comments) to be provided as input.","bodyPreview":"# Bug Reproduction Framework\n\nGiven a Linear ticket context ($ARGUMENTS), systematically reproduce the bug\nwith a failing regression test.\n\n## Step 1: Parse Signals\n\nExtract the following from the provided ticket context:\n- **Error message / stack trace** (if provided)\n- **Reproduction steps** (if provided)\n- **Workflow JSON** (if attached)\n- **Affected area** (node, execution engine, editor, API, config, etc.)\n- **Version where it broke / last working version**\n\n\n## Step 2: Route to Test Strate","body":"# Bug Reproduction Framework\n\nGiven a Linear ticket context ($ARGUMENTS), systematically reproduce the bug\nwith a failing regression test.\n\n## Step 1: Parse Signals\n\nExtract the following from the provided ticket context:\n- **Error message / stack trace** (if provided)\n- **Reproduction steps** (if provided)\n- **Workflow JSON** (if attached)\n- **Affected area** (node, execution engine, editor, API, config, etc.)\n- **Version where it broke / last working version**\n\n\n## Step 2: Route to Test Strategy\n\nBased on the affected area, pick the test layer and pattern:\n\n| Area | Test Layer | Pattern | Key Location |\n|------|-----------|---------|--------------|\n| Node operation | Jest unit | NodeTestHarness + nock | `packages/nodes-base/nodes/*/test/` |\n| Node credential | Jest unit | jest-mock-extended | `packages/nodes-base/nodes/*/test/` |\n| Trigger webhook | Jest unit | mock IHookFunctions + jest.mock GenericFunctions | `packages/nodes-base/nodes/*/test/` |\n| Binary data | Jest unit | NodeTestHarness assertBinaryData | `packages/core/nodes-testing/` |\n| Execution engine | Jest integration | WorkflowRunner + DI container | `packages/cli/src/__tests__/` |\n| CLI / API | Jest integration | setupTestServer + supertest | `packages/cli/test/integration/` |\n| Config | Jest unit | GlobalConfig + Container | `packages/@n8n/config/src/__tests__/` |\n| Editor UI | Vitest | Vue Test Utils + Pinia | `packages/frontend/editor-ui/src/**/__tests__/` |\n| E2E / Canvas | Playwright | Test containers + composables | `packages/testing/playwright/` |\n\n## Step 3: Locate Source Files\n\nFind the source code for the affected area:\n1. Search for the node/service/component mentioned in the ticket\n2. Find the GenericFunctions file (common bug location for nodes)\n3. Check for existing test files in the same area\n4. Look at recent git history on affected files (`git log --oneline -10 -- <path>`)\n\n## Step 4: Trace the Code Path\n\nRead the source code and trace the execution path that triggers the bug:\n- Follow the call chain from entry point to the failure\n- Identify the specific line(s) where the bug manifests\n- Note any error handling (or lack thereof) around the bug\n\n## Step 5: Form Hypothesis\n\nState a clear, testable hypothesis:\n- \"When [input/condition], the code does [wrong thing] because [root cause]\"\n- Identify the exact line(s) that need to change\n- Predict what the test output will show\n\n## Step 6: Find Test Patterns\n\nLook for existing tests in the same area:\n1. Check `test/` directories near the affected code\n2. Identify which mock/setup patterns they use\n3. Use the same patterns for consistency\n4. If no tests exist, find the closest similar node/service tests as a template\n\n## Step 7: Write Failing Test\n\nWrite a regression test that:\n- Uses the patterns found in Step 6\n- Targets the specific hypothesis from Step 5\n- Includes a comment referencing the ticket ID\n- Asserts the CORRECT behavior (test will fail on current code)\n- Also includes a \"happy path\" test to prove the setup works\n\n## Step 8: Run and Score\n\nRun the test from the package directory (e.g., `cd packages/nodes-base && pnpm test <file>`).\n\nClassify the result:\n\n| Confidence | Criteria | Output |\n|------------|----------|--------|\n| **CONFIRMED** | Test fails consistently, failure matches hypothesis | Reproduction Report |\n| **LIKELY** | Test fails but failure mode differs slightly | Report + caveat |\n| **UNCONFIRMED** | Cannot trigger the failure | Report: what was tried |\n| **SKIPPED** | Hit a hard bailout trigger | Report: why skipped |\n| **ALREADY_FIXED** | Bug no longer reproduces on current code | Report: when fixed |\n\n## Step 9: Iterate or Bail\n\nIf UNCONFIRMED after first attempt:\n- Revisit hypothesis — re-read the code path\n- Try a different test approach or layer\n- Maximum 3 attempts before declaring UNCONFIRMED\n\n**Hard bailout triggers** (stop immediately):\n- Requires real third-party API credentials\n- Race condition / timing-dependent\n- Requires specific cloud/enterprise infrastructure\n- Requires manual UI interaction that can''t be scripted\n\n## Output: Reproduction Report\n\nPresent findings in this format:\n\n---\n\n**Ticket:** [ID] — [title]\n**Confidence:** [CONFIRMED | LIKELY | UNCONFIRMED | SKIPPED | ALREADY_FIXED]\n\n### Root Cause\n[1-2 sentences explaining the bug mechanism]\n\n### Location\n| File | Lines | Issue |\n|------|-------|-------|\n| `path/to/file.ts` | XX-YY | Description of the problem |\n\n### Failing Test\n`path/to/test/file.test.ts` — X/Y tests fail:\n1. `test name` — [failure description]\n\n### Fix Hint\n[Pseudocode or description of the fix approach]\n\n---\n\n## Important\n\n- **DO NOT fix the bug** — only reproduce it with a failing test\n- **Leave test files in place** as evidence (don''t commit unless asked)\n- **Run tests from the package directory** (e.g., `pushd packages/nodes-base && pnpm test <file> && popd`)\n- **Always redirect build output**: `pnpm build > build.log 2>&1`\n- **DO NOT look at existing fix PRs** — the goal is to reproduce from signals alone\n"},"category":"official","lastSynced":"2026-03-06T06:23:00.081Z","seo":{"title":{"en":"reproduce-bug: Bug Reproduction Framework for AI Agents","zh":"AIエージェント：Reproduce-Bug故障复现设置指南","ja":"AIエージェント：Reproduce-Bugバグ再現セットアップガイド","ko":"AI 에이전트: Reproduce-Bug 오류 재현 설정 가이드","es":"Reproducir errores con herramientas de AI: Guía de config...","fr":"Reproduire les bogues avec des outils d''IA : Guide de dém...","de":"Fehler reproduzieren mit AI-Tools: Einrichtungsanleitung","pt":"Guia de Configuração do Reproduce-Bug: Automatize Testes ...","ru":"Инструмент ИИ Агенты: Руководство по Настройке Reproduce-...","ar":"دليل إعداد إعادة إنتاج الخطأ: إعادة إنتاج الخطأ مع أدوات ..."},"description":{"en":"Unlock efficient bug reproduction with reproduce-bug. Learn how to systematically reproduce bugs from Linear tickets and streamline your development workflow","zh":"使用Reproduce-Bug AIエージェント自动化故障复现，支持Linear ticket上下文解析、错误消息提取和工作流JSON分析","ja":"Reproduce-Bug AIエージェントを使用してバグを自動再現します。Linear ticketのコンテキスト解析、エラーメッセージの抽出、ワークフローJSONの分析をサポートします","ko":"Reproduce-Bug AI 에이전트를 사용하여 오류를 자동으로 재현합니다. Linear 티켓 컨텍스트 파싱, 오류 메시지 추출 및 워크플ロー JSON 분석을 지원합니다","es":"Aprende a reproducir errores de forma sistemática con nuestra herramienta de AI, utilizando tecnologías como Linear y n8n","fr":"Découvrez comment reproduire les bogues de manière systématique avec notre outil d''IA, utilisant des technologies comme Linear et n8n","de":"Erfahren Sie, wie Sie Fehler systematisch mit unserem AI-Tool reproduzieren können, mit Technologien wie Linear und n8n","pt":"Aprenda a configurar o Recreate-Bug para automatizar testes de reprodução de erros e melhorar a eficiência do seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить Reproduce-Bug для автоматизации тестирования и улучшения эффективности вашего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد إعادة إنتاج الخطأ لتحسين كفاءة تدفق عمل التطوير باستخدام أدوات الـ AI"},"definition":{"en":"reproduce-bug is a skill that systematically reproduces bugs from Linear tickets with failing regression tests, using a bug reproduction framework","zh":"Reproduce-Bug是AIエージェント的一种，用于自动化故障复现，支持Linear ticket上下文解析、错误消息提取和工作流JSON分析","ja":"Reproduce-BugはAIエージェントの一種で、バグを自動再現するために使用されます。Linear ticketのコンテキスト解析、エラーメッセージの抽出、ワークフローJSONの分析をサポートします","ko":"Reproduce-Bug는 AI 에이전트의 일종으로, 오류를 자동으로 재현하는 데 사용됩니다. Linear 티켓 컨텍스트 파싱, 오류 메시지 추출 및 워크플ロー JSON 분석을 지원합니다","es":"La reproducción de errores es una técnica que utiliza herramientas de AI para reproducir errores de forma sistemática, utilizando tecnologías como Linear y n8n","fr":"La reproduction de bogues est une technique qui utilise des outils d''IA pour reproduire les bogues de manière systématique, utilisant des technologies comme Linear et n8n","de":"Die Fehlerreproduktion ist eine Technik, die AI-Tools verwendet, um Fehler systematisch zu reproduzieren, mit Technologien wie Linear und n8n","pt":"O que é Reproduce-Bug? É uma ferramenta de automação que reproduce erros a partir de tickets do Linear.","ru":"Что такое Reproduce-Bug? Это инструмент автоматизации, который воспроизводит ошибки из тикетов Linear.","ar":"ما هي إعادة إنتاج الخطأ؟ هي أداة تلقائية تعيد إنتاج الأخطاء من تذاكر Linear"},"features":{"en":["Parses error messages and stack traces from Linear ticket context","Extracts reproduction steps and workflow JSON for automated testing","Identifies affected areas, including nodes, execution engines, and APIs","Routes to test strategies based on extracted signals and data","Supports integration with low-code platforms and workflow automation tools like n8n"],"zh":["Linear ticket上下文解析","错误消息提取","工作流JSON分析","自动化故障复现","支持CLI和API集成"],"ja":["Linear ticketのコンテキスト解析","エラーメッセージの抽出","ワークフローJSONの分析","バグの自動再現","CLIとAPIの統合をサポート"],"ko":["Linear 티켓 컨텍스트 파싱","오류 메시지 추출","워크플ロー JSON 분석","오류 자동 재현","CLI 및 API 통합 지원"],"es":["Análisis de errores con tecnologías como Linear","Reproducción de errores de forma sistemática","Utilización de n8n para automatizar flujos de trabajo","Soporte para tecnologías como TypeScript y CLI","Integración con plataformas de integración como IPAAS"],"fr":["Analyse des bogues avec des technologies comme Linear","Reproduction des bogues de manière systématique","Utilisation de n8n pour automatiser les flux de travail","Prise en charge des technologies comme TypeScript et CLI","Intégration avec des plateformes d''intégration comme IPAAS"],"de":["Fehleranalyse mit Technologien wie Linear","Fehlerreproduktion in systematischer Form","Verwendung von n8n zur Automatisierung von Workflows","Unterstützung für Technologien wie TypeScript und CLI","Integration mit Integrationsplattformen wie IPAAS"],"pt":["Extração de informações de tickets do Linear","Reprodução de erros com testes de regressão falhos","Análise de mensagens de erro e passos de reprodução","Integração com workflows de desenvolvimento","Suporte a automação de testes com CLI"],"ru":["Извлечение информации из тикетов Linear","Воспроизведение ошибок с неудачными тестами регрессии","Анализ сообщений об ошибках и шагов воспроизведения","Интеграция с рабочими процессами разработки","Поддержка автоматизации тестирования с CLI"],"ar":["استخراج المعلومات من تذاكر Linear","إعادة إنتاج الأخطاء مع اختبارات回归 فاشلة","تحليل رسائل الخطأ وخطوات الإعادة","التكامل مع تدفقات عمل التطوير","دعم التلقائية لاختبارات مع CLI"]},"keywords":{"en":["how to use reproduce-bug","reproduce-bug setup guide","bug reproduction framework","Linear ticket integration","automated testing with reproduce-bug","reproduce-bug vs manual testing","reproduce-bug install for AI agents","reproduce-bug alternative for developers","reproduce-bug and low-code platform integration"],"zh":["AIエージェント","Reproduce-Bug","故障复现","Linear ticket","错误消息提取","工作流JSON分析","自动化测试","CLI集成","API集成"],"ja":["AIエージェント","Reproduce-Bug","バグ再現","Linear ticket","エラーメッセージの抽出","ワークフローJSONの分析","自動テスト","CLI統合","API統合"],"ko":["AI 에이전트","Reproduce-Bug","오류 재현","Linear 티켓","오류 메시지 추출","워크플ロー JSON 분석","자동화 테스트","CLI 통합","API 통합"],"es":["herramientas de AI para reproducción de errores","reproducir errores con Linear","automatización de flujos de trabajo con n8n","desarrollo de software con TypeScript","integración de sistemas con IPAAS","reproducción de errores sistemática"],"fr":["outils d''IA pour reproduction de bogues","reproduire les bogues avec Linear","automatisation des flux de travail avec n8n","développement de logiciels avec TypeScript","intégration de systèmes avec IPAAS","reproduction de bogues systématique"],"de":["AI-Tools für Fehlerreproduktion","Fehler reproduzieren mit Linear","Automatisierung von Workflows mit n8n","Softwareentwicklung mit TypeScript","Systemintegration mit IPAAS","Fehlerreproduktion in systematischer Form"],"pt":["reproduce bug","automatização de testes","tickets do Linear","testes de regressão","CLI","desenvolvimento de software","ferramentas de automação","Integração contínua"],"ru":["Reproduce-Bug","автоматизация тестирования","тикеты Linear","тесты регрессии","CLI","разработка программного обеспечения","инструменты автоматизации","ИИ Агенты"],"ar":["إعادة إنتاج الخطأ","التلقائية لاختبارات","تذاكر Linear","اختبارات回归","CLI","تطوير البرمجيات","أدوات التلقائية","أدوات الـ AI"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Debugging Agents needing advanced bug reproduction capabilities with Linear ticket integration.","zh":"适用于需要高级错误复现能力和线性票据集成的调试代理。","ja":"Linear のチケットとの統合により、高度なバグ再現機能を必要とするデバッグ エージェントに最適。","ko":"선형 티켓 통합 및 고급 버그 재현 기능이 필요한 디버깅 에이전트에 적합합니다.","es":"Ideal para agentes de depuración que necesitan capacidades avanzadas de reproducción de errores con integración de tickets lineales.","fr":"Idéal pour les agents de débogage nécessitant des capacités de reproduction de bogues avancées avec une intégration de tickets linéaires.","de":"Ideal für Debugging-Agents, die erweiterte Fehlernachbildungs-Funktionen mit Linear-Ticket-Integration benötigen.","pt":"Ideal para agentes de depuração que precisam de capacidades avançadas de reprodução de bugs com integração de ticket linear.","ru":"Идеально для агентов отладки, требующих расширенных возможностей воспроизведения ошибок с интеграцией линейных тикетов.","ar":"مثالي لعمليات وكيل التصحيح التي تتطلب إمكانيات متقدمة لإعادة إنتاج العيوب مع دمج تذاكر الخطي"},"recommendation":{"en":"Empowers agents to systematically reproduce bugs from Linear tickets using error messages, reproduction steps, and workflow JSON, streamlining the debugging process with automated regression testing.","zh":"使代理能够系统地使用错误消息、再现步骤和工作流 JSON 从线性票据中再现错误，通过自动化回归测试简化调试过程。","ja":"エージェントがエラーメッセージ、再現手順、ワークフロー JSON を使用して Linear のチケットからバグを体系的に再現できるようにし、自動化された回帰テストでデバッグ プロセスを合理化します。","ko":"에이전트가 오류 메시지, 재현 단계 및 워크플로 JSON을 사용하여 선형 티켓에서 버그를 체계적으로 재현할 수 있도록 하여 자동화된 회귀 테스트로 디버깅 프로세스를 간소화합니다.","es":"Permite a los agentes reproducir sistemáticamente errores desde tickets lineales utilizando mensajes de error, pasos de reproducción y JSON de flujo de trabajo, simplificando el proceso de depuración con pruebas de regresión automatizadas.","fr":"Permet aux agents de reproduire systématiquement des bogues à partir de tickets linéaires en utilisant des messages d''erreur, des étapes de reproduction et du JSON de workflow, simplifiant le processus de débogage avec des tests de régression automatisés.","de":"Ermöglicht es Agents, Fehler systematisch aus Linear-Tickets mithilfe von Fehlermeldungen, Reproduktionsschritten und Workflow-JSON zu reproduzieren, wodurch der Debugging-Prozess mit automatisierten Regressions-Tests gestreamlined wird.","pt":"Habilita os agentes a reproduzir sistematicamente bugs a partir de tiquetes lineares usando mensagens de erro, etapas de reprodução e fluxo de trabalho JSON, otimizando o processo de depuração com testes de regressão automatizados.","ru":"Наделяет агентов возможностью систематически воспроизводить ошибки из линейных тикетов, используя сообщения об ошибках, шаги воспроизведения и рабочий процесс JSON, оптимизируя процесс отладки с помощью автоматизированных тестов на регресс.","ar":"تمكين الوكيل من إعادة إنتاج الأخطاء بشكل منهجي من تذاكر الخطية باستخدام رسائل الخطأ وخطوات الإعادة وإنتاج JSON للعمل ، وضبط عملية التصحيح مع الاختبارات التلقائية للانحدار"},"useCases":{"en":["Automating bug reproduction from Linear tickets","Generating failing regression tests for identified bugs","Debugging issues with workflow JSON and error message analysis"],"zh":["从线性票据中自动化错误复现","为识别的错误生成失败的回归测试","使用工作流 JSON 和错误消息分析进行错误调试"],"ja":["Linear のチケットからのバグ再現の自動化","特定のバグの失敗した回帰テストの生成","ワークフロー JSON およびエラーメッセージ分析を使用したバグのデバッグ"],"ko":["선형 티켓에서 버그 재현 자동화","식별된 버그에 대한 실패한 회귀 테스트 생성","워크플로 JSON 및 오류 메시지 분석을 사용한 버그 디버깅"],"es":["Automatizar la reproducción de errores desde tickets lineales","Generar pruebas de regresión fallidas para errores identificados","Depurar problemas con análisis de JSON de flujo de trabajo y mensajes de error"],"fr":["Automatiser la reproduction de bogues à partir de tickets linéaires","Générer des tests de régression en échec pour des bogues identifiés","Déboguer des problèmes avec l''analyse de JSON de workflow et de messages d''erreur"],"de":["Automatisierung der Fehlernachbildung aus Linear-Tickets","Generieren fehlgeschlagener Regressions-Tests für identifizierte Fehler","Fehlerbehebung mit Workflow-JSON- und Fehlermeldungsanalyse"],"pt":["Automatizar a reprodução de bugs a partir de tiquetes lineares","Gerar testes de regressão com falha para bugs identificados","Depurar problemas com análise de fluxo de trabalho JSON e mensagem de erro"],"ru":["Автоматизировать воспроизведение ошибок из линейных тикетов","Генерировать неудачные тесты на регресс для выявленных ошибок","Отлаживать проблемы с анализом рабочего процесса JSON и сообщений об ошибках"],"ar":["توفير إعادة إنتاج الأخطاء تلقائيا من تذاكر الخطية","إنتاج اختبارات انحدار فاشلة للأخطاء المحددة","تصحيح المشاكل مع تحليل JSON للعمل والرسائل الخطأ"]},"limitations":{"en":["Requires full Linear ticket context as input","Limited to bugs with provided reproduction steps or error messages","Dependent on the quality and completeness of the Linear ticket data"],"zh":["需要完整的线性票据上下文作为输入","仅限于具有提供的再现步骤或错误消息的错误","依赖于线性票据数据的质量和完整性"],"ja":["入力として完全な Linear チケットのコンテキストが必要","提供された再現手順またはエラーメッセージを持つバグに限られる","Linear チケットデータの品質と完全性に依存する"],"ko":["입력으로完整한 선형 티켓 컨텍스트가 필요함","제공된 재현 단계 또는 오류 메시지를 갖는 버그에만 한정됨","선형 티켓 데이터의 품질 및 완전성에 의존함"],"es":["Requiere contexto completo de ticket lineal como entrada","Limitado a errores con pasos de reproducción o mensajes de error proporcionados","Dependiente de la calidad y la completitud de los datos del ticket lineal"],"fr":["Nécessite un contexte de ticket linéaire complet comme entrée","Limité aux bogues avec des étapes de reproduction ou des messages d''erreur fournis","Dépend de la qualité et de l''exhaustivité des données du ticket linéaire"],"de":["Benötigt vollständigen Linear-Ticket-Kontext als Eingabe","Begrenzt auf Fehler mit bereitgestellten Reproduktionsschritten oder Fehlermeldungen","Abhängig von der Qualität und Vollständigkeit der Linear-Ticket-Daten"],"pt":["Exige contexto completo do tiquete linear como entrada","Limitado a bugs com etapas de reprodução ou mensagens de erro fornecidas","Dependente da qualidade e completude dos dados do tiquete linear"],"ru":["Требует полный контекст линейного тикета в качестве входных данных","Ограничен ошибками с предоставленными шагами воспроизведения или сообщениями об ошибках","Зависит от качества и полноты данных линейного тикета"],"ar":["يتطلب سياق التذكرة الخطية الكامل كمدخل","محدود للأخطاء التي تحتوي على خطوات إعادة الإنتاج أو رسائل الخطأ المحددة","يعتمد على جودة واكتمال بيانات التذكرة الخطية"]},"version":4},"contentHash":"3bd0e16cdf07eca0de32aac67a10f37578e1027fbac57fd80f1a4e82ff303a40","repoEtag":"W/\"3826f18d1894df306122a172f629759ce7b1aa3bff04dbe05feba05281ded220\"","qualityScore":85}');
