INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/browser-automation', 'browser-automation', 'aiskillstore', 'marketplace', 'community', 'browser-automation aiskillstore marketplace community 该技能提供了使用rust-browser-mcp服务器的指导，实现企业级浏览器自动化，支持性能监控和多会话 このスキルは、rust-browser-mcpサーバーを使用して企業級ブラウザ自動化を実現するためのガイダンスを提供し、パフォーマンス監視と複数セッションをサポートします 이 기술은 rust-browser-mcp 서버를 사용하여 기업급 브라우저 자동화를 구현하는 데 대한 지침을 제공하며, 성능 모니터링 및 다중 세션을 지원합니다 La automatización de navegador permite controlar y monitorear navegadores de forma eficiente L''automatisation de navigateur permet de contrôler et de surveiller les navigateurs de manière efficace Die Browser-Automatisierung ermöglicht eine effiziente Steuerung und Überwachung von Browsern O servidor rust-browser-mcp fornece ferramentas de automação de navegador para controle de navegador de ponta com monitoramento de desempenho e suporte a multi-sessão Сервер rust-browser-mcp предоставляет инструменты автоматизации браузера для управления браузером высшего класса с мониторингом производительности и поддержкой нескольких сессий خادم rust-browser-mcp يوفر أدوات توتير المتصفح للتحكم في المتصفح ذو الأداء العالي مع مراقبة الأداء ودعم الجلسات المتعددة Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. 浏览器自动化 rust-browser-mcp WebDriver 企业级浏览器控制 性能监控 多会话支持 Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/best-practices', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'best-practices', 0, 0, 85, '2026-02-20T04:13:19.580Z', '2026-03-02T09:49:30.668Z', 'f32182e2cd742818f6b3b86f40be319eeae9cb10e392e3e4a8e8f586bad4eccf', '{"id":"majiayu000/claude-skill-registry/best-practices","name":"best-practices","description":{"zh":"应用现代-web开发最佳实践，确保安全、兼容性和代码质量。适用于安全审计、代码现代化、代码质量审查或漏洞检查","ja":"モダンなウェブ開発のベストプラクティスを適用して、セキュリティ、互換性、コード品質を確保します。セキュリティ監査、コードのモダナイズ、コード品質レビュー、または脆弱性のチェックに使用します","ko":"최신 웹 개발 모범 사례를 적용하여 보안, 호환성 및 코드 품질을 확보합니다. 보안 감사, 코드 현대화, 코드 품질 검토 또는 취약성 확인에 사용합니다","es":"Aplica las mejores prácticas de desarrollo web para seguridad, compatibilidad y calidad de código con herramientas AI","fr":"Appliquez les meilleures pratiques de développement web pour la sécurité, la compatibilité et la qualité de code avec des outils IA","de":"Wenden Sie die besten Praktiken im Webdevelopment für Sicherheit, Kompatibilität und Code-Qualität mit AI-Tools an","pt":"Aplicar melhores práticas de desenvolvimento web para segurança, compatibilidade e qualidade de código com Ferramentas de IA. Use para auditoria de segurança, modernização de código e revisão de qualidade de código.","ru":"Применять лучшие практики веб-разработки для безопасности, совместимости и качества кода с помощью ИИ Агентов. Используйте для аудита безопасности, модернизации кода и проверки качества кода.","ar":"تطبيق أفضل الممارسات لتطوير الويب لتحقيق الأمان والموائمة وضمان جودة الكود باستخدام أدوات الذكاء الاصطناعي. استخدم لمراجعة أمان الشفرة وتحديثها ومراجعة جودة الشفرة.","en":"Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security audit, modernize code, code quality review, or check for vulnerabilities."},"seo":{"title":{"zh":"AI智能工具：最佳实践","ja":"AIエージェント：モダンなウェブ開発ベストプラクティス","ko":"AI 에이전트: 최신 웹 개발 모범 사례","es":"Herramientas AI para Mejores Prácticas de Desarrollo Web","fr":"Outils IA pour les Meilleures Pratiques de Développement Web","de":"AI-Tools für Beste Praktiken im Webdevelopment","pt":"Melhores Práticas de Desenvolvimento Web com Ferramentas ...","ru":"Лучшие практики веб-разработки с помощью ИИ Агентов","ar":"أفضل الممارسات لتطوير الويب باستخدام أدوات الذكاء الاصطناعي","en":"best-practices"},"description":{"zh":"应用现代-web开发最佳实践，确保安全、兼容性和代码质量。适用于安全审计、代码现代化、代码质量审查或漏洞检查","ja":"モダンなウェブ開発のベストプラクティスを適用して、セキュリティ、互換性、コード品質を確保します。セキュリティ監査、コードのモダナイズ、コード品質レビュー、または脆弱性のチェックに使用します","ko":"최신 웹 개발 모범 사례를 적용하여 보안, 호환성 및 코드 품질을 확보합니다. 보안 감사, 코드 현대화, 코드 품질 검토 또는 취약성 확인에 사용합니다","es":"Aplica las mejores prácticas de desarrollo web para seguridad, compatibilidad y calidad de código con herramientas AI","fr":"Appliquez les meilleures pratiques de développement web pour la sécurité, la compatibilité et la qualité de code avec des outils IA","de":"Wenden Sie die besten Praktiken im Webdevelopment für Sicherheit, Kompatibilität und Code-Qualität mit AI-Tools an","pt":"Aplicar melhores práticas de desenvolvimento web para segurança, compatibilidade e qualidade de código com Ferramentas de IA. Use para auditoria de segurança...","ru":"Применять лучшие практики веб-разработки для безопасности, совместимости и качества кода с помощью ИИ Агентов. Используйте для аудита безопасности, модерниза...","ar":"تطبيق أفضل الممارسات لتطوير الويب لتحقيق الأمان والموائمة وضمان جودة الكود باستخدام أدوات الذكاء الاصطناعي. استخدم لمراجعة أمان الشفرة وتحديثها ومراجعة جودة ...","en":"Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security audit, modernize ..."},"definition":{"en":"Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security 