INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/best-practices', 'best-practices', 'majiayu000', 'claude-skill-registry', 'community', 'best-practices majiayu000 claude-skill-registry community 应用现代-web开发最佳实践，确保安全、兼容性和代码质量。适用于安全审计、代码现代化、代码质量审查或漏洞检查 モダンなウェブ開発のベストプラクティスを適用して、セキュリティ、互換性、コード品質を確保します。セキュリティ監査、コードのモダナイズ、コード品質レビュー、または脆弱性のチェックに使用します 최신 웹 개발 모범 사례를 적용하여 보안, 호환성 및 코드 품질을 확보합니다. 보안 감사, 코드 현대화, 코드 품질 검토 또는 취약성 확인에 사용합니다 Aplica las mejores prácticas de desarrollo web para seguridad, compatibilidad y calidad de código con herramientas AI Appliquez les meilleures pratiques de développement web pour la sécurité, la compatibilité et la qualité de code avec des outils IA Wenden Sie die besten Praktiken im Webdevelopment für Sicherheit, Kompatibilität und Code-Qualität mit AI-Tools an Aplicar melhores práticas de desenvolvimento web para segurança, compatibilidade e qualidade de código com Ferramentas de IA. Use para auditoria de segurança, modernização de código e revisão de qualidade de código. Применять лучшие практики веб-разработки для безопасности, совместимости и качества кода с помощью ИИ Агентов. Используйте для аудита безопасности, модернизации кода и проверки качества кода. تطبيق أفضل الممارسات لتطوير الويب لتحقيق الأمان والموائمة وضمان جودة الكود باستخدام أدوات الذكاء الاصطناعي. استخدم لمراجعة أمان الشفرة وتحديثها ومراجعة جودة الشفرة. Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security audit, modernize code, code quality review, or check for vulnerabilities. 如何使用AI智能工具 什么是最佳实践 AI智能工具替代品 AI智能工具安装 AI智能工具设置指南 现代-web开发安全最佳实践 兼容性和代码质量保证 安全审计和漏洞检查 Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security audit, modernize code, code quality review, or check for vulnerabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/API Development', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'API Development', 0, 0, 85, '2026-02-20T04:13:19.579Z', '2026-03-02T09:49:38.572Z', 'e1489fbfe053bd90b44f2f7bebdc22b3c262c6d553777679a5321ad9f0705e80', '{"id":"majiayu000/claude-skill-registry/API Development","name":"API Development","description":{"zh":"使用AI智能开发构建REST API，实现错误处理、状态码、请求验证、响应格式化和限速，适用于创建API路由、处理错误、验证输入或设计API响应","ja":"AIエージェントを使用してREST APIを開発し、エラーハンドリング、ステータスコード、リクエスト検証、レスポンス形式、レート制限を実現、APIルートの作成、エラーハンドリング、入力の検証、またはAPIレスポンスの設計に適しています","ko":"AI 에이전트를 사용하여 REST API를 개발하고 오류 처리, 상태 코드, 요청 검증, 응답 형식 및 속도 제한을 구현하여 API 루트 생성, 오류 처리, 입력 검증 또는 API 응답 설계에 적합","es":"El desarrollo de API implica crear APIs REST con manejo de errores, validación de solicitudes y limitación de velocidad. Aprende a aplicar estas habilidades en tus proyectos.","fr":"Le développement d''API consiste à créer des API REST avec gestion d''erreurs, validation des requêtes et limitation de débit. Apprenez à appliquer ces compétences dans vos projets.","de":"Die API-Entwicklung beinhaltet die Erstellung von REST-APIs mit Fehlerbehandlung, Anfragevalidierung und Rate Limiting. Erfahren Sie, wie Sie diese Fähigkeiten in Ihren Projekten anwenden.","pt":"Construa APIs REST com tratamento de erros, status codes e validação de solicitações. Aprenda a aplicar esses conceitos com as Ferramentas de IA","ru":"Создайте REST API с обработкой ошибок, статус-кодами и валидацией запросов. Примените эти концепции с помощью ИИ Агентов","ar":"ابني واجهات برمجة التطبيقات مع معالجة الأخطاء ورموز الحالة وتصديق الطلبات. تعلم كيفية تطبيق هذه المفاهيم باستخدام أدوات الذكاء الاصطناعي","en":"Build REST APIs with proper error handling, status codes, request validation, response formatting, and rate limiting. Apply whe