INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/swift-actor-persistence', 'swift-actor-persistence', 'affaan-m', 'everything-claude-code', 'official', 'swift-actor-persistence affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity swift-actor-persistence provides thread-safe data persistence in Swift using actors, combining in-memory caching with file-backed storage. It benefits developers building offline-first apps with local storage. Swift Actor Persistence 提供线程安全的数据持久化解决方案，结合内存缓存和文件存储，消除数据竞争 Swift Actor Persistence はスレッドセーフなデータ永続化ソリューションを提供し、メモリキャッシュとファイルストレージを組み合わせてデータ競争を排除 Swift Actor Persistence는 스레드 안전한 데이터 지속성 솔루션을 제공하며, 메모리 캐시와 파일 저장소를 결합하여 데이터 경쟁을 제거 Patrón de persistencia de datos thread-safe usando actores de Swift 5.5+. Combina caché en memoria con almacenamiento respaldado por archivos, eliminando carreras de datos mediante el modelo de actores en tiempo de compilación. Modèle de persistance de données thread-safe utilisant les acteurs Swift 5.5+. Combine cache mémoire et stockage fichier, éliminant les races conditions via le modèle acteur au moment de la compilation. Thread-sicheres Datenpersistenzmuster mit Swift 5.5+ Actors. Kombiniert In-Memory-Caching mit dateibasiertem Speicher und eliminiert Data Races durch das Actor-Modell zur Kompilierzeit. O swift-actor-persistence oferece persistência de dados thread-safe em Swift, combinando cache em memória com armazenamento em arquivo swift-actor-persistence обеспечивает потокобезопасное хранение данных в Swift, сочетая кэш в памяти и файловое хранилище swift-actor-persistence يوفر استمرارية البيانات آمنة في Swift، مع دمج ذاكرة مؤقتة في الذاكرة وتخزين الملفات how to use swift-actor-persistence swift-actor-persistence alternative swift-actor-persistence setup guide what is swift-actor-persistence swift-actor-persistence vs core data swift-actor-persistence install thread-safe data persistence in Swift swift 5.5+ data persistence actor model in Swift Swift Actor Persistence 线程安全数据持久化 内存缓存 文件存储 AIエージェント Swift 5.5+ 离线优先的应用程序 Combines in-memory caching with file-backed storage Leverages the actor model to eliminate data races at compile time Provides thread-safe access to shared mutable state Eliminates manual synchronization using locks or DispatchQueues Supports building offline-first apps with local storage swift-actor-persistence is a thread-safe data persistence pattern in Swift using actors, eliminating data races at compile time');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/shadcn-ui', 'community', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'shadcn-ui', 0, 0, 82, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:33.117Z', '2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304', '{"id":"google-labs-code/stitch-skills/shadcn-ui","name":"shadcn-ui","description":{"en":"shadcn-ui is a collection of reusable components built with Radix UI and Tailwind CSS, helping frontend engineers build accessible applications. It benefits developers by providing customizable components.","zh":"shadcn-ui 是一个高度可定制的 UI 组件集合，使用 Radix UI 或 Base UI 和 Tailwind CSS 构建。它提供了全面的所有权和自定义能力","ja":"shadcn-ui は、高度にカスタマイズ可能な UI コンポーネントのコレクションであり、Radix UI または Base UI と Tailwind CSS で構築されています。全面的所有権とカスタマイズ能力を提供します","ko":"shadcn-ui는高度로 맞춤형 UI 컴포넌트 컬렉션으로, Radix UI 또는 Base UI와 Tailwind CSS로 구축되었습니다. 전체적인 소유권과 맞춤형 기능을 제공합니다","es":"shadcn-ui es una colección de componentes personalizables y accesibles construidos con Radix UI y Tailwind CSS","fr":"shadcn-ui est une collection de composants personnalisables et accessibles construits avec Radix UI et Tailwind CSS","de":"shadcn-ui ist eine Sammlung von anpassbaren und zugänglichen Komponenten, die mit Radix UI und Tailwind CSS erstellt wurden","pt":"shadcn-ui é uma coleção de componentes reutilizáveis projetados com Radix UI e Tailwind CSS para criar aplicações acessíveis e personalizadas","ru":"shadcn/ui — это коллекция повторно используемых компонентов, разработанных с помощью Radix UI и Tailwind CSS для создания доступных и настраиваемых приложений","ar":"شادCN-UI هي مجموعة من المكونات القابلة لإعادة الاستخدام المصممة مع Radix UI و Tailwind CSS لإنشاء تطبيقات يمكن الوصول إليها وتخصيصها"},"seo":{"title":{"en":"shadcn-ui: Radix UI Component Integration Setup Guide | A...","zh":"shadcn-ui 组件集成指南 - 高度可定制的 UI 解决方案","ja":"shadcn-ui コンポーネント統合ガイド - カスタマイズ可能な UI ソリューション","ko":"shadcn-ui 컴포넌트 통합 가이드 -高度로 맞춤형 UI 솔루션","es":"Guía de configuración de shadcn-ui para desarrolladores","fr":"Guide d''intégration de shadcn-ui pour les développeurs","de":"Einrichtungsleitfaden für shadcn-ui für Entwickler","pt":"Guia de Configuração shadcn-ui: Melhores Práticas para De...","ru":"ИИ Агенты: shadcn-ui Настройка и Лучшие Практики","ar":"إعداد شادCN-UI: دليل أفضل الممارسات للاستفادة القصوى من ا..."},"description":{"en":"Discover how to integrate shadcn/ui components with Radix UI and Tailwind CSS. Learn best practices for customization and setup with our expert guide.","zh":"发现 shadcn-ui 的强大功能，了解如何将其集成到您的项目中，实现高度可定制的 UI 解决方案","ja":"shadcn-ui の強力な機能を発見し、プロジェクトに統合する方法を学び、カスタマイズ可能な UI ソリューションを実現します","ko":"shadcn-ui의 강력한 기능을 발견하고 프로젝트에 통합하는 방법을 배우고高度로 맞춤형 UI 솔루션을 구현하십시오","es":"Aprende a integrar shadcn-ui en tus proyectos con nuestros consejos y mejores prácticas para desarrolladores","fr":"Découvrez comment intégrer shadcn-ui dans vos projets avec nos conseils et meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie shadcn-ui in Ihre Projekte integrieren, mit unseren Tipps und Best Practices für Entwickler","pt":"Aprenda a integrar e personalizar componentes shadcn-ui com Radix UI, Base UI e Tailwind CSS para criar aplicações acessíveis e personalizadas","ru":"Откройте для себя возможности shadcn/ui с ИИ Агентами: интеграция и настройка компонентов для создания доступных и настраиваемых приложений","ar":"استكشف إمكانيات شادCN-UI مع أدوات الذكاء الإصطناعي: دمج ومخصّص للمكونات لإنشاء تطبيقات يمكن الوصول إليها وتخصيصها"},"definition":{"en":"shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.","zh":"shadcn-ui 是一个 UI 组件集合，提供高度可定制的解决方案","ja":"shadcn-ui は、カスタマイズ可能なソリューションを提供する UI コンポーネントのコレクションです","ko":"shadcn-ui는高度로 맞춤형 솔루션을 제공하는 UI 컴포넌트 컬렉션입니다","es":"shadcn-ui es una colección de componentes reutilizables no basada en bibliotecas","fr":"shadcn-ui est une collection de composants réutilisables qui ne repose pas sur des bibliothèques","de":"shadcn-ui ist eine Sammlung von wiederverwendbaren Komponenten, die nicht auf Bibliotheken basiert","pt":"shadcn-ui é uma coleção de componentes reutilizáveis para aplicações web","ru":"shadcn/ui — это коллекция повторно используемых компонентов для веб-приложений","ar":"شادCN-UI هي مجموعة من المكونات القابلة لإعادة الاستخدام لتطبيقات الويب"},"features":{"en":["Provides reusable components built with Radix UI and Tailwind CSS","Supports customization following best practices","Allows for full ownership of components copied into projects","Utilizes Base UI for additional component functionality","Integrates with Tailwind CSS for styling and layout control","Enables accessible application development"],"zh":["使用 Radix UI 或 Base UI 构建","高度可定制的 UI 解决方案","全面的所有权和自定义能力","支持 Tailwind CSS","可复用的组件集合"],"ja":["Radix UI または Base UI で構築","カスタマイズ可能な UI ソリューション","全面的所有権とカスタマイズ能力","Tailwind CSS をサポート","再利用可能なコンポーネントのコレクション"],"ko":["Radix UI 또는 Base UI로 구축","高度로 맞춤형 UI 솔루션","전체적인 소유권과 맞춤형 기능","Tailwind CSS 지원","재사용 가능한 컴포넌트 컬렉션"],"es":["Componentes personalizables con Radix UI","Compatibilidad con Tailwind CSS","Accesibilidad y diseño responsivo","Copia y pega de componentes en tu proyecto","Total control sobre el código y la personalización"],"fr":["Composants personnalisables avec Radix UI","Compatibilité avec Tailwind CSS","Accessibilité et conception réactive","Copier-coller de composants dans votre projet","Contrôle total sur le code et la personnalisation"],"de":["Anpassbare Komponenten mit Radix UI","Kompatibilität mit Tailwind CSS","Zugänglichkeit und responsives Design","Kopieren und Einfügen von Komponenten in Ihr Projekt","Vollständige Kontrolle über den Code und die Anpassung"],"pt":["Componentes reutilizáveis com Radix UI","Personalização com Tailwind CSS","Acessibilidade em aplicações web","Integração com Base UI","Desenvolvimento de aplicações personalizadas"],"ru":["Повторно используемые компоненты с Radix UI","Настройка с помощью Tailwind CSS","Доступность в веб-приложениях","Интеграция с Base UI","Разработка настраиваемых приложений"],"ar":["مكونات قابلة لإعادة الاستخدام مع Radix UI","تخصيص مع Tailwind CSS","إمكانية الوصول إلى تطبيقات الويب","دمج مع Base UI","تنمية تطبيقات مخصصة"]},"keywords":{"en":["how to use shadcn-ui","shadcn-ui vs Radix UI","shadcn-ui setup guide","what is shadcn-ui","shadcn-ui alternative","shadcn-ui install with Tailwind CSS","customizing shadcn-ui components","shadcn-ui and Base UI integration","shadcn-ui accessibility features"],"zh":["shadcn-ui","UI 组件","高度可定制","Radix UI","Base UI","Tailwind CSS","前端开发","UI 设计"],"ja":["shadcn-ui","UI コンポーネント","カスタマイズ可能","Radix UI","Base UI","Tailwind CSS","フロントエンド開発","UI デザイン"],"ko":["shadcn-ui","UI 컴포넌트","高度로 맞춤형","Radix UI","Base UI","Tailwind CSS","프론트엔드 개발","UI 디자인"],"es":["shadcn-ui","integración de componentes","Radix UI","Tailwind CSS","desarrollo frontend","componentes personalizables","accesibilidad web","diseño responsivo"],"fr":["shadcn-ui","intégration de composants","Radix UI","Tailwind CSS","développement frontend","composants personnalisables","accessibilité web","conception réactive"],"de":["shadcn-ui","Komponenten-Integration","Radix UI","Tailwind CSS","Frontend-Entwicklung","anpassbare Komponenten","Zugänglichkeit im Web","responsives Design"],"pt":["shadcn-ui","componentes reutilizáveis","Radix UI","Tailwind CSS","acessibilidade web","desenvolvimento web","aplicações personalizadas"],"ru":["shadcn/ui","ИИ Агенты","повторно используемые компоненты","Radix UI","Tailwind CSS","доступность веб-приложений","разработка веб-приложений"],"ar":["شادCN-UI","أدوات الذكاء الإصطناعي","مكونات قابلة لإعادة الاستخدام","Radix UI","Tailwind CSS","إمكانية الوصول إلى تطبيقات الويب","تنمية تطبيقات الويب"]}},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Expert guidance for integrating and building applications with shadcn/ui components, including component discovery, installation, customization, and best practices.","bodyPreview":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full owner","body":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full ownership**: Components live in your codebase, not node_modules\n- **Complete customization**: Modify styling, behavior, and structure freely, including choosing between Radix UI or Base UI primitives\n- **No version lock-in**: Update components selectively at your own pace\n- **Zero runtime overhead**: No library bundle, just the code you need\n\n## Component Discovery and Installation\n\n### 1. Browse Available Components\n\nUse the shadcn MCP tools to explore the component catalog and Registry Directory:\n- **List all components**: Use `list_components` to see the complete catalog\n- **Get component metadata**: Use `get_component_metadata` to understand props, dependencies, and usage\n- **View component demos**: Use `get_component_demo` to see implementation examples\n\n### 2. Component Installation\n\nThere are two approaches to adding components:\n\n**A. Direct Installation (Recommended)**\n```bash\nnpx shadcn@latest add [component-name]\n```\n\nThis command:\n- Downloads the component source code (adapting to your config: Radix vs Base UI)\n- Installs required dependencies\n- Places files in `components/ui/`\n- Updates your `components.json` config\n\n**B. Manual Integration**\n1. Use `get_component` to retrieve the source code\n2. Create the file in `components/ui/[component-name].tsx`\n3. Install peer dependencies manually\n4. Adjust imports if needed\n\n### 3. Registry and Custom Registries\n\nIf working with a custom registry (defined in `components.json`) or exploring the Registry Directory:\n- Use `get_project_registries` to list available registries\n- Use `list_items_in_registries` to see registry-specific components\n- Use `view_items_in_registries` for detailed component information\n- Use `search_items_in_registries` to find specific components\n\n## Project Setup\n\n### Initial Configuration\n\nFor **new projects**, use the `create` command to customize everything (style, fonts, component library):\n\n```bash\nnpx shadcn@latest create\n```\n\nFor **existing projects**, initialize configuration:\n\n```bash\nnpx shadcn@latest init\n```\n\nThis creates `components.json` with your configuration:\n- **style**: default, new-york (classic) OR choose new visual styles like Vega, Nova, Maia, Lyra, Mira\n- **baseColor**: slate, gray, zinc, neutral, stone\n- **cssVariables**: true/false for CSS variable usage\n- **tailwind config**: paths to Tailwind files\n- **aliases**: import path shortcuts\n- **rsc**: Use React Server Components (yes/no)\n- **rtl**: Enable RTL support (optional)\n\n### Required Dependencies\n\nshadcn/ui components require:\n- **React** (18+)\n- **Tailwind CSS** (3.0+)\n- **Primitives**: Radix UI OR Base UI (depending on your choice)\n- **class-variance-authority** (for variant styling)\n- **clsx** and **tailwind-merge** (for class composition)\n\n## Component Architecture\n\n### File Structure\n```\nsrc/\n├── components/\n│   ├── ui/              # shadcn components\n│   │   ├── button.tsx\n│   │   ├── card.tsx\n│   │   └── dialog.tsx\n│   └── [custom]/        # your composed components\n│       └── user-card.tsx\n├── lib/\n│   └── utils.ts         # cn() utility\n└── app/\n    └── page.tsx\n```\n\n### The `cn()` Utility\n\nAll shadcn components use the `cn()` helper for class merging:\n\n```typescript\nimport { clsx, type ClassValue } from \"clsx\"\nimport { twMerge } from \"tailwind-merge\"\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs))\n}\n```\n\nThis allows you to:\n- Override default styles without conflicts\n- Conditionally apply classes\n- Merge Tailwind classes intelligently\n\n## Customization Best Practices\n\n### 1. Theme Customization\n\nEdit your Tailwind config and CSS variables in `app/globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 221.2 83.2% 53.3%;\n    /* ... more variables */\n  }\n  \n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    /* ... dark mode overrides */\n  }\n}\n```\n\n### 2. Component Variants\n\nUse `class-variance-authority` (cva) for variant logic:\n\n```typescript\nimport { cva } from \"class-variance-authority\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        outline: \"border border-input\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n```\n\n### 3. Extending Components\n\nCreate wrapper components in `components/` (not `components/ui/`):\n\n```typescript\n// components/custom-button.tsx\nimport { Button } from \"@/components/ui/button\"\nimport { Loader2 } from \"lucide-react\"\n\nexport function LoadingButton({ \n  loading, \n  children, \n  ...props \n}: ButtonProps & { loading?: boolean }) {\n  return (\n    <Button disabled={loading} {...props}>\n      {loading && <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />}\n      {children}\n    </Button>\n  )\n}\n```\n\n## Blocks and Complex Components\n\nshadcn/ui provides complete UI blocks (authentication forms, dashboards, etc.):\n\n1. **List available blocks**: Use `list_blocks` with optional category filter\n2. **Get block source**: Use `get_block` with the block name\n3. **Install blocks**: Many blocks include multiple component files\n\nBlocks are organized by category:\n- **calendar**: Calendar interfaces\n- **dashboard**: Dashboard layouts\n- **login**: Authentication flows\n- **sidebar**: Navigation sidebars\n- **products**: E-commerce components\n\n## Accessibility\n\nAll shadcn/ui components are built on Radix UI primitives, ensuring:\n- **Keyboard navigation**: Full keyboard support out of the box\n- **Screen reader support**: Proper ARIA attributes\n- **Focus management**: Logical focus flow\n- **Disabled states**: Proper disabled and aria-disabled handling\n\nWhen customizing, maintain accessibility:\n- Keep ARIA attributes\n- Preserve keyboard handlers\n- Test with screen readers\n- Maintain focus indicators\n\n## Common Patterns\n\n### Form Building\n```typescript\nimport { Button } from \"@/components/ui/button\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\n// Use with react-hook-form for validation\nimport { useForm } from \"react-hook-form\"\n```\n\n### Dialog/Modal Patterns\n```typescript\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n```\n\n### Data Display\n```typescript\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n```\n\n## Troubleshooting\n\n### Import Errors\n- Check `components.json` for correct alias configuration\n- Verify `tsconfig.json` includes the `@` path alias:\n  ```json\n  {\n    \"compilerOptions\": {\n      \"paths\": {\n        \"@/*\": [\"./src/*\"]\n      }\n    }\n  }\n  ```\n\n### Style Conflicts\n- Ensure Tailwind CSS is properly configured\n- Check that `globals.css` is imported in your root layout\n- Verify CSS variable names match between components and theme\n\n### Missing Dependencies\n- Run component installation via CLI to auto-install deps\n- Manually check `package.json` for required Radix UI packages\n- Use `get_component_metadata` to see dependency lists\n\n### Version Compatibility\n- shadcn/ui v4 requires React 18+ and Next.js 13+ (if using Next.js)\n- Some components require specific Radix UI versions\n- Check documentation for breaking changes between versions\n\n## Validation and Quality\n\nBefore committing components:\n1. **Type check**: Run `tsc --noEmit` to verify TypeScript\n2. **Lint**: Run your linter to catch style issues\n3. **Test accessibility**: Use tools like axe DevTools\n4. **Visual QA**: Test in light and dark modes\n5. **Responsive check**: Verify behavior at different breakpoints\n\n## Resources\n\nRefer to the following resource files for detailed guidance:\n- `resources/setup-guide.md` - Step-by-step project initialization\n- `resources/component-catalog.md` - Complete component reference\n- `resources/customization-guide.md` - Theming and variant patterns\n- `resources/migration-guide.md` - Upgrading from other UI libraries\n\n## Examples\n\nSee the `examples/` directory for:\n- Complete component implementations\n- Form patterns with validation\n- Dashboard layouts\n- Authentication flows\n- Data table implementations\n"},"lastSynced":"2026-03-08T02:00:33.117Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing accessible and customizable UI components built with Radix UI and Tailwind CSS.","zh":"非常适合需要可访问和自定义UI组件的前端代理，使用Radix UI和Tailwind CSS构建。","ja":"Radix UIとTailwind CSSで構築されたアクセシブルでカスタマイズ可能なUIコンポーネントを必要とするフロントエンドエージェントに最適です。","ko":"Radix UI와 Tailwind CSS로 구축된 접근 가능하고 사용자 지정 가능한 UI 컴포넌트가 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan componentes de UI accesibles y personalizables construidos con Radix UI y Tailwind CSS.","fr":"Parfait pour les agents Frontend qui ont besoin de composants d''interface utilisateur accessibles et personnalisables construits avec Radix UI et Tailwind CSS.","de":"Perfekt für Frontend-Agents, die zugängliche und anpassbare UI-Komponenten benötigen, die mit Radix UI und Tailwind CSS erstellt wurden.","pt":"Perfeito para Agentes Frontend que precisam de componentes de UI acessíveis e personalizáveis construídos com Radix UI e Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходимы доступные и настраиваемые компоненты пользовательского интерфейса, построенные с помощью Radix UI и Tailwind CSS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى مكونات واجهة المستخدم القابلة للوصول والمتوافقة والمبنية باستخدام Radix UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to build accessible applications with customizable components, utilizing Radix UI and Tailwind CSS for seamless integration and styling, while following best practices for component discovery and customization.","zh":"赋予代理构建可访问应用程序的能力，具有可定制的组件，利用Radix UI和Tailwind CSS实现无缝集成和样式，同时遵循组件发现和自定义的最佳实践。","ja":"Radix UIとTailwind CSSを利用してシームレスな統合とスタイリングを行い、コンポーネントの発見とカスタマイズのベストプラクティスに従って、アクセシブルなアプリケーションを構築するためのエージェントをエンパワーメントします。","ko":"Radix UI와 Tailwind CSS를 사용하여 무결점 통합과 스타일링을 제공하면서 컴포넌트 발견과 사용자 지정에 대한 모범 사례를 따르도록 에이전트를赋予权限하여 접근 가능한 응용 프로그램을 구축합니다.","es":"Habilita a los agentes a crear aplicaciones accesibles con componentes personalizables, utilizando Radix UI y Tailwind CSS para una integración y estilismo sin problemas, siguiendo las mejores prácticas para el descubrimiento y la personalización de componentes.","fr":"Permet aux agents de créer des applications accessibles avec des composants personnalisables, en utilisant Radix UI et Tailwind CSS pour une intégration et un style sans problème, en suivant les meilleures pratiques pour la découverte et la personnalisation de composants.","de":"Ermöglicht es Agents, zugängliche Anwendungen mit anpassbaren Komponenten zu erstellen, indem Radix UI und Tailwind CSS für eine nahtlose Integration und Stilgebung verwendet werden, unter Einhaltung der besten Praktiken für die Komponentenentdeckung und -anpassung.","pt":"Habilita os agentes a construir aplicações acessíveis com componentes personalizáveis, utilizando Radix UI e Tailwind CSS para integração e estilização sem problemas, seguindo as melhores práticas para descoberta e personalização de componentes.","ru":"Наделяет агентов возможностью создавать доступные приложения с настраиваемыми компонентами, используя Radix UI и Tailwind CSS для беспроблемной интеграции и стилизации, следуя最佳 практикам для открытия и настройки компонентов.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات يمكن الوصول إليها مع مكونات قابلة للتعديل، باستخدام Radix UI و Tailwind CSS من أجل التكامل السلس والأسلوب، مع اتباع أفضل الممارسات لاكتشاف مكونات التعديل."},"useCases":{"en":["Integrating accessible UI components into web applications","Customizing shadcn/ui components for tailored user experiences","Building reusable component libraries with Radix UI and Tailwind CSS"],"zh":["将可访问的UI组件集成到Web应用程序中","自定义shadcn/ui组件以实现个性化用户体验","使用Radix UI和Tailwind CSS构建可重用组件库"],"ja":["WebアプリケーションにアクセシブルなUIコンポーネントを統合する","shadcn/uiコンポーネントをカスタマイズしてユーザー体験を最適化する","Radix UIとTailwind CSSを使用して再利用可能なコンポーネントライブラリを構築する"],"ko":["웹 애플리케이션에 접근 가능한 UI 컴포넌트를 통합하는こと","shadcn/ui 컴포넌트를 사용자 지정하여 사용자 경험을 최적화하는 것","Radix UI와 Tailwind CSS를 사용하여 재사용 가능한 컴포넌트 라이브러리를 구축하는 것"],"es":["Integrar componentes de UI accesibles en aplicaciones web","Personalizar componentes shadcn/ui para experiencias de usuario personalizadas","Crear bibliotecas de componentes reutilizables con Radix UI y Tailwind CSS"],"fr":["Intégrer des composants d''interface utilisateur accessibles dans des applications Web","Personnaliser des composants shadcn/ui pour des expériences utilisateur personnalisées","Créer des bibliothèques de composants réutilisables avec Radix UI et Tailwind CSS"],"de":["Zugängliche UI-Komponenten in Webanwendungen integrieren","shadcn/ui-Komponenten für maßgeschneiderte Benutzeroberflächen anpassen","Wiederverwendbare Komponentenbibliotheken mit Radix UI und Tailwind CSS erstellen"],"pt":["Integrar componentes de UI acessíveis em aplicações web","Personalizar componentes shadcn/ui para experiências de usuário personalizadas","Construir bibliotecas de componentes reutilizáveis com Radix UI e Tailwind CSS"],"ru":["Интегрировать доступные компоненты пользовательского интерфейса в веб-приложения","Настроить компоненты shadcn/ui для индивидуальных пользовательских опытов","Построить библиотеки повторно используемых компонентов с помощью Radix UI и Tailwind CSS"],"ar":["إضافة مكونات واجهة المستخدم القابلة للوصول إلى التطبيقات الويب","تخصيص مكونات shadcn/ui لتجارب المستخدم المخصصة","بناء مكتبات مكونات قابلة لإعادة الاستخدام مع Radix UI و Tailwind CSS"]},"limitations":{"en":["Requires knowledge of Radix UI and Tailwind CSS","Not a traditional component library, but rather a collection of reusable components"],"zh":["需要Radix UI和Tailwind CSS的知识","不是传统的组件库，而是一组可重用的组件"],"ja":["Radix UIとTailwind CSSの知識が必要","従来のコンポーネントライブラリではなく、再利用可能なコンポーネントのコレクション"],"ko":["Radix UI와 Tailwind CSS에 대한 지식이 필요함","전통적인 컴포넌트 라이브러리가 아니라 재사용 가능한 컴포넌트의 컬렉션"],"es":["Requiere conocimiento de Radix UI y Tailwind CSS","No es una biblioteca de componentes tradicional, sino más bien una colección de componentes reutilizables"],"fr":["Nécessite des connaissances en Radix UI et Tailwind CSS","N''est pas une bibliothèque de composants traditionnelle, mais plutôt une collection de composants réutilisables"],"de":["Benötigt Kenntnisse von Radix UI und Tailwind CSS","Ist keine herkömmliche Komponentenbibliothek, sondern eher eine Sammlung wiederverwendbarer Komponenten"],"pt":["Exige conhecimento de Radix UI e Tailwind CSS","Não é uma biblioteca de componentes tradicional, mas sim uma coleção de componentes reutilizáveis"],"ru":["Требует знания Radix UI и Tailwind CSS","Не является традиционной библиотекой компонентов, а скорее коллекцией повторно используемых компонентов"],"ar":["يتطلب معرفة Radix UI و Tailwind CSS","ليست مكتبة مكونات تقليدية، بل مجموعة من المكونات القابلة لإعادة الاستخدام"]},"version":4},"contentHash":"2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304","qualityScore":82}');
