INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/shadcn-ui', 'shadcn-ui', 'google-labs-code', 'stitch-skills', 'community', 'shadcn-ui google-labs-code stitch-skills community shadcn-ui is a collection of reusable components built with Radix UI and Tailwind CSS, helping frontend engineers build accessible applications. It benefits developers by providing customizable components. shadcn-ui 是一个高度可定制的 UI 组件集合，使用 Radix UI 或 Base UI 和 Tailwind CSS 构建。它提供了全面的所有权和自定义能力 shadcn-ui は、高度にカスタマイズ可能な UI コンポーネントのコレクションであり、Radix UI または Base UI と Tailwind CSS で構築されています。全面的所有権とカスタマイズ能力を提供します shadcn-ui는高度로 맞춤형 UI 컴포넌트 컬렉션으로, Radix UI 또는 Base UI와 Tailwind CSS로 구축되었습니다. 전체적인 소유권과 맞춤형 기능을 제공합니다 shadcn-ui es una colección de componentes personalizables y accesibles construidos con Radix UI y Tailwind CSS shadcn-ui est une collection de composants personnalisables et accessibles construits avec Radix UI et Tailwind CSS shadcn-ui ist eine Sammlung von anpassbaren und zugänglichen Komponenten, die mit Radix UI und Tailwind CSS erstellt wurden shadcn-ui é uma coleção de componentes reutilizáveis projetados com Radix UI e Tailwind CSS para criar aplicações acessíveis e personalizadas shadcn/ui — это коллекция повторно используемых компонентов, разработанных с помощью Radix UI и Tailwind CSS для создания доступных и настраиваемых приложений شادCN-UI هي مجموعة من المكونات القابلة لإعادة الاستخدام المصممة مع Radix UI و Tailwind CSS لإنشاء تطبيقات يمكن الوصول إليها وتخصيصها how to use shadcn-ui shadcn-ui vs Radix UI shadcn-ui setup guide what is shadcn-ui shadcn-ui alternative shadcn-ui install with Tailwind CSS customizing shadcn-ui components shadcn-ui and Base UI integration shadcn-ui accessibility features shadcn-ui UI 组件 高度可定制 Radix UI Base UI Tailwind CSS 前端开发 UI 设计 Provides reusable components built with Radix UI and Tailwind CSS Supports customization following best practices Allows for full ownership of components copied into projects Utilizes Base UI for additional component functionality Integrates with Tailwind CSS for styling and layout control Enables accessible application development shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/brand-guidelines', 'official', 'getsentry', 'skills', 'getsentry/skills', 'brand-guidelines', 360, 11, 82, '2026-03-06T00:20:36Z', '2026-03-06T04:57:19.082Z', '59c75b089fc355f34862172222344801d267ea8158d1bcddb9d1338ba8e9bc39', '{"id":"getsentry/skills/brand-guidelines","name":"brand-guidelines","description":{"en":"The brand-guidelines skill generates UI text following Sentry''s brand guidelines, benefiting developers and content creators. It covers tone selection for various contexts, including Plain Speech and Sentry Voice.","zh":"Sentry 品牌指南提供了 Plain Speech 和 Sentry Voice 两种语气选择，用于不同上下文的 UI 文本、错误消息和文档等","ja":"Sentry ブランドガイドラインでは、Plain Speech と Sentry Voice の 2 つのトーンを提供し、UI テキスト、エラーメッセージ、ドキュメントなどの異なるコンテキストに適用できる","ko":"Sentry 브랜드 가이드라인은 Plain Speech와 Sentry Voice의 2가지 톤을 제공하며 UI 텍스트, 에러 메시지, 문서 등의 다양한 컨텍스트에 적용할 수 있다","es":"Escribe copias siguiendo las pautas de marca de Sentry con nuestra herramienta de AI. Aprende a aplicar tonos de voz en diferentes contextos","fr":"Écrivez des copies conformes aux directives de marque de Sentry avec notre outil d''IA. Apprenez à appliquer les tons de voix dans différents contextes","de":"Schreiben Sie Kopien gemäß den Markenrichtlinien von Sentry mit unserem KI-Tool. Erfahren Sie, wie Sie Sprachtonen in verschiedenen Kontexten anwenden","pt":"Escreva cópias seguindo as diretrizes de marca Sentry para UI, erros e fluxos de entrada","ru":"Пишите копии в соответствии с руководствами по бренду Sentry для пользовательского интерфейса, ошибок и потоков входа","ar":"اكتب النسخ اتباعاً لإرشادات العلامة التجارية Sentry للواجهة المستخدمة وأخطاء والعمليات"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"brand-guidelines","description":"Write copy following Sentry brand guidelines. Use when writing UI text, error messages, empty states, onboarding flows, 404 pages, documentation, marketing copy, or any user-facing content. Covers both Plain Speech (default) and Sentry Voice tones.","bodyPreview":"# Brand Guidelines\n\nWrite user-facing copy following Sentry''s brand guidelines.\n\n## Tone Selection\n\nChoose the appropriate tone based on context:\n\n| Use Plain Speech | Use Sentry Voice |\n|------------------|------------------|\n| Product UI (buttons, labels, forms) | 404 pages |\n| Documentation | Empty states |\n| Error messages | Onboarding flows |\n| Settings pages | Loading states |\n| Transactional emails | \"What''s New\" announcements |\n| Help text | Marketing copy |\n\n**Default to Plain Speech**","body":"# Brand Guidelines\n\nWrite user-facing copy following Sentry''s brand guidelines.\n\n## Tone Selection\n\nChoose the appropriate tone based on context:\n\n| Use Plain Speech | Use Sentry Voice |\n|------------------|------------------|\n| Product UI (buttons, labels, forms) | 404 pages |\n| Documentation | Empty states |\n| Error messages | Onboarding flows |\n| Settings pages | Loading states |\n| Transactional emails | \"What''s New\" announcements |\n| Help text | Marketing copy |\n\n**Default to Plain Speech** unless the context specifically calls for personality.\n\n## Plain Speech (Default)\n\nPlain Speech is clear, direct, and functional. Use it for most UI elements.\n\n### Rules\n\n1. **Be concise** - Use the fewest words needed\n2. **Be direct** - Tell users what to do, not what they can do\n3. **Use active voice** - \"Save your changes\" not \"Your changes will be saved\"\n4. **Avoid jargon** - Use simple words users understand\n5. **Be specific** - \"3 errors found\" not \"Some errors found\"\n\n### Examples\n\n| Instead of | Write |\n|------------|-------|\n| \"Click here to save your changes\" | \"Save\" |\n| \"You can filter results by date\" | \"Filter by date\" |\n| \"An error has occurred\" | \"Something went wrong\" |\n| \"Please enter a valid email address\" | \"Enter a valid email\" |\n| \"Are you sure you want to delete?\" | \"Delete this item?\" |\n\n## Sentry Voice\n\nSentry Voice adds personality in appropriate moments. It''s empathetic, self-aware, and occasionally snarky.\n\n### Principles\n\n1. **Empathetic snark** - Direct frustration at the situation, never the user\n2. **Self-aware** - Acknowledge the absurdity of software\n3. **Fun but functional** - Personality should enhance, not obscure meaning\n4. **Earned moments** - Only use when users have time to appreciate it\n\n### Examples\n\n**404 Pages:**\n> \"This page doesn''t exist. Maybe it never did. Maybe it was a dream. Either way, let''s get you back on track.\"\n\n**Empty States:**\n> \"No errors yet. Enjoy this moment of peace while it lasts.\"\n\n**Onboarding:**\n> \"Let''s get your first error. Don''t worry, it''s not as scary as it sounds.\"\n\n**Loading States:**\n> \"Crunching the numbers...\"\n> \"Fetching your data...\"\n\n### When NOT to Use Sentry Voice\n\n- Error messages (users are frustrated)\n- Settings pages (users are focused)\n- Documentation (users need information)\n- Billing/payment flows (users need trust)\n\n## General Rules\n\n### Spelling and Grammar\n\n- Use **American English** spelling (color, not colour)\n- Use **Title Case** for headings and page titles\n- Use **Sentence case** for body text, buttons, and labels\n\n### Punctuation\n\n- **No exclamation marks** in UI text (exception: celebratory moments)\n- **No periods** in short UI labels or button text\n- **Use periods** in complete sentences and help text\n- **No ALL CAPS** except for acronyms (API, SDK, URL)\n\n### Word Choices\n\n| Avoid | Prefer |\n|-------|--------|\n| Please | (omit) |\n| Sorry | (be specific about the problem) |\n| Error occurred | Something went wrong |\n| Invalid | (explain what''s wrong) |\n| Success! | (describe what happened) |\n| Oops | (be specific) |\n\n## Dash Usage\n\n| Type | Use | Example |\n|------|-----|---------|\n| Hyphen (-) | Compound words, ranges | \"real-time\", \"1-10\" |\n| En-dash (--) | Ranges, relationships | \"2023--2024\", \"parent--child\" |\n| Em-dash (---) | Interruption, emphasis | \"Errors---even small ones---matter\" |\n\nIn most UI contexts, use hyphens. Reserve en-dashes for date ranges and em-dashes for longer prose.\n\n## UI Element Guidelines\n\n### Buttons\n\n- Use action verbs: \"Save\", \"Delete\", \"Create\"\n- Be specific: \"Create Project\" not just \"Create\"\n- Max 2-3 words when possible\n- No periods or exclamation marks\n\n### Error Messages\n\n1. Say what happened\n2. Say why (if helpful)\n3. Say what to do next\n\n**Good:** \"Could not save changes. Check your connection and try again.\"\n**Bad:** \"Error: Save failed.\"\n\n### Empty States\n\n1. Explain what would normally be here\n2. Provide a clear action to populate the state\n3. Sentry Voice is appropriate here\n\n**Good:** \"No projects yet. Create your first project to start tracking errors.\"\n\n### Confirmation Dialogs\n\n- Make the action clear in the title\n- Explain consequences if destructive\n- Use specific button labels (\"Delete Project\", not \"OK\")\n\n### Tooltips and Help Text\n\n- Keep under 2 sentences\n- Explain the \"why\", not just the \"what\"\n- Link to docs for complex topics\n\n## Anti-Patterns\n\nAvoid these common mistakes:\n\n- **Robot speak:** \"Item has been successfully deleted\" -> \"Deleted\"\n- **Passive voice:** \"Changes were saved\" -> \"Changes saved\"\n- **Unnecessary words:** \"In order to\" -> \"To\"\n- **Hedging:** \"This might cause...\" -> \"This will cause...\"\n- **Double negatives:** \"Not unlike...\" -> \"Similar to...\"\n- **Marketing speak in UI:** \"Supercharge your workflow\" -> \"Speed up your workflow\"\n\n## References\n\n- [Sentry Voice Guidelines](https://develop.sentry.dev/frontend/sentry-voice/)\n- [Sentry Frontend Handbook](https://develop.sentry.dev/frontend/)\n"},"category":"official","lastSynced":"2026-03-06T04:57:19.082Z","seo":{"title":{"en":"Brand-Guidelines: UI Text Generation Setup Guide | AI Age...","zh":"Sentry 品牌指南设置指南 - AIエージェント","ja":"Sentry ブランドガイドラインの設定方法 - AIエージェント","ko":"Sentry 브랜드 가이드라인 설정 가이드 - AI 에이전트","es":"Guía de configuración de pautas de marca con herramientas...","fr":"Guide de mise en place des directives de marque avec les ...","de":"Einrichtungsleitfaden für Markenrichtlinien mit KI-Tools","pt":"Guia de Configuração de Diretrizes de Marca para Sentry","ru":"Руководство по настройке руководств по бренду Sentry для ...","ar":"دليل إعداد إرشادات العلامة التجارية Sentry للعمليات الروب..."},"description":{"en":"Discover how to write user-facing copy with Sentry''s brand guidelines. Learn tone selection and implementation for 404 pages, onboarding flows, and more. Get...","zh":"了解 Sentry 品牌指南的技术细节，包括 Plain Speech 和 Sentry Voice 的语气选择，用于 UI 文本、错误消息和文档等","ja":"Sentry ブランドガイドラインの技術的な詳細を学び、Plain Speech と Sentry Voice のトーン選択を UI テキスト、エラーメッセージ、ドキュメントなどに適用する","ko":"Sentry 브랜드 가이드라인의 기술적인 세부 정보를 알아보고 Plain Speech와 Sentry Voice의 톤 선택을 UI 텍스트, 에러 메시지, 문서 등에 적용하는 방법","es":"Aprende a escribir copias siguiendo las pautas de marca de Sentry con nuestra herramienta de AI. Descubre cómo aplicar tonos de voz en UI, errores y document...","fr":"Découvrez comment écrire des copies conformes aux directives de marque de Sentry avec notre outil d''IA. Apprenez à appliquer les tons de voix dans l''UI, les ...","de":"Erfahren Sie, wie Sie mit unserem KI-Tool Kopien gemäß den Markenrichtlinien von Sentry schreiben. Entdecken Sie, wie Sie Sprachtonen in der Benutzeroberfläc...","pt":"Aprenda a escrever cópias seguindo as diretrizes de marca Sentry para UI, erros, fluxos de entrada e mais","ru":"Узнайте, как писать копии в соответствии с руководствами по бренду Sentry для пользовательского интерфейса, ошибок, потоков входа и многое другое","ar":"تعلم كيفية كتابة النسخ اتباعاً لإرشادات العلامة التجارية Sentry للواجهة المستخدمة وأخطاء و-operational والكثير غيرها"},"definition":{"en":"Brand-guidelines is a set of rules for writing user-facing copy, including tone selection and implementation for product UI, documentation, and marketing copy.","zh":"Sentry 品牌指南是用于撰写用户界面文本、错误消息和文档等的品牌指南","ja":"Sentry ブランドガイドラインは、ユーザーインターフェイステキスト、エラーメッセージ、ドキュメントなどの作成に使用されるブランドガイドライン","ko":"Sentry 브랜드 가이드라인은 사용자 인터페이스 텍스트, 에러 메시지, 문서 등의 작성에 사용되는 브랜드 가이드라인","es":"Las pautas de marca son un conjunto de reglas para escribir copias coherentes con la identidad de la marca","fr":"Les directives de marque sont un ensemble de règles pour écrire des copies cohérentes avec l''identité de la marque","de":"Die Markenrichtlinien sind ein Satz von Regeln für das Schreiben von Kopien, die mit der Markenidentität übereinstimmen","pt":"As diretrizes de marca Sentry são um conjunto de regras para escrever cópias de marca","ru":"Руководства по бренду Sentry - это набор правил для написания копий бренда","ar":"إرشادات العلامة التجارية Sentry هي مجموعة من القواعد لكتابة نسخ العلامة التجارية"},"features":{"en":["Generates UI text following Sentry''s brand guidelines","Supports tone selection for Plain Speech and Sentry Voice","Covers various contexts, including 404 pages and onboarding flows","Provides guidance for documentation and marketing copy","Default tone set to Plain Speech for product UI and settings pages"],"zh":["Plain Speech 和 Sentry Voice 两种语气选择","用于 UI 文本、错误消息和文档等","支持不同上下文的语气选择","提供默认的 Plain Speech 语气","用于 404 页面、空状态、引导流程和加载状态等"],"ja":["Plain Speech と Sentry Voice の 2 つのトーンを選択","UI テキスト、エラーメッセージ、ドキュメントなどの作成に使用","異なるコンテキストに応じたトーン選択をサポート","デフォルトの Plain Speech トーンを提供","404 ページ、空の状態、ガイドフロー、ローディング状態などの作成に使用"],"ko":["Plain Speech와 Sentry Voice의 2가지 톤 선택","UI 텍스트, 에러 메시지, 문서 등의 작성에 사용","다양한 컨텍스트에 따른 톤 선택 지원","기본 Plain Speech 톤 제공","404 페이지, 빈 상태, 가이드 흐름, 로딩 상태 등의 작성에 사용"],"es":["Aplicación de tonos de voz en UI y documentación","Uso de Plain Speech y Sentry Voice en diferentes contextos","Creación de copias para errores, estados vacíos y flujos de inicio","Personalización de la voz para marketing y anuncios","Compatibilidad con diferentes tipos de contenido de usuario","Integración con la plataforma de Sentry"],"fr":["Application des tons de voix dans l''UI et la documentation","Utilisation de Plain Speech et Sentry Voice dans différents contextes","Création de copies pour les erreurs, les états vides et les flux de démarrage","Personnalisation de la voix pour le marketing et les annonces","Compatibilité avec différents types de contenu utilisateur","Intégration avec la plateforme de Sentry"],"de":["Anwendung von Sprachtonen in der Benutzeroberfläche und Dokumentation","Verwendung von Plain Speech und Sentry Voice in verschiedenen Kontexten","Erstellung von Kopien für Fehler, leere Zustände und Startflüsse","Anpassung der Stimme für Marketing und Ankündigungen","Kompatibilität mit verschiedenen Arten von Benutzerinhalten","Integration mit der Sentry-Plattform"],"pt":["Escreva cópias em Plain Speech e Sentry Voice","Aplique as diretrizes de marca em UI, erros e fluxos de entrada","Use as diretrizes para 404 pages, documentação e marketing","Default para Plain Speech","Suporte para várias linguagens"],"ru":["Пишите копии в Plain Speech и Sentry Voice","Применяйте руководства по бренду в пользовательском интерфейсе, ошибках и потоках входа","Используйте руководства для 404 страниц, документации и маркетинга","По умолчанию используйте Plain Speech","Поддержка нескольких языков"],"ar":["اكتب النسخ بلغة پلين سبش و‌سنتري فويس","طبق إرشادات العلامة التجارية في الواجهة المستخدمة وأخطاء والعمليات","استخدم الإرشادات للصفحات 404 والتوثيق والتسويق","افتراضياً استخدم پلين سبش","دعم اللغات المتعددة"]},"keywords":{"en":["how to use brand-guidelines","what is brand-guidelines","brand-guidelines alternative","brand-guidelines vs tone of voice","brand-guidelines install","brand-guidelines setup guide","Sentry brand guidelines","UI text generation","tone selection for UI text"],"zh":["Sentry 品牌指南","AIエージェント","Plain Speech","Sentry Voice","UI 文本","错误消息","文档","品牌指南","语气选择"],"ja":["Sentry ブランドガイドライン","AIエージェント","Plain Speech","Sentry Voice","UI テキスト","エラーメッセージ","ドキュメント","ブランドガイドライン","トーン選択"],"ko":["Sentry 브랜드 가이드라인","AI 에이전트","Plain Speech","Sentry Voice","UI 텍스트","에러 메시지","문서","브랜드 가이드라인","톤 선택"],"es":["pautas de marca","herramientas de AI","tonos de voz","Plain Speech","Sentry Voice","UI","documentación","errores","estados vacíos","flujos de inicio","marketing","anuncios"],"fr":["directives de marque","outils d''IA","tons de voix","Plain Speech","Sentry Voice","UI","documentation","erreurs","états vides","flux de démarrage","marketing","annonces"],"de":["Markenrichtlinien","KI-Tools","Sprachtonen","Plain Speech","Sentry Voice","Benutzeroberfläche","Dokumentation","Fehler","leere Zustände","Startflüsse","Marketing","Ankündigungen"],"pt":["diretrizes de marca Sentry"," Plain Speech","Sentry Voice","UI text","erros","fluxos de entrada","documentação","marketing","ИИ Агенты","AI Tools"],"ru":["руководства по бренду Sentry","Plain Speech","Sentry Voice","пользовательский интерфейс","ошибки","потоки входа","документация","маркетинг","ИИ Агенты","AI Tools"],"ar":["إرشادات العلامة التجارية Sentry","پلين سبش","سنتري فويس","الواجهة المستخدمة","أخطاء","العمليات","التوثيق","التسويق","العمليات الروبوتية","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Content Generation Agents needing to adhere to Sentry''s brand guidelines for user-facing content.","zh":"适合需要遵循Sentry品牌指南以生成用户面向内容的内容生成代理。","ja":"Sentryのブランドガイドラインに従ってユーザー向けコンテンツを生成する必要があるコンテンツ生成エージェントに適しています。","ko":"Sentry 브랜드 가이드라인을 따라 사용자용 콘텐츠를 생성해야 하는 콘텐츠 생성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Generación de Contenido que necesitan adherirse a las pautas de marca de Sentry para contenido orientado al usuario.","fr":"Parfait pour les Agents de Génération de Contenu qui doivent suivre les directives de marque de Sentry pour le contenu orienté vers l''utilisateur.","de":"Perfekt für Inhalts-Generierungsagenten, die den Markenrichtlinien von Sentry für benutzerorientierte Inhalte entsprechen müssen.","pt":"Perfeito para Agentes de Geração de Conteúdo que precisam aderir às diretrizes de marca da Sentry para conteúdo voltado ao usuário.","ru":"Идеально подходит для агентов по генерации контента, которым необходимо соблюдать руководящие принципы бренда Sentry для пользовательского контента.","ar":"مثالي لعميل توليد المحتوى الذين بحاجة إلى الالتزام بإرشادات العلامة التجارية لشركة Sentry لمحتوى موجه للمستخدمين."},"recommendation":{"en":"Empowers agents to craft high-quality, tone-specific copy using Plain Speech and Sentry Voice tones, ensuring consistency across UI text, error messages, and marketing materials, leveraging context-based tone selection and Sentry''s brand guidelines.","zh":"赋予代理使用Plain Speech和Sentry Voice语调生成高质量、语调特定的副本的能力，确保在UI文本、错误消息和营销材料中保持一致性，利用基于上下文的语调选择和Sentry的品牌指南。","ja":"Plain SpeechとSentry Voiceのトーンを使用して、高品質でトーンに特化したコピーを生成するエージェントの能力を提供し、UIテキスト、エラーメッセージ、マーケティング資料を通して一貫性を保ち、コンテキストベースのトーン選択とSentryのブランドガイドラインを活用します。","ko":"Plain Speech와 Sentry Voice의 음색을 사용하여 높은 품질의 음색 특정 복사를 생성할 수 있는 에이전트의 능력을 제공하고, UI 텍스트, 오류 메시지, 마케팅 자료를 통해 일관성을 유지하고, 문脈 기반 음색 선택과 Sentry의 브랜드 가이드라인을 활용합니다.","es":"Habilita a los agentes a crear copias de alta calidad y específicas de tono utilizando Plain Speech y tonos de voz de Sentry, garantizando la consistencia en texto de interfaz de usuario, mensajes de error y materiales de marketing, aprovechando la selección de tono basada en el contexto y las pautas de marca de Sentry.","fr":"Permet aux agents de créer des copies de haute qualité et spécifiques au ton en utilisant Plain Speech et les tons de voix de Sentry, garantissant la cohérence dans le texte de l''interface utilisateur, les messages d''erreur et les supports marketing, en exploitant la sélection de ton basée sur le contexte et les directives de marque de Sentry.","de":"Ermöglicht es Agenten, hochwertige, tonspezifische Kopien mithilfe von Plain Speech und Sentry-Sprachtonen zu erstellen, wodurch die Konsistenz über Benutzeroberflächentext, Fehlermeldungen und Marketingmaterialien hinweg gewährleistet wird, indem die kontextbasierte Tonwahl und die Markenrichtlinien von Sentry genutzt werden.","pt":"Habilita os agentes a criar cópias de alta qualidade e específicas de tom, utilizando Plain Speech e tons de voz da Sentry, garantindo a consistência em todo o texto da interface do usuário, mensagens de erro e materiais de marketing, aproveitando a seleção de tom baseada no contexto e as diretrizes de marca da Sentry.","ru":"Наделяет агентов возможностью создавать высококачественные, тоном конкретные копии, используя Plain Speech и тона голоса Sentry, обеспечивая согласованность во всем тексте интерфейса пользователя, сообщениях об ошибках и материалах маркетинга, используя контекстную выбор тона и руководящие принципы бренда Sentry.","ar":"تمكّن الوكيل من إنشاء نسخ ذات جودة عالية وملائمة للنبرة، باستخدام كلام بسيط وأصوات صوت شركة Sentry، مما يضمن الاتساق في جميع نصات واجهة المستخدم ورسائل الخطأ والمواد التسويقية، مستفيداً من اختيار النبرة المستندة إلى السياق وإرشادات العلامة التجارية لشركة Sentry."},"useCases":{"en":["Generating error messages with Plain Speech tone","Crafting onboarding flows with Sentry Voice tone","Creating 404 pages that align with brand guidelines"],"zh":["使用Plain Speech语调生成错误消息","使用Sentry Voice语调创建入门流程","创建与品牌指南一致的404页面"],"ja":["Plain Speechのトーンを使用してエラーメッセージを生成する","Sentry Voiceのトーンを使用してオンボーディングフローを作成する","ブランドガイドラインに沿った404ページを作成する"],"ko":["Plain Speech의 음색을 사용하여 오류 메시지를 생성하는 것","Sentry Voice의 음색을 사용하여 온보딩 흐름을 만들기","브랜드 가이드라인과 일치하는 404 페이지를 생성하는 것"],"es":["Generación de mensajes de error con tono Plain Speech","Creación de flujos de incorporación con tono de voz de Sentry","Creación de páginas 404 que se alinean con las pautas de marca"],"fr":["Génération de messages d''erreur avec ton Plain Speech","Création de flux d''intégration avec ton de voix de Sentry","Création de pages 404 qui s''alignent sur les directives de marque"],"de":["Generierung von Fehlermeldungen mit Plain-Speech-Ton","Erstellung von Onboarding-Flows mit Sentry-Sprachton","Erstellung von 404-Seiten, die mit den Markenrichtlinien übereinstimmen"],"pt":["Gerar mensagens de erro com tom de Plain Speech","Criar fluxos de integração com tom de voz da Sentry","Criar páginas 404 que estejam alinhadas com as diretrizes de marca"],"ru":["Генерировать сообщения об ошибках с тоном Plain Speech","Создавать потоки настройки с тоном голоса Sentry","Создавать страницы 404, соответствующие руководящим принципам бренда"],"ar":["توليد رسائل الأخطاء بنبرة الكلام البسيط","إنشاء تدفقات التهيئة بنبرة صوت شركة Sentry","إنشاء صفحات 404 التي تتوافق مع إرشادات العلامة التجارية"]},"limitations":{"en":["Requires understanding of Sentry''s brand guidelines and tone selection","Limited to generating copy for user-facing content"],"zh":["需要了解Sentry的品牌指南和语调选择","仅限于生成用户面向内容的副本"],"ja":["Sentryのブランドガイドラインとトーン選択を理解する必要がある","ユーザー向けコンテンツのコピー生成に限定される"],"ko":["Sentry의 브랜드 가이드라인과 음색 선택을 이해해야 함","사용자용 콘텐츠의 복사 생성에만 제한됨"],"es":["Requiere comprensión de las pautas de marca de Sentry y la selección de tono","Limitado a la generación de copias para contenido orientado al usuario"],"fr":["Nécessite une compréhension des directives de marque de Sentry et de la sélection de ton","Limité à la génération de copies pour le contenu orienté vers l''utilisateur"],"de":["Erfordert das Verständnis der Markenrichtlinien von Sentry und der Tonwahl","Begrenzt auf die Generierung von Kopien für benutzerorientierte Inhalte"],"pt":["Exige compreensão das diretrizes de marca da Sentry e seleção de tom","Limitado à geração de cópias para conteúdo voltado ao usuário"],"ru":["Требует понимания руководящих принципов бренда Sentry и выбора тона","Ограничен генерацией копий для пользовательского контента"],"ar":["يتطلب فهم إرشادات العلامة التجارية لشركة Sentry واختيار النبرة","محدود بمحتوى موجه للمستخدمين"]},"version":4},"contentHash":"59c75b089fc355f34862172222344801d267ea8158d1bcddb9d1338ba8e9bc39","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":82}');
