INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/brand-guidelines', 'brand-guidelines', 'getsentry', 'skills', 'official', 'brand-guidelines getsentry skills official tag-production The brand-guidelines skill generates UI text following Sentry''s brand guidelines, benefiting developers and content creators. It covers tone selection for various contexts, including Plain Speech and Sentry Voice. Sentry 品牌指南提供了 Plain Speech 和 Sentry Voice 两种语气选择，用于不同上下文的 UI 文本、错误消息和文档等 Sentry ブランドガイドラインでは、Plain Speech と Sentry Voice の 2 つのトーンを提供し、UI テキスト、エラーメッセージ、ドキュメントなどの異なるコンテキストに適用できる Sentry 브랜드 가이드라인은 Plain Speech와 Sentry Voice의 2가지 톤을 제공하며 UI 텍스트, 에러 메시지, 문서 등의 다양한 컨텍스트에 적용할 수 있다 Escribe copias siguiendo las pautas de marca de Sentry con nuestra herramienta de AI. Aprende a aplicar tonos de voz en diferentes contextos Écrivez des copies conformes aux directives de marque de Sentry avec notre outil d''IA. Apprenez à appliquer les tons de voix dans différents contextes Schreiben Sie Kopien gemäß den Markenrichtlinien von Sentry mit unserem KI-Tool. Erfahren Sie, wie Sie Sprachtonen in verschiedenen Kontexten anwenden Escreva cópias seguindo as diretrizes de marca Sentry para UI, erros e fluxos de entrada Пишите копии в соответствии с руководствами по бренду Sentry для пользовательского интерфейса, ошибок и потоков входа اكتب النسخ اتباعاً لإرشادات العلامة التجارية Sentry للواجهة المستخدمة وأخطاء والعمليات how to use brand-guidelines what is brand-guidelines brand-guidelines alternative brand-guidelines vs tone of voice brand-guidelines install brand-guidelines setup guide Sentry brand guidelines UI text generation tone selection for UI text Sentry 品牌指南 AIエージェント Plain Speech Sentry Voice UI 文本 错误消息 文档 品牌指南 语气选择 Generates UI text following Sentry''s brand guidelines Supports tone selection for Plain Speech and Sentry Voice Covers various contexts, including 404 pages and onboarding flows Provides guidance for documentation and marketing copy Default tone set to Plain Speech for product UI and settings pages Brand-guidelines is a set of rules for writing user-facing copy, including tone selection and implementation for product UI, documentation, and marketing copy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/e2e-testing', 'community', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'e2e-testing', 55501, 6825, 80, '2026-03-01T12:42:49Z', '2026-03-07T01:50:10.060Z', 'f84ae93c159bf6ecef5a60c9735dc82d96bc5f977ef52eb71678b66722acf684', '{"id":"affaan-m/everything-claude-code/e2e-testing","name":"e2e-testing","description":{"en":"The e2e-testing skill enables developers to create comprehensive and maintainable E2E test suites using Playwright patterns, benefiting AI agent developers and testers.","zh":"使用 Playwright 模式和 Page Object 模式构建稳定、快速和可维护的 E2E 测试套件","ja":"Playwright パターンと Page Object モードを使用して安定した E2E テストスイートを構築します","ko":"Playwright 패턴과 Page Object 모드를 사용하여 안정적이고 빠르고 유지 보수 가능한 E2E 테스트 스위트를 구축합니다","es":"El agente de pruebas E2E ofrece patrones de Playwright para construir suites de pruebas estables y rápidas","fr":"L''agent de tests E2E propose des modèles Playwright pour créer des suites de tests stables et rapides","de":"Der E2E-Testagent bietet Playwright-Muster für den Aufbau stabiler und schneller Test-Suites","pt":"O teste E2E é uma abordagem abrangente para garantir a qualidade dos projetos de desenvolvimento, utilizando padrões de teste do Playwright","ru":"Тестирование E2E - это комплексный подход к обеспечению качества проектов разработки, использующий шаблоны тестирования Playwright для ИИ Агентов","ar":"الاختبار من النهاية إلى النهاية هو نهج شامل لضمان جودة مشاريع التطوير، يستخدم أنماط اختبار Playwright لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"e2e-testing: Comprehensive Playwright Patterns Setup Guid...","zh":"E2E 测试最佳实践指南","ja":"E2E テストの設定ガイド - AIエージェント","ko":"E2E 테스트 설정 방법 - AI 에이전트","es":"Guía de configuración para pruebas E2E con Playwright","fr":"Guide de mise en place des tests E2E avec Playwright","de":"Einrichtungsleitfaden für E2E-Tests mit Playwright","pt":"Guia de Configuração de Testes E2E com Playwright","ru":"Настройка тестирования E2E с помощью Playwright для ИИ Аг...","ar":"دليل إعداد اختبارات E2E باستخدام Playwright لأدوات الذكاء..."},"description":{"en":"Unlock efficient testing with e2e-testing! Discover how to build stable E2E test suites using Playwright patterns and optimize your development workflow today.","zh":"学习如何使用 Playwright 模式构建稳定、快速和可维护的 E2E 测试套件","ja":"Playwright パターンを使用して安定した E2E テストスイートを構築する方法を学びましょう","ko":"Playwright 패턴을 사용하여 안정적이고 빠르고 유지 보수 가능한 E2E 테스트 스위트를 구축하는 방법을 알아보세요","es":"Aprende a implementar pruebas E2E con Playwright y mejora la estabilidad de tus aplicaciones","fr":"Découvrez comment mettre en place des tests E2E avec Playwright pour améliorer la stabilité de vos applications","de":"Erfahren Sie, wie Sie E2E-Tests mit Playwright implementieren und die Stabilität Ihrer Anwendungen verbessern","pt":"Aprenda a configurar testes E2E eficazes com Playwright para melhorar a estabilidade e velocidade dos seus projetos de desenvolvimento","ru":"Узнайте, как настроить эффективное тестирование E2E с помощью Playwright для улучшения стабильности и скорости ваших проектов разработки с ИИ Агентами","ar":"تعلم كيفية إعداد اختبارات E2E فعالة باستخدام Playwright لتحسين الاستقرار والسرعة لمشاريع التطوير الخاصة بك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"e2e-testing is a set of comprehensive Playwright patterns for building stable, fast, and maintainable end-to-end test suites.","zh":"E2E 测试是一种端到端的测试方法，使用 Playwright 模式确保应用程序的稳定性和性能","ja":"E2E テストは、Playwright パターンを使用してアプリケーションの安定性とパフォーマンスを保証するエンドツーエンドのテスト方法です","ko":"E2E 테스트는 Playwright 패턴을 사용하여 애플리케이션의 안정성과 성능을 보장하는 종단 간 테스트 방법입니다","es":"Las pruebas E2E son un tipo de prueba que verifica la funcionalidad de una aplicación desde el inicio hasta el final","fr":"Les tests E2E sont un type de test qui vérifie la fonctionnalité d''une application desde le début jusqu''à la fin","de":"E2E-Tests sind eine Art von Test, die die Funktionalität einer Anwendung von Anfang bis Ende überprüft","pt":"Teste E2E é uma técnica de teste que verifica a funcionalidade de um sistema desde a interface do usuário até a base de dados","ru":"Тестирование E2E - это техника тестирования, которая проверяет функциональность системы от интерфейса пользователя до базы данных для ИИ Агентов","ar":"الاختبار من النهاية إلى النهاية هو تقنية اختبار تحقق من وظيفة النظام من واجهة المستخدم إلى قاعدة البيانات لأدوات الذكاء الاصطناعي"},"features":{"en":["Organizes test files using a structured directory layout (e.g., tests/e2e/auth, tests/e2e/features)","Supports Page Object Mode for efficient test development","Includes fixtures for authentication and data management (e.g., auth.ts, data.ts)","Utilizes Playwright configuration files (playwright.config.ts) for customized testing","Enables testing of API endpoints using endpoints.spec.ts","Facilitates testing of features like login, logout, and registration using spec.ts files"],"zh":["使用 Playwright 模式构建稳定和快速的 E2E 测试套件","支持 Page Object 模式","测试文件组织和配置","fixtures 和数据管理","Playwright 配置文件管理"],"ja":["Playwright パターンを使用して安定した E2E テストスイートを構築","Page Object モードをサポート","テストファイルの組織化と設定","fixtures とデータ管理","Playwright 構成ファイルの管理"],"ko":["Playwright 패턴을 사용하여 안정적이고 빠른 E2E 테스트 스위트를 구축","Page Object 모드를 지원","테스트 파일의 구성과 설정","fixtures와 데이터 관리","Playwright 구성 파일 관리"],"es":["Patrones de Playwright para pruebas E2E","Organización de archivos de prueba con tests/e2e","Compatibilidad con Page Object Model","Soporte para fixtures y datos de prueba","Configuración de Playwright con playwright.config.ts","Pruebas de autenticación y autorización"],"fr":["Modèles Playwright pour les tests E2E","Organisation des fichiers de test avec tests/e2e","Compatibilité avec le modèle Page Object","Prise en charge des fixtures et des données de test","Configuration de Playwright avec playwright.config.ts","Tests d''authentification et d''autorisation"],"de":["Playwright-Muster für E2E-Tests","Dateiorganisation mit tests/e2e","Unterstützung für Page Object Model","Einbindung von Fixtures und Testdaten","Konfiguration von Playwright mit playwright.config.ts","Authentifizierungs- und Autorisierungstests"],"pt":["Padrões de teste do Playwright para construir conjuntos de testes estáveis e rápidos","Organização de arquivos de teste com pastas e subpastas","Utilização de Page Object Model para simplificar a escrita de testes","Suporte a fixtures e dados de teste","Integração com o Claude Code e outras ferramentas de desenvolvimento"],"ru":["Шаблоны тестирования Playwright для построения стабильных и быстрых наборов тестов для ИИ Агентов","Организация файлов тестирования с папками и подпапками","Использование модели объекта страницы для упрощения написания тестов","Поддержка фикстур и данных тестирования","Интеграция с Claude Code и другими инструментами разработки"],"ar":["أنماط اختبار Playwright لإنشاء مجموعات اختبار مستقرة وسريعة لأدوات الذكاء الاصطناعي","تنظيم ملفات الاختبار مع المجلدات والفرعي","استخدام نموذج كائن الصفحة لتسهيل كتابة الاختبارات","دعم الإصطبات والبيانات الاختبارية","التكامل مع Claude Code وأدوات التطوير الأخرى"]},"keywords":{"en":["e2e-testing setup guide","Playwright patterns for E2E testing","how to use e2e-testing","e2e-testing vs Cypress","e2e-testing install","what is e2e-testing","e2e-testing alternative","e2e-testing for AI agents","Comprehensive E2E testing with Playwright"],"zh":["E2E 测试","Playwright","Page Object","测试自动化","AIエージェント"," Claude Code","Codex","Cowork"],"ja":["E2E テスト","Playwright","Page Object","テスト自動化","AIエージェント"," Claude Code","Codex","Cowork"],"ko":["E2E 테스트","Playwright","Page Object","테스트 자동화","AI 에이전트"," Claude Code","Codex","Cowork"],"es":["pruebas E2E","Playwright","tests automatizados","desarrollo de software","agente de pruebas","patrones de prueba","Page Object Model","fixtures","datos de prueba","configuración de Playwright"],"fr":["tests E2E","Playwright","tests automatisés","développement de logiciels","agent de tests","modèles de test","Page Object Model","fixtures","données de test","configuration de Playwright"],"de":["E2E-Tests","Playwright","automatisierte Tests","Software-Entwicklung","Testagent","Testmuster","Page Object Model","Fixtures","Testdaten","Playwright-Konfiguration"],"pt":["teste e2e","playwright","desenvolvimento de software","testes automatizados","claude code","ferramentas de desenvolvimento","ai agents","teste de sistema","qualidade de software"],"ru":["тестирование e2e","playwright","разработка программного обеспечения","автоматизированное тестирование","claude code","инструменты разработки","ии агенты","тестирование системы","качество программного обеспечения"],"ar":["اختبار من النهاية إلى النهاية","playwright","تطوير البرمجيات","اختبارات آلية","claude code","أدوات التطوير","أدوات الذكاء الاصطناعي","اختبار النظام","جودة البرمجيات"]}},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":55501,"forks":6825,"updatedAt":"2026-03-01T12:42:49Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"category":"community","skillMd":{"name":"e2e-testing","description":"Playwright E2E testing patterns, Page Object Model, configuration, CI/CD integration, artifact management, and flaky test strategies.","bodyPreview":"# E2E Testing Patterns\n\nComprehensive Playwright patterns for building stable, fast, and maintainable E2E test suites.\n\n## Test File Organization\n\n```\ntests/\n├── e2e/\n│   ├── auth/\n│   │   ├── login.spec.ts\n│   │   ├── logout.spec.ts\n│   │   └── register.spec.ts\n│   ├── features/\n│   │   ├── browse.spec.ts\n│   │   ├── search.spec.ts\n│   │   └── create.spec.ts\n│   └── api/\n│       └── endpoints.spec.ts\n├── fixtures/\n│   ├── auth.ts\n│   └── data.ts\n└── playwright.config.ts\n```\n\n## Page Object Mode","body":"# E2E Testing Patterns\n\nComprehensive Playwright patterns for building stable, fast, and maintainable E2E test suites.\n\n## Test File Organization\n\n```\ntests/\n├── e2e/\n│   ├── auth/\n│   │   ├── login.spec.ts\n│   │   ├── logout.spec.ts\n│   │   └── register.spec.ts\n│   ├── features/\n│   │   ├── browse.spec.ts\n│   │   ├── search.spec.ts\n│   │   └── create.spec.ts\n│   └── api/\n│       └── endpoints.spec.ts\n├── fixtures/\n│   ├── auth.ts\n│   └── data.ts\n└── playwright.config.ts\n```\n\n## Page Object Model (POM)\n\n```typescript\nimport { Page, Locator } from ''@playwright/test''\n\nexport class ItemsPage {\n  readonly page: Page\n  readonly searchInput: Locator\n  readonly itemCards: Locator\n  readonly createButton: Locator\n\n  constructor(page: Page) {\n    this.page = page\n    this.searchInput = page.locator(''[data-testid=\"search-input\"]'')\n    this.itemCards = page.locator(''[data-testid=\"item-card\"]'')\n    this.createButton = page.locator(''[data-testid=\"create-btn\"]'')\n  }\n\n  async goto() {\n    await this.page.goto(''/items'')\n    await this.page.waitForLoadState(''networkidle'')\n  }\n\n  async search(query: string) {\n    await this.searchInput.fill(query)\n    await this.page.waitForResponse(resp => resp.url().includes(''/api/search''))\n    await this.page.waitForLoadState(''networkidle'')\n  }\n\n  async getItemCount() {\n    return await this.itemCards.count()\n  }\n}\n```\n\n## Test Structure\n\n```typescript\nimport { test, expect } from ''@playwright/test''\nimport { ItemsPage } from ''../../pages/ItemsPage''\n\ntest.describe(''Item Search'', () => {\n  let itemsPage: ItemsPage\n\n  test.beforeEach(async ({ page }) => {\n    itemsPage = new ItemsPage(page)\n    await itemsPage.goto()\n  })\n\n  test(''should search by keyword'', async ({ page }) => {\n    await itemsPage.search(''test'')\n\n    const count = await itemsPage.getItemCount()\n    expect(count).toBeGreaterThan(0)\n\n    await expect(itemsPage.itemCards.first()).toContainText(/test/i)\n    await page.screenshot({ path: ''artifacts/search-results.png'' })\n  })\n\n  test(''should handle no results'', async ({ page }) => {\n    await itemsPage.search(''xyznonexistent123'')\n\n    await expect(page.locator(''[data-testid=\"no-results\"]'')).toBeVisible()\n    expect(await itemsPage.getItemCount()).toBe(0)\n  })\n})\n```\n\n## Playwright Configuration\n\n```typescript\nimport { defineConfig, devices } from ''@playwright/test''\n\nexport default defineConfig({\n  testDir: ''./tests/e2e'',\n  fullyParallel: true,\n  forbidOnly: !!process.env.CI,\n  retries: process.env.CI ? 2 : 0,\n  workers: process.env.CI ? 1 : undefined,\n  reporter: [\n    [''html'', { outputFolder: ''playwright-report'' }],\n    [''junit'', { outputFile: ''playwright-results.xml'' }],\n    [''json'', { outputFile: ''playwright-results.json'' }]\n  ],\n  use: {\n    baseURL: process.env.BASE_URL || ''http://localhost:3000'',\n    trace: ''on-first-retry'',\n    screenshot: ''only-on-failure'',\n    video: ''retain-on-failure'',\n    actionTimeout: 10000,\n    navigationTimeout: 30000,\n  },\n  projects: [\n    { name: ''chromium'', use: { ...devices[''Desktop Chrome''] } },\n    { name: ''firefox'', use: { ...devices[''Desktop Firefox''] } },\n    { name: ''webkit'', use: { ...devices[''Desktop Safari''] } },\n    { name: ''mobile-chrome'', use: { ...devices[''Pixel 5''] } },\n  ],\n  webServer: {\n    command: ''npm run dev'',\n    url: ''http://localhost:3000'',\n    reuseExistingServer: !process.env.CI,\n    timeout: 120000,\n  },\n})\n```\n\n## Flaky Test Patterns\n\n### Quarantine\n\n```typescript\ntest(''flaky: complex search'', async ({ page }) => {\n  test.fixme(true, ''Flaky - Issue #123'')\n  // test code...\n})\n\ntest(''conditional skip'', async ({ page }) => {\n  test.skip(process.env.CI, ''Flaky in CI - Issue #123'')\n  // test code...\n})\n```\n\n### Identify Flakiness\n\n```bash\nnpx playwright test tests/search.spec.ts --repeat-each=10\nnpx playwright test tests/search.spec.ts --retries=3\n```\n\n### Common Causes & Fixes\n\n**Race conditions:**\n```typescript\n// Bad: assumes element is ready\nawait page.click(''[data-testid=\"button\"]'')\n\n// Good: auto-wait locator\nawait page.locator(''[data-testid=\"button\"]'').click()\n```\n\n**Network timing:**\n```typescript\n// Bad: arbitrary timeout\nawait page.waitForTimeout(5000)\n\n// Good: wait for specific condition\nawait page.waitForResponse(resp => resp.url().includes(''/api/data''))\n```\n\n**Animation timing:**\n```typescript\n// Bad: click during animation\nawait page.click(''[data-testid=\"menu-item\"]'')\n\n// Good: wait for stability\nawait page.locator(''[data-testid=\"menu-item\"]'').waitFor({ state: ''visible'' })\nawait page.waitForLoadState(''networkidle'')\nawait page.locator(''[data-testid=\"menu-item\"]'').click()\n```\n\n## Artifact Management\n\n### Screenshots\n\n```typescript\nawait page.screenshot({ path: ''artifacts/after-login.png'' })\nawait page.screenshot({ path: ''artifacts/full-page.png'', fullPage: true })\nawait page.locator(''[data-testid=\"chart\"]'').screenshot({ path: ''artifacts/chart.png'' })\n```\n\n### Traces\n\n```typescript\nawait browser.startTracing(page, {\n  path: ''artifacts/trace.json'',\n  screenshots: true,\n  snapshots: true,\n})\n// ... test actions ...\nawait browser.stopTracing()\n```\n\n### Video\n\n```typescript\n// In playwright.config.ts\nuse: {\n  video: ''retain-on-failure'',\n  videosPath: ''artifacts/videos/''\n}\n```\n\n## CI/CD Integration\n\n```yaml\n# .github/workflows/e2e.yml\nname: E2E Tests\non: [push, pull_request]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm ci\n      - run: npx playwright install --with-deps\n      - run: npx playwright test\n        env:\n          BASE_URL: ${{ vars.STAGING_URL }}\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: playwright-report\n          path: playwright-report/\n          retention-days: 30\n```\n\n## Test Report Template\n\n```markdown\n# E2E Test Report\n\n**Date:** YYYY-MM-DD HH:MM\n**Duration:** Xm Ys\n**Status:** PASSING / FAILING\n\n## Summary\n- Total: X | Passed: Y (Z%) | Failed: A | Flaky: B | Skipped: C\n\n## Failed Tests\n\n### test-name\n**File:** `tests/e2e/feature.spec.ts:45`\n**Error:** Expected element to be visible\n**Screenshot:** artifacts/failed.png\n**Recommended Fix:** [description]\n\n## Artifacts\n- HTML Report: playwright-report/index.html\n- Screenshots: artifacts/*.png\n- Videos: artifacts/videos/*.webm\n- Traces: artifacts/*.zip\n```\n\n## Wallet / Web3 Testing\n\n```typescript\ntest(''wallet connection'', async ({ page, context }) => {\n  // Mock wallet provider\n  await context.addInitScript(() => {\n    window.ethereum = {\n      isMetaMask: true,\n      request: async ({ method }) => {\n        if (method === ''eth_requestAccounts'')\n          return [''0x1234567890123456789012345678901234567890'']\n        if (method === ''eth_chainId'') return ''0x1''\n      }\n    }\n  })\n\n  await page.goto(''/'')\n  await page.locator(''[data-testid=\"connect-wallet\"]'').click()\n  await expect(page.locator(''[data-testid=\"wallet-address\"]'')).toContainText(''0x1234'')\n})\n```\n\n## Financial / Critical Flow Testing\n\n```typescript\ntest(''trade execution'', async ({ page }) => {\n  // Skip on production — real money\n  test.skip(process.env.NODE_ENV === ''production'', ''Skip on production'')\n\n  await page.goto(''/markets/test-market'')\n  await page.locator(''[data-testid=\"position-yes\"]'').click()\n  await page.locator(''[data-testid=\"trade-amount\"]'').fill(''1.0'')\n\n  // Verify preview\n  const preview = page.locator(''[data-testid=\"trade-preview\"]'')\n  await expect(preview).toContainText(''1.0'')\n\n  // Confirm and wait for blockchain\n  await page.locator(''[data-testid=\"confirm-trade\"]'').click()\n  await page.waitForResponse(\n    resp => resp.url().includes(''/api/trade'') && resp.status() === 200,\n    { timeout: 30000 }\n  )\n\n  await expect(page.locator(''[data-testid=\"trade-success\"]'')).toBeVisible()\n})\n```\n"},"lastSynced":"2026-03-07T01:50:10.060Z","agentAnalysis":{"suitability":{"en":"Perfect for Automated Testing Agents needing comprehensive end-to-end testing capabilities with Playwright patterns.","zh":"适合需要使用Playwright模式进行全面端到端测试的自动化测试代理。","ja":"Playwrightパターンを使用した包括的なエンドツーエンドテスト機能を必要とする自動テストエージェントに最適です。","ko":"Playwright 패턴을 사용한 포괄적인 엔드 투 엔드 테스트 기능이 필요한 자동화 테스트 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Pruebas Automatizadas que necesitan capacidades de prueba de extremo a extremo integrales con patrones de Playwright.","fr":"Parfait pour les agents de test automatisés ayant besoin de capacités de test de bout en bout complètes avec des modèles Playwright.","de":"Perfekt für automatisierte Testagenten, die umfassende End-to-End-Testfunktionen mit Playwright-Mustern benötigen.","pt":"Perfeito para Agentes de Testes Automatizados que precisam de capacidades de teste abrangentes de ponta a ponta com padrões do Playwright.","ru":"Идеально подходит для агентов автоматизированного тестирования, которым требуются всесторонние возможности тестирования от начала до конца с использованием шаблонов Playwright.","ar":"مثالي لعميل اختبار آلي يحتاج إلى إمكانيات اختبار شاملة من النهاية إلى النهاية باستخدام أنماط Playwright."},"recommendation":{"en":"Empowers agents to create stable, fast, and maintainable E2E test suites using Playwright, supporting test file organization and page object models, and enabling the use of TypeScript for test specification and configuration via playwright.config.ts.","zh":"赋予代理创建使用Playwright的稳定、快速、可维护的端到端测试套件的能力，支持测试文件组织和页面对象模型，并通过playwright.config.ts启用使用TypeScript进行测试规范和配置。","ja":"Playwrightを使用して、テストファイルの組織化やページオブジェクトモデルをサポートし、playwright.config.ts経由でTypeScriptを使用したテストの仕様や構成を可能にすることで、エージェントが安定した、高速で、保守可能なエンドツーエンドテストスイートを作成できるようにします。","ko":"Playwright를 사용하여 테스트 파일 조직 및 페이지 객체 모델을 지원하고, playwright.config.ts를 통해 TypeScript를 사용한 테스트 사양 및 구성이 가능하도록 함으로써, 에이전트가 안정적이고 빠르며 유지 보수가 가능한 엔드 투 엔드 테스트套件을 만들 수 있도록 합니다.","es":"Habilita a los agentes a crear conjuntos de pruebas E2E estables, rápidos y mantenibles utilizando Playwright, que admiten la organización de archivos de prueba y modelos de objetos de página, y permiten el uso de TypeScript para la especificación y configuración de pruebas a través de playwright.config.ts.","fr":"Permet aux agents de créer des suites de tests E2E stables, rapides et maintenables en utilisant Playwright, en prenant en charge l''organisation des fichiers de test et les modèles d''objets de page, et en permettant l''utilisation de TypeScript pour la spécification et la configuration des tests via playwright.config.ts.","de":"Ermöglicht es Agenten, stabile, schnelle und wartbare E2E-Test-Suiten mit Playwright zu erstellen, die die Organisation von Testdateien und Seitenobjektmodellen unterstützen und die Verwendung von TypeScript für die Test-Spezifikation und -Konfiguration über playwright.config.ts ermöglichen.","pt":"Habilita os agentes a criar conjuntos de testes de ponta a ponta estáveis, rápidos e mantenedores usando Playwright, com suporte à organização de arquivos de teste e modelos de objetos de página, e permitindo o uso de TypeScript para especificação e configuração de testes via playwright.config.ts.","ru":"Позволяет агентам создавать стабильные, быстрые и поддерживаемые наборы тестов от начала до конца, используя Playwright, поддерживающий организацию тестовых файлов и модели объектов страницы, и позволяющий использовать TypeScript для спецификации и конфигурации тестов через playwright.config.ts.","ar":"يُمكّن الوكيل من إنشاء مجموعات اختبار من النهاية إلى النهاية مستقرة وسريعة وقابلة للصيانة باستخدام Playwright، مع دعم تنظيم ملفات الاختبار ونماذج كائنات الصفحة، وتمكين استخدام TypeScript لتحديد مواصفات الاختبار والتهيئة عبر playwright.config.ts."},"useCases":{"en":["Automating browser interactions for authentication testing","Generating test suites for API endpoint validation","Debugging complex user interface workflows with page object models"],"zh":["用于身份验证测试的浏览器交互自动化","用于API端点验证的测试套件生成","使用页面对象模型调试复杂的用户界面工作流"],"ja":["認証テストのためのブラウザ操作の自動化","APIエンドポイントの検証のためのテストスイートの生成","ページオブジェクトモデルを使用した複雑なユーザーインターフェイスのワークフローのデバッグ"],"ko":["인증 테스트를 위한 브라우저 상호작용 자동화","API 엔드포인트 유효성 검사용 테스트 스위트 생성","페이지 객체 모델을 사용한 복잡한 사용자 인터페이스 워크플로우 디버깅"],"es":["Automatizar las interacciones del navegador para pruebas de autenticación","Generar conjuntos de pruebas para la validación de puntos de conexión de API","Depurar flujos de trabajo de interfaz de usuario complejos con modelos de objetos de página"],"fr":["Automatiser les interactions de navigateur pour les tests d''authentification","Générer des suites de tests pour la validation des points de terminaison d''API","Déboguer des flux de travail d''interface utilisateur complexes avec des modèles d''objets de page"],"de":["Automatisieren von Browser-Interaktionen für Authentifizierungstests","Erstellen von Test-Suiten für die Überprüfung von API-Endpunkten","Fehlersuche in komplexen Benutzeroberflächen-Workflows mit Seitenobjektmodellen"],"pt":["Automatizar interações do navegador para testes de autenticação","Gerar conjuntos de testes para validação de endpoints de API","Depurar fluxos de trabalho de interface do usuário complexos com modelos de objetos de página"],"ru":["Автоматизировать взаимодействия браузера для тестирования аутентификации","Генерировать наборы тестов для валидации конечных точек API","Отлаживать сложные рабочие процессы пользовательского интерфейса с помощью моделей объектов страницы"],"ar":["توسيعโตيلات المتصفح لأجل اختبار المصادقة","توليد مجموعات اختبار للتحقق من نقاط النهاية API","تصحيح اخطاء في سلاسل عمل واجهة المستخدم المعقدة باستخدام نماذج كائنات الصفحة"]},"limitations":{"en":["Requires Playwright installation and configuration","TypeScript knowledge for test specification and configuration"],"zh":["需要Playwright的安装和配置","需要TypeScript知识用于测试规范和配置"],"ja":["Playwrightのインストールと設定が必要","テストの仕様や構成にTypeScriptの知識が必要"],"ko":["Playwright의 설치 및 구성이 필요","테스트 사양 및 구성에 TypeScript 지식이 필요"],"es":["Requiere la instalación y configuración de Playwright","Conocimientos de TypeScript para la especificación y configuración de pruebas"],"fr":["Nécessite l''installation et la configuration de Playwright","Connaissances de TypeScript pour la spécification et la configuration des tests"],"de":["Erfordert die Installation und Konfiguration von Playwright","TypeScript-Kenntnisse für die Test-Spezifikation und -Konfiguration"],"pt":["Requer instalação e configuração do Playwright","Conhecimento de TypeScript para especificação e configuração de testes"],"ru":["Требуется установка и конфигурация Playwright","Знания TypeScript для спецификации и конфигурации тестов"],"ar":["يتطلب تثبيت Playwright وتهيئته","معرفة TypeScript لتحديد مواصفات الاختبار والتهيئة"]},"version":4},"contentHash":"f84ae93c159bf6ecef5a60c9735dc82d96bc5f977ef52eb71678b66722acf684","qualityScore":80}');
