INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/e2e-testing', 'e2e-testing', 'affaan-m', 'everything-claude-code', 'community', 'e2e-testing affaan-m everything-claude-code community ai-agents anthropic claude claude-code developer-tools llm mcp productivity The e2e-testing skill enables developers to create comprehensive and maintainable E2E test suites using Playwright patterns, benefiting AI agent developers and testers. 使用 Playwright 模式和 Page Object 模式构建稳定、快速和可维护的 E2E 测试套件 Playwright パターンと Page Object モードを使用して安定した E2E テストスイートを構築します Playwright 패턴과 Page Object 모드를 사용하여 안정적이고 빠르고 유지 보수 가능한 E2E 테스트 스위트를 구축합니다 El agente de pruebas E2E ofrece patrones de Playwright para construir suites de pruebas estables y rápidas L''agent de tests E2E propose des modèles Playwright pour créer des suites de tests stables et rapides Der E2E-Testagent bietet Playwright-Muster für den Aufbau stabiler und schneller Test-Suites O teste E2E é uma abordagem abrangente para garantir a qualidade dos projetos de desenvolvimento, utilizando padrões de teste do Playwright Тестирование E2E - это комплексный подход к обеспечению качества проектов разработки, использующий шаблоны тестирования Playwright для ИИ Агентов الاختبار من النهاية إلى النهاية هو نهج شامل لضمان جودة مشاريع التطوير، يستخدم أنماط اختبار Playwright لأدوات الذكاء الاصطناعي e2e-testing setup guide Playwright patterns for E2E testing how to use e2e-testing e2e-testing vs Cypress e2e-testing install what is e2e-testing e2e-testing alternative e2e-testing for AI agents Comprehensive E2E testing with Playwright E2E 测试 Playwright Page Object 测试自动化 AIエージェント Claude Code Codex Cowork Organizes test files using a structured directory layout (e.g., tests/e2e/auth, tests/e2e/features) Supports Page Object Mode for efficient test development Includes fixtures for authentication and data management (e.g., auth.ts, data.ts) Utilizes Playwright configuration files (playwright.config.ts) for customized testing Enables testing of API endpoints using endpoints.spec.ts Facilitates testing of features like login, logout, and registration using spec.ts files e2e-testing is a set of comprehensive Playwright patterns for building stable, fast, and maintainable end-to-end test suites.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/docx', 'official', 'anthropics', 'skills', 'anthropics/skills', 'docx', 85097, 8974, 80, '2026-03-06T03:11:21Z', '2026-03-06T03:16:51.860Z', 'cfbabd72b1aec7dfaad988fb6e5e16b27dc744b9a00cae15db9045e95f53903e', '{"id":"anthropics/skills/docx","name":"docx","description":{"en":"This AI Agent Skill enables developers to programmatically create, read, edit, and analyze Microsoft Word (.docx) documents. It handles tasks like XML manipulation, content extraction with `pandoc`, and generating new files with `docx-js`.","es":"Esta habilidad de AI Agent permite la creación, edición y análisis programático de documentos Word (.docx). Utiliza técnicas como la manipulación directa de XML, la librería docx-js y herramientas CLI como pandoc para automatizar tareas complejas de documentos.","fr":"Cette compétence d''AI Agent permet la création, l''édition et l''analyse programmatique de documents Word (.docx). Elle utilise des techniques comme la manipulation directe de XML, la bibliothèque docx-js et des outils CLI comme pandoc pour automatiser des tâches documentaires complexes.","de":"Diese AI Agent Fähigkeit ermöglicht die programmatische Erstellung, Bearbeitung und Analyse von Word-Dokumenten (.docx). Sie nutzt Techniken wie direkte XML-Manipulation, die docx-js-Bibliothek und CLI-Tools wie pandoc zur Automatisierung komplexer Dokumentenaufgaben.","pt":"Uma habilidade técnica para AI Agents que permite a manipulação programática de documentos Word (.docx). Ela trata o arquivo como um arquivo ZIP contendo XML, permitindo criação, edição e análise de conteúdo com ferramentas como docx-js e pandoc.","ru":"Технический навык для ИИ Агентов, обеспечивающий программную работу с документами Word (.docx). Он рассматривает файл как ZIP-архив с XML, позволяя создавать, редактировать и анализировать контент с помощью инструментов docx-js и pandoc.","ar":"مهارة تقنية لأدوات الذكاء الاصطناعي تتيح المعالجة البرمجية لمستندات Word (.docx). تعامل الملف كأرشيف ZIP يحتوي على XML، مما يتيح إنشاء المحتوى وتحريره وتحليله باستخدام أدوات مثل docx-js وpandoc."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"docx","description":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files). Triggers include: any mention of Word doc, word document, .docx, or requests to produce professional documents with formatting like tables of contents, headings, page numbers, or letterheads. Also use when extracting or reorganizing content from .docx files, inserting or replacing images in documents, performing find-and-replace in Word files, working with tracked changes or comments, or converting content into a polished Word document. If the user asks for a report, memo, letter, template, or similar deliverable as a Word or .docx file, use this skill. Do NOT use for PDFs, spreadsheets, Google Docs, or general coding tasks unrelated to document generation.","bodyPreview":"# DOCX creation, editing, and analysis\n\n## Overview\n\nA .docx file is a ZIP archive containing XML files.\n\n## Quick Reference\n\n| Task | Approach |\n|------|----------|\n| Read/analyze content | `pandoc` or unpack for raw XML |\n| Create new document | Use `docx-js` - see Creating New Documents below |\n| Edit existing document | Unpack → edit XML → repack - see Editing Existing Documents below |\n\n### Converting .doc to .docx\n\nLegacy `.doc` files must be converted before editing:\n\n```bash\npython scrip","body":"# DOCX creation, editing, and analysis\n\n## Overview\n\nA .docx file is a ZIP archive containing XML files.\n\n## Quick Reference\n\n| Task | Approach |\n|------|----------|\n| Read/analyze content | `pandoc` or unpack for raw XML |\n| Create new document | Use `docx-js` - see Creating New Documents below |\n| Edit existing document | Unpack → edit XML → repack - see Editing Existing Documents below |\n\n### Converting .doc to .docx\n\nLegacy `.doc` files must be converted before editing:\n\n```bash\npython scripts/office/soffice.py --headless --convert-to docx document.doc\n```\n\n### Reading Content\n\n```bash\n# Text extraction with tracked changes\npandoc --track-changes=all document.docx -o output.md\n\n# Raw XML access\npython scripts/office/unpack.py document.docx unpacked/\n```\n\n### Converting to Images\n\n```bash\npython scripts/office/soffice.py --headless --convert-to pdf document.docx\npdftoppm -jpeg -r 150 document.pdf page\n```\n\n### Accepting Tracked Changes\n\nTo produce a clean document with all tracked changes accepted (requires LibreOffice):\n\n```bash\npython scripts/accept_changes.py input.docx output.docx\n```\n\n---\n\n## Creating New Documents\n\nGenerate .docx files with JavaScript, then validate. Install: `npm install -g docx`\n\n### Setup\n```javascript\nconst { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,\n        Header, Footer, AlignmentType, PageOrientation, LevelFormat, ExternalHyperlink,\n        InternalHyperlink, Bookmark, FootnoteReferenceRun, PositionalTab,\n        PositionalTabAlignment, PositionalTabRelativeTo, PositionalTabLeader,\n        TabStopType, TabStopPosition, Column, SectionType,\n        TableOfContents, HeadingLevel, BorderStyle, WidthType, ShadingType,\n        VerticalAlign, PageNumber, PageBreak } = require(''docx'');\n\nconst doc = new Document({ sections: [{ children: [/* content */] }] });\nPacker.toBuffer(doc).then(buffer => fs.writeFileSync(\"doc.docx\", buffer));\n```\n\n### Validation\nAfter creating the file, validate it. If validation fails, unpack, fix the XML, and repack.\n```bash\npython scripts/office/validate.py doc.docx\n```\n\n### Page Size\n\n```javascript\n// CRITICAL: docx-js defaults to A4, not US Letter\n// Always set page size explicitly for consistent results\nsections: [{\n  properties: {\n    page: {\n      size: {\n        width: 12240,   // 8.5 inches in DXA\n        height: 15840   // 11 inches in DXA\n      },\n      margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } // 1 inch margins\n    }\n  },\n  children: [/* content */]\n}]\n```\n\n**Common page sizes (DXA units, 1440 DXA = 1 inch):**\n\n| Paper | Width | Height | Content Width (1\" margins) |\n|-------|-------|--------|---------------------------|\n| US Letter | 12,240 | 15,840 | 9,360 |\n| A4 (default) | 11,906 | 16,838 | 9,026 |\n\n**Landscape orientation:** docx-js swaps width/height internally, so pass portrait dimensions and let it handle the swap:\n```javascript\nsize: {\n  width: 12240,   // Pass SHORT edge as width\n  height: 15840,  // Pass LONG edge as height\n  orientation: PageOrientation.LANDSCAPE  // docx-js swaps them in the XML\n},\n// Content width = 15840 - left margin - right margin (uses the long edge)\n```\n\n### Styles (Override Built-in Headings)\n\nUse Arial as the default font (universally supported). Keep titles black for readability.\n\n```javascript\nconst doc = new Document({\n  styles: {\n    default: { document: { run: { font: \"Arial\", size: 24 } } }, // 12pt default\n    paragraphStyles: [\n      // IMPORTANT: Use exact IDs to override built-in styles\n      { id: \"Heading1\", name: \"Heading 1\", basedOn: \"Normal\", next: \"Normal\", quickFormat: true,\n        run: { size: 32, bold: true, font: \"Arial\" },\n        paragraph: { spacing: { before: 240, after: 240 }, outlineLevel: 0 } }, // outlineLevel required for TOC\n      { id: \"Heading2\", name: \"Heading 2\", basedOn: \"Normal\", next: \"Normal\", quickFormat: true,\n        run: { size: 28, bold: true, font: \"Arial\" },\n        paragraph: { spacing: { before: 180, after: 180 }, outlineLevel: 1 } },\n    ]\n  },\n  sections: [{\n    children: [\n      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(\"Title\")] }),\n    ]\n  }]\n});\n```\n\n### Lists (NEVER use unicode bullets)\n\n```javascript\n// ❌ WRONG - never manually insert bullet characters\nnew Paragraph({ children: [new TextRun(\"• Item\")] })  // BAD\nnew Paragraph({ children: [new TextRun(\"\\u2022 Item\")] })  // BAD\n\n// ✅ CORRECT - use numbering config with LevelFormat.BULLET\nconst doc = new Document({\n  numbering: {\n    config: [\n      { reference: \"bullets\",\n        levels: [{ level: 0, format: LevelFormat.BULLET, text: \"•\", alignment: AlignmentType.LEFT,\n          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },\n      { reference: \"numbers\",\n        levels: [{ level: 0, format: LevelFormat.DECIMAL, text: \"%1.\", alignment: AlignmentType.LEFT,\n          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },\n    ]\n  },\n  sections: [{\n    children: [\n      new Paragraph({ numbering: { reference: \"bullets\", level: 0 },\n        children: [new TextRun(\"Bullet item\")] }),\n      new Paragraph({ numbering: { reference: \"numbers\", level: 0 },\n        children: [new TextRun(\"Numbered item\")] }),\n    ]\n  }]\n});\n\n// ⚠️ Each reference creates INDEPENDENT numbering\n// Same reference = continues (1,2,3 then 4,5,6)\n// Different reference = restarts (1,2,3 then 1,2,3)\n```\n\n### Tables\n\n**CRITICAL: Tables need dual widths** - set both `columnWidths` on the table AND `width` on each cell. Without both, tables render incorrectly on some platforms.\n\n```javascript\n// CRITICAL: Always set table width for consistent rendering\n// CRITICAL: Use ShadingType.CLEAR (not SOLID) to prevent black backgrounds\nconst border = { style: BorderStyle.SINGLE, size: 1, color: \"CCCCCC\" };\nconst borders = { top: border, bottom: border, left: border, right: border };\n\nnew Table({\n  width: { size: 9360, type: WidthType.DXA }, // Always use DXA (percentages break in Google Docs)\n  columnWidths: [4680, 4680], // Must sum to table width (DXA: 1440 = 1 inch)\n  rows: [\n    new TableRow({\n      children: [\n        new TableCell({\n          borders,\n          width: { size: 4680, type: WidthType.DXA }, // Also set on each cell\n          shading: { fill: \"D5E8F0\", type: ShadingType.CLEAR }, // CLEAR not SOLID\n          margins: { top: 80, bottom: 80, left: 120, right: 120 }, // Cell padding (internal, not added to width)\n          children: [new Paragraph({ children: [new TextRun(\"Cell\")] })]\n        })\n      ]\n    })\n  ]\n})\n```\n\n**Table width calculation:**\n\nAlways use `WidthType.DXA` — `WidthType.PERCENTAGE` breaks in Google Docs.\n\n```javascript\n// Table width = sum of columnWidths = content width\n// US Letter with 1\" margins: 12240 - 2880 = 9360 DXA\nwidth: { size: 9360, type: WidthType.DXA },\ncolumnWidths: [7000, 2360]  // Must sum to table width\n```\n\n**Width rules:**\n- **Always use `WidthType.DXA`** — never `WidthType.PERCENTAGE` (incompatible with Google Docs)\n- Table width must equal the sum of `columnWidths`\n- Cell `width` must match corresponding `columnWidth`\n- Cell `margins` are internal padding - they reduce content area, not add to cell width\n- For full-width tables: use content width (page width minus left and right margins)\n\n### Images\n\n```javascript\n// CRITICAL: type parameter is REQUIRED\nnew Paragraph({\n  children: [new ImageRun({\n    type: \"png\", // Required: png, jpg, jpeg, gif, bmp, svg\n    data: fs.readFileSync(\"image.png\"),\n    transformation: { width: 200, height: 150 },\n    altText: { title: \"Title\", description: \"Desc\", name: \"Name\" } // All three required\n  })]\n})\n```\n\n### Page Breaks\n\n```javascript\n// CRITICAL: PageBreak must be inside a Paragraph\nnew Paragraph({ children: [new PageBreak()] })\n\n// Or use pageBreakBefore\nnew Paragraph({ pageBreakBefore: true, children: [new TextRun(\"New page\")] })\n```\n\n### Hyperlinks\n\n```javascript\n// External link\nnew Paragraph({\n  children: [new ExternalHyperlink({\n    children: [new TextRun({ text: \"Click here\", style: \"Hyperlink\" })],\n    link: \"https://example.com\",\n  })]\n})\n\n// Internal link (bookmark + reference)\n// 1. Create bookmark at destination\nnew Paragraph({ heading: HeadingLevel.HEADING_1, children: [\n  new Bookmark({ id: \"chapter1\", children: [new TextRun(\"Chapter 1\")] }),\n]})\n// 2. Link to it\nnew Paragraph({ children: [new InternalHyperlink({\n  children: [new TextRun({ text: \"See Chapter 1\", style: \"Hyperlink\" })],\n  anchor: \"chapter1\",\n})]})\n```\n\n### Footnotes\n\n```javascript\nconst doc = new Document({\n  footnotes: {\n    1: { children: [new Paragraph(\"Source: Annual Report 2024\")] },\n    2: { children: [new Paragraph(\"See appendix for methodology\")] },\n  },\n  sections: [{\n    children: [new Paragraph({\n      children: [\n        new TextRun(\"Revenue grew 15%\"),\n        new FootnoteReferenceRun(1),\n        new TextRun(\" using adjusted metrics\"),\n        new FootnoteReferenceRun(2),\n      ],\n    })]\n  }]\n});\n```\n\n### Tab Stops\n\n```javascript\n// Right-align text on same line (e.g., date opposite a title)\nnew Paragraph({\n  children: [\n    new TextRun(\"Company Name\"),\n    new TextRun(\"\\tJanuary 2025\"),\n  ],\n  tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],\n})\n\n// Dot leader (e.g., TOC-style)\nnew Paragraph({\n  children: [\n    new TextRun(\"Introduction\"),\n    new TextRun({ children: [\n      new PositionalTab({\n        alignment: PositionalTabAlignment.RIGHT,\n        relativeTo: PositionalTabRelativeTo.MARGIN,\n        leader: PositionalTabLeader.DOT,\n      }),\n      \"3\",\n    ]}),\n  ],\n})\n```\n\n### Multi-Column Layouts\n\n```javascript\n// Equal-width columns\nsections: [{\n  properties: {\n    column: {\n      count: 2,          // number of columns\n      space: 720,        // gap between columns in DXA (720 = 0.5 inch)\n      equalWidth: true,\n      separate: true,    // vertical line between columns\n    },\n  },\n  children: [/* content flows naturally across columns */]\n}]\n\n// Custom-width columns (equalWidth must be false)\nsections: [{\n  properties: {\n    column: {\n      equalWidth: false,\n      children: [\n        new Column({ width: 5400, space: 720 }),\n        new Column({ width: 3240 }),\n      ],\n    },\n  },\n  children: [/* content */]\n}]\n```\n\nForce a column break with a new section using `type: SectionType.NEXT_COLUMN`.\n\n### Table of Contents\n\n```javascript\n// CRITICAL: Headings must use HeadingLevel ONLY - no custom styles\nnew TableOfContents(\"Table of Contents\", { hyperlink: true, headingStyleRange: \"1-3\" })\n```\n\n### Headers/Footers\n\n```javascript\nsections: [{\n  properties: {\n    page: { margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } // 1440 = 1 inch\n  },\n  headers: {\n    default: new Header({ children: [new Paragraph({ children: [new TextRun(\"Header\")] })] })\n  },\n  footers: {\n    default: new Footer({ children: [new Paragraph({\n      children: [new TextRun(\"Page \"), new TextRun({ children: [PageNumber.CURRENT] })]\n    })] })\n  },\n  children: [/* content */]\n}]\n```\n\n### Critical Rules for docx-js\n\n- **Set page size explicitly** - docx-js defaults to A4; use US Letter (12240 x 15840 DXA) for US documents\n- **Landscape: pass portrait dimensions** - docx-js swaps width/height internally; pass short edge as `width`, long edge as `height`, and set `orientation: PageOrientation.LANDSCAPE`\n- **Never use `\\n`** - use separate Paragraph elements\n- **Never use unicode bullets** - use `LevelFormat.BULLET` with numbering config\n- **PageBreak must be in Paragraph** - standalone creates invalid XML\n- **ImageRun requires `type`** - always specify png/jpg/etc\n- **Always set table `width` with DXA** - never use `WidthType.PERCENTAGE` (breaks in Google Docs)\n- **Tables need dual widths** - `columnWidths` array AND cell `width`, both must match\n- **Table width = sum of columnWidths** - for DXA, ensure they add up exactly\n- **Always add cell margins** - use `margins: { top: 80, bottom: 80, left: 120, right: 120 }` for readable padding\n- **Use `ShadingType.CLEAR`** - never SOLID for table shading\n- **Never use tables as dividers/rules** - cells have minimum height and render as empty boxes (including in headers/footers); use `border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: \"2E75B6\", space: 1 } }` on a Paragraph instead. For two-column footers, use tab stops (see Tab Stops section), not tables\n- **TOC requires HeadingLevel only** - no custom styles on heading paragraphs\n- **Override built-in styles** - use exact IDs: \"Heading1\", \"Heading2\", etc.\n- **Include `outlineLevel`** - required for TOC (0 for H1, 1 for H2, etc.)\n\n---\n\n## Editing Existing Documents\n\n**Follow all 3 steps in order.**\n\n### Step 1: Unpack\n```bash\npython scripts/office/unpack.py document.docx unpacked/\n```\nExtracts XML, pretty-prints, merges adjacent runs, and converts smart quotes to XML entities (`&#x201C;` etc.) so they survive editing. Use `--merge-runs false` to skip run merging.\n\n### Step 2: Edit XML\n\nEdit files in `unpacked/word/`. See XML Reference below for patterns.\n\n**Use \"Claude\" as the author** for tracked changes and comments, unless the user explicitly requests use of a different name.\n\n**Use the Edit tool directly for string replacement. Do not write Python scripts.** Scripts introduce unnecessary complexity. The Edit tool shows exactly what is being replaced.\n\n**CRITICAL: Use smart quotes for new content.** When adding text with apostrophes or quotes, use XML entities to produce smart quotes:\n```xml\n<!-- Use these entities for professional typography -->\n<w:t>Here&#x2019;s a quote: &#x201C;Hello&#x201D;</w:t>\n```\n| Entity | Character |\n|--------|-----------|\n| `&#x2018;` | ‘ (left single) |\n| `&#x2019;` | ’ (right single / apostrophe) |\n| `&#x201C;` | “ (left double) |\n| `&#x201D;` | ” (right double) |\n\n**Adding comments:** Use `comment.py` to handle boilerplate across multiple XML files (text must be pre-escaped XML):\n```bash\npython scripts/comment.py unpacked/ 0 \"Comment text with &amp; and &#x2019;\"\npython scripts/comment.py unpacked/ 1 \"Reply text\" --parent 0  # reply to comment 0\npython scripts/comment.py unpacked/ 0 \"Text\" --author \"Custom Author\"  # custom author name\n```\nThen add markers to document.xml (see Comments in XML Reference).\n\n### Step 3: Pack\n```bash\npython scripts/office/pack.py unpacked/ output.docx --original document.docx\n```\nValidates with auto-repair, condenses XML, and creates DOCX. Use `--validate false` to skip.\n\n**Auto-repair will fix:**\n- `durableId` >= 0x7FFFFFFF (regenerates valid ID)\n- Missing `xml:space=\"preserve\"` on `<w:t>` with whitespace\n\n**Auto-repair won''t fix:**\n- Malformed XML, invalid element nesting, missing relationships, schema violations\n\n### Common Pitfalls\n\n- **Replace entire `<w:r>` elements**: When adding tracked changes, replace the whole `<w:r>...</w:r>` block with `<w:del>...<w:ins>...` as siblings. Don''t inject tracked change tags inside a run.\n- **Preserve `<w:rPr>` formatting**: Copy the original run''s `<w:rPr>` block into your tracked change runs to maintain bold, font size, etc.\n\n---\n\n## XML Reference\n\n### Schema Compliance\n\n- **Element order in `<w:pPr>`**: `<w:pStyle>`, `<w:numPr>`, `<w:spacing>`, `<w:ind>`, `<w:jc>`, `<w:rPr>` last\n- **Whitespace**: Add `xml:space=\"preserve\"` to `<w:t>` with leading/trailing spaces\n- **RSIDs**: Must be 8-digit hex (e.g., `00AB1234`)\n\n### Tracked Changes\n\n**Insertion:**\n```xml\n<w:ins w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:t>inserted text</w:t></w:r>\n</w:ins>\n```\n\n**Deletion:**\n```xml\n<w:del w:id=\"2\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:delText>deleted text</w:delText></w:r>\n</w:del>\n```\n\n**Inside `<w:del>`**: Use `<w:delText>` instead of `<w:t>`, and `<w:delInstrText>` instead of `<w:instrText>`.\n\n**Minimal edits** - only mark what changes:\n```xml\n<!-- Change \"30 days\" to \"60 days\" -->\n<w:r><w:t>The term is </w:t></w:r>\n<w:del w:id=\"1\" w:author=\"Claude\" w:date=\"...\">\n  <w:r><w:delText>30</w:delText></w:r>\n</w:del>\n<w:ins w:id=\"2\" w:author=\"Claude\" w:date=\"...\">\n  <w:r><w:t>60</w:t></w:r>\n</w:ins>\n<w:r><w:t> days.</w:t></w:r>\n```\n\n**Deleting entire paragraphs/list items** - when removing ALL content from a paragraph, also mark the paragraph mark as deleted so it merges with the next paragraph. Add `<w:del/>` inside `<w:pPr><w:rPr>`:\n```xml\n<w:p>\n  <w:pPr>\n    <w:numPr>...</w:numPr>  <!-- list numbering if present -->\n    <w:rPr>\n      <w:del w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\"/>\n    </w:rPr>\n  </w:pPr>\n  <w:del w:id=\"2\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n    <w:r><w:delText>Entire paragraph content being deleted...</w:delText></w:r>\n  </w:del>\n</w:p>\n```\nWithout the `<w:del/>` in `<w:pPr><w:rPr>`, accepting changes leaves an empty paragraph/list item.\n\n**Rejecting another author''s insertion** - nest deletion inside their insertion:\n```xml\n<w:ins w:author=\"Jane\" w:id=\"5\">\n  <w:del w:author=\"Claude\" w:id=\"10\">\n    <w:r><w:delText>their inserted text</w:delText></w:r>\n  </w:del>\n</w:ins>\n```\n\n**Restoring another author''s deletion** - add insertion after (don''t modify their deletion):\n```xml\n<w:del w:author=\"Jane\" w:id=\"5\">\n  <w:r><w:delText>deleted text</w:delText></w:r>\n</w:del>\n<w:ins w:author=\"Claude\" w:id=\"10\">\n  <w:r><w:t>deleted text</w:t></w:r>\n</w:ins>\n```\n\n### Comments\n\nAfter running `comment.py` (see Step 2), add markers to document.xml. For replies, use `--parent` flag and nest markers inside the parent''s.\n\n**CRITICAL: `<w:commentRangeStart>` and `<w:commentRangeEnd>` are siblings of `<w:r>`, never inside `<w:r>`.**\n\n```xml\n<!-- Comment markers are direct children of w:p, never inside w:r -->\n<w:commentRangeStart w:id=\"0\"/>\n<w:del w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:delText>deleted</w:delText></w:r>\n</w:del>\n<w:r><w:t> more text</w:t></w:r>\n<w:commentRangeEnd w:id=\"0\"/>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"0\"/></w:r>\n\n<!-- Comment 0 with reply 1 nested inside -->\n<w:commentRangeStart w:id=\"0\"/>\n  <w:commentRangeStart w:id=\"1\"/>\n  <w:r><w:t>text</w:t></w:r>\n  <w:commentRangeEnd w:id=\"1\"/>\n<w:commentRangeEnd w:id=\"0\"/>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"0\"/></w:r>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"1\"/></w:r>\n```\n\n### Images\n\n1. Add image file to `word/media/`\n2. Add relationship to `word/_rels/document.xml.rels`:\n```xml\n<Relationship Id=\"rId5\" Type=\".../image\" Target=\"media/image1.png\"/>\n```\n3. Add content type to `[Content_Types].xml`:\n```xml\n<Default Extension=\"png\" ContentType=\"image/png\"/>\n```\n4. Reference in document.xml:\n```xml\n<w:drawing>\n  <wp:inline>\n    <wp:extent cx=\"914400\" cy=\"914400\"/>  <!-- EMUs: 914400 = 1 inch -->\n    <a:graphic>\n      <a:graphicData uri=\".../picture\">\n        <pic:pic>\n          <pic:blipFill><a:blip r:embed=\"rId5\"/></pic:blipFill>\n        </pic:pic>\n      </a:graphicData>\n    </a:graphic>\n  </wp:inline>\n</w:drawing>\n```\n\n---\n\n## Dependencies\n\n- **pandoc**: Text extraction\n- **docx**: `npm install -g docx` (new documents)\n- **LibreOffice**: PDF conversion (auto-configured for sandboxed environments via `scripts/office/soffice.py`)\n- **Poppler**: `pdftoppm` for images\n"},"category":"official","lastSynced":"2026-03-06T03:16:51.860Z","seo":{"title":{"en":"docx: Programmatic Word Document Manipulation | AI Agent ...","es":"docx AI Agent: Guía de manipulación de documentos Word","fr":"docx AI Agent: Guide de manipulation des documents Word","de":"docx AI Agent: Leitfaden zur Bearbeitung von Word-Dokumenten","pt":"Habilidade docx para AI Agents: Manipulação Técnica de Do...","ru":"Навык docx для ИИ Агентов: Создание и Редактирование DOCX","ar":"مهارة docx لأدوات الذكاء الاصطناعي: معالجة مستندات وورد ا..."},"description":{"en":"Learn how this AI Agent Skill manipulates .docx files via XML editing, `pandoc`, and `docx-js`. Automate document creation, editing, and content extraction f...","es":"Aprende a usar el AI Agent docx para crear, editar y analizar archivos .docx mediante manipulación XML, pandoc y docx-js. Automatiza la generación de documen...","fr":"Apprenez à utiliser l''AI Agent docx pour créer, éditer et analyser des fichiers .docx via la manipulation XML, pandoc et docx-js. Automatisez la génération d...","de":"Erfahren Sie, wie Sie den AI Agent docx zum Erstellen, Bearbeiten und Analysieren von .docx-Dateien über XML-Manipulation, pandoc und docx-js verwenden. Auto...","pt":"Guia para desenvolvedores: use a habilidade docx em AI Agents para criar, editar e analisar arquivos .docx programaticamente. Inclui manipulação de XML, uso ...","ru":"Руководство для разработчиков: используйте навык docx в ИИ Агентах для программного создания, редактирования и анализа файлов .docx. Включает работу с XML, p...","ar":"دليل للمطورين: استخدم مهارة docx في أدوات الذكاء الاصطناعي لإنشاء وتحرير وتحليل ملفات .docx برمجياً. يتضمن معالجة XML واستخدام pandoc وdocx-js لأتمتة مستندات..."},"definition":{"en":"docx is an AI Agent Skill for programmatically manipulating Microsoft Word documents. It treats .docx files as ZIP archives containing XML, enabling direct editing, content extraction with `pandoc`, and new document creation via `docx-js`.","es":"docx es una habilidad de AI Agent especializada en la manipulación programática de archivos Word (.docx). Trata los documentos como archivos ZIP que contienen XML, permitiendo la automatización de tareas como edición de contenido, inserción de imágenes, gestión de comentarios y generación de documentos con formato profesional.","fr":"docx est une compétence d''AI Agent spécialisée dans la manipulation programmatique de fichiers Word (.docx). Elle traite les documents comme des archives ZIP contenant du XML, permettant d''automatiser des tâches comme l''édition de contenu, l''insertion d''images, la gestion de commentaires et la génération de documents avec mise en forme professionnelle.","de":"docx ist eine AI Agent Fähigkeit zur programmatischen Bearbeitung von Word-Dateien (.docx). Sie behandelt Dokumente als ZIP-Archive mit XML-Inhalten und ermöglicht die Automatisierung von Aufgaben wie Inhaltsbearbeitung, Bildereinfügung, Kommentarverwaltung und Generierung professionell formatierter Dokumente.","pt":"A habilidade docx é uma função para AI Agents especializada na manipulação de documentos Word (.docx). Ela opera entendendo que um arquivo .docx é um arquivo ZIP contendo vários arquivos XML, permitindo a automação de tarefas como criação, edição de conteúdo, formatação e extração de dados.","ru":"Навык docx — это функция для ИИ Агентов, предназначенная для работы с документами Word (.docx). Он работает на основе того, что файл .docx является ZIP-архивом, содержащим XML-файлы, что позволяет автоматизировать создание, редактирование, форматирование и извлечение данных.","ar":"مهارة docx هي وظيفة لأدوات الذكاء الاصطناعي متخصصة في معالجة مستندات Word (.docx). تعمل على أساس أن ملف .docx هو أرشيف ZIP يحتوي على ملفات XML متعددة، مما يمكن من أتمتة إنشاء المحتوى وتحريره وتنسيقه واستخراج البيانات."},"features":{"en":["Unpacks .docx files as ZIP archives for raw XML editing and repacking","Reads and analyzes document content using the `pandoc` utility","Creates new Word documents programmatically using the `docx-js` library","Converts legacy .doc files to the modern .docx format for editing","Performs content extraction and reorganization from existing documents"],"es":["Manipulación de XML interno para edición avanzada de documentos .docx","Creación de nuevos documentos mediante la librería docx-js","Análisis de contenido con herramientas CLI como pandoc","Conversión programática de archivos .doc legacy a .docx","Gestión de cambios tracked y comentarios en documentos Word","Inserción y reemplazo de imágenes mediante manipulación de archivos"],"fr":["Manipulation de XML interne pour l''édition avancée de documents .docx","Création de nouveaux documents via la bibliothèque docx-js","Analyse de contenu avec des outils CLI comme pandoc","Conversion programmatique de fichiers .doc legacy en .docx","Gestion des changements suivis et des commentaires dans les documents Word","Insertion et remplacement d''images via la manipulation de fichiers"],"de":["Manipulation interner XML-Dateien für erweiterte .docx-Bearbeitung","Erstellung neuer Dokumente mit der docx-js-Bibliothek","Inhaltsanalyse mit CLI-Tools wie pandoc","Programmatische Konvertierung von Legacy-.doc- zu .docx-Dateien","Verwaltung von Nachverfolgten Änderungen und Kommentaren in Word-Dokumenten","Einfügung und Ersetzung von Bildern durch Dateimanipulation"],"pt":["Manipulação de arquivos .docx como arquivos ZIP contendo XML para edição de baixo nível","Criação de novos documentos programaticamente usando a biblioteca docx-js","Edição de documentos existentes através de descompactar, editar XML e recompactar","Conversão de documentos legados .doc para o formato .docx moderno","Análise e extração de conteúdo usando a ferramenta de linha de comando pandoc","Suporte para operações complexas como inserir imagens, TOC e tracked changes"],"ru":["Обработка файлов .docx как ZIP-архивов, содержащих XML, для низкоуровневого редактирования","Программное создание новых документов с использованием библиотеки docx-js","Редактирование существующих документов путем распаковки, правки XML и повторной упаковки","Преобразование устаревших документов .doc в современный формат .docx","Анализ и извлечение содержимого с использованием CLI-инструмента pandoc","Поддержка сложных операций: вставка изображений, оглавление, отслеживание изменений"],"ar":["معالجة ملفات .docx كأرشيفات ZIP تحتوي على XML للتحرير على مستوى منخفض","إنشاء مستندات جديدة برمجياً باستخدام مكتبة docx-js","تحرير المستندات الموجودة through فك الضغط وتحرير XML وإعادة الضغط","تحويل المستندات القديمة .doc إلى تنسيق .docx الحديث","تحليل المحتوى واستخراجه using أداة سطر الأوامر pandoc","دعم عمليات معقدة like إدراج الصور، جدول المحتويات، والتعقب التغييرات"]},"keywords":{"en":["how to edit docx xml","docx vs google docs automation","pandoc extract docx content","docx-js create word document","convert doc to docx programmatically","ai agent docx manipulation skill","programmatic word document generation","edit docx file with code"],"es":["docx AI Agent manipulación","automatizar documentos word","docx-js crear documentos","pandoc analizar docx","xml word document","convertir doc a docx python","editar tracked changes programáticamente","insertar imágenes docx automáticamente"],"fr":["docx AI Agent manipulation","automatiser documents word","docx-js créer documents","pandoc analyser docx","xml word document","convertir doc en docx python","éditer changements suivis programmatiquement","insérer images docx automatiquement"],"de":["docx AI Agent Bearbeitung","word dokumente automatisieren","docx-js dokumente erstellen","pandoc docx analysieren","xml word dokument","doc zu docx konvertieren python","nachverfolgte änderungen programmatisch bearbeiten","bilder docx automatisch einfügen"],"pt":["ai agent manipular docx","criar documento word programaticamente","editar xml docx","python script converter doc para docx","automatizar relatorio word","pandoc extrair conteudo docx","docx-js tutorial","habilidade técnica ai agent"],"ru":["ИИ агент работать с docx","создать документ word программно","редактировать xml docx","python конвертировать doc в docx","автоматизировать отчет word","pandoc извлечь контент docx","docx-js руководство","технический навык ИИ агент"],"ar":["أداة ذكاء اصطناعي معالجة docx","إنشاء مستند وورد برمجياً","تحرير xml docx","بايثون تحويل doc إلى docx","أتمتة تقرير word","pandoc استخراج محتوى docx","docx-js tutorial","مهارة تقنية أداة الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Document Automation Agents requiring precise Word document creation, editing, and content extraction.","zh":"对于需要精确创建、编辑和提取Word文档内容的文档自动化AI Agent来说，这是必不可少的技能。","ja":"Word文書の正確な作成、編集、およびコンテンツ抽出を必要とする文書自動化エージェントにとって必須です。","ko":"정확한 Word 문서 생성, 편집 및 콘텐츠 추출이 필요한 문서 자동화 에이전트에게 필수적인 기술입니다.","es":"Esencial para los Document Automation Agents que requieren la creación, edición y extracción de contenido precisa de documentos de Word.","fr":"Essentiel pour les agents d''automatisation de documents nécessitant une création, une édition et une extraction de contenu précises de documents Word.","de":"Unverzichtbar für Document Automation Agents, die eine präzise Erstellung, Bearbeitung und Inhaltsentnahme von Word-Dokumenten erfordern.","pt":"Essencial para Agentes de Automação de Documentos que exigem criação, edição e extração de conteúdo precisa em documentos do Word.","ru":"Необходим для Агентов автоматизации документов, требующих точного создания, редактирования и извлечения содержимого документов Word.","ar":"أساسي لوكلاء أتمتة المستندات التي تتطلب إنشاء مستندات Word وتحريرها واستخراج محتواها بدقة."},"recommendation":{"en":"Empowers agents to programmatically generate professional Word documents with advanced formatting like tables of contents, headings, and page numbers. Enables direct manipulation of .docx files by treating them as ZIP archives containing editable XML, supporting operations from simple find-and-replace to complex image insertion and tracked changes management.","zh":"使Agent能够通过编程方式生成具有高级格式（如目录、标题和页码）的专业Word文档。通过将.docx文件视为包含可编辑XML的ZIP存档来实现直接操作，支持从简单的查找替换到复杂的图像插入和修订跟踪管理等操作。","ja":"目次、見出し、ページ番号などの高度な書式設定を備えたプロフェッショナルなWord文書をプログラムで生成する機能をエージェントに提供します。編集可能なXMLを含むZIPアーカイブとして.docxファイルを扱うことで直接操作を可能にし、単純な検索と置換から複雑な画像挿入、変更履歴の管理までの操作をサポートします。","ko":"목차, 제목, 페이지 번호와 같은 고급 서식을 갖춘 전문적인 Word 문서를 프로그래밍 방식으로 생성하는 기능을 에이전트에 부여합니다. 편집 가능한 XML을 포함하는 ZIP 아카이브로 .docx 파일을 처리하여 직접 조작을 가능하게 하며, 단순 찾기 및 바꾸기부터 복잡한 이미지 삽입 및 변경 내용 관리 작업까지 지원합니다.","es":"Permite a los agentes generar programáticamente documentos de Word profesionales con formato avanzado, como tablas de contenido, encabezados y números de página. Permite la manipulación directa de archivos .docx tratándolos como archivos ZIP que contienen XML editable, admitiendo operaciones desde la búsqueda y reemplazo simple hasta la inserción compleja de imágenes y la gestión de cambios realizados.","fr":"Permet aux agents de générer programmatiquement des documents Word professionnels avec une mise en forme avancée, telle que des tables des matières, des en-têtes et des numéros de page. Permet la manipulation directe des fichiers .docx en les traitant comme des archives ZIP contenant du XML modifiable, prenant en charge des opérations allant de la simple recherche et remplacement à l''insertion complexe d''images et à la gestion des modifications suivies.","de":"Ermöglicht es Agents, programmgesteuert professionelle Word-Dokumente mit erweiterten Formatierungen wie Inhaltsverzeichnissen, Überschriften und Seitenzahlen zu erstellen. Ermöglicht die direkte Manipulation von .docx-Dateien, indem sie als ZIP-Archive behandelt werden, die bearbeitbares XML enthalten, und unterstützt Operationen vom einfachen Suchen und Ersetzen bis zur komplexen Bildinsertion und Verwaltung von Nachverfolgungsänderungen.","pt":"Capacita os agentes a gerar programaticamente documentos do Word profissionais com formatação avançada, como sumários, cabeçalhos e números de página. Permite a manipulação direta de arquivos .docx tratando-os como arquivos ZIP contendo XML editável, suportando operações desde simples localizar-e-substituir até inserção complexa de imagens e gerenciamento de alterações controladas.","ru":"Позволяет агентам программно генерировать профессиональные документы Word с расширенным форматированием, таким как оглавление, заголовки и номера страниц. Обеспечивает прямое манипулирование файлами .docx, рассматривая их как ZIP-архивы, содержащие редактируемый XML, поддерживая операции от простого поиска-и-замены до сложной вставки изображений и управления отслеживаемыми изменениями.","ar":"يمكن الوكلاء من إنشاء مستندات Word احترافية برمجيًا بتنسيق متقدم مثل جداول المحتويات والعناوين وأرقام الصفحات. يتيح التلاعب المباشر بملفات .docx عن طريق معاملتها كأرشيفات ZIP تحتوي على XML قابل للتحرير، مما يدعم العمليات من البحث والاستبدال البسيط إلى إدراج الصور المعقدة وإدارة التغييرات المتعقبة."},"useCases":{"en":["Generating professional reports and memos with automated formatting","Extracting and reorganizing content from existing .docx files","Performing batch find-and-replace operations across multiple documents","Inserting or replacing images and managing tracked changes/comments"],"zh":["使用自动格式生成专业报告和备忘录","从现有.docx文件中提取内容并重新组织","跨多个文档执行批量查找替换操作","插入或替换图像以及管理修订跟踪/批注"],"ja":["自動フォーマットを使用したプロフェッショナルなレポートとメモの生成","既存の.docxファイルからのコンテンツの抽出と再編成","複数のドキュメントにわたるバッチ検索および置換操作の実行","画像の挿入または置換、および変更履歴/コメントの管理"],"ko":["자동 서식을 사용하여 전문적인 보고서 및 메모 생성","기존 .docx 파일에서 콘텐츠 추출 및 재구성","여러 문서에 걸친 일괄 찾기 및 바꾸기 작업 수행","이미지 삽입 또는 교체 및 변경 내용 추적/주석 관리"],"es":["Generación de informes y memorandos profesionales con formato automatizado","Extracción y reorganización de contenido de archivos .docx existentes","Realización de operaciones por lotes de búsqueda y reemplazo en múltiples documentos","Inserción o reemplazo de imágenes y gestión de cambios realizados/comentarios"],"fr":["Génération de rapports et de mémos professionnels avec une mise en forme automatisée","Extraction et réorganisation du contenu à partir de fichiers .docx existants","Exécution d''opérations de recherche et remplacement par lots sur plusieurs documents","Insertion ou remplacement d''images et gestion des modifications suivies/commentaires"],"de":["Generierung professioneller Berichte und Memos mit automatisierter Formatierung","Extrahieren und Neuorganisieren von Inhalten aus bestehenden .docx-Dateien","Durchführung von Stapel-Suchen-und-Ersetzen-Operationen über mehrere Dokumente hinweg","Einfügen oder Ersetzen von Bildern und Verwalten von Nachverfolgungsänderungen/Kommentaren"],"pt":["Geração de relatórios e memorandos profissionais com formatação automatizada","Extração e reorganização de conteúdo de arquivos .docx existentes","Realização de operações em lote de localizar-e-substituir em vários documentos","Inserção ou substituição de imagens e gerenciamento de alterações controladas/comentários"],"ru":["Генерация профессиональных отчетов и меморандумов с автоматическим форматированием","Извлечение и реорганизация содержимого из существующих файлов .docx","Выполнение пакетных операций поиска-и-замены в нескольких документах","Вставка или замена изображений и управление отслеживаемыми изменениями/комментариями"],"ar":["إنشاء التقارير والمذكرات الاحترافية بالتنسيق الآلي","استخراج وإعادة تنظيم المحتوى من ملفات .docx الموجودة","إجراء عمليات البحث والاستبدال المجمعة عبر مستندات متعددة","إدراج الصور أو استبدالها وإدارة التغييرات المتعقبة/التعليقات"]},"limitations":{"en":["Requires conversion of legacy .doc files to .docx format before editing","Involves low-level XML manipulation for advanced edits","No native support for PDFs, spreadsheets, or Google Docs formats"],"zh":["编辑前需要将旧版.doc文件转换为.docx格式","高级编辑涉及底层XML操作","对PDF、电子表格或Google Docs格式没有原生支持"],"ja":["編集前に従来の.docファイルを.docx形式に変換する必要がある","高度な編集には低レベルなXML操作が伴う","PDF、スプレッドシート、またはGoogle Docs形式のネイティブサポートがない"],"ko":["편집 전에 기존 .doc 파일을 .docx 형식으로 변환해야 함","고급 편집에는 저수준 XML 조작이 필요함","PDF, 스프레드시트 또는 Google Docs 형식에 대한 기본 지원 없음"],"es":["Requiere la conversión de archivos heredados .doc al formato .docx antes de la edición","Implica la manipulación de XML de bajo nivel para ediciones avanzadas","No hay soporte nativo para formatos PDF, hojas de cálculo o Google Docs"],"fr":["Nécessite la conversion des anciens fichiers .doc au format .docx avant l''édition","Implique une manipulation XML de bas niveau pour les modifications avancées","Aucune prise en charge native des formats PDF, feuilles de calcul ou Google Docs"],"de":["Erfordert die Konvertierung älterer .doc-Dateien in das .docx-Format vor der Bearbeitung","Beinhaltet Low-Level-XML-Manipulation für erweiterte Bearbeitungen","Keine native Unterstützung für PDFs, Tabellenkalkulationen oder Google Docs-Formate"],"pt":["Requer conversão de arquivos legados .doc para o formato .docx antes da edição","Envolve manipulação de XML de baixo nível para edições avançadas","Sem suporte nativo para PDFs, planilhas ou formatos do Google Docs"],"ru":["Требует преобразования устаревших файлов .doc в формат .docx перед редактированием","Включает низкоуровневое манипулирование XML для расширенных правок","Отсутствует нативная поддержка PDF, электронных таблиц или форматов Google Docs"],"ar":["يتطلب تحويل ملفات .doc القديمة إلى تنسيق .docx قبل التحرير","يتضمن التلاعب منخفض المستوى بـ XML للتعديلات المتقدمة","لا يوجد دعم أصلي لتنسيقات PDFs أو جداول البيانات أو Google Docs"]},"version":4},"contentHash":"cfbabd72b1aec7dfaad988fb6e5e16b27dc744b9a00cae15db9045e95f53903e","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":80}');
