INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/docx', 'docx', 'anthropics', 'skills', 'official', 'docx anthropics skills official agent-skills This AI Agent Skill enables developers to programmatically create, read, edit, and analyze Microsoft Word (.docx) documents. It handles tasks like XML manipulation, content extraction with `pandoc`, and generating new files with `docx-js`. Esta habilidad de AI Agent permite la creación, edición y análisis programático de documentos Word (.docx). Utiliza técnicas como la manipulación directa de XML, la librería docx-js y herramientas CLI como pandoc para automatizar tareas complejas de documentos. Cette compétence d''AI Agent permet la création, l''édition et l''analyse programmatique de documents Word (.docx). Elle utilise des techniques comme la manipulation directe de XML, la bibliothèque docx-js et des outils CLI comme pandoc pour automatiser des tâches documentaires complexes. Diese AI Agent Fähigkeit ermöglicht die programmatische Erstellung, Bearbeitung und Analyse von Word-Dokumenten (.docx). Sie nutzt Techniken wie direkte XML-Manipulation, die docx-js-Bibliothek und CLI-Tools wie pandoc zur Automatisierung komplexer Dokumentenaufgaben. Uma habilidade técnica para AI Agents que permite a manipulação programática de documentos Word (.docx). Ela trata o arquivo como um arquivo ZIP contendo XML, permitindo criação, edição e análise de conteúdo com ferramentas como docx-js e pandoc. Технический навык для ИИ Агентов, обеспечивающий программную работу с документами Word (.docx). Он рассматривает файл как ZIP-архив с XML, позволяя создавать, редактировать и анализировать контент с помощью инструментов docx-js и pandoc. مهارة تقنية لأدوات الذكاء الاصطناعي تتيح المعالجة البرمجية لمستندات Word (.docx). تعامل الملف كأرشيف ZIP يحتوي على XML، مما يتيح إنشاء المحتوى وتحريره وتحليله باستخدام أدوات مثل docx-js وpandoc. how to edit docx xml docx vs google docs automation pandoc extract docx content docx-js create word document convert doc to docx programmatically ai agent docx manipulation skill programmatic word document generation edit docx file with code Unpacks .docx files as ZIP archives for raw XML editing and repacking Reads and analyzes document content using the `pandoc` utility Creates new Word documents programmatically using the `docx-js` library Converts legacy .doc files to the modern .docx format for editing Performs content extraction and reorganization from existing documents docx is an AI Agent Skill for programmatically manipulating Microsoft Word documents. It treats .docx files as ZIP archives containing XML, enabling direct editing, content extraction with `pandoc`, and new document creation via `docx-js`.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/mcp-builder', 'official', 'anthropics', 'skills', 'anthropics/skills', 'mcp-builder', 85097, 8974, 80, '2026-03-06T03:11:21Z', '2026-03-06T03:19:22.587Z', '0f4592dcb53cf2b5d6b7febee6b4152018b565551a1c29e3c612f57b218ab295', '{"id":"anthropics/skills/mcp-builder","name":"mcp-builder","description":{"en":"mcp-builder is a guide for developers creating MCP (Model Context Protocol) servers that enable LLMs to interact with external services. It provides a structured workflow for building high-quality tools in Python or Node/TypeScript.","zh":"MCP服务器开发专业指南，提供Python（FastMCP）和Node.js/TypeScript（MCP SDK）两种实现方式。通过四阶段高质量工作流，帮助开发者创建能够使LLM完成实际任务的MCP工具。","ja":"Python（FastMCP）とNode.js/TypeScript（MCP SDK）を使ったMCPサーバー開発ガイド。4段階のワークフローでAIエージェントが実世界のタスクを遂行できる高品質ツールを構築。","ko":"Python(FastMCP)와 Node.js/TypeScript(MCP SDK)를 이용한 MCP 서버 개발 가이드. 4단계 워크플로우를 통해 LLM이 실제 작업을 수행할 수 있는 고품질 도구 구축.","es":"Guía completa para desarrollar servidores MCP que permiten a los modelos de lenguaje interactuar con servicios externos mediante herramientas bien diseñadas. Cubre Python con FastMCP y Node.js/TypeScript con el SDK oficial.","fr":"Guide complet pour développer des serveurs MCP permettant aux modèles de langage d''interagir avec des services externes via des outils bien conçus. Couvre Python avec FastMCP et Node.js/TypeScript avec le SDK officiel.","de":"Umfassende Anleitung zur Entwicklung von MCP Servern, die Sprachmodellen die Interaktion mit externen Diensten über gut gestaltete Tools ermöglicht. Behandelt Python mit FastMCP und Node.js/TypeScript mit dem offiziellen SDK.","pt":"O mcp-builder é uma ferramenta para criar servidores MCP que permitem que LLMs interajam com serviços externos. Aprenda a configurá-lo para Python ou Node/TypeScript","ru":"mcp-builder - это инструмент для создания серверов MCP, позволяющих LLM взаимодействовать с внешними сервисами. Узнайте, как настроить его для Python или Node/TypeScript (ИИ Агенты)","ar":"mcp-builder هو أداة لإنشاء خادم MCP يسمح للنماذج بالتفاعل مع الخدمات الخارجية. تعلم كيفية إعداده لPython أو Node/TypeScript"},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"mcp-builder","description":"Guide for creating high-quality MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. Use when building MCP servers to integrate external APIs or services, whether in Python (FastMCP) or Node/TypeScript (MCP SDK).","bodyPreview":"# MCP Server Development Guide\n\n## Overview\n\nCreate MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. The quality of an MCP server is measured by how well it enables LLMs to accomplish real-world tasks.\n\n---\n\n# Process\n\n## 🚀 High-Level Workflow\n\nCreating a high-quality MCP server involves four main phases:\n\n### Phase 1: Deep Research and Planning\n\n#### 1.1 Understand Modern MCP Design\n\n**API Coverage vs. Workflow Tools:**\nBalan","body":"# MCP Server Development Guide\n\n## Overview\n\nCreate MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. The quality of an MCP server is measured by how well it enables LLMs to accomplish real-world tasks.\n\n---\n\n# Process\n\n## 🚀 High-Level Workflow\n\nCreating a high-quality MCP server involves four main phases:\n\n### Phase 1: Deep Research and Planning\n\n#### 1.1 Understand Modern MCP Design\n\n**API Coverage vs. Workflow Tools:**\nBalance comprehensive API endpoint coverage with specialized workflow tools. Workflow tools can be more convenient for specific tasks, while comprehensive coverage gives agents flexibility to compose operations. Performance varies by client—some clients benefit from code execution that combines basic tools, while others work better with higher-level workflows. When uncertain, prioritize comprehensive API coverage.\n\n**Tool Naming and Discoverability:**\nClear, descriptive tool names help agents find the right tools quickly. Use consistent prefixes (e.g., `github_create_issue`, `github_list_repos`) and action-oriented naming.\n\n**Context Management:**\nAgents benefit from concise tool descriptions and the ability to filter/paginate results. Design tools that return focused, relevant data. Some clients support code execution which can help agents filter and process data efficiently.\n\n**Actionable Error Messages:**\nError messages should guide agents toward solutions with specific suggestions and next steps.\n\n#### 1.2 Study MCP Protocol Documentation\n\n**Navigate the MCP specification:**\n\nStart with the sitemap to find relevant pages: `https://modelcontextprotocol.io/sitemap.xml`\n\nThen fetch specific pages with `.md` suffix for markdown format (e.g., `https://modelcontextprotocol.io/specification/draft.md`).\n\nKey pages to review:\n- Specification overview and architecture\n- Transport mechanisms (streamable HTTP, stdio)\n- Tool, resource, and prompt definitions\n\n#### 1.3 Study Framework Documentation\n\n**Recommended stack:**\n- **Language**: TypeScript (high-quality SDK support and good compatibility in many execution environments e.g. MCPB. Plus AI models are good at generating TypeScript code, benefiting from its broad usage, static typing and good linting tools)\n- **Transport**: Streamable HTTP for remote servers, using stateless JSON (simpler to scale and maintain, as opposed to stateful sessions and streaming responses). stdio for local servers.\n\n**Load framework documentation:**\n\n- **MCP Best Practices**: [📋 View Best Practices](./reference/mcp_best_practices.md) - Core guidelines\n\n**For TypeScript (recommended):**\n- **TypeScript SDK**: Use WebFetch to load `https://raw.githubusercontent.com/modelcontextprotocol/typescript-sdk/main/README.md`\n- [⚡ TypeScript Guide](./reference/node_mcp_server.md) - TypeScript patterns and examples\n\n**For Python:**\n- **Python SDK**: Use WebFetch to load `https://raw.githubusercontent.com/modelcontextprotocol/python-sdk/main/README.md`\n- [🐍 Python Guide](./reference/python_mcp_server.md) - Python patterns and examples\n\n#### 1.4 Plan Your Implementation\n\n**Understand the API:**\nReview the service''s API documentation to identify key endpoints, authentication requirements, and data models. Use web search and WebFetch as needed.\n\n**Tool Selection:**\nPrioritize comprehensive API coverage. List endpoints to implement, starting with the most common operations.\n\n---\n\n### Phase 2: Implementation\n\n#### 2.1 Set Up Project Structure\n\nSee language-specific guides for project setup:\n- [⚡ TypeScript Guide](./reference/node_mcp_server.md) - Project structure, package.json, tsconfig.json\n- [🐍 Python Guide](./reference/python_mcp_server.md) - Module organization, dependencies\n\n#### 2.2 Implement Core Infrastructure\n\nCreate shared utilities:\n- API client with authentication\n- Error handling helpers\n- Response formatting (JSON/Markdown)\n- Pagination support\n\n#### 2.3 Implement Tools\n\nFor each tool:\n\n**Input Schema:**\n- Use Zod (TypeScript) or Pydantic (Python)\n- Include constraints and clear descriptions\n- Add examples in field descriptions\n\n**Output Schema:**\n- Define `outputSchema` where possible for structured data\n- Use `structuredContent` in tool responses (TypeScript SDK feature)\n- Helps clients understand and process tool outputs\n\n**Tool Description:**\n- Concise summary of functionality\n- Parameter descriptions\n- Return type schema\n\n**Implementation:**\n- Async/await for I/O operations\n- Proper error handling with actionable messages\n- Support pagination where applicable\n- Return both text content and structured data when using modern SDKs\n\n**Annotations:**\n- `readOnlyHint`: true/false\n- `destructiveHint`: true/false\n- `idempotentHint`: true/false\n- `openWorldHint`: true/false\n\n---\n\n### Phase 3: Review and Test\n\n#### 3.1 Code Quality\n\nReview for:\n- No duplicated code (DRY principle)\n- Consistent error handling\n- Full type coverage\n- Clear tool descriptions\n\n#### 3.2 Build and Test\n\n**TypeScript:**\n- Run `npm run build` to verify compilation\n- Test with MCP Inspector: `npx @modelcontextprotocol/inspector`\n\n**Python:**\n- Verify syntax: `python -m py_compile your_server.py`\n- Test with MCP Inspector\n\nSee language-specific guides for detailed testing approaches and quality checklists.\n\n---\n\n### Phase 4: Create Evaluations\n\nAfter implementing your MCP server, create comprehensive evaluations to test its effectiveness.\n\n**Load [✅ Evaluation Guide](./reference/evaluation.md) for complete evaluation guidelines.**\n\n#### 4.1 Understand Evaluation Purpose\n\nUse evaluations to test whether LLMs can effectively use your MCP server to answer realistic, complex questions.\n\n#### 4.2 Create 10 Evaluation Questions\n\nTo create effective evaluations, follow the process outlined in the evaluation guide:\n\n1. **Tool Inspection**: List available tools and understand their capabilities\n2. **Content Exploration**: Use READ-ONLY operations to explore available data\n3. **Question Generation**: Create 10 complex, realistic questions\n4. **Answer Verification**: Solve each question yourself to verify answers\n\n#### 4.3 Evaluation Requirements\n\nEnsure each question is:\n- **Independent**: Not dependent on other questions\n- **Read-only**: Only non-destructive operations required\n- **Complex**: Requiring multiple tool calls and deep exploration\n- **Realistic**: Based on real use cases humans would care about\n- **Verifiable**: Single, clear answer that can be verified by string comparison\n- **Stable**: Answer won''t change over time\n\n#### 4.4 Output Format\n\nCreate an XML file with this structure:\n\n```xml\n<evaluation>\n  <qa_pair>\n    <question>Find discussions about AI model launches with animal codenames. One model needed a specific safety designation that uses the format ASL-X. What number X was being determined for the model named after a spotted wild cat?</question>\n    <answer>3</answer>\n  </qa_pair>\n<!-- More qa_pairs... -->\n</evaluation>\n```\n\n---\n\n# Reference Files\n\n## 📚 Documentation Library\n\nLoad these resources as needed during development:\n\n### Core MCP Documentation (Load First)\n- **MCP Protocol**: Start with sitemap at `https://modelcontextprotocol.io/sitemap.xml`, then fetch specific pages with `.md` suffix\n- [📋 MCP Best Practices](./reference/mcp_best_practices.md) - Universal MCP guidelines including:\n  - Server and tool naming conventions\n  - Response format guidelines (JSON vs Markdown)\n  - Pagination best practices\n  - Transport selection (streamable HTTP vs stdio)\n  - Security and error handling standards\n\n### SDK Documentation (Load During Phase 1/2)\n- **Python SDK**: Fetch from `https://raw.githubusercontent.com/modelcontextprotocol/python-sdk/main/README.md`\n- **TypeScript SDK**: Fetch from `https://raw.githubusercontent.com/modelcontextprotocol/typescript-sdk/main/README.md`\n\n### Language-Specific Implementation Guides (Load During Phase 2)\n- [🐍 Python Implementation Guide](./reference/python_mcp_server.md) - Complete Python/FastMCP guide with:\n  - Server initialization patterns\n  - Pydantic model examples\n  - Tool registration with `@mcp.tool`\n  - Complete working examples\n  - Quality checklist\n\n- [⚡ TypeScript Implementation Guide](./reference/node_mcp_server.md) - Complete TypeScript guide with:\n  - Project structure\n  - Zod schema patterns\n  - Tool registration with `server.registerTool`\n  - Complete working examples\n  - Quality checklist\n\n### Evaluation Guide (Load During Phase 4)\n- [✅ Evaluation Guide](./reference/evaluation.md) - Complete evaluation creation guide with:\n  - Question creation guidelines\n  - Answer verification strategies\n  - XML format specifications\n  - Example questions and answers\n  - Running an evaluation with the provided scripts\n"},"category":"official","lastSynced":"2026-03-06T03:19:22.587Z","seo":{"title":{"en":"mcp-builder: Guide for Creating High-Quality MCP Servers ...","zh":"MCP服务器开发指南：构建高质量AI代理工具","ja":"MCPサーバー開発ガイド：AIエージェント連携のベストプラクティス","ko":"MCP 서버 개발 가이드: 고품질 AI 에이전트 구축","es":"Guía de Desarrollo MCP Server: Mejores Prácticas para IA ...","fr":"Guide de Développement MCP Server: Bonnes Pratiques pour ...","de":"MCP Server Entwicklung: Best Practices für KI Agenten","pt":"Guia de Configuração do mcp-builder para Servidores MCP","ru":"Настройка mcp-builder для серверов MCP (ИИ Агенты)","ar":"دليل إعداد mcp-builder لخادم MCP"},"description":{"en":"Learn the 4-phase workflow for building MCP servers that integrate APIs with LLMs. This developer guide covers deep research, planning, and implementation fo...","zh":"MCP服务器开发完整指南，涵盖Python FastMCP和Node.js/TypeScript SDK。学习四阶段高质量工作流，从深度研究到工具设计，实现LLM与外部服务的无缝集成。","ja":"Python FastMCPとNode.js/TypeScript SDKを使ったMCPサーバー開発ガイド。4段階の高品質ワークフローでAIエージェントと外部サービスの連携を実現。","ko":"Python FastMCP와 Node.js/TypeScript SDK를 활용한 MCP 서버 개발 가이드. 4단계 고품질 워크플로우로 LLM과 외부 서비스 통합 구현.","es":"Guía técnica para crear servidores MCP de alta calidad en Python (FastMCP) o Node/TypeScript. Aprende a integrar APIs externas y diseñar herramientas efectiv...","fr":"Guide technique pour créer des serveurs MCP de haute qualité en Python (FastMCP) ou Node/TypeScript. Apprenez à intégrer des APIs externes et concevoir des o...","de":"Technische Anleitung zur Entwicklung hochwertiger MCP Server in Python (FastMCP) oder Node/TypeScript. Lernen Sie, externe APIs zu integrieren und effektive ...","pt":"Aprenda a criar servidores MCP de alta qualidade com o mcp-builder, integrando APIs externas em Python ou Node/TypeScript","ru":"Создайте высококачественные серверы MCP с помощью mcp-builder, интегрируя внешние API на Python или Node/TypeScript (ИИ Агенты)","ar":"تعلم كيفية إنشاء خادم MCP عالي الجودة باستخدام mcp-builder، وتكامل واجهات برمجة التطبيقات الخارجية في Python أو Node/TypeScript"},"definition":{"en":"mcp-builder is a specialized guide for developing Model Context Protocol (MCP) servers. It provides a high-level workflow for creating tools that allow Large Language Models to integrate with and operate external APIs and services effectively.","zh":"MCP服务器是遵循模型上下文协议的组件，使大型语言模型能够通过精心设计的工具与外部服务交互。质量衡量标准是LLM完成实际任务的能力，支持Python和Node.js/TypeScript两种开发方式。","ja":"MCPサーバーはモデルコンテキストプロトコルに準拠したコンポーネントで、AIエージェントが外部サービスと連携するためのツールを提供します。品質は実世界タスクの達成度で測定され、PythonとNode.js/TypeScriptをサポート。","ko":"MCP 서버는 모델 컨텍스트 프로토콜을 준수하는 컴포넌트로, LLM이 외부 서비스와 상호작용할 수 있도록 설계된 도구를 제공합니다. 품질은 실제 작업 수행 능력으로 측정되며 Python과 Node.js/TypeScript를 지원합니다.","es":"MCP Builder es una guía especializada para crear servidores del Model Context Protocol que permiten a los agentes de IA interactuar con APIs y servicios externos. Se enfoca en el diseño de herramientas efectivas para Python (FastMCP) y Node.js/TypeScript (MCP SDK).","fr":"MCP Builder est un guide spécialisé pour créer des serveurs Model Context Protocol permettant aux outils IA d''interagir avec des APIs et services externes. Il se concentre sur la conception d''outils efficaces pour Python (FastMCP) et Node.js/TypeScript (MCP SDK).","de":"MCP Builder ist eine spezialisierte Anleitung zur Erstellung von Model Context Protocol Servern, die KI Agenten die Interaktion mit externen APIs und Diensten ermöglicht. Der Fokus liegt auf dem Entwurf effektiver Tools für Python (FastMCP) und Node.js/TypeScript (MCP SDK).","pt":"O mcp-builder é uma ferramenta para criar servidores MCP que habilitam a interação entre LLMs e serviços externos","ru":"mcp-builder - это инструмент для создания серверов MCP, обеспечивающих взаимодействие между LLM и внешними сервисами (ИИ Агенты)","ar":"mcp-builder هو أداة لإنشاء خادم MCP يتيح التفاعل بين النماذج وخدمات خارجية"},"features":{"en":["Guides through a 4-phase MCP server development workflow","Focuses on designing tools for real-world LLM task accomplishment","Covers deep research and planning for API integration","Supports implementation in Python using FastMCP","Supports implementation in Node/TypeScript using the MCP SDK","Emphasizes balancing API coverage with workflow tools"],"zh":["四阶段高质量开发工作流（深度研究、规划、实现、测试）","Python FastMCP框架集成支持","Node.js/TypeScript MCP SDK完整开发指南","API覆盖与工作流工具的平衡设计","LLM实际任务完成度优化策略","外部服务无缝集成最佳实践"],"ja":["4段階の高品質開発ワークフロー（詳細調査、計画、実装、テスト）","Python FastMCPフレームワーク統合サポート","Node.js/TypeScript MCP SDK完全開発ガイド","APIカバレッジとワークフローツールのバランス設計","AIエージェントの実世界タスク達成度最適化","外部サービス連携のベストプラクティス"],"ko":["4단계 고품질 개발 워크플로우（심층 연구, 계획, 구현, 테스트）","Python FastMCP 프레임워크 통합 지원","Node.js/TypeScript MCP SDK 완전 개발 가이드","API 커버리지와 워크플로우 도구의 균형 설계","LLM 실제 작업 수행도 최적화 전략","외부 서비스 연동 베스트 프랙티스"],"es":["Desarrollo con FastMCP para Python y MCP SDK para Node.js/TypeScript","Metodología de 4 fases: investigación, planificación, implementación y pruebas","Diseño de herramientas centrado en workflows reales en lugar de cobertura API","Integración de servicios y APIs externas para agentes de IA","Enfoque en calidad medible por capacidad de completar tareas del mundo real"],"fr":["Développement avec FastMCP pour Python et MCP SDK pour Node.js/TypeScript","Méthodologie en 4 phases: recherche, planification, implémentation et tests","Conception d''outils axée sur les workflows réels plutôt que la couverture API","Intégration de services et APIs externes pour outils IA","Focus sur la qualité mesurée par la capacité à accomplir des tâches réelles"],"de":["Entwicklung mit FastMCP für Python und MCP SDK für Node.js/TypeScript","4-Phasen-Methodik: Forschung, Planung, Implementierung und Testing","Tool-Design fokussiert auf reale Workflows statt API-Abdeckung","Integration externer Services und APIs für KI Agenten","Qualitätsfokus gemessen an der Fähigkeit, reale Aufgaben zu erledigen"],"pt":["Criação de servidores MCP de alta qualidade","Integração com APIs externas em Python ou Node/TypeScript","Suporte ao FastMCP em Python","Suporte ao MCP SDK em Node/TypeScript","Desenvolvimento de ferramentas personalizadas para LLMs"],"ru":["Создание высококачественных серверов MCP","Интеграция с внешними API на Python или Node/TypeScript (ИИ Агенты)","Поддержка FastMCP в Python","Поддержка MCP SDK в Node/TypeScript","Разработка индивидуальных инструментов для LLM"],"ar":["إنشاء خادم MCP عالي الجودة","التكامل مع واجهات برمجة التطبيقات الخارجية في Python أو Node/TypeScript","دعم FastMCP في Python","دعم MCP SDK في Node/TypeScript","تطوير أدوات مخصصة للنماذج"]},"keywords":{"en":["how to use mcp-builder","what is mcp-builder","mcp-builder vs mcp sdk","mcp-builder alternative","mcp-builder install","mcp-builder setup guide","build mcp server python","create mcp server typescript","model context protocol tutorial","fastmcp vs mcp sdk"],"zh":["MCP服务器开发","模型上下文协议","FastMCP Python","MCP SDK Node.js","LLM工具集成","AI代理开发","外部API集成","四阶段工作流"],"ja":["MCPサーバー開発","モデルコンテキストプロトコル","FastMCP Python","MCP SDK Node.js","AIエージェント連携","外部API統合","LLMツール開発","4段階ワークフロー"],"ko":["MCP 서버 개발","모델 컨텍스트 프로토콜","FastMCP Python","MCP SDK Node.js","AI 에이전트 통합","외부 API 연동","LLM 도구 개발","4단계 워크플로우"],"es":["desarrollo servidor MCP","model context protocol guía","fastmcp python tutorial","mcp sdk nodejs","integrar APIs con agentes IA","herramientas para modelos de lenguaje","arquitectura servidor MCP","tutorial typescript mcp"],"fr":["développement serveur MCP","model context protocol guide","fastmcp python tutoriel","mcp sdk nodejs","intégrer APIs avec outils IA","outils pour modèles de langage","architecture serveur MCP","tutoriel typescript mcp"],"de":["mcp server entwicklung","model context protocol anleitung","fastmcp python tutorial","mcp sdk nodejs","apis integrieren mit ki agenten","tools für sprachmodelle","mcp server architektur","typescript mcp tutorial"],"pt":["mcp-builder","servidores MCP","LLMs","integração de APIs","Python","Node/TypeScript","FastMCP","MCP SDK","desenvolvimento de ferramentas"],"ru":["mcp-builder","серверы MCP","ИИ Агенты","LLMs","интеграция API","Python","Node/TypeScript","FastMCP","MCP SDK","разработка инструментов"],"ar":["mcp-builder","خادم MCP","النماذج","تكامل واجهات برمجة التطبيقات","Python","Node/TypeScript","FastMCP","MCP SDK","تطوير الأدوات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers building Model Context Protocol servers to integrate external APIs and services.","zh":"非常适合构建模型上下文协议（MCP）服务器以集成外部API和服务的AI代理开发者。","ja":"外部APIとサービスを統合するモデルコンテキストプロトコル（MCP）サーバーを構築するAIエージェント開発者に最適です。","ko":"외부 API 및 서비스를 통합하기 위해 모델 컨텍스트 프로토콜(MCP) 서버를 구축하는 AI 에이전트 개발자에게 완벽합니다.","es":"Perfect for AI Agent Developers building Model Context Protocol servers to integrate external APIs and services.","fr":"Perfect for AI Agent Developers building Model Context Protocol servers to integrate external APIs and services.","de":"Perfect for AI Agent Developers building Model Context Protocol servers to integrate external APIs and services.","pt":"Ideal para desenvolvedores de Agentes de IA que constroem servidores do Protocolo de Contexto de Modelo (MCP) para integrar APIs e serviços externos.","ru":"Идеально подходит для разработчиков ИИ-агентов, создающих серверы Model Context Protocol (MCP) для интеграции внешних API и сервисов.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يقومون ببناء خوادم بروتوكول سياق النموذج (MCP) لدمج واجهات برمجة التطبيقات والخدمات الخارجية."},"recommendation":{"en":"Enables creation of high-quality MCP servers that bridge LLMs with external services through well-designed tools, supporting both Python (FastMCP) and Node/TypeScript (MCP SDK) implementations for comprehensive API coverage and workflow tool development.","zh":"支持通过精心设计的工具，创建连接LLM与外部服务的高质量MCP服务器，提供Python（FastMCP）和Node/TypeScript（MCP SDK）两种实现方式，以实现全面的API覆盖和工作流工具开发。","ja":"Python（FastMCP）とNode/TypeScript（MCP SDK）の両方の実装をサポートし、包括的なAPIカバレッジとワークフローツールの開発を実現する、よく設計されたツールを通じてLLMと外部サービスを橋渡しする高品質なMCPサーバーの作成を可能にします。","ko":"잘 설계된 도구를 통해 LLM과 외부 서비스를 연결하는 고품질 MCP 서버 생성이 가능하며, 포괄적인 API 커버리지 및 워크플로우 도구 개발을 위해 Python(FastMCP) 및 Node/TypeScript(MCP SDK) 구현을 모두 지원합니다.","es":"Enables creation of high-quality MCP servers that bridge LLMs with external services through well-designed tools, supporting both Python (FastMCP) and Node/TypeScript (MCP SDK) implementations for comprehensive API coverage and workflow tool development.","fr":"Enables creation of high-quality MCP servers that bridge LLMs with external services through well-designed tools, supporting both Python (FastMCP) and Node/TypeScript (MCP SDK) implementations for comprehensive API coverage and workflow tool development.","de":"Enables creation of high-quality MCP servers that bridge LLMs with external services through well-designed tools, supporting both Python (FastMCP) and Node/TypeScript (MCP SDK) implementations for comprehensive API coverage and workflow tool development.","pt":"Permite a criação de servidores MCP de alta qualidade que conectam LLMs a serviços externos por meio de ferramentas bem projetadas, suportando implementações em Python (FastMCP) e Node/TypeScript (MCP SDK) para cobertura abrangente de API e desenvolvimento de ferramentas de fluxo de trabalho.","ru":"Позволяет создавать высококачественные серверы MCP, которые связывают LLM с внешними сервисами через хорошо продуманные инструменты, поддерживая реализации на Python (FastMCP) и Node/TypeScript (MCP SDK) для комплексного покрытия API и разработки инструментов workflow.","ar":"يتيح إنشاء خوادم MCP عالية الجودة تربط نماذج اللغة الكبيرة (LLMs) بالخدمات الخارجية من خلال أدوات مصممة جيدًا، مع دعم تطبيقات Python (FastMCP) وNode/TypeScript (MCP SDK) لتغطية شاملة لواجهة برمجة التطبيقات وتطوير أدوات سير العمل."},"useCases":{"en":["Building Python-based MCP servers using FastMCP","Developing Node/TypeScript MCP servers with MCP SDK","Integrating external APIs with LLM capabilities","Creating workflow tools for AI agent ecosystems"],"zh":["使用FastMCP构建基于Python的MCP服务器","使用MCP SDK开发Node/TypeScript MCP服务器","将外部API与LLM功能集成","为AI代理生态系统创建工作流工具"],"ja":["FastMCPを使用したPythonベースのMCPサーバーの構築","MCP SDKを使用したNode/TypeScript MCPサーバーの開発","外部APIとLLM機能の統合","AIエージェントエコシステムのためのワークフローツールの作成"],"ko":["FastMCP를 사용한 Python 기반 MCP 서버 구축","MCP SDK를 사용한 Node/TypeScript MCP 서버 개발","외부 API와 LLM 기능 통합","AI 에이전트 생태계를 위한 워크플로우 도구 생성"],"es":["Building Python-based MCP servers using FastMCP","Developing Node/TypeScript MCP servers with MCP SDK","Integrating external APIs with LLM capabilities","Creating workflow tools for AI agent ecosystems"],"fr":["Building Python-based MCP servers using FastMCP","Developing Node/TypeScript MCP servers with MCP SDK","Integrating external APIs with LLM capabilities","Creating workflow tools for AI agent ecosystems"],"de":["Building Python-based MCP servers using FastMCP","Developing Node/TypeScript MCP servers with MCP SDK","Integrating external APIs with LLM capabilities","Creating workflow tools for AI agent ecosystems"],"pt":["Construção de servidores MCP baseados em Python usando FastMCP","Desenvolvimento de servidores MCP Node/TypeScript com MCP SDK","Integração de APIs externas com capacidades de LLM","Criação de ferramentas de fluxo de trabalho para ecossistemas de agentes de IA"],"ru":["Создание серверов MCP на основе Python с использованием FastMCP","Разработка серверов MCP Node/TypeScript с MCP SDK","Интеграция внешних API с возможностями LLM","Создание инструментов workflow для экосистем ИИ-агентов"],"ar":["بناء خوادم MCP تعتمد على Python باستخدام FastMCP","تطوير خوادم MCP بـ Node/TypeScript باستخدام MCP SDK","دمج واجهات برمجة التطبيقات الخارجية مع إمكانات نماذج اللغة الكبيرة (LLMs)","إنشاء أدوات سير العمل لأنظمة وكلاء الذكاء الاصطناعي"]},"limitations":{"en":["Requires deep research and planning phase","Needs understanding of modern MCP design principles","Must balance API coverage versus workflow tools"],"zh":["需要深入的研究和规划阶段","需要理解现代MCP设计原则","必须在API覆盖和工作流工具之间取得平衡"],"ja":["深い研究と計画段階が必要","現代のMCP設計原則の理解が必要","APIカバレッジとワークフローツールのバランスを取る必要がある"],"ko":["심층적인 연구 및 계획 단계 필요","현대 MCP 설계 원칙에 대한 이해 필요","API 커버리지와 워크플로우 도구 간의 균형 유지 필요"],"es":["Requires deep research and planning phase","Needs understanding of modern MCP design principles","Must balance API coverage versus workflow tools"],"fr":["Requires deep research and planning phase","Needs understanding of modern MCP design principles","Must balance API coverage versus workflow tools"],"de":["Requires deep research and planning phase","Needs understanding of modern MCP design principles","Must balance API coverage versus workflow tools"],"pt":["Requer uma fase profunda de pesquisa e planejamento","Necessita de compreensão dos princípios modernos de design MCP","Deve equilibrar a cobertura de API em relação às ferramentas de fluxo de trabalho"],"ru":["Требует глубокой фазы исследования и планирования","Необходимо понимание современных принципов проектирования MCP","Необходимо балансировать покрытие API и инструменты workflow"],"ar":["يتطلب مرحلة بحث وتخطيط عميقة","يحتاج إلى فهم مبادئ تصميم MCP الحديثة","يجب الموازنة بين تغطية واجهة برمجة التطبيقات وأدوات سير العمل"]},"version":4},"contentHash":"0f4592dcb53cf2b5d6b7febee6b4152018b565551a1c29e3c612f57b218ab295","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":80}');
