INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/mcp-builder', 'mcp-builder', 'anthropics', 'skills', 'official', 'mcp-builder anthropics skills official agent-skills mcp-builder is a guide for developers creating MCP (Model Context Protocol) servers that enable LLMs to interact with external services. It provides a structured workflow for building high-quality tools in Python or Node/TypeScript. MCP服务器开发专业指南，提供Python（FastMCP）和Node.js/TypeScript（MCP SDK）两种实现方式。通过四阶段高质量工作流，帮助开发者创建能够使LLM完成实际任务的MCP工具。 Python（FastMCP）とNode.js/TypeScript（MCP SDK）を使ったMCPサーバー開発ガイド。4段階のワークフローでAIエージェントが実世界のタスクを遂行できる高品質ツールを構築。 Python(FastMCP)와 Node.js/TypeScript(MCP SDK)를 이용한 MCP 서버 개발 가이드. 4단계 워크플로우를 통해 LLM이 실제 작업을 수행할 수 있는 고품질 도구 구축. Guía completa para desarrollar servidores MCP que permiten a los modelos de lenguaje interactuar con servicios externos mediante herramientas bien diseñadas. Cubre Python con FastMCP y Node.js/TypeScript con el SDK oficial. Guide complet pour développer des serveurs MCP permettant aux modèles de langage d''interagir avec des services externes via des outils bien conçus. Couvre Python avec FastMCP et Node.js/TypeScript avec le SDK officiel. Umfassende Anleitung zur Entwicklung von MCP Servern, die Sprachmodellen die Interaktion mit externen Diensten über gut gestaltete Tools ermöglicht. Behandelt Python mit FastMCP und Node.js/TypeScript mit dem offiziellen SDK. O mcp-builder é uma ferramenta para criar servidores MCP que permitem que LLMs interajam com serviços externos. Aprenda a configurá-lo para Python ou Node/TypeScript mcp-builder - это инструмент для создания серверов MCP, позволяющих LLM взаимодействовать с внешними сервисами. Узнайте, как настроить его для Python или Node/TypeScript (ИИ Агенты) mcp-builder هو أداة لإنشاء خادم MCP يسمح للنماذج بالتفاعل مع الخدمات الخارجية. تعلم كيفية إعداده لPython أو Node/TypeScript how to use mcp-builder what is mcp-builder mcp-builder vs mcp sdk mcp-builder alternative mcp-builder install mcp-builder setup guide build mcp server python create mcp server typescript model context protocol tutorial fastmcp vs mcp sdk MCP服务器开发 模型上下文协议 FastMCP Python MCP SDK Node.js LLM工具集成 AI代理开发 外部API集成 四阶段工作流 Guides through a 4-phase MCP server development workflow Focuses on designing tools for real-world LLM task accomplishment Covers deep research and planning for API integration Supports implementation in Python using FastMCP Supports implementation in Node/TypeScript using the MCP SDK Emphasizes balancing API coverage with workflow tools mcp-builder is a specialized guide for developing Model Context Protocol (MCP) servers. It provides a high-level workflow for creating tools that allow Large Language Models to integrate with and operate external APIs and services effectively.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/pdf', 'official', 'anthropics', 'skills', 'anthropics/skills', 'pdf', 85097, 8974, 80, '2026-03-06T03:11:21Z', '2026-03-06T03:20:17.677Z', '9f78b8359fbd4943ad260a7a1e436e5a96503406d6c34e99f69223d647d85b9c', '{"id":"anthropics/skills/pdf","name":"pdf","description":{"en":"This AI Agent skill enables developers to programmatically manipulate PDF files using Python. It provides capabilities for text extraction, document splitting/merging, and form handling, primarily through the PyPDF library for backend automation tasks.","zh":"该AI代理技能提供完整的PDF处理能力，包括使用Python PyPDF库进行文本提取、页面操作、文档合并拆分，以及通过OCR使扫描文档可搜索。","ja":"このAIエージェントスキルは、PythonのPyPDFライブラリを使用したテキスト抽出、ページ操作、文書結合・分割、OCRによるスキャン文書の検索可能化など、完全なPDF処理機能を提供します。","ko":"이 AI 에이전트 스킬은 Python PyPDF 라이브러리를 사용한 텍스트 추출, 페이지 조작, 문서 병합/분할, OCR을 통한 스캔 문서 검색 가능화 등 완전한 PDF 처리 기능을 제공합니다.","es":"Esta habilidad de agente IA permite automatizar operaciones esenciales de procesamiento de PDFs. Utiliza bibliotecas Python como PyPDF para leer, extraer texto, combinar archivos y realizar OCR en documentos escaneados mediante comandos CLI.","fr":"Cette compétence d''agent IA permet d''automatiser les opérations essentielles de traitement PDF. Utilise des bibliothèques Python comme PyPDF pour lire, extraire du texte, fusionner des fichiers et effectuer une OCR sur des documents scannés via des commandes CLI.","de":"Diese KI-Agenten Fähigkeit automatisiert essentielle PDF-Verarbeitungsvorgänge. Nutzt Python-Bibliotheken wie PyPDF zum Lesen, Textextrahieren, Dateien kombinieren und zur OCR auf gescannten Dokumenten über CLI-Befehle.","pt":"Esta skill permite que Agentes IA realizem operações avançadas de processamento de PDFs. Utilize a biblioteca PyPDF em Python para extrair texto, manipular páginas, preencher formulários e aplicar criptografia em arquivos PDF.","ru":"Этот навык позволяет ИИ Агентам выполнять расширенные операции обработки PDF. Используйте библиотеку PyPDF в Python для извлечения текста, управления страницами, заполнения форм и применения шифрования PDF-файлов.","ar":"تتيح هذه المهارة لعوامل الذكاء الاصطناعي إجراء عمليات معالجة متقدمة لملفات PDF. استخدم مكتبة PyPDF في Python لاستخراج النص، وإدارة الصفحات، وملء النماذج، وتطبيق التشفير على ملفات PDF."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"pdf","description":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multiple PDFs into one, splitting PDFs apart, rotating pages, adding watermarks, creating new PDFs, filling PDF forms, encrypting/decrypting PDFs, extracting images, and OCR on scanned PDFs to make them searchable. If the user mentions a .pdf file or asks to produce one, use this skill.","bodyPreview":"# PDF Processing Guide\n\n## Overview\n\nThis guide covers essential PDF processing operations using Python libraries and command-line tools. For advanced features, JavaScript libraries, and detailed examples, see REFERENCE.md. If you need to fill out a PDF form, read FORMS.md and follow its instructions.\n\n## Quick Start\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Read a PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"Pages: {len(reader.pages)}\")\n\n# Extract text\ntext = \"\"\nfor page in reader.","body":"# PDF Processing Guide\n\n## Overview\n\nThis guide covers essential PDF processing operations using Python libraries and command-line tools. For advanced features, JavaScript libraries, and detailed examples, see REFERENCE.md. If you need to fill out a PDF form, read FORMS.md and follow its instructions.\n\n## Quick Start\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Read a PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"Pages: {len(reader.pages)}\")\n\n# Extract text\ntext = \"\"\nfor page in reader.pages:\n    text += page.extract_text()\n```\n\n## Python Libraries\n\n### pypdf - Basic Operations\n\n#### Merge PDFs\n```python\nfrom pypdf import PdfWriter, PdfReader\n\nwriter = PdfWriter()\nfor pdf_file in [\"doc1.pdf\", \"doc2.pdf\", \"doc3.pdf\"]:\n    reader = PdfReader(pdf_file)\n    for page in reader.pages:\n        writer.add_page(page)\n\nwith open(\"merged.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n#### Split PDF\n```python\nreader = PdfReader(\"input.pdf\")\nfor i, page in enumerate(reader.pages):\n    writer = PdfWriter()\n    writer.add_page(page)\n    with open(f\"page_{i+1}.pdf\", \"wb\") as output:\n        writer.write(output)\n```\n\n#### Extract Metadata\n```python\nreader = PdfReader(\"document.pdf\")\nmeta = reader.metadata\nprint(f\"Title: {meta.title}\")\nprint(f\"Author: {meta.author}\")\nprint(f\"Subject: {meta.subject}\")\nprint(f\"Creator: {meta.creator}\")\n```\n\n#### Rotate Pages\n```python\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\npage = reader.pages[0]\npage.rotate(90)  # Rotate 90 degrees clockwise\nwriter.add_page(page)\n\nwith open(\"rotated.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### pdfplumber - Text and Table Extraction\n\n#### Extract Text with Layout\n```python\nimport pdfplumber\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for page in pdf.pages:\n        text = page.extract_text()\n        print(text)\n```\n\n#### Extract Tables\n```python\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for i, page in enumerate(pdf.pages):\n        tables = page.extract_tables()\n        for j, table in enumerate(tables):\n            print(f\"Table {j+1} on page {i+1}:\")\n            for row in table:\n                print(row)\n```\n\n#### Advanced Table Extraction\n```python\nimport pandas as pd\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    all_tables = []\n    for page in pdf.pages:\n        tables = page.extract_tables()\n        for table in tables:\n            if table:  # Check if table is not empty\n                df = pd.DataFrame(table[1:], columns=table[0])\n                all_tables.append(df)\n\n# Combine all tables\nif all_tables:\n    combined_df = pd.concat(all_tables, ignore_index=True)\n    combined_df.to_excel(\"extracted_tables.xlsx\", index=False)\n```\n\n### reportlab - Create PDFs\n\n#### Basic PDF Creation\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.pdfgen import canvas\n\nc = canvas.Canvas(\"hello.pdf\", pagesize=letter)\nwidth, height = letter\n\n# Add text\nc.drawString(100, height - 100, \"Hello World!\")\nc.drawString(100, height - 120, \"This is a PDF created with reportlab\")\n\n# Add a line\nc.line(100, height - 140, 400, height - 140)\n\n# Save\nc.save()\n```\n\n#### Create PDF with Multiple Pages\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak\nfrom reportlab.lib.styles import getSampleStyleSheet\n\ndoc = SimpleDocTemplate(\"report.pdf\", pagesize=letter)\nstyles = getSampleStyleSheet()\nstory = []\n\n# Add content\ntitle = Paragraph(\"Report Title\", styles[''Title''])\nstory.append(title)\nstory.append(Spacer(1, 12))\n\nbody = Paragraph(\"This is the body of the report. \" * 20, styles[''Normal''])\nstory.append(body)\nstory.append(PageBreak())\n\n# Page 2\nstory.append(Paragraph(\"Page 2\", styles[''Heading1'']))\nstory.append(Paragraph(\"Content for page 2\", styles[''Normal'']))\n\n# Build PDF\ndoc.build(story)\n```\n\n#### Subscripts and Superscripts\n\n**IMPORTANT**: Never use Unicode subscript/superscript characters (₀₁₂₃₄₅₆₇₈₉, ⁰¹²³⁴⁵⁶⁷⁸⁹) in ReportLab PDFs. The built-in fonts do not include these glyphs, causing them to render as solid black boxes.\n\nInstead, use ReportLab''s XML markup tags in Paragraph objects:\n```python\nfrom reportlab.platypus import Paragraph\nfrom reportlab.lib.styles import getSampleStyleSheet\n\nstyles = getSampleStyleSheet()\n\n# Subscripts: use <sub> tag\nchemical = Paragraph(\"H<sub>2</sub>O\", styles[''Normal''])\n\n# Superscripts: use <super> tag\nsquared = Paragraph(\"x<super>2</super> + y<super>2</super>\", styles[''Normal''])\n```\n\nFor canvas-drawn text (not Paragraph objects), manually adjust font the size and position rather than using Unicode subscripts/superscripts.\n\n## Command-Line Tools\n\n### pdftotext (poppler-utils)\n```bash\n# Extract text\npdftotext input.pdf output.txt\n\n# Extract text preserving layout\npdftotext -layout input.pdf output.txt\n\n# Extract specific pages\npdftotext -f 1 -l 5 input.pdf output.txt  # Pages 1-5\n```\n\n### qpdf\n```bash\n# Merge PDFs\nqpdf --empty --pages file1.pdf file2.pdf -- merged.pdf\n\n# Split pages\nqpdf input.pdf --pages . 1-5 -- pages1-5.pdf\nqpdf input.pdf --pages . 6-10 -- pages6-10.pdf\n\n# Rotate pages\nqpdf input.pdf output.pdf --rotate=+90:1  # Rotate page 1 by 90 degrees\n\n# Remove password\nqpdf --password=mypassword --decrypt encrypted.pdf decrypted.pdf\n```\n\n### pdftk (if available)\n```bash\n# Merge\npdftk file1.pdf file2.pdf cat output merged.pdf\n\n# Split\npdftk input.pdf burst\n\n# Rotate\npdftk input.pdf rotate 1east output rotated.pdf\n```\n\n## Common Tasks\n\n### Extract Text from Scanned PDFs\n```python\n# Requires: pip install pytesseract pdf2image\nimport pytesseract\nfrom pdf2image import convert_from_path\n\n# Convert PDF to images\nimages = convert_from_path(''scanned.pdf'')\n\n# OCR each page\ntext = \"\"\nfor i, image in enumerate(images):\n    text += f\"Page {i+1}:\\n\"\n    text += pytesseract.image_to_string(image)\n    text += \"\\n\\n\"\n\nprint(text)\n```\n\n### Add Watermark\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Create watermark (or load existing)\nwatermark = PdfReader(\"watermark.pdf\").pages[0]\n\n# Apply to all pages\nreader = PdfReader(\"document.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    page.merge_page(watermark)\n    writer.add_page(page)\n\nwith open(\"watermarked.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### Extract Images\n```bash\n# Using pdfimages (poppler-utils)\npdfimages -j input.pdf output_prefix\n\n# This extracts all images as output_prefix-000.jpg, output_prefix-001.jpg, etc.\n```\n\n### Password Protection\n```python\nfrom pypdf import PdfReader, PdfWriter\n\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    writer.add_page(page)\n\n# Add password\nwriter.encrypt(\"userpassword\", \"ownerpassword\")\n\nwith open(\"encrypted.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n## Quick Reference\n\n| Task | Best Tool | Command/Code |\n|------|-----------|--------------|\n| Merge PDFs | pypdf | `writer.add_page(page)` |\n| Split PDFs | pypdf | One page per file |\n| Extract text | pdfplumber | `page.extract_text()` |\n| Extract tables | pdfplumber | `page.extract_tables()` |\n| Create PDFs | reportlab | Canvas or Platypus |\n| Command line merge | qpdf | `qpdf --empty --pages ...` |\n| OCR scanned PDFs | pytesseract | Convert to image first |\n| Fill PDF forms | pdf-lib or pypdf (see FORMS.md) | See FORMS.md |\n\n## Next Steps\n\n- For advanced pypdfium2 usage, see REFERENCE.md\n- For JavaScript libraries (pdf-lib), see REFERENCE.md\n- If you need to fill out a PDF form, follow the instructions in FORMS.md\n- For troubleshooting guides, see REFERENCE.md\n"},"category":"official","lastSynced":"2026-03-06T03:20:17.677Z","seo":{"title":{"en":"PDF Skill: Python Processing & Manipulation Setup Guide |...","zh":"PDF处理AI代理技能：Python与CLI操作指南","ja":"PDF処理AIエージェントスキル：PythonとCLI操作ガイド","ko":"PDF 처리 AI 에이전트 스킬: Python 및 CLI 작업 가이드","es":"PDF Agent Skill: Guía de Procesamiento con Python y CLI","fr":"Skill Agent PDF : Guide de Traitement avec Python et CLI","de":"PDF Agent Skill: Verarbeitungsanleitung mit Python und CLI","pt":"PDF Skill para Agentes IA: Guia de Configuração e Uso com...","ru":"PDF Skill для ИИ Агентов: Руководство по настройке и испо...","ar":"مهارة PDF لعوامل الذكاء الاصطناعي: دليل الإعداد والاستخدا..."},"description":{"en":"Learn how to use the PDF AI Agent skill for Python-based text extraction, merging, splitting, and form filling with PyPDF. Get code snippets for immediate im...","zh":"学习如何使用AI代理技能处理PDF文件。Python PyPDF库提取文本/表格，合并拆分PDF，添加水印，加密解密，OCR扫描文档。包含代码示例和最佳实践。","ja":"AIエージェントスキルでPDFファイルを処理する方法。PyPDFライブラリを使ったテキスト/表抽出、PDF結合/分割、透かし追加、暗号化/復号、OCR処理。コード例付き。","ko":"AI 에이전트 스킬로 PDF 파일 처리 방법. PyPDF 라이브러리를 사용한 텍스트/표 추출, PDF 병합/분할, 워터마크 추가, 암호화/복호화, OCR 처리. 코드 예제 포함.","es":"Automatiza el procesamiento de PDFs con esta AI Agent Skill. Extrae texto y tablas, combina, divide, rota páginas, añade marcas de agua y más usando PyPDF y ...","fr":"Automatisez le traitement des PDFs avec cette Skill d''Agent IA. Extrayez texte et tableaux, fusionnez, divisez, pivotez des pages, ajoutez des filigranes et ...","de":"Automatisieren Sie die PDF-Verarbeitung mit dieser KI-Agenten Skill. Extrahieren Sie Text und Tabellen, kombinieren, teilen, rotieren Sie Seiten, fügen Sie W...","pt":"Aprenda a usar a skill PDF para Agentes IA. Extraia texto e tabelas, combine ou divida PDFs, rotacione páginas, adicione marcas d''água, preencha formulários ...","ru":"Узнайте, как использовать PDF Skill для ИИ Агентов. Извлекайте текст и таблицы, объединяйте или разделяйте PDF, поворачивайте страницы, добавляйте водяные зн...","ar":"تعلم كيفية استخدام مهارة PDF لعوامل الذكاء الاصطناعي. استخرج النصوص والجداول، ادمج أو قسم ملفات PDF، أدرج الصفحات، أضف علامات مائية، املأ النماذج وقم بتشفير ..."},"definition":{"en":"pdf is an AI Agent skill for programmatically processing Portable Document Format files. It uses Python libraries like PyPDF to perform operations including text extraction, merging multiple PDFs, splitting documents, rotating pages, and filling out interactive forms for backend automation.","zh":"PDF AI代理技能是一个专门处理PDF文件的工具，能够执行文本提取、表格读取、文档合并拆分、页面旋转、水印添加、表单填写、加密解密和OCR光学字符识别等操作。","ja":"PDF AIエージェントスキルは、テキスト抽出、表読み取り、文書結合・分割、ページ回転、透かし追加、フォーム記入、暗号化/復号、OCR光学文字認識などの操作を実行できるPDFファイル処理専用ツールです。","ko":"PDF AI 에이전트 스킬은 텍스트 추출, 표 읽기, 문서 병합/분할, 페이지 회전, 워터마크 추가, 양식 작성, 암호화/복호화, OCR 광학 문자 인식 등의 작업을 수행할 수 있는 PDF 파일 처리 전용 도구입니다.","es":"Una habilidad de agente de IA diseñada para manipular archivos PDF mediante programación. Incluye operaciones como extracción de texto/tablas, combinación y división de PDFs, rotación de páginas, adición de marcas de agua y OCR para documentos escaneados usando Python y herramientas de línea de comandos.","fr":"Une compétence d''agent IA conçue pour manipuler programmatiquement des fichiers PDF. Inclut des opérations comme l''extraction de texte/tableaux, la fusion et la division de PDFs, la rotation de pages, l''ajout de filigranes et l''OCR pour documents scannés en utilisant Python et des outils en ligne de commande.","de":"Eine KI-Agenten Fähigkeit zur programmatischen Manipulation von PDF-Dateien. Beinhaltet Operationen wie Text-/Tabellenextraktion, Kombinieren und Teilen von PDFs, Seitenrotation, Hinzufügen von Wasserzeichen und OCR für gescannte Dokumente mit Python und Command-Line-Tools.","pt":"A skill PDF é uma capacidade integrada a Agentes IA para manipulação programática de documentos PDF. Ela utiliza bibliotecas como PyPDF para Python, permitindo operações como extração de texto, fusão, divisão, rotação de páginas, adição de marcas d''água, preenchimento de formulários e criptografia.","ru":"PDF Skill — это встроенная возможность ИИ Агентов для программной обработки PDF-документов. Она использует такие библиотеки, как PyPDF для Python, и позволяет выполнять операции извлечения текста, объединения, разделения, поворота страниц, добавления водяных знаков, заполнения форм и шифрования.","ar":"مهارة PDF هي قدرة مدمجة في عوامل الذكاء الاصطناعي للمعالجة البرمجية لمستندات PDF. تستخدم مكتبات مثل PyPDF لـ Python، مما يتيح عمليات مثل استخراج النص، الدمج، التقسيم، تدوير الصفحات، إضافة العلامات المائية، ملء النماذج والتشفير."},"features":{"en":["Extracts text and tables from PDFs using PdfReader","Merges multiple PDF documents into one with PdfWriter","Splits PDFs into individual pages or sections","Fills out PDF forms programmatically (requires FORMS.md)","Performs OCR on scanned PDFs to make them searchable","Encrypts and decrypts PDF documents for security"],"zh":["使用PyPDF库提取PDF文本和表格内容","合并多个PDF文档或拆分单个PDF为多个文件","旋转PDF页面和添加水印标识","加密PDF文档和解密受保护文件","对扫描PDF执行OCR使其文本可搜索","填充PDF表单字段和提取嵌入图像"],"ja":["PyPDFライブラリを使用したPDFテキストと表の抽出","複数PDF文書の結合と単一文書の分割","PDFページの回転と透かしの追加","PDF文書の暗号化と保護ファイルの復号","スキャンPDFへのOCR処理による検索可能化","PDFフォームへの入力と埋め込み画像の抽出"],"ko":["PyPDF 라이브러리를 사용한 PDF 텍스트 및 표 추출","여러 PDF 문서 병합 및 단일 문서 분할","PDF 페이지 회전 및 워터마크 추가","PDF 문서 암호화 및 보호 파일 복호화","스캔 PDF에 대한 OCR 처리로 검색 가능화","PDF 양식 작성 및 embedded 이미지 추출"],"es":["Extracción de texto y tablas de PDFs con PyPDF","Combinar y dividir múltiples archivos PDF en uno","Rotar páginas y añadir marcas de agua mediante programación","Realizar OCR en PDFs escaneados para hacerlos buscables","Cifrado y descifrado de documentos PDF","Rellenar formularios PDF automáticamente"],"fr":["Extraction de texte et de tableaux à partir de PDFs avec PyPDF","Fusionner et diviser plusieurs fichiers PDF en un","Pivoter des pages et ajouter des filigranes par programmation","Effectuer une OCR sur des PDFs scannés pour les rendre consultables","Chiffrement et déchiffrement de documents PDF","Remplissage automatique de formulaires PDF"],"de":["Textextraktion und Tabellenextraktion aus PDFs mit PyPDF","Mehrere PDF-Dateien zu einer zusammenführen und teilen","Seiten drehen und Wasserzeichen programmgesteuert hinzufügen","OCR auf gescannten PDFs durchführen, um sie durchsuchbar zu machen","Verschlüsselung und Entschlüsselung von PDF-Dokumenten","PDF-Formulare automatisch ausfüllen"],"pt":["Leitura e extração de texto/tabelas de PDFs usando PdfReader","Combinação e fusão de múltiplos PDFs em um único arquivo com PdfWriter","Divisão de um PDF grande em vários arquivos menores","Rotação de páginas dentro de um documento PDF","Preenchimento de formulários PDF interativos","Criptografia e descriptografia de PDFs para segurança"],"ru":["Чтение и извлечение текста/таблиц из PDF с помощью PdfReader","Объединение и слияние нескольких PDF в один файл с помощью PdfWriter","Разделение большого PDF на несколько меньших файлов","Поворот страниц внутри PDF-документа","Заполнение интерактивных PDF-форм","Шифрование и дешифрование PDF для безопасности"],"ar":["قراءة واستخراج النصوص/الجداول من ملفات PDF باستخدام PdfReader","دمج ودمج عدة ملفات PDF في ملف واحد باستخدام PdfWriter","تقسيم ملف PDF كبير إلى عدة ملفات أصغر","تدوير الصفحات داخل مستند PDF","ملء نماذج PDF التفاعلية","تشفير وفك تشفير ملفات PDF للأمان"]},"keywords":{"en":["how to extract text from pdf python","pdf vs pypdf library","merge multiple pdfs into one","pdf skill install guide","fill pdf forms programmatically","python pdf ocr tutorial","split pdf document pages","what is pypdf used for","encrypt decrypt pdf python","ai agent pdf processing"],"zh":["PDF文本提取Python","合并PDF文件CLI","PDF OCR扫描文档","PyPDF库使用教程","PDF加密解密方法","AI代理处理PDF","PDF表单填写技术","拆分PDF文档指南"],"ja":["PDFテキスト抽出Python","PDF結合CLI","PDF OCRスキャン文書","PyPDFライブラリチュートリアル","PDF暗号化復号方法","AIエージェントPDF処理","PDFフォーム記入技術","PDF分割ガイド"],"ko":["PDF 텍스트 추출 Python","PDF 병합 CLI","PDF OCR 스캔 문서","PyPDF 라이브러리 튜토리얼","PDF 암호화 복호화 방법","AI 에이전트 PDF 처리","PDF 양식 작성 기술","PDF 분할 가이드"],"es":["procesamiento pdf python","extraer texto pdf pypdf","combinar pdfs agente ia","ocr pdf escaneado python","dividir pdf línea de comandos","rellenar formularios pdf automático","herramientas cli para pdf","criptografía pdf python"],"fr":["traitement pdf python","extraire texte pdf pypdf","fusionner pdfs agent ia","ocr pdf scanné python","diviser pdf ligne de commande","remplir formulaires pdf automatique","outils cli pour pdf","cryptographie pdf python"],"de":["pdf verarbeitung python","text extrahieren pdf pypdf","pdfs zusammenführen ki agent","ocr gescanntes pdf python","pdf teilen kommandozeile","pdf formulare automatisch ausfüllen","cli tools für pdf","pdf verschlüsselung python"],"pt":["skill pdf agente ia","processar pdf python","extrair texto pdf pypdf","combinar pdfs","preencher formulário pdf","criptografar pdf python","pypdf tutorial","manipular pdf programaticamente"],"ru":["pdf skill ии агенты","обработка pdf python","извлечь текст pdf pypdf","объединить pdf файлы","заполнить форму pdf","зашифровать pdf python","pypdf руководство","программно управлять pdf"],"ar":["مهارة pdf عوامل الذكاء الاصطناعي","معالجة pdf بيثون","استخراج نص pdf pypdf","دمج ملفات pdf","ملء نموذج pdf","تشفير pdf بيثون","برنامج pypdf تعليمي","معالجة pdf برمجياً"]}},"agentAnalysis":{"suitability":{"en":"Essential for Document Processing Agents handling text extraction, form manipulation, and PDF transformation tasks.","zh":"对于处理文本提取、表单操作和PDF转换任务的文档处理AI代理至关重要。","ja":"テキスト抽出、フォーム操作、PDF変換タスクを扱う文書処理エージェントにとって不可欠です。","ko":"텍스트 추출, 양식 조작 및 PDF 변환 작업을 처리하는 문서 처리 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Procesamiento de Documentos que manejan tareas de extracción de texto, manipulación de formularios y transformación de PDF.","fr":"Essentiel pour les Agents de Traitement de Documents gérant les tâches d''extraction de texte, de manipulation de formulaires et de transformation de PDF.","de":"Essenziell für Dokumentenverarbeitungs-Agenten, die Aufgaben der Textextraktion, Formularmanipulation und PDF-Transformation bearbeiten.","pt":"Essencial para Agentes de Processamento de Documentos que lidam com tarefas de extração de texto, manipulação de formulários e transformação de PDF.","ru":"Необходим для Агентов Обработки Документов, выполняющих задачи извлечения текста, манипуляции с формами и преобразования PDF.","ar":"أساسي لوكلاء معالجة المستندات التي تتعامل مع مهام استخراج النص، ومعالجة النماذج، وتحويل ملفات PDF."},"recommendation":{"en":"Enables comprehensive PDF operations including text/tables extraction with PyPDF, OCR processing for scanned documents, PDF merging/splitting, form filling, and encryption/decryption. Provides direct integration with Python libraries like PyPDF for programmatic document control.","zh":"支持全面的PDF操作，包括使用PyPDF进行文本/表格提取、针对扫描文档的OCR处理、PDF合并/拆分、表单填写以及加密/解密。通过与PyPDF等Python库的直接集成，实现程序化文档控制。","ja":"PyPDFを使用したテキスト/表の抽出、スキャン文書のOCR処理、PDFの結合/分割、フォーム入力、暗号化/復号化を含む包括的なPDF操作を可能にします。PyPDFなどのPythonライブラリとの直接統合により、プログラムによる文書制御を提供します。","ko":"PyPDF를 사용한 텍스트/표 추출, 스캔 문서에 대한 OCR 처리, PDF 병합/분할, 양식 작성 및 암호화/복호화를 포함한 포괄적인 PDF 작업을 가능하게 합니다. PyPDF와 같은 Python 라이브러리와의 직접 통합을 통해 프로그램 방식의 문서 제어를 제공합니다.","es":"Permite operaciones integrales de PDF que incluyen extracción de texto/tablas con PyPDF, procesamiento OCR para documentos escaneados, fusión/división de PDF, llenado de formularios y cifrado/descifrado. Proporciona integración directa con bibliotecas de Python como PyPDF para el control programático de documentos.","fr":"Permet des opérations PDF complètes incluant l''extraction de texte/tableaux avec PyPDF, le traitement OCR pour les documents numérisés, la fusion/division de PDF, le remplissage de formulaires et le chiffrement/déchiffrement. Fournit une intégration directe avec des bibliothèques Python comme PyPDF pour le contrôle programmatique des documents.","de":"Ermöglicht umfassende PDF-Operationen, einschließlich der Extraktion von Text/Tabellen mit PyPDF, OCR-Verarbeitung für gescannte Dokumente, PDF-Zusammenführung/-Teilung, Formularausfüllung und Verschlüsselung/Entschlüsselung. Bietet direkte Integration mit Python-Bibliotheken wie PyPDF für die programmatische Dokumentensteuerung.","pt":"Permite operações abrangentes em PDF, incluindo extração de texto/tabelas com PyPDF, processamento OCR para documentos digitalizados, fusão/divisão de PDF, preenchimento de formulários e criptografia/descriptografia. Fornece integração direta com bibliotecas Python como PyPDF para controle programático de documentos.","ru":"Обеспечивает комплексные операции с PDF, включая извлечение текста/таблиц с помощью PyPDF, обработку OCR для сканированных документов, объединение/разделение PDF, заполнение форм, а также шифрование/дешифрование. Обеспечивает прямую интеграцию с библиотеками Python, такими как PyPDF, для программного управления документами.","ar":"يتيح عمليات PDF شاملة بما في ذلك استخراج النص/الجداول باستخدام PyPDF، ومعالجة OCR للمستندات الممسوحة ضوئيًا، ودمج/تقسيم PDF، وملء النماذج، والتشفير/فك التشفير. يوفر تكاملاً مباشرًا مع مكتبات Python مثل PyPDF للتحكم البرمجي في المستندات."},"useCases":{"en":["Extracting structured text and tables from research papers","Merging multiple PDF reports into consolidated documents","Performing OCR on scanned PDFs to create searchable text","Filling and processing PDF forms automatically","Encrypting sensitive documents with password protection"],"zh":["从研究论文中提取结构化文本和表格","将多个PDF报告合并为统一文档","对扫描的PDF执行OCR以创建可搜索文本","自动填写和处理PDF表单","通过密码保护加密敏感文档"],"ja":["研究論文から構造化されたテキストと表を抽出する","複数のPDFレポートを統合文書に結合する","スキャンされたPDFに対してOCRを実行し、検索可能なテキストを作成する","PDFフォームを自動的に記入および処理する","パスワード保護で機密文書を暗号化する"],"ko":["연구 논문에서 구조화된 텍스트와 표 추출","여러 PDF 보고서를 통합 문서로 병합","스캔된 PDF에 OCR 수행하여 검색 가능한 텍스트 생성","PDF 양식을 자동으로 작성 및 처리","비밀번호 보호로 민감한 문서 암호화"],"es":["Extracción de texto estructurado y tablas de artículos de investigación","Combinación de múltiples informes PDF en documentos consolidados","Realización de OCR en PDF escaneados para crear texto buscable","Llenado y procesamiento de formularios PDF automáticamente","Cifrado de documentos sensibles con protección por contraseña"],"fr":["Extraction de texte structuré et de tableaux à partir d''articles de recherche","Fusion de plusieurs rapports PDF en documents consolidés","Réalisation d''OCR sur des PDF numérisés pour créer du texte consultable","Remplissage et traitement automatique de formulaires PDF","Chiffrement de documents sensibles avec protection par mot de passe"],"de":["Extrahieren von strukturiertem Text und Tabellen aus Forschungsarbeiten","Zusammenführen mehrerer PDF-Berichte zu konsolidierten Dokumenten","Durchführen von OCR auf gescannten PDFs, um durchsuchbaren Text zu erstellen","Automatisches Ausfüllen und Verarbeiten von PDF-Formularen","Verschlüsseln sensibler Dokumente mit Passwortschutz"],"pt":["Extrair texto estruturado e tabelas de artigos de pesquisa","Fundir múltiplos relatórios PDF em documentos consolidados","Executar OCR em PDFs digitalizados para criar texto pesquisável","Preencher e processar formulários PDF automaticamente","Criptografar documentos confidenciais com proteção por senha"],"ru":["Извлечение структурированного текста и таблиц из научных статей","Объединение нескольких отчетов в формате PDF в консолидированные документы","Выполнение OCR для отсканированных PDF-файлов для создания доступного для поиска текста","Автоматическое заполнение и обработка форм PDF","Шифрование конфиденциальных документов с защитой паролем"],"ar":["استخراج النص المنظم والجداول من أوراق البحث","دمج تقارير PDF متعددة في مستندات موحدة","إجراء OCR على ملفات PDF الممسوحة ضوئيًا لإنشاء نص قابل للبحث","ملء نماذج PDF ومعالجتها تلقائيًا","تشفير المستندات الحساسة بحماية كلمة المرور"]},"limitations":{"en":["Requires PyPDF library installation","OCR functionality depends on additional dependencies","Form filling requires specific PDF form structure","Python environment required for full functionality"],"zh":["需要安装PyPDF库","OCR功能依赖于额外的依赖项","表单填写需要特定的PDF表单结构","完整功能需要Python环境"],"ja":["PyPDFライブラリのインストールが必要","OCR機能は追加の依存関係に依存する","フォーム入力には特定のPDFフォーム構造が必要","完全な機能にはPython環境が必要"],"ko":["PyPDF 라이브러리 설치 필요","OCR 기능은 추가 종속성에 의존함","양식 작성에는 특정 PDF 양식 구조가 필요함","전체 기능에는 Python 환경이 필요함"],"es":["Requiere la instalación de la biblioteca PyPDF","La funcionalidad OCR depende de dependencias adicionales","El llenado de formularios requiere una estructura de formulario PDF específica","Se requiere un entorno Python para la funcionalidad completa"],"fr":["Nécessite l''installation de la bibliothèque PyPDF","La fonctionnalité OCR dépend de dépendances supplémentaires","Le remplissage de formulaires nécessite une structure de formulaire PDF spécifique","Un environnement Python est requis pour une fonctionnalité complète"],"de":["Erfordert die Installation der PyPDF-Bibliothek","Die OCR-Funktionalität hängt von zusätzlichen Abhängigkeiten ab","Das Ausfüllen von Formularen erfordert eine spezifische PDF-Formularstruktur","Python-Umgebung für vollständige Funktionalität erforderlich"],"pt":["Requer instalação da biblioteca PyPDF","A funcionalidade OCR depende de dependências adicionais","O preenchimento de formulários requer uma estrutura específica de formulário PDF","Ambiente Python necessário para funcionalidade completa"],"ru":["Требует установки библиотеки PyPDF","Функциональность OCR зависит от дополнительных зависимостей","Заполнение форм требует определенной структуры формы PDF","Для полной функциональности требуется среда Python"],"ar":["يتطلب تثبيت مكتبة PyPDF","تعتمد وظيفة OCR على تبعيات إضافية","يتطلب ملء النماذج بنية نموذج PDF محددة","يتطلب بيئة Python للوظائف الكاملة"]},"version":4},"contentHash":"9f78b8359fbd4943ad260a7a1e436e5a96503406d6c34e99f69223d647d85b9c","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":80}');
