INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/skill-creator', 'skill-creator', 'anthropics', 'skills', 'official', 'skill-creator anthropics skills official agent-skills The skill-creator is an AI agent skill designed for developers to create new skills from scratch and iteratively improve existing ones. It facilitates the entire lifecycle, from drafting a skill to running performance evals and variance analysis for benchmarking. skill-creator是一种用于创建新技能和迭代改进现有技能的AIエージェント技能，支持运行评估和优化 skill-creatorは、新しいスキルを作成し、既存のスキルを改善するためのAIエージェントスキルです。評価の実行や最適化もサポートしています skill-creator는 새로운 스킬을 생성하고 기존 스킬을 개선하는 AI 에이전트 스킬입니다. 평가 실행 및 최적화도 지원합니다 La herramienta skill-creator permite a los desarrolladores crear nuevas habilidades para agentes de IA, iterar sobre las existentes y medir su rendimiento mediante evaluaciones cuantitativas y análisis de varianza utilizando claude-with-access-to-the-skill. L''outil skill-creator permet aux développeurs de créer de nouvelles compétences pour agents IA, d''itérer sur celles existantes et de mesurer leurs performances via des évaluations quantitatives et des analyses de variance en utilisant claude-with-access-to-the-skill. Das Tool skill-creator ermöglicht Entwicklern, neue Fähigkeiten für KI-Agenten zu erstellen, bestehende zu iterieren und ihre Leistung durch quantitative Auswertungen und Varianzanalysen mit claude-with-access-to-the-skill zu messen. O Skill Creator é uma habilidade para criar novas habilidades e melhorá-las iterativamente, utilizando testes e análise de desempenho Skill Creator - это навык для создания новых навыков и их итеративного улучшения, используя тестирование и анализ производительности ИИ Агентов Skill Creator هو مهارة لإنشاء مهارات جديدة وتحسينها باستمرار، باستخدام الاختبارات وتحليل الأداء how to use skill-creator what is skill-creator skill-creator vs manual skill development skill-creator alternative skill-creator install skill-creator setup guide run evals with skill-creator optimize AI agent skills skill-creator benchmark performance AIエージェント开发 skill-creator 创建新技能 修改和优化现有技能 运行评估 claude-with-access-to-the-skill 量化评估 定性评估 Creates new skills from scratch based on user-defined objectives Modifies and improves existing skills through iterative optimization Runs test prompts using ''claude-with-access-to-the-skill'' for validation Conducts qualitative evaluation of skill performance results Drafts and runs quantitative evals for performance benchmarking Optimizes skill descriptions to improve triggering accuracy skill-creator is an AI agent skill used to create new skills, modify and improve existing skills, and measure skill performance. It helps users draft skills, run test prompts, and conduct qualitative and quantitative evaluations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/writing-plans', 'official', 'obra', 'superpowers', 'obra/superpowers', 'writing-plans', 71924, 5546, 80, '2026-03-06T03:26:30Z', '2026-03-06T03:38:57.091Z', '8a9198d4d9efbcad6e019b17c422c182113062c864b6154ec2a3ba2ed0b6b9d0', '{"id":"obra/superpowers/writing-plans","name":"writing-plans","description":{"en":"The writing-plans AI Agent Skill generates detailed technical implementation plans from a specification. It produces bite-sized tasks for developers, specifying files to modify, testing procedures, and documentation, assuming zero prior knowledge of the codebase or domain.","zh":"Writing Plans AI代理技能根据规格要求生成多步骤编码任务的详细实施计划，包括文件修改指南、测试流程和文档要求，帮助零上下文开发者高效完成复杂任务。","ja":"Writing Plans AIエージェントスキルは仕様に基づきマルチステップ開発タスクの詳細な実装計画を生成。ファイル変更ガイド、テストプロセス、ドキュメント要件を含み、コンテキストのない開発者の作業を支援。","ko":"Writing Plans AI 에이전트 스킬은 사양에 따라 다단계 개발 작업의 상세한 구현 계획을 생성. 파일 수정 가이드, 테스트 프로세스, 문서 요구사항을 포함하여 컨텍스트가 없는 개발자의 작업을 지원.","es":"Esta skill de Agente IA genera planes de implementación técnica detallados para tareas multi-paso. Proporciona instrucciones específicas sobre archivos, testing, documentación y estrategias de commits para desarrolladores que necesitan orientación en codebases desconocidos.","fr":"Cette compétence d''Outil IA génère des plans d''implémentation technique détaillés pour des tâches multi-étapes. Fournit des instructions spécifiques sur les fichiers, tests, documentation et stratégies de commits pour développeurs dans des codebases inconnus.","de":"Diese KI-Agenten Skill erstellt detaillierte technische Implementierungspläne für mehrstufige Aufgaben. Liefert spezifische Anweisungen zu Dateien, Testing, Dokumentation und Commit-Strategien für Entwickler in unbekannten Codebasen.","pt":"Gera planos de implementação abrangentes para tarefas de múltiplas etapas, documentando arquivos, código, testes e documentação necessários. Assume um desenvolvedor habilidoso mas sem contexto do codebase, seguindo princípios DRY, YAGNI e TDD.","ru":"Создает комплексные планы реализации для многоэтапных задач, документируя необходимые файлы, код, тесты и документацию. Предполагает опытного разработчика без контекста кодовой базы, следуя принципам DRY, YAGNI и TDD.","ar":"تولّد خطط تنفيذ شاملة لمهام متعددة المراحل، موثقةً الملفات، الكود، الاختبارات، والوثائق المطلوبة. تفترض مطورًا ماهرًا بدون سياق قاعدة الكود، وتتبع مبادئ DRY وYAGNI وTDD."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"writing-plans","description":"Use when you have a spec or requirements for a multi-step task, before touching code","bodyPreview":"# Writing Plans\n\n## Overview\n\nWrite comprehensive implementation plans assuming the engineer has zero context for our codebase and questionable taste. Document everything they need to know: which files to touch for each task, code, testing, docs they might need to check, how to test it. Give them the whole plan as bite-sized tasks. DRY. YAGNI. TDD. Frequent commits.\n\nAssume they are a skilled developer, but know almost nothing about our toolset or problem domain. Assume they don''t know good test","body":"# Writing Plans\n\n## Overview\n\nWrite comprehensive implementation plans assuming the engineer has zero context for our codebase and questionable taste. Document everything they need to know: which files to touch for each task, code, testing, docs they might need to check, how to test it. Give them the whole plan as bite-sized tasks. DRY. YAGNI. TDD. Frequent commits.\n\nAssume they are a skilled developer, but know almost nothing about our toolset or problem domain. Assume they don''t know good test design very well.\n\n**Announce at start:** \"I''m using the writing-plans skill to create the implementation plan.\"\n\n**Context:** This should be run in a dedicated worktree (created by brainstorming skill).\n\n**Save plans to:** `docs/plans/YYYY-MM-DD-<feature-name>.md`\n\n## Bite-Sized Task Granularity\n\n**Each step is one action (2-5 minutes):**\n- \"Write the failing test\" - step\n- \"Run it to make sure it fails\" - step\n- \"Implement the minimal code to make the test pass\" - step\n- \"Run the tests and make sure they pass\" - step\n- \"Commit\" - step\n\n## Plan Document Header\n\n**Every plan MUST start with this header:**\n\n```markdown\n# [Feature Name] Implementation Plan\n\n> **For Claude:** REQUIRED SUB-SKILL: Use superpowers:executing-plans to implement this plan task-by-task.\n\n**Goal:** [One sentence describing what this builds]\n\n**Architecture:** [2-3 sentences about approach]\n\n**Tech Stack:** [Key technologies/libraries]\n\n---\n```\n\n## Task Structure\n\n````markdown\n### Task N: [Component Name]\n\n**Files:**\n- Create: `exact/path/to/file.py`\n- Modify: `exact/path/to/existing.py:123-145`\n- Test: `tests/exact/path/to/test.py`\n\n**Step 1: Write the failing test**\n\n```python\ndef test_specific_behavior():\n    result = function(input)\n    assert result == expected\n```\n\n**Step 2: Run test to verify it fails**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: FAIL with \"function not defined\"\n\n**Step 3: Write minimal implementation**\n\n```python\ndef function(input):\n    return expected\n```\n\n**Step 4: Run test to verify it passes**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: PASS\n\n**Step 5: Commit**\n\n```bash\ngit add tests/path/test.py src/path/file.py\ngit commit -m \"feat: add specific feature\"\n```\n````\n\n## Remember\n- Exact file paths always\n- Complete code in plan (not \"add validation\")\n- Exact commands with expected output\n- Reference relevant skills with @ syntax\n- DRY, YAGNI, TDD, frequent commits\n\n## Execution Handoff\n\nAfter saving the plan, offer execution choice:\n\n**\"Plan complete and saved to `docs/plans/<filename>.md`. Two execution options:**\n\n**1. Subagent-Driven (this session)** - I dispatch fresh subagent per task, review between tasks, fast iteration\n\n**2. Parallel Session (separate)** - Open new session with executing-plans, batch execution with checkpoints\n\n**Which approach?\"**\n\n**If Subagent-Driven chosen:**\n- **REQUIRED SUB-SKILL:** Use superpowers:subagent-driven-development\n- Stay in this session\n- Fresh subagent per task + code review\n\n**If Parallel Session chosen:**\n- Guide them to open new session in worktree\n- **REQUIRED SUB-SKILL:** New session uses superpowers:executing-plans\n"},"category":"official","lastSynced":"2026-03-06T03:38:57.091Z","seo":{"title":{"en":"writing-plans: Generate Zero-Context Dev Implementation P...","zh":"Writing Plans AI代理技能：多步骤任务实施指南","ja":"Writing Plans AIエージェントスキル：マルチステップタスク実装ガイド","ko":"Writing Plans AI 에이전트 스킬: 다단계 작업 구현 가이드","es":"Writing Plans: Guía de Planificación Técnica para Agentes IA","fr":"Writing Plans : Guide des Bonnes Pratiques pour Outils IA","de":"Writing Plans: Best Practices Guide für KI-Agenten","pt":"Writing Plans: Guia de Implementação para Desenvolvedores","ru":"Writing Plans: Руководство по реализации для разработчиков","ar":"Writing Plans: دليل التنفيذ للمطورين"},"description":{"en":"Stop context switching. This AI Agent Skill crafts comprehensive, multi-step dev plans for any spec. It details files, code, testing, and docs needed for eac...","zh":"使用Writing Plans AI代理技能为多步骤编码任务生成详细实施计划。提供文件修改指南、测试方法、文档要求和提交策略，适用于零上下文开发者。","ja":"Writing Plans AIエージェントスキルでマルチステップ開発タスクの詳細な実装計画を作成。ファイル変更ガイド、テスト方法、ドキュメント要件、コミット戦略を提供。コンテキストのない開発者に最適。","ko":"Writing Plans AI 에이전트 스킬로 다단계 개발 작업을 위한 상세한 구현 계획 생성. 파일 수정 가이드, 테스트 방법, 문서 요구사항, 커밋 전략 제공. 컨텍스트가 없는 개발자에게 적합.","es":"Genera planes de implementación detallados para desarrolladores sin contexto del codebase. Especifica archivos, testing, commits y documentación para tareas ...","fr":"Créez des plans d''implémentation détaillés pour développeurs sans contexte du codebase. Spécifiez fichiers, tests, commits et documentation pour tâches techn...","de":"Erstellt detaillierte Implementierungspläne für Entwickler ohne Codebase-Kontext. Spezifiziert Dateien, Testing, Commits und Dokumentation für mehrstufige te...","pt":"Skill de IA para criar planos de implementação técnica detalhados. Especifica arquivos, código, testes e documentação para desenvolvedores sem contexto do co...","ru":"ИИ Агент для создания детальных планов технической реализации. Указывает файлы, код, тесты и документацию для разработчиков без контекста кодовой базы. Следу...","ar":"مهارة الذكاء الاصطناعي لإنشاء خطط تنفيذ فنية مفصلة. تحدد الملفات، الكود، الاختبارات، والوثائق للمطورين بدون سياق قاعدة الكود. تتبع TDD، عمليات commit متكررة."},"definition":{"en":"writing-plans is an AI Agent Skill that creates comprehensive, multi-step implementation plans for developers from a given specification. It meticulously documents every required action, from which files to touch and code to write, to testing and documentation, assuming the engineer has zero context.","zh":"Writing Plans是一种AI代理技能，专门为多步骤编码任务生成全面的实施计划。它提供详细的文件修改指导、测试方法、文档参考和提交策略，遵循DRY、YAGNI和TDD原则，适用于对代码库零上下文的熟练开发者。","ja":"Writing Plansは、マルチステップ開発タスクのための包括的な実装計画を生成するAIエージェントスキルです。ファイル変更ガイド、テスト方法、ドキュメント参照、コミット戦略を提供。DRY、YAGNI、TDD原則に従い、コードベースのコンテキストがない熟練開発者向け。","ko":"Writing Plans는 다단계 개발 작업을 위한 포괄적인 구현 계획을 생성하는 AI 에이전트 스킬입니다. 파일 수정 가이드, 테스트 방법, 문서 참조, 커밋 전략을 제공. DRY, YAGNI, TDD 원칙을 따르며 코드베이스 컨텍스트가 없는 숙련된 개발자에게 적합.","es":"Writing Plans es una skill de Agente IA que crea planes de implementación técnica completos para desarrolladores. Documenta archivos específicos, estrategias de testing, documentación requerida y enfoques de commits frecuentes para tareas multi-paso antes de escribir código.","fr":"Writing Plans est une compétence d''Outil IA qui crée des plans d''implémentation technique complets pour développeurs. Documente les fichiers spécifiques, stratégies de test, documentation requise et approches de commits fréquents pour tâches multi-étapes avant l''écriture de code.","de":"Writing Plans ist eine KI-Agenten Skill, die umfassende technische Implementierungspläne für Entwickler erstellt. Dokumentiert spezifische Dateien, Testing-Strategien, benötigte Dokumentation und Ansätze für häufige Commits bei mehrstufigen Aufgaben vor der Code-Erstellung.","pt":"Uma skill de IA que cria planos de implementação técnica detalhados para desenvolvedores. Documenta arquivos específicos, código, testes, documentação e estratégias de commit para tarefas complexas, assumindo zero contexto do codebase.","ru":"ИИ Агент, который создает детальные планы технической реализации для разработчиков. Документирует конкретные файлы, код, тесты, документацию и стратегии коммитов для сложных задач, предполагая нулевой контекст кодовой базы.","ar":"مهارة ذكاء اصطناعي تُنشئ خطط تنفيذ فنية مفصلة للمطورين. توثق ملفات محددة، كود، اختبارات، وثائق، واستراتيجيات commit للمهام المعقدة، بافتراض عدم وجود سياق لقاعدة الكود."},"features":{"en":["Generates comprehensive multi-step implementation plans from a spec","Documents specific files to modify for each task","Outlines testing procedures and required documentation checks","Assumes zero developer context for the codebase or problem domain","Enforces software principles like DRY, YAGNI, and TDD","Delivers the entire plan as a series of bite-sized tasks"],"zh":["为零上下文开发者生成详细文件修改指南","提供完整的测试流程和实施方法","包含必要的文档参考和要求","遵循DRY、YAGNI和TDD开发原则","推荐频繁提交的小型任务分解策略","适用于多步骤复杂编码任务的规划"],"ja":["コンテキストのない開発者のための詳細なファイル変更ガイド生成","完全なテストプロセスと実装方法の提供","必要なドキュメント参照と要件の包含","DRY、YAGNI、TDD開発原則への準拠","頻繁なコミットのための小型タスク分解戦略の推奨","マルチステップ複雑開発タスクの計画に適応"],"ko":["컨텍스트가 없는 개발자를 위한 상세한 파일 수정 가이드 생성","완전한 테스트 프로세스와 구현 방법 제공","필요한 문서 참조와 요구사항 포함","DRY, YAGNI, TDD 개발 원칙 준수","빈번한 커밋을 위한 소형 작업 분해 전략 권장","다단계 복잡 개발 작업 계획에 적응"],"es":["Identificación de archivos específicos para modificar en cada tarea","Guía de testing exhaustiva para desarrolladores sin contexto del codebase","Estrategias de commits frecuentes siguiendo mejores prácticas","Documentación técnica requerida para cada paso de implementación","Enfoque TDD (Test-Driven Development) para planificación","Aplicación de principios DRY y YAGNI en planificación técnica"],"fr":["Identification des fichiers spécifiques à modifier pour chaque tâche","Guide de test complet pour développeurs sans contexte du codebase","Stratégies de commits fréquents suivant les bonnes pratiques","Documentation technique requise pour chaque étape d''implémentation","Approche TDD (Test-Driven Development) pour la planification","Application des principes DRY et YAGNI en planification technique"],"de":["Identifizierung spezifischer Dateien für jede Aufgabe","Umfassende Testing-Anleitung für Entwickler ohne Codebase-Kontext","Strategien für häufige Commits nach Best Practices","Erforderliche technische Dokumentation für jeden Implementierungsschritt","TDD (Test-Driven Development) Ansatz für die Planung","Anwendung von DRY und YAGNI Prinzipien in technischer Planung"],"pt":["Identificação de arquivos específicos para modificar em cada tarefa","Geração de código e testes seguindo princípios TDD","Documentação de requisitos de teste e verificação","Estruturação de tarefas complexas em subtarefas menores (bite-sized tasks)","Recomendações para commits frequentes e granularidade","Aplicação de princípios DRY e YAGNI no planejamento"],"ru":["Идентификация конкретных файлов для изменения в каждой задаче","Генерация кода и тестов по принципам TDD","Документирование требований к тестированию и проверке","Структурирование сложных задач на более мелкие подзадачи (bite-sized tasks)","Рекомендации по частым коммитам и гранулярности","Применение принципов DRY и YAGNI в планировании"],"ar":["تحديد ملفات محددة للتعديل في كل مهمة","توليد كود واختبارات تتبع مبادئ TDD","توثيق متطلبات الاختبار والتحقق","هيكلة المهام المعقدة إلى مهام فرعية أصغر (bite-sized tasks)","توصيات بعمليات commit متكررة وحبيبية","تطبيق مبادئ DRY وYAGNI في التخطيط"]},"keywords":{"en":["what is writing-plans","how to use writing-plans for development","writing-plans vs manual planning","writing-plans alternative","writing-plans install guide","writing-plans setup for AI agents","AI agent skill for technical specs","generate dev plan from requirements"],"zh":["Writing Plans AI代理","多步骤任务实施计划","零上下文开发指南","DRY YAGNI TDD原则","文件修改指导","测试流程规划","频繁提交策略","开发者任务分解"],"ja":["Writing Plans AIエージェント","マルチステップタスク実装計画","コンテキストなし開発ガイド","DRY YAGNI TDD原則","ファイル変更ガイド","テストプロセス計画","頻繁なコミット戦略","開発者タスク分解"],"ko":["Writing Plans AI 에이전트","다단계 작업 구현 계획","컨텍스트 없음 개발 가이드","DRY YAGNI TDD 원칙","파일 수정 가이드","테스트 프로세스 계획","빈번한 커밋 전략","개발자 작업 분해"],"es":["planificación implementación técnica","agentes IA desarrollo software","guía testing codebase","estrategia commits frecuentes","TDD planificación proyectos","documentación técnica desarrolladores","multi-step task planning","codebase onboarding developers"],"fr":["planification implémentation technique","outils IA développement logiciel","guide testing codebase","stratégie commits fréquents","TDD planification projets","documentation technique développeurs","multi-step task planning","codebase onboarding developers"],"de":["technische Implementierungsplanung","KI-Agenten Softwareentwicklung","Testing Anleitung Codebase","häufige Commits Strategie","TDD Projektplanung","technische Dokumentation Entwickler","multi-step task planning","codebase onboarding developers"],"pt":["planos de implementação técnica","skill IA para desenvolvedores","documentação de codebase","TDD planning","multi-step task planning","ferramentas AI para desenvolvimento","testes unitários automation","frequent commits strategy"],"ru":["планы технической реализации","ИИ Агенты для разработчиков","документирование кодовой базы","TDD планирование","планирование многоэтапных задач","AI инструменты для разработки","автоматизация модульного тестирования","стратегия частых коммитов"],"ar":["خطط التنفيذ الفني","مهارات الذكاء الاصطناعي للمطورين","توثيق قاعدة الكود","تخطيط TDD","تخطيط المهام متعددة المراحل","أدوات الذكاء الاصطناعي للتطوير","أتمتة الاختبارات unit","استراتيجية عمليات commit المتكررة"]}},"agentAnalysis":{"suitability":{"en":"Essential for Development Agents tasked with breaking down complex specs into executable implementation plans.","zh":"适用于负责将复杂规格分解为可执行实施计划的开发代理。","ja":"複雑な仕様を実行可能な実装計画に分解する開発エージェントに不可欠。","ko":"복잡한 사양을 실행 가능한 구현 계획으로 분해하는 개발 에이전트에게 필수적입니다.","es":"Esencial para los Agentes de Desarrollo encargados de descomponer especificaciones complejas en planes de implementación ejecutables.","fr":"Essentiel pour les Agents de Développement chargés de décomposer des spécifications complexes en plans d''implémentation exécutables.","de":"Wesentlich für Entwicklungsmittel, die komplexe Spezifikationen in ausführbare Implementierungspläne aufteilen.","pt":"Essencial para Agentes de Desenvolvimento encarregados de decompor especificações complexas em planos de implementação executáveis.","ru":"Необходим для Агентов Разработки, задача которых — разбивать сложные спецификации на исполнимые планы реализации.","ar":"أساسي لوكلاء التطوير المكلفين بتفصيل المواصفات المعقدة إلى خطط تنفيذية قابلة للتنفيذ."},"recommendation":{"en":"Transforms agents into systematic project planners by generating comprehensive, bite-sized task breakdowns that enforce DRY, YAGNI, and TDD principles. Provides zero-context engineers with detailed file-by-file instructions, testing requirements, and documentation checks.","zh":"通过生成全面、可执行的任务分解，将代理转化为系统的项目规划者，强制实施 DRY、YAGNI 和 TDD 原则。为零上下文工程师提供详细的文件到文件的指令、测试要求和文档检查。","ja":"包括 DRY、YAGNI、TDD 原則を実施する完全で実行可能なタスク分解を生成することで、エージェントを体系的なプロジェクトプランナーに変える。ゼロコンテキストのエンジニアに詳細なファイルバイファイルの指示、テスト要件、およびドキュメントチェックを提供する。","ko":"포괄적이고 실행 가능한 작업 분해를 생성하여 DRY, YAGNI, TDD 원칙을 강제로 구현함으로써 에이전트를 체계적인 프로젝트 계획자로 변환합니다. 파일별 상세 지침, 테스트 요구 사항 및 문서 확인을 제공하여 Zero-Context 엔지니어를 지원합니다.","es":"Transforma a los agentes en planificadores de proyectos sistemáticos al generar desgloses de tareas integrales y en pequeñas porciones que hacen cumplir los principios DRY, YAGNI y TDD. Proporciona a los ingenieros con cero contexto instrucciones detalladas archivo por archivo, requisitos de prueba y controles de documentación.","fr":"Transforme les agents en planificateurs de projets systématiques en générant des décompositions de tâches complètes et en petites parties qui font respecter les principes DRY, YAGNI et TDD. Fournit aux ingénieurs avec zéro contexte des instructions détaillées fichier par fichier, des exigences de test et des contrôles de documentation.","de":"Wandelt die Agenten in systematische Projektplaner um, indem umfassende, portionsweise Aufgabenzerlegungen generiert werden, die die Prinzipien DRY, YAGNI und TDD durchsetzen. Bietet Ingenieuren mit Null-Kontext detaillierte Datei-für-Datei-Anweisungen, Testanforderungen und Dokumentationsprüfungen.","pt":"Transforma agentes em planejadores de projetos sistemáticos, gerando divisões de tarefas abrangentes e de fácil digestão que aplicam os princípios DRY, YAGNI e TDD. Fornece aos engenheiros sem contexto instruções detalhadas arquivo por arquivo, requisitos de teste e verificações de documentação.","ru":"Преобразует агентов в системных планировщиков проектов путем создания комплексных, пошаговых разбиений задач, которые применяют принципы DRY, YAGNI и TDD. Предоставляет инженерам без контекста детальные пофайловые инструкции, требования к тестированию и проверки документации.","ar":"يحول الوكلاء إلى مخططي مشاريع منهجيين من خلال توليد تقسيمات مهام شاملة وسهلة التنفيذ تُطبق مبادئ DRY وYAGNI وTDD. يزود المهندسين الذين يفتقرون إلى السياق بتعليمات مفصلة لكل ملف، ومتطلبات الاختبار، وفحوصات التوثيق."},"useCases":{"en":["Breaking down multi-step requirements into actionable tasks","Generating TDD-focused implementation roadmaps","Documenting file dependencies and testing procedures","Creating commit strategies for complex feature development"],"zh":["将多步骤要求分解为可执行任务","生成 TDD 集中型实现路线图","记录文件依赖关系和测试程序","为复杂功能开发创建提交策略"],"ja":["マルチステップ要件を実行可能なタスクに分解する","TDD 導向の実装ロードマップを生成する","ファイル依存関係とテスト手順を文書化する","複雑な機能開発のためのコミット戦略を作成する"],"ko":["다단계 요구 사항을 실행 가능한 작업으로 분해","TDD 중심의 구현 로드맵 생성","파일 종속성 및 테스트 절차 문서화","복잡한 기능 개발을 위한 커밋 전략 생성"],"es":["Descomponer requisitos multietapa en tareas realizables","Generar hojas de ruta de implementación centradas en TDD","Documentar dependencias de archivos y procedimientos de prueba","Crear estrategias de confirmación para el desarrollo de características complejas"],"fr":["Décomposer les exigences multétapes en tâches réalisables","Générer des feuilles de route d''implémentation axées sur TDD","Documenter les dépendances de fichiers et les procédures de test","Créer des stratégies de validation pour le développement de fonctionnalités complexes"],"de":["Mehrschrittige Anforderungen in handhabbare Aufgaben aufteilen","TDD-fokussierte Implementierungs-Roadmaps generieren","Datei-Abhängigkeiten und Testverfahren dokumentieren","Commit-Strategien für die Entwicklung komplexer Funktionen erstellen"],"pt":["Decompor requisitos de múltiplas etapas em tarefas acionáveis","Gerar roteiros de implementação focados em TDD","Documentar dependências de arquivo e procedimentos de teste","Criar estratégias de commit para desenvolvimento de recursos complexos"],"ru":["Разбивание многоэтапных требований на выполняемые задачи","Генерация дорожных карт реализации, ориентированных на TDD","Документирование зависимостей файлов и процедур тестирования","Создание стратегий коммитов для сложной разработки функций"],"ar":["تفصيل المتطلبات متعددة المراحل إلى مهام قابلة للتنفيذ","إنشاء خطط تنفيذية تركز على TDD","توثيق تبعيات الملفات وإجراءات الاختبار","وضع استراتيجيات الالتزام (commit) لتطوير الميزات المعقدة"]},"limitations":{"en":["Requires detailed specifications as input","Assumes developer skill but zero codebase context","Focuses on planning rather than direct code execution"],"zh":["需要详细的规格作为输入","假设开发者技能但零代码库上下文","侧重于规划而不是直接代码执行"],"ja":["入力として詳細な仕様が必要","開発者スキルはあるがゼロコードベースコンテキスト","直接コードの実行ではなく計画に重点を置く"],"ko":["입력으로 자세한 사양이 필요","개발자 기술은 있지만 코드베이스 컨텍스트가 없음","직접 코드 실행보다 계획에 중점을 둠"],"es":["Requiere especificaciones detalladas como entrada","Supone habilidad de desarrollador pero cero contexto de código base","Se centra en la planificación en lugar de la ejecución directa de código"],"fr":["Nécessite des spécifications détaillées comme entrée","Suppose une compétence de développeur mais zéro contexte de base de code","Se concentre sur la planification plutôt que sur l''exécution directe de code"],"de":["Benötigt detaillierte Spezifikationen als Eingabe","Geht von Entwicklerfähigkeiten, aber Null-Kontext der Codebasis aus","Konzentriert sich auf die Planung statt auf die direkte Codeausführung"],"pt":["Requer especificações detalhadas como entrada","Assume habilidade do desenvolvedor, mas zero contexto da base de código","Foca no planejamento em vez da execução direta de código"],"ru":["Требует детальных спецификаций на входе","Предполагает наличие навыков разработчика, но отсутствие контекста кодовой базы","Сосредоточен на планировании, а не на прямом выполнении кода"],"ar":["يتطلب مواصفات مفصلة كمدخلات","يفترض مهارة المطور ولكن عدم وجود سياق قاعدة التعليمات البرمجية","يركز على التخطيط بدلاً من التنفيذ المباشر للكود"]},"version":4},"contentHash":"8a9198d4d9efbcad6e019b17c422c182113062c864b6154ec2a3ba2ed0b6b9d0","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":80}');
