INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/writing-plans', 'writing-plans', 'obra', 'superpowers', 'official', 'writing-plans obra superpowers official The writing-plans AI Agent Skill generates detailed technical implementation plans from a specification. It produces bite-sized tasks for developers, specifying files to modify, testing procedures, and documentation, assuming zero prior knowledge of the codebase or domain. Writing Plans AI代理技能根据规格要求生成多步骤编码任务的详细实施计划，包括文件修改指南、测试流程和文档要求，帮助零上下文开发者高效完成复杂任务。 Writing Plans AIエージェントスキルは仕様に基づきマルチステップ開発タスクの詳細な実装計画を生成。ファイル変更ガイド、テストプロセス、ドキュメント要件を含み、コンテキストのない開発者の作業を支援。 Writing Plans AI 에이전트 스킬은 사양에 따라 다단계 개발 작업의 상세한 구현 계획을 생성. 파일 수정 가이드, 테스트 프로세스, 문서 요구사항을 포함하여 컨텍스트가 없는 개발자의 작업을 지원. Esta skill de Agente IA genera planes de implementación técnica detallados para tareas multi-paso. Proporciona instrucciones específicas sobre archivos, testing, documentación y estrategias de commits para desarrolladores que necesitan orientación en codebases desconocidos. Cette compétence d''Outil IA génère des plans d''implémentation technique détaillés pour des tâches multi-étapes. Fournit des instructions spécifiques sur les fichiers, tests, documentation et stratégies de commits pour développeurs dans des codebases inconnus. Diese KI-Agenten Skill erstellt detaillierte technische Implementierungspläne für mehrstufige Aufgaben. Liefert spezifische Anweisungen zu Dateien, Testing, Dokumentation und Commit-Strategien für Entwickler in unbekannten Codebasen. Gera planos de implementação abrangentes para tarefas de múltiplas etapas, documentando arquivos, código, testes e documentação necessários. Assume um desenvolvedor habilidoso mas sem contexto do codebase, seguindo princípios DRY, YAGNI e TDD. Создает комплексные планы реализации для многоэтапных задач, документируя необходимые файлы, код, тесты и документацию. Предполагает опытного разработчика без контекста кодовой базы, следуя принципам DRY, YAGNI и TDD. تولّد خطط تنفيذ شاملة لمهام متعددة المراحل، موثقةً الملفات، الكود، الاختبارات، والوثائق المطلوبة. تفترض مطورًا ماهرًا بدون سياق قاعدة الكود، وتتبع مبادئ DRY وYAGNI وTDD. what is writing-plans how to use writing-plans for development writing-plans vs manual planning writing-plans alternative writing-plans install guide writing-plans setup for AI agents AI agent skill for technical specs generate dev plan from requirements Writing Plans AI代理 多步骤任务实施计划 零上下文开发指南 DRY YAGNI TDD原则 文件修改指导 测试流程规划 频繁提交策略 开发者任务分解 Generates comprehensive multi-step implementation plans from a spec Documents specific files to modify for each task Outlines testing procedures and required documentation checks Assumes zero developer context for the codebase or problem domain Enforces software principles like DRY, YAGNI, and TDD Delivers the entire plan as a series of bite-sized tasks writing-plans is an AI Agent Skill that creates comprehensive, multi-step implementation plans for developers from a given specification. It meticulously documents every required action, from which files to touch and code to write, to testing and documentation, assuming the engineer has zero context.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/configure-ecc', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'configure-ecc', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T03:50:18.001Z', '5f3506f77baf2b910b89dd66d98eb47ed0135e77d6b81d10e233d596cff0cf19', '{"id":"affaan-m/everything-claude-code/configure-ecc","name":"configure-ecc","description":{"en":"An interactive installer wizard for Everything Claude Code that guides developers through selective installation of skills and rules to user-level or project-level directories. It verifies paths and optionally optimizes installed files for Claude AI development workflows.","zh":"configure-ecc 是 Everything Claude Code 项目的交互式安装向导，使用 AskUserQuestion 引导用户选择性安装技能和规则到指定目录，验证安装正确性并提供优化选项。","ja":"configure-ecc は Everything Claude Code プロジェクトのインタラクティブインストールウィザードです。AskUserQuestionを使用してユーザーをガイドし、AIエージェントのスキルとルールを選択的にインストールし、正確性を検証します。","ko":"configure-ecc는 Everything Claude Code 프로젝트의 대화형 설치 마법사입니다. AskUserQuestion을 사용하여 사용자를 안내하고, 스킬과 규칙을 선택적으로 설치하며 정확성을 검증합니다.","es":"Configure Everything Claude Code con nuestra herramienta de instalación interactiva que guía la selección y instalación de habilidades y reglas","fr":"Configurez Everything Claude Code avec notre outil d''installation interactif qui guide la sélection et l''installation de compétences et de règles","de":"Konfigurieren Sie Everything Claude Code mit unserem interaktiven Installationswerkzeug, das die Auswahl und Installation von Fähigkeiten und Regeln erleichtert","pt":"Wizard interativo que guia desenvolvedores na instalação seletiva de skills e rules do Everything Claude Code. Verifica paths, instala em diretórios user-level ou project-level e oferece otimização opcional de arquivos instalados.","ru":"Интерактивный мастер, который проводит разработчиков через выборочную установку навыков и правил Everything Claude Code. Проверяет пути, устанавливает в каталоги уровня пользователя или проекта и предлагает оптимизацию установленных файлов.","ar":"مساعد تفاعلي يوجه المطورين خلال التثبيت الانتقائي لمهارات وقواعد Everything Claude Code. يتحقق من المسارات، يثبت في مجلدات مستوى المستخدم أو المشروع ويقدم تحسينًا اختياريًا للملفات المثبتة."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"configure-ecc","description":"Interactive installer for Everything Claude Code — guides users through selecting and installing skills and rules to user-level or project-level directories, verifies paths, and optionally optimizes installed files.","bodyPreview":"# Configure Everything Claude Code (ECC)\n\nAn interactive, step-by-step installation wizard for the Everything Claude Code project. Uses `AskUserQuestion` to guide users through selective installation of skills and rules, then verifies correctness and offers optimization.\n\n## When to Activate\n\n- User says \"configure ecc\", \"install ecc\", \"setup everything claude code\", or similar\n- User wants to selectively install skills or rules from this project\n- User wants to verify or fix an existing ECC ins","body":"# Configure Everything Claude Code (ECC)\n\nAn interactive, step-by-step installation wizard for the Everything Claude Code project. Uses `AskUserQuestion` to guide users through selective installation of skills and rules, then verifies correctness and offers optimization.\n\n## When to Activate\n\n- User says \"configure ecc\", \"install ecc\", \"setup everything claude code\", or similar\n- User wants to selectively install skills or rules from this project\n- User wants to verify or fix an existing ECC installation\n- User wants to optimize installed skills or rules for their project\n\n## Prerequisites\n\nThis skill must be accessible to Claude Code before activation. Two ways to bootstrap:\n1. **Via Plugin**: `/plugin install everything-claude-code` — the plugin loads this skill automatically\n2. **Manual**: Copy only this skill to `~/.claude/skills/configure-ecc/SKILL.md`, then activate by saying \"configure ecc\"\n\n---\n\n## Step 0: Clone ECC Repository\n\nBefore any installation, clone the latest ECC source to `/tmp`:\n\n```bash\nrm -rf /tmp/everything-claude-code\ngit clone https://github.com/affaan-m/everything-claude-code.git /tmp/everything-claude-code\n```\n\nSet `ECC_ROOT=/tmp/everything-claude-code` as the source for all subsequent copy operations.\n\nIf the clone fails (network issues, etc.), use `AskUserQuestion` to ask the user to provide a local path to an existing ECC clone.\n\n---\n\n## Step 1: Choose Installation Level\n\nUse `AskUserQuestion` to ask the user where to install:\n\n```\nQuestion: \"Where should ECC components be installed?\"\nOptions:\n  - \"User-level (~/.claude/)\" — \"Applies to all your Claude Code projects\"\n  - \"Project-level (.claude/)\" — \"Applies only to the current project\"\n  - \"Both\" — \"Common/shared items user-level, project-specific items project-level\"\n```\n\nStore the choice as `INSTALL_LEVEL`. Set the target directory:\n- User-level: `TARGET=~/.claude`\n- Project-level: `TARGET=.claude` (relative to current project root)\n- Both: `TARGET_USER=~/.claude`, `TARGET_PROJECT=.claude`\n\nCreate the target directories if they don''t exist:\n```bash\nmkdir -p $TARGET/skills $TARGET/rules\n```\n\n---\n\n## Step 2: Select & Install Skills\n\n### 2a: Choose Scope (Core vs Niche)\n\nDefault to **Core (recommended for new users)** — copy `.agents/skills/*` plus `skills/search-first/` for research-first workflows. This bundle covers engineering, evals, verification, security, strategic compaction, frontend design, and Anthropic cross-functional skills (article-writing, content-engine, market-research, frontend-slides).\n\nUse `AskUserQuestion` (single select):\n```\nQuestion: \"Install core skills only, or include niche/framework packs?\"\nOptions:\n  - \"Core only (recommended)\" — \"tdd, e2e, evals, verification, research-first, security, frontend patterns, compacting, cross-functional Anthropic skills\"\n  - \"Core + selected niche\" — \"Add framework/domain-specific skills after core\"\n  - \"Niche only\" — \"Skip core, install specific framework/domain skills\"\nDefault: Core only\n```\n\nIf the user chooses niche or core + niche, continue to category selection below and only include those niche skills they pick.\n\n### 2b: Choose Skill Categories\n\nThere are 27 skills organized into 4 categories. Use `AskUserQuestion` with `multiSelect: true`:\n\n```\nQuestion: \"Which skill categories do you want to install?\"\nOptions:\n  - \"Framework & Language\" — \"Django, Spring Boot, Go, Python, Java, Frontend, Backend patterns\"\n  - \"Database\" — \"PostgreSQL, ClickHouse, JPA/Hibernate patterns\"\n  - \"Workflow & Quality\" — \"TDD, verification, learning, security review, compaction\"\n  - \"All skills\" — \"Install every available skill\"\n```\n\n### 2c: Confirm Individual Skills\n\nFor each selected category, print the full list of skills below and ask the user to confirm or deselect specific ones. If the list exceeds 4 items, print the list as text and use `AskUserQuestion` with an \"Install all listed\" option plus \"Other\" for the user to paste specific names.\n\n**Category: Framework & Language (17 skills)**\n\n| Skill | Description |\n|-------|-------------|\n| `backend-patterns` | Backend architecture, API design, server-side best practices for Node.js/Express/Next.js |\n| `coding-standards` | Universal coding standards for TypeScript, JavaScript, React, Node.js |\n| `django-patterns` | Django architecture, REST API with DRF, ORM, caching, signals, middleware |\n| `django-security` | Django security: auth, CSRF, SQL injection, XSS prevention |\n| `django-tdd` | Django testing with pytest-django, factory_boy, mocking, coverage |\n| `django-verification` | Django verification loop: migrations, linting, tests, security scans |\n| `frontend-patterns` | React, Next.js, state management, performance, UI patterns |\n| `frontend-slides` | Zero-dependency HTML presentations, style previews, and PPTX-to-web conversion |\n| `golang-patterns` | Idiomatic Go patterns, conventions for robust Go applications |\n| `golang-testing` | Go testing: table-driven tests, subtests, benchmarks, fuzzing |\n| `java-coding-standards` | Java coding standards for Spring Boot: naming, immutability, Optional, streams |\n| `python-patterns` | Pythonic idioms, PEP 8, type hints, best practices |\n| `python-testing` | Python testing with pytest, TDD, fixtures, mocking, parametrization |\n| `springboot-patterns` | Spring Boot architecture, REST API, layered services, caching, async |\n| `springboot-security` | Spring Security: authn/authz, validation, CSRF, secrets, rate limiting |\n| `springboot-tdd` | Spring Boot TDD with JUnit 5, Mockito, MockMvc, Testcontainers |\n| `springboot-verification` | Spring Boot verification: build, static analysis, tests, security scans |\n\n**Category: Database (3 skills)**\n\n| Skill | Description |\n|-------|-------------|\n| `clickhouse-io` | ClickHouse patterns, query optimization, analytics, data engineering |\n| `jpa-patterns` | JPA/Hibernate entity design, relationships, query optimization, transactions |\n| `postgres-patterns` | PostgreSQL query optimization, schema design, indexing, security |\n\n**Category: Workflow & Quality (8 skills)**\n\n| Skill | Description |\n|-------|-------------|\n| `continuous-learning` | Auto-extract reusable patterns from sessions as learned skills |\n| `continuous-learning-v2` | Instinct-based learning with confidence scoring, evolves into skills/commands/agents |\n| `eval-harness` | Formal evaluation framework for eval-driven development (EDD) |\n| `iterative-retrieval` | Progressive context refinement for subagent context problem |\n| `security-review` | Security checklist: auth, input, secrets, API, payment features |\n| `strategic-compact` | Suggests manual context compaction at logical intervals |\n| `tdd-workflow` | Enforces TDD with 80%+ coverage: unit, integration, E2E |\n| `verification-loop` | Verification and quality loop patterns |\n\n**Category: Business & Content (5 skills)**\n\n| Skill | Description |\n|-------|-------------|\n| `article-writing` | Long-form writing in a supplied voice using notes, examples, or source docs |\n| `content-engine` | Multi-platform social content, scripts, and repurposing workflows |\n| `market-research` | Source-attributed market, competitor, fund, and technology research |\n| `investor-materials` | Pitch decks, one-pagers, investor memos, and financial models |\n| `investor-outreach` | Personalized investor cold emails, warm intros, and follow-ups |\n\n**Standalone**\n\n| Skill | Description |\n|-------|-------------|\n| `project-guidelines-example` | Template for creating project-specific skills |\n\n### 2d: Execute Installation\n\nFor each selected skill, copy the entire skill directory:\n```bash\ncp -r $ECC_ROOT/skills/<skill-name> $TARGET/skills/\n```\n\nNote: `continuous-learning` and `continuous-learning-v2` have extra files (config.json, hooks, scripts) — ensure the entire directory is copied, not just SKILL.md.\n\n---\n\n## Step 3: Select & Install Rules\n\nUse `AskUserQuestion` with `multiSelect: true`:\n\n```\nQuestion: \"Which rule sets do you want to install?\"\nOptions:\n  - \"Common rules (Recommended)\" — \"Language-agnostic principles: coding style, git workflow, testing, security, etc. (8 files)\"\n  - \"TypeScript/JavaScript\" — \"TS/JS patterns, hooks, testing with Playwright (5 files)\"\n  - \"Python\" — \"Python patterns, pytest, black/ruff formatting (5 files)\"\n  - \"Go\" — \"Go patterns, table-driven tests, gofmt/staticcheck (5 files)\"\n```\n\nExecute installation:\n```bash\n# Common rules (flat copy into rules/)\ncp -r $ECC_ROOT/rules/common/* $TARGET/rules/\n\n# Language-specific rules (flat copy into rules/)\ncp -r $ECC_ROOT/rules/typescript/* $TARGET/rules/   # if selected\ncp -r $ECC_ROOT/rules/python/* $TARGET/rules/        # if selected\ncp -r $ECC_ROOT/rules/golang/* $TARGET/rules/        # if selected\n```\n\n**Important**: If the user selects any language-specific rules but NOT common rules, warn them:\n> \"Language-specific rules extend the common rules. Installing without common rules may result in incomplete coverage. Install common rules too?\"\n\n---\n\n## Step 4: Post-Installation Verification\n\nAfter installation, perform these automated checks:\n\n### 4a: Verify File Existence\n\nList all installed files and confirm they exist at the target location:\n```bash\nls -la $TARGET/skills/\nls -la $TARGET/rules/\n```\n\n### 4b: Check Path References\n\nScan all installed `.md` files for path references:\n```bash\ngrep -rn \"~/.claude/\" $TARGET/skills/ $TARGET/rules/\ngrep -rn \"../common/\" $TARGET/rules/\ngrep -rn \"skills/\" $TARGET/skills/\n```\n\n**For project-level installs**, flag any references to `~/.claude/` paths:\n- If a skill references `~/.claude/settings.json` — this is usually fine (settings are always user-level)\n- If a skill references `~/.claude/skills/` or `~/.claude/rules/` — this may be broken if installed only at project level\n- If a skill references another skill by name — check that the referenced skill was also installed\n\n### 4c: Check Cross-References Between Skills\n\nSome skills reference others. Verify these dependencies:\n- `django-tdd` may reference `django-patterns`\n- `springboot-tdd` may reference `springboot-patterns`\n- `continuous-learning-v2` references `~/.claude/homunculus/` directory\n- `python-testing` may reference `python-patterns`\n- `golang-testing` may reference `golang-patterns`\n- Language-specific rules reference `common/` counterparts\n\n### 4d: Report Issues\n\nFor each issue found, report:\n1. **File**: The file containing the problematic reference\n2. **Line**: The line number\n3. **Issue**: What''s wrong (e.g., \"references ~/.claude/skills/python-patterns but python-patterns was not installed\")\n4. **Suggested fix**: What to do (e.g., \"install python-patterns skill\" or \"update path to .claude/skills/\")\n\n---\n\n## Step 5: Optimize Installed Files (Optional)\n\nUse `AskUserQuestion`:\n\n```\nQuestion: \"Would you like to optimize the installed files for your project?\"\nOptions:\n  - \"Optimize skills\" — \"Remove irrelevant sections, adjust paths, tailor to your tech stack\"\n  - \"Optimize rules\" — \"Adjust coverage targets, add project-specific patterns, customize tool configs\"\n  - \"Optimize both\" — \"Full optimization of all installed files\"\n  - \"Skip\" — \"Keep everything as-is\"\n```\n\n### If optimizing skills:\n1. Read each installed SKILL.md\n2. Ask the user what their project''s tech stack is (if not already known)\n3. For each skill, suggest removals of irrelevant sections\n4. Edit the SKILL.md files in-place at the installation target (NOT the source repo)\n5. Fix any path issues found in Step 4\n\n### If optimizing rules:\n1. Read each installed rule .md file\n2. Ask the user about their preferences:\n   - Test coverage target (default 80%)\n   - Preferred formatting tools\n   - Git workflow conventions\n   - Security requirements\n3. Edit the rule files in-place at the installation target\n\n**Critical**: Only modify files in the installation target (`$TARGET/`), NEVER modify files in the source ECC repository (`$ECC_ROOT/`).\n\n---\n\n## Step 6: Installation Summary\n\nClean up the cloned repository from `/tmp`:\n\n```bash\nrm -rf /tmp/everything-claude-code\n```\n\nThen print a summary report:\n\n```\n## ECC Installation Complete\n\n### Installation Target\n- Level: [user-level / project-level / both]\n- Path: [target path]\n\n### Skills Installed ([count])\n- skill-1, skill-2, skill-3, ...\n\n### Rules Installed ([count])\n- common (8 files)\n- typescript (5 files)\n- ...\n\n### Verification Results\n- [count] issues found, [count] fixed\n- [list any remaining issues]\n\n### Optimizations Applied\n- [list changes made, or \"None\"]\n```\n\n---\n\n## Troubleshooting\n\n### \"Skills not being picked up by Claude Code\"\n- Verify the skill directory contains a `SKILL.md` file (not just loose .md files)\n- For user-level: check `~/.claude/skills/<skill-name>/SKILL.md` exists\n- For project-level: check `.claude/skills/<skill-name>/SKILL.md` exists\n\n### \"Rules not working\"\n- Rules are flat files, not in subdirectories: `$TARGET/rules/coding-style.md` (correct) vs `$TARGET/rules/common/coding-style.md` (incorrect for flat install)\n- Restart Claude Code after installing rules\n\n### \"Path reference errors after project-level install\"\n- Some skills assume `~/.claude/` paths. Run Step 4 verification to find and fix these.\n- For `continuous-learning-v2`, the `~/.claude/homunculus/` directory is always user-level — this is expected and not an error.\n"},"category":"official","lastSynced":"2026-03-06T03:50:18.001Z","seo":{"title":{"en":"configure-ecc: Interactive Installation Wizard | AI Agent...","zh":"configure-ecc 设置指南：交互式 ECC 安装向导","ja":"configure-ecc セットアップガイド：AIエージェント向けインタラクティブインストーラー","ko":"configure-ecc 설정 가이드: 대화형 ECC 설치 마법사","es":"Guía de configuración de Everything Claude Code (ECC) - I...","fr":"Guide de configuration d''Everything Claude Code (ECC) - I...","de":"Konfigurationsleitfaden für Everything Claude Code (ECC) ...","pt":"Configure ECC: Guia de Instalação Interativa para Everyth...","ru":"Configure ECC: Интерактивный мастер установки для Everyth...","ar":"Configure ECC: دليل التثبيت التفاعلي لأداة Everything Cla..."},"description":{"en":"Step-by-step guide to install Everything Claude Code skills & rules. Uses AskUserQuestion for selective installation, path verification, and optimization. Pe...","zh":"Everything Claude Code 交互式安装向导，指导用户选择技能和规则，安装到用户或项目级目录，验证路径并提供文件优化。支持选择性安装和现有安装验证。","ja":"Everything Claude Codeのインタラクティブインストールウィザード。AIエージェントのスキルとルールを選択的にインストールし、パスを検証し、ファイル最適化を提供。ユーザーレベルとプロジェクトレベルに対応。","ko":"Everything Claude Code용 대화형 설치 마법사. 사용자가 스킬과 규칙을 선택적으로 설치하고, 경로를 검증하며 파일 최적화를 제공합니다. 사용자 및 프로젝트 수준 디렉토리 지원.","es":"Descubre cómo configurar Everything Claude Code con nuestra guía de instalación interactiva y selecciona habilidades y reglas personalizadas","fr":"Découvrez comment configurer Everything Claude Code avec notre guide d''installation interactif et sélectionnez des compétences et des règles personnalisées","de":"Erfahren Sie, wie Sie Everything Claude Code mit unserem interaktiven Installationsleitfaden konfigurieren und benutzerdefinierte Fähigkeiten und Regeln ausw...","pt":"Assistente interativo para instalação seletiva de skills e rules do Everything Claude Code. Verifica caminhos, instala em nível de usuário ou projeto e otimi...","ru":"Интерактивный мастер выборочной установки навыков и правил Everything Claude Code. Проверяет пути, устанавливает на уровне пользователя или проекта и оптимиз...","ar":"مساعد تفاعلي للتثبيت الانتقائي لمهارات وقواعد Everything Claude Code. يتحقق من المسارات، يثبت على مستوى المستخدم أو المشروع ويحسن الملفات."},"definition":{"en":"configure-ecc is an interactive installation wizard for the Everything Claude Code project that uses AskUserQuestion to guide users through selective installation of skills and rules. It verifies installation paths and offers file optimization for user-level or project-level directories.","zh":"configure-ecc 是一个专为 Everything Claude Code 项目设计的交互式安装工具。它通过逐步向导引导用户选择安装特定的 AI 技能和规则到用户级或项目级目录，验证安装路径的正确性，并可选择对已安装文件进行优化处理。","ja":"configure-ecc は、Everything Claude Code プロジェクト専用のインタラクティブインストールツールです。AIエージェントのスキルとルールをユーザーレベルまたはプロジェクトレベルディレクトリに選択的にインストールするステップバイステップウィザードを提供し、パス検証とファイル最適化機能を備えています。","ko":"configure-ecc는 Everything Claude Code 프로젝트를 위한 전용 대화형 설치 도구입니다. 사용자 수준 또는 프로젝트 수준 디렉토리에 AI 스킬과 규칙을 선택적으로 설치하는 단계별 마법사를 제공하며 경로 검증 및 파일 최적화 기능을 포함합니다.","es":"Un agente de IA que configura Everything Claude Code mediante una instalación interactiva","fr":"Un agent IA qui configure Everything Claude Code via une installation interactive","de":"Ein KI-Agent, der Everything Claude Code über eine interaktive Installation konfiguriert","pt":"Configure ECC é um instalador interativo para Everything Claude Code que usa AskUserQuestion para guiar usuários na instalação seletiva de skills e rules. Verifica caminhos, instala em diretórios user-level ou project-level e oferece otimização de arquivos.","ru":"Configure ECC — это интерактивный установщик для Everything Claude Code, который использует AskUserQuestion для выборочной установки навыков и правил. Проверяет пути, устанавливает в каталоги уровня пользователя или проекта и предлагает оптимизацию файлов.","ar":"Configure ECC هو مثبت تفاعلي لأداة Everything Claude Code يستخدم AskUserQuestion لتوجيه المستخدمين خلال التثبيت الانتقائي للمهارات والقواعد. يتحقق من المسارات، يثبت في مجلدات مستوى المستخدم أو المشروع ويقدم تحسينًا للملفات."},"features":{"en":["Interactive step-by-step installation using AskUserQuestion protocol","Selective installation of specific ECC skills and rules","User-level and project-level directory path verification","Optional file optimization for installed components","Activation via configure/setup/install ecc commands","Existing ECC installation verification and repair"],"zh":["使用 AskUserQuestion 的交互式安装向导","支持用户级和项目级目录选择性安装","安装路径验证和正确性检查","可选的文件优化功能","现有 ECC 安装的验证和修复","支持选择性技能和规则安装"],"ja":["AskUserQuestionを使用したインタラクティブインストールウィザード","ユーザーレベルとプロジェクトレベルディレクトリへの選択的インストール","インストールパスの検証と正確性チェック","オプションファイル最適化機能","既存のECCインストールの検証と修復","AIエージェントのスキルとルールの選択的インストール"],"ko":["AskUserQuestion을 사용한 대화형 설치 마법사","사용자 수준 및 프로젝트 수준 디렉토리 선택적 설치","설치 경로 검증 및 정확성 확인","선택적 파일 최적화 기능","기존 ECC 설치 검증 및 수리","선택적 스킬 및 규칙 설치 지원"],"es":["Instalación interactiva de habilidades y reglas","Verificación de rutas y optimización de archivos instalados","Uso de AskUserQuestion para guiar la instalación","Instalación selectiva de habilidades y reglas","Compatibilidad con directorios de usuario y proyecto"],"fr":["Installation interactive de compétences et de règles","Vérification des chemins et optimisation des fichiers installés","Utilisation de AskUserQuestion pour guider l''installation","Installation sélective de compétences et de règles","Compatibilité avec les répertoires utilisateur et projet"],"de":["Interaktive Installation von Fähigkeiten und Regeln","Überprüfung von Pfaden und Optimierung installierter Dateien","Verwendung von AskUserQuestion zur Steuerung der Installation","Selektive Installation von Fähigkeiten und Regeln","Kompatibilität mit Benutzer- und Projektverzeichnissen"],"pt":["Instalação interativa usando AskUserQuestion","Seleção seletiva de skills e rules para instalação","Verificação de caminhos e diretórios","Instalação em nível de usuário ou projeto","Otimização opcional de arquivos instalados","Validação de instalações existentes do ECC"],"ru":["Интерактивная установка с использованием AskUserQuestion","Выборочная установка навыков и правил","Проверка путей и каталогов","Установка на уровне пользователя или проекта","Опциональная оптимизация установленных файлов","Проверка существующих установок ECC"],"ar":["تثبيت تفاعلي باستخدام AskUserQuestion","تثبيت انتقائي للمهارات والقواعد","التحقق من المسارات والمجلدات","تثبيت على مستوى المستخدم أو المشروع","تحسين اختياري للملفات المثبتة","التحقق من التثبيتات الموجودة لـ ECC"]},"keywords":{"en":["how to use configure-ecc","configure-ecc install guide","everything claude code setup","configure-ecc vs manual installation","ecc skills installation wizard","mcp developer tools configure-ecc","claude code rules installation","configure-ecc path verification","askuserquestion installation workflow","configure-ecc optimization features"],"zh":["configure-ecc 安装指南","Everything Claude Code 设置","AI 代理技能安装","交互式安装向导","用户级目录安装","项目级技能配置","ECC 路径验证","Claude Code 优化","选择性技能安装","AskUserQuestion 使用"],"ja":["configure-ecc セットアップ","Everything Claude Code インストール","AIエージェント スキルインストール","インタラクティブインストールウィザード","ユーザーレベルディレクトリ設定","プロジェクトレベルスキル設定","ECC パス検証","Claude Code 最適化","選択的スキルインストール","AskUserQuestion 使用方法"],"ko":["configure-ecc 설정 방법","Everything Claude Code 설치","AI 에이전트 스킬 설치","대화형 설치 마법사","사용자 수준 디렉토리 설정","프로젝트 수준 스킬 구성","ECC 경로 검증","Claude Code 최적화","선택적 스킬 설치","AskUserQuestion 사용법"],"es":["configure ecc","instalación de habilidades y reglas","agentes de ia","herramientas de desarrollo","productividad","claude code","everything claude code"],"fr":["configure ecc","installation de compétences et de règles","agents ia","outils de développement","productivité","claude code","everything claude code"],"de":["configure ecc","installation von fähigkeiten und regeln","ki-agenten","entwicklerwerkzeuge","produktivität","claude code","everything claude code"],"pt":["configure ecc instalacao","everything claude code setup","instalador interativo mcp","skills claude code install","rules ecc developer tools","anthropic claude configuration","otimizacao arquivos ecc","user-level project-level installation"],"ru":["configure ecc установка","everything claude code настройка","интерактивный установщик mcp","навыки claude code установка","правила ecc инструменты разработчика","anthropic claude конфигурация","оптимизация файлов ecc","установка уровня пользователя проекта"],"ar":["configure ecc تثبيت","everything claude code إعداد","مثبت تفاعلي mcp","مهارات claude code تثبيت","قواعد ecc أدوات المطور","anthropic claude تكوين","تحسين ملفات ecc","تثبيت مستوى المستخدم المشروع"]}},"agentAnalysis":{"suitability":{"en":"Essential for AI Agent Ecosystem Managers handling Everything Claude Code installations and configurations.","zh":"对于处理Everything Claude Code安装和配置的AI Agent生态系统管理者至关重要。","ja":"Everything Claude Codeのインストールと設定を扱うAI Agentエコシステム管理者にとって不可欠です。","ko":"Everything Claude Code 설치 및 구성을 처리하는 AI Agent 에코시스템 관리자에게 필수적입니다.","es":"Esencial para administradores de ecosistemas de agentes de inteligencia artificial que manejan instalaciones y configuraciones de Everything Claude Code.","fr":"Essentiel pour les gestionnaires d''écosystèmes d''agents d''intelligence artificielle qui gèrent les installations et les configurations d''Everything Claude Code.","de":"Wesentlich für AI-Agent-Ökosystem-Manager, die Everything Claude Code-Installationen und -Konfigurationen verwalten.","pt":"Essencial para Gestores de Ecossistema de Agentes de IA que lidam com instalações e configurações do Everything Claude Code.","ru":"Необходим для менеджеров экосистемы AI Agent, занимающихся установкой и настройкой Everything Claude Code.","ar":"أساسي لمديري نظام عملاء الذكاء الاصطناعي الذين يتعاملون مع تثبيت وتكوين Everything Claude Code."},"recommendation":{"en":"Enables guided installation workflows for Everything Claude Code components using AskUserQuestion for interactive path selection and verification. Provides selective installation of skills and rules to user-level or project-level directories with optional file optimization capabilities.","zh":"通过使用AskUserQuestion进行交互式路径选择和验证，实现Everything Claude Code组件的引导式安装工作流程。提供将技能和规则选择性安装到用户级或项目级目录的功能，并具备可选的文件优化能力。","ja":"AskUserQuestionを使用した対話型パス選択と検証を通じて、Everything Claude Codeコンポーネントのガイド付きインストールワークフローを実現します。ユーザーレベルまたはプロジェクトレベルのディレクトリへのスキルとルールの選択的インストールと、オプションのファイル最適化機能を提供します。","ko":"AskUserQuestion을 사용한 대화형 경로 선택 및 검증을 통해 Everything Claude Code 컴포넌트의 안내된 설치 워크플로우를 가능하게 합니다. 사용자 수준 또는 프로젝트 수준 디렉토리에 대한 스킬 및 규칙의 선택적 설치와 선택적 파일 최적화 기능을 제공합니다.","es":"Permite flujos de trabajo de instalación guiados para componentes de Everything Claude Code utilizando AskUserQuestion para la selección y verificación de rutas interactivas. Proporciona instalación selectiva de habilidades y reglas en directorios de nivel de usuario o proyecto con capacidades de optimización de archivos opcionales.","fr":"Permet des flux de travail d''installation guidés pour les composants d''Everything Claude Code en utilisant AskUserQuestion pour la sélection et la vérification de chemins interactifs. Fournit une installation sélective de compétences et de règles dans des répertoires de niveau utilisateur ou de projet avec des capacités d''optimisation de fichiers optionnelles.","de":"Ermöglicht geleitete Installationsworkflows für Everything Claude Code-Komponenten unter Verwendung von AskUserQuestion für interaktive Pfadselektion und -verifizierung. Bietet selektive Installation von Fähigkeiten und Regeln in Benutzerverzeichnissen oder Projektverzeichnissen mit optionalen Datei-Optimierungsfunktionen.","pt":"Permite fluxos de trabalho de instalação guiada para componentes do Everything Claude Code usando AskUserQuestion para seleção e verificação interativa de caminhos. Fornece instalação seletiva de skills e rules para diretórios de nível de usuário ou de projeto com capacidades opcionais de otimização de arquivos.","ru":"Обеспечивает управляемые рабочие процессы установки компонентов Everything Claude Code с использованием AskUserQuestion для интерактивного выбора и проверки путей. Обеспечивает выборочную установку навыков и правил в каталоги уровня пользователя или уровня проекта с дополнительными возможностями оптимизации файлов.","ar":"يتيح سير عمل التثبيت الموجه لمكونات Everything Claude Code باستخدام AskUserQuestion للاختيار التفاعلي للمسار والتحقق منه. يوفر التثبيت الانتقائي للمهارات والقواعد في أدلة مستوى المستخدم أو مستوى المشروع مع قدرات اختيارية لتحسين الملفات."},"useCases":{"en":["Guiding users through selective ECC component installation","Verifying installation paths and directory structures","Optimizing installed skill and rule files for performance","Fixing existing ECC installation configurations"],"zh":["引导用户进行选择性ECC组件安装","验证安装路径和目录结构","优化已安装技能和规则文件以提高性能","修复现有ECC安装配置"],"ja":["ユーザーへの選択的ECCコンポーネントインストールのガイド","インストールパスとディレクトリ構造の検証","パフォーマンス向上のためのインストール済みスキルとルールファイルの最適化","既存のECCインストール設定の修正"],"ko":["사용자에게 선택적 ECC 컴포넌트 설치 안내","설치 경로 및 디렉토리 구조 검증","성능을 위한 설치된 스킬 및 규칙 파일 최적화","기존 ECC 설치 구성 수정"],"es":["Guía a los usuarios a través de la instalación selectiva de componentes de ECC","Verifica los caminos y estructuras de directorios de instalación","Optimiza los archivos de habilidades y reglas instalados para el rendimiento","Repara las configuraciones de instalación de ECC existentes"],"fr":["Guide les utilisateurs à travers l''installation sélective des composants d''ECC","Vérifie les chemins et les structures de répertoires d''installation","Optimise les fichiers de compétences et de règles installés pour les performances","Répare les configurations d''installation d''ECC existantes"],"de":["Leitet Benutzer durch die selektive Installation von ECC-Komponenten","Überprüft Installationspfade und -verzeichnisstrukturen","Optimiert installierte Fähigkeits- und Regeldateien für die Leistung","Behebt bestehende ECC-Installationskonfigurationen"],"pt":["Guiar usuários através da instalação seletiva de componentes ECC","Verificar caminhos de instalação e estruturas de diretórios","Otimizar arquivos de skills e rules instalados para desempenho","Corrigir configurações de instalação ECC existentes"],"ru":["Направление пользователей через выборочную установку компонентов ECC","Проверка путей установки и структуры каталогов","Оптимизация установленных файлов навыков и правил для повышения производительности","Исправление существующих конфигураций установки ECC"],"ar":["توجيه المستخدمين خلال التثبيت الانتقائي لمكونات ECC","التحقق من مسارات التثبيت وهياكل الدلائل","تحسين ملفات المهارات والقواعد المثبتة للأداء","إصلاح تكوينات تثبيت ECC الحالية"]},"limitations":{"en":["Requires filesystem access permissions","Dependent on Everything Claude Code project structure","Needs user interaction for path selection and configuration choices"],"zh":["需要文件系统访问权限","依赖于Everything Claude Code项目结构","需要用户交互进行路径选择和配置选择"],"ja":["ファイルシステムアクセス権限が必要","Everything Claude Codeプロジェクト構造に依存","パス選択と設定選択のためのユーザーインタラクションが必要"],"ko":["파일 시스템 액세스 권한 필요","Everything Claude Code 프로젝트 구조에 종속적","경로 선택 및 구성 선택을 위한 사용자 상호 작용 필요"],"es":["Requiere permisos de acceso al sistema de archivos","Dependiente de la estructura del proyecto de Everything Claude Code","Necesita interacción del usuario para la selección de rutas y opciones de configuración"],"fr":["Nécessite des autorisations d''accès au système de fichiers","Dépend de la structure du projet d''Everything Claude Code","Nécessite une interaction utilisateur pour la sélection de chemins et les choix de configuration"],"de":["Benötigt Dateisystemzugriffsberechtigungen","Abhängig von der Projektstruktur von Everything Claude Code","Benötigt Benutzereingriff für Pfadselektion und Konfigurationsauswahlen"],"pt":["Requer permissões de acesso ao sistema de arquivos","Dependente da estrutura do projeto Everything Claude Code","Requer interação do usuário para seleção de caminho e escolhas de configuração"],"ru":["Требует разрешений на доступ к файловой системе","Зависит от структуры проекта Everything Claude Code","Требует взаимодействия с пользователем для выбора пути и конфигурации"],"ar":["يتطلب أذونات الوصول إلى نظام الملفات","يعتمد على هيكل مشروع Everything Claude Code","يتطلب تفاعل المستخدم لاختيار المسار وخيارات التكوين"]},"version":4},"contentHash":"5f3506f77baf2b910b89dd66d98eb47ed0135e77d6b81d10e233d596cff0cf19","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":80}');
