INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/configure-ecc', 'configure-ecc', 'affaan-m', 'everything-claude-code', 'official', 'configure-ecc affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity An interactive installer wizard for Everything Claude Code that guides developers through selective installation of skills and rules to user-level or project-level directories. It verifies paths and optionally optimizes installed files for Claude AI development workflows. configure-ecc 是 Everything Claude Code 项目的交互式安装向导，使用 AskUserQuestion 引导用户选择性安装技能和规则到指定目录，验证安装正确性并提供优化选项。 configure-ecc は Everything Claude Code プロジェクトのインタラクティブインストールウィザードです。AskUserQuestionを使用してユーザーをガイドし、AIエージェントのスキルとルールを選択的にインストールし、正確性を検証します。 configure-ecc는 Everything Claude Code 프로젝트의 대화형 설치 마법사입니다. AskUserQuestion을 사용하여 사용자를 안내하고, 스킬과 규칙을 선택적으로 설치하며 정확성을 검증합니다. Configure Everything Claude Code con nuestra herramienta de instalación interactiva que guía la selección y instalación de habilidades y reglas Configurez Everything Claude Code avec notre outil d''installation interactif qui guide la sélection et l''installation de compétences et de règles Konfigurieren Sie Everything Claude Code mit unserem interaktiven Installationswerkzeug, das die Auswahl und Installation von Fähigkeiten und Regeln erleichtert Wizard interativo que guia desenvolvedores na instalação seletiva de skills e rules do Everything Claude Code. Verifica paths, instala em diretórios user-level ou project-level e oferece otimização opcional de arquivos instalados. Интерактивный мастер, который проводит разработчиков через выборочную установку навыков и правил Everything Claude Code. Проверяет пути, устанавливает в каталоги уровня пользователя или проекта и предлагает оптимизацию установленных файлов. مساعد تفاعلي يوجه المطورين خلال التثبيت الانتقائي لمهارات وقواعد Everything Claude Code. يتحقق من المسارات، يثبت في مجلدات مستوى المستخدم أو المشروع ويقدم تحسينًا اختياريًا للملفات المثبتة. how to use configure-ecc configure-ecc install guide everything claude code setup configure-ecc vs manual installation ecc skills installation wizard mcp developer tools configure-ecc claude code rules installation configure-ecc path verification askuserquestion installation workflow configure-ecc optimization features configure-ecc 安装指南 Everything Claude Code 设置 AI 代理技能安装 交互式安装向导 用户级目录安装 项目级技能配置 ECC 路径验证 Claude Code 优化 选择性技能安装 AskUserQuestion 使用 Interactive step-by-step installation using AskUserQuestion protocol Selective installation of specific ECC skills and rules User-level and project-level directory path verification Optional file optimization for installed components Activation via configure/setup/install ecc commands Existing ECC installation verification and repair configure-ecc is an interactive installation wizard for the Everything Claude Code project that uses AskUserQuestion to guide users through selective installation of skills and rules. It verifies installation paths and offers file optimization for user-level or project-level directories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/deployment-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'deployment-patterns', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T04:00:48.486Z', 'b2d18f90ea5f5b7e6c357c3ded7353fa2d23b04464eed4b81745b0c8340e31ba', '{"id":"affaan-m/everything-claude-code/deployment-patterns","name":"deployment-patterns","description":{"en":"The deployment-patterns skill provides technical workflows for CI/CD pipelines, Docker containerization, and production readiness. It benefits developers and teams deploying web applications.","zh":"部署模式提供CI/CD管道、Docker容器化和滚动部署等功能，帮助开发者实现高效的部署策略","ja":"デプロイパターンはCI/CDパイプライン、Dockerコンテナ化、ローリングデプロイなどの機能を提供し、開発者が効率的なデプロイ戦略を実現できるようにします","ko":"배포 패턴은 CI/CD 파이프라인, 도커 컨테이너화, 롤링 배포 등의 기능을 제공하여 개발자가 효율적인 배포 전략을 구현할 수 있습니다","es":"Los patrones de implementación permiten configurar flujos de trabajo de deploy y pipelines CI/CD para aplicaciones web","fr":"Les modèles de déploiement permettent de configurer des flux de travail de déploiement et des pipelines CI/CD pour les applications web","de":"Deploy-Patterns ermöglichen die Konfiguration von Deploy-Workflows und CI/CD-Pipelines für Webanwendungen","pt":"Implantação de aplicações web com padrões de implantação, incluindo CI/CD e containerização com Docker","ru":"Развертывание веб-приложений с помощью паттернов развертывания, включая CI/CD и контейнеризацию с Docker для ИИ Агентов","ar":"نشر التطبيقات الويب باستخدام أنماط النشر، بما في ذلك عمليات CI/CD وتصوير Docker للعمليات الية"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"deployment-patterns","description":"Deployment workflows, CI/CD pipeline patterns, Docker containerization, health checks, rollback strategies, and production readiness checklists for web applications.","bodyPreview":"# Deployment Patterns\n\nProduction deployment workflows and CI/CD best practices.\n\n## When to Activate\n\n- Setting up CI/CD pipelines\n- Dockerizing an application\n- Planning deployment strategy (blue-green, canary, rolling)\n- Implementing health checks and readiness probes\n- Preparing for a production release\n- Configuring environment-specific settings\n\n## Deployment Strategies\n\n### Rolling Deployment (Default)\n\nReplace instances gradually — old and new versions run simultaneously during rollout.","body":"# Deployment Patterns\n\nProduction deployment workflows and CI/CD best practices.\n\n## When to Activate\n\n- Setting up CI/CD pipelines\n- Dockerizing an application\n- Planning deployment strategy (blue-green, canary, rolling)\n- Implementing health checks and readiness probes\n- Preparing for a production release\n- Configuring environment-specific settings\n\n## Deployment Strategies\n\n### Rolling Deployment (Default)\n\nReplace instances gradually — old and new versions run simultaneously during rollout.\n\n```\nInstance 1: v1 → v2  (update first)\nInstance 2: v1        (still running v1)\nInstance 3: v1        (still running v1)\n\nInstance 1: v2\nInstance 2: v1 → v2  (update second)\nInstance 3: v1\n\nInstance 1: v2\nInstance 2: v2\nInstance 3: v1 → v2  (update last)\n```\n\n**Pros:** Zero downtime, gradual rollout\n**Cons:** Two versions run simultaneously — requires backward-compatible changes\n**Use when:** Standard deployments, backward-compatible changes\n\n### Blue-Green Deployment\n\nRun two identical environments. Switch traffic atomically.\n\n```\nBlue  (v1) ← traffic\nGreen (v2)   idle, running new version\n\n# After verification:\nBlue  (v1)   idle (becomes standby)\nGreen (v2) ← traffic\n```\n\n**Pros:** Instant rollback (switch back to blue), clean cutover\n**Cons:** Requires 2x infrastructure during deployment\n**Use when:** Critical services, zero-tolerance for issues\n\n### Canary Deployment\n\nRoute a small percentage of traffic to the new version first.\n\n```\nv1: 95% of traffic\nv2:  5% of traffic  (canary)\n\n# If metrics look good:\nv1: 50% of traffic\nv2: 50% of traffic\n\n# Final:\nv2: 100% of traffic\n```\n\n**Pros:** Catches issues with real traffic before full rollout\n**Cons:** Requires traffic splitting infrastructure, monitoring\n**Use when:** High-traffic services, risky changes, feature flags\n\n## Docker\n\n### Multi-Stage Dockerfile (Node.js)\n\n```dockerfile\n# Stage 1: Install dependencies\nFROM node:22-alpine AS deps\nWORKDIR /app\nCOPY package.json package-lock.json ./\nRUN npm ci --production=false\n\n# Stage 2: Build\nFROM node:22-alpine AS builder\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nRUN npm run build\nRUN npm prune --production\n\n# Stage 3: Production image\nFROM node:22-alpine AS runner\nWORKDIR /app\n\nRUN addgroup -g 1001 -S appgroup && adduser -S appuser -u 1001\nUSER appuser\n\nCOPY --from=builder --chown=appuser:appgroup /app/node_modules ./node_modules\nCOPY --from=builder --chown=appuser:appgroup /app/dist ./dist\nCOPY --from=builder --chown=appuser:appgroup /app/package.json ./\n\nENV NODE_ENV=production\nEXPOSE 3000\n\nHEALTHCHECK --interval=30s --timeout=3s --start-period=5s --retries=3 \\\n  CMD wget --no-verbose --tries=1 --spider http://localhost:3000/health || exit 1\n\nCMD [\"node\", \"dist/server.js\"]\n```\n\n### Multi-Stage Dockerfile (Go)\n\n```dockerfile\nFROM golang:1.22-alpine AS builder\nWORKDIR /app\nCOPY go.mod go.sum ./\nRUN go mod download\nCOPY . .\nRUN CGO_ENABLED=0 GOOS=linux go build -ldflags=\"-s -w\" -o /server ./cmd/server\n\nFROM alpine:3.19 AS runner\nRUN apk --no-cache add ca-certificates\nRUN adduser -D -u 1001 appuser\nUSER appuser\n\nCOPY --from=builder /server /server\n\nEXPOSE 8080\nHEALTHCHECK --interval=30s --timeout=3s CMD wget -qO- http://localhost:8080/health || exit 1\nCMD [\"/server\"]\n```\n\n### Multi-Stage Dockerfile (Python/Django)\n\n```dockerfile\nFROM python:3.12-slim AS builder\nWORKDIR /app\nRUN pip install --no-cache-dir uv\nCOPY requirements.txt .\nRUN uv pip install --system --no-cache -r requirements.txt\n\nFROM python:3.12-slim AS runner\nWORKDIR /app\n\nRUN useradd -r -u 1001 appuser\nUSER appuser\n\nCOPY --from=builder /usr/local/lib/python3.12/site-packages /usr/local/lib/python3.12/site-packages\nCOPY --from=builder /usr/local/bin /usr/local/bin\nCOPY . .\n\nENV PYTHONUNBUFFERED=1\nEXPOSE 8000\n\nHEALTHCHECK --interval=30s --timeout=3s CMD python -c \"import urllib.request; urllib.request.urlopen(''http://localhost:8000/health/'')\" || exit 1\nCMD [\"gunicorn\", \"config.wsgi:application\", \"--bind\", \"0.0.0.0:8000\", \"--workers\", \"4\"]\n```\n\n### Docker Best Practices\n\n```\n# GOOD practices\n- Use specific version tags (node:22-alpine, not node:latest)\n- Multi-stage builds to minimize image size\n- Run as non-root user\n- Copy dependency files first (layer caching)\n- Use .dockerignore to exclude node_modules, .git, tests\n- Add HEALTHCHECK instruction\n- Set resource limits in docker-compose or k8s\n\n# BAD practices\n- Running as root\n- Using :latest tags\n- Copying entire repo in one COPY layer\n- Installing dev dependencies in production image\n- Storing secrets in image (use env vars or secrets manager)\n```\n\n## CI/CD Pipeline\n\n### GitHub Actions (Standard Pipeline)\n\n```yaml\nname: CI/CD\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run typecheck\n      - run: npm test -- --coverage\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: coverage\n          path: coverage/\n\n  build:\n    needs: test\n    runs-on: ubuntu-latest\n    if: github.ref == ''refs/heads/main''\n    steps:\n      - uses: actions/checkout@v4\n      - uses: docker/setup-buildx-action@v3\n      - uses: docker/login-action@v3\n        with:\n          registry: ghcr.io\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - uses: docker/build-push-action@v5\n        with:\n          push: true\n          tags: ghcr.io/${{ github.repository }}:${{ github.sha }}\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n  deploy:\n    needs: build\n    runs-on: ubuntu-latest\n    if: github.ref == ''refs/heads/main''\n    environment: production\n    steps:\n      - name: Deploy to production\n        run: |\n          # Platform-specific deployment command\n          # Railway: railway up\n          # Vercel: vercel --prod\n          # K8s: kubectl set image deployment/app app=ghcr.io/${{ github.repository }}:${{ github.sha }}\n          echo \"Deploying ${{ github.sha }}\"\n```\n\n### Pipeline Stages\n\n```\nPR opened:\n  lint → typecheck → unit tests → integration tests → preview deploy\n\nMerged to main:\n  lint → typecheck → unit tests → integration tests → build image → deploy staging → smoke tests → deploy production\n```\n\n## Health Checks\n\n### Health Check Endpoint\n\n```typescript\n// Simple health check\napp.get(\"/health\", (req, res) => {\n  res.status(200).json({ status: \"ok\" });\n});\n\n// Detailed health check (for internal monitoring)\napp.get(\"/health/detailed\", async (req, res) => {\n  const checks = {\n    database: await checkDatabase(),\n    redis: await checkRedis(),\n    externalApi: await checkExternalApi(),\n  };\n\n  const allHealthy = Object.values(checks).every(c => c.status === \"ok\");\n\n  res.status(allHealthy ? 200 : 503).json({\n    status: allHealthy ? \"ok\" : \"degraded\",\n    timestamp: new Date().toISOString(),\n    version: process.env.APP_VERSION || \"unknown\",\n    uptime: process.uptime(),\n    checks,\n  });\n});\n\nasync function checkDatabase(): Promise<HealthCheck> {\n  try {\n    await db.query(\"SELECT 1\");\n    return { status: \"ok\", latency_ms: 2 };\n  } catch (err) {\n    return { status: \"error\", message: \"Database unreachable\" };\n  }\n}\n```\n\n### Kubernetes Probes\n\n```yaml\nlivenessProbe:\n  httpGet:\n    path: /health\n    port: 3000\n  initialDelaySeconds: 10\n  periodSeconds: 30\n  failureThreshold: 3\n\nreadinessProbe:\n  httpGet:\n    path: /health\n    port: 3000\n  initialDelaySeconds: 5\n  periodSeconds: 10\n  failureThreshold: 2\n\nstartupProbe:\n  httpGet:\n    path: /health\n    port: 3000\n  initialDelaySeconds: 0\n  periodSeconds: 5\n  failureThreshold: 30    # 30 * 5s = 150s max startup time\n```\n\n## Environment Configuration\n\n### Twelve-Factor App Pattern\n\n```bash\n# All config via environment variables — never in code\nDATABASE_URL=postgres://user:pass@host:5432/db\nREDIS_URL=redis://host:6379/0\nAPI_KEY=${API_KEY}           # injected by secrets manager\nLOG_LEVEL=info\nPORT=3000\n\n# Environment-specific behavior\nNODE_ENV=production          # or staging, development\nAPP_ENV=production           # explicit app environment\n```\n\n### Configuration Validation\n\n```typescript\nimport { z } from \"zod\";\n\nconst envSchema = z.object({\n  NODE_ENV: z.enum([\"development\", \"staging\", \"production\"]),\n  PORT: z.coerce.number().default(3000),\n  DATABASE_URL: z.string().url(),\n  REDIS_URL: z.string().url(),\n  JWT_SECRET: z.string().min(32),\n  LOG_LEVEL: z.enum([\"debug\", \"info\", \"warn\", \"error\"]).default(\"info\"),\n});\n\n// Validate at startup — fail fast if config is wrong\nexport const env = envSchema.parse(process.env);\n```\n\n## Rollback Strategy\n\n### Instant Rollback\n\n```bash\n# Docker/Kubernetes: point to previous image\nkubectl rollout undo deployment/app\n\n# Vercel: promote previous deployment\nvercel rollback\n\n# Railway: redeploy previous commit\nrailway up --commit <previous-sha>\n\n# Database: rollback migration (if reversible)\nnpx prisma migrate resolve --rolled-back <migration-name>\n```\n\n### Rollback Checklist\n\n- [ ] Previous image/artifact is available and tagged\n- [ ] Database migrations are backward-compatible (no destructive changes)\n- [ ] Feature flags can disable new features without deploy\n- [ ] Monitoring alerts configured for error rate spikes\n- [ ] Rollback tested in staging before production release\n\n## Production Readiness Checklist\n\nBefore any production deployment:\n\n### Application\n- [ ] All tests pass (unit, integration, E2E)\n- [ ] No hardcoded secrets in code or config files\n- [ ] Error handling covers all edge cases\n- [ ] Logging is structured (JSON) and does not contain PII\n- [ ] Health check endpoint returns meaningful status\n\n### Infrastructure\n- [ ] Docker image builds reproducibly (pinned versions)\n- [ ] Environment variables documented and validated at startup\n- [ ] Resource limits set (CPU, memory)\n- [ ] Horizontal scaling configured (min/max instances)\n- [ ] SSL/TLS enabled on all endpoints\n\n### Monitoring\n- [ ] Application metrics exported (request rate, latency, errors)\n- [ ] Alerts configured for error rate > threshold\n- [ ] Log aggregation set up (structured logs, searchable)\n- [ ] Uptime monitoring on health endpoint\n\n### Security\n- [ ] Dependencies scanned for CVEs\n- [ ] CORS configured for allowed origins only\n- [ ] Rate limiting enabled on public endpoints\n- [ ] Authentication and authorization verified\n- [ ] Security headers set (CSP, HSTS, X-Frame-Options)\n\n### Operations\n- [ ] Rollback plan documented and tested\n- [ ] Database migration tested against production-sized data\n- [ ] Runbook for common failure scenarios\n- [ ] On-call rotation and escalation path defined\n"},"category":"official","lastSynced":"2026-03-06T04:00:48.486Z","seo":{"title":{"en":"Deployment-Patterns: CI/CD Pipeline Setup Guide | AI Agen...","zh":"部署模式设置指南 - CI/CD管道和Docker容器化","ja":"デプロイパターンのベストプラクティス - CI/CDパイプラインとDockerコンテナ化","ko":"배포 패턴 설정 가이드 - CI/CD 파이프라인과 도커 컨테이너화","es":"Patrones de implementación: Guía de configuración para CI/CD","fr":"Modèles de déploiement : Meilleures pratiques pour les pi...","de":"Deploy-Patterns: Einrichtungsleitfaden für CI/CD-Pipelines","pt":"Padrões de Implantação: Guia de Configuração","ru":"Паттерны Развертывания: Лучшие Практики для ИИ Агентов","ar":"أنماط النشر: دليل الإعداد للعمليات الية"},"description":{"en":"Streamline your web app deployment with expert workflows, Docker containerization, and health checks. Learn how to implement deployment-patterns today!","zh":"了解部署模式的最佳实践，包括CI/CD管道、Docker容器化、滚动部署和健康检查","ja":"デプロイパターンのベストプラクティスを学び、CI/CDパイプライン、Dockerコンテナ化、ローリングデプロイ、ヘルスチェックを実現する","ko":"배포 패턴의 베스트 프랙티스를 알아보고 CI/CD 파이프라인, 도커 컨테이너화, 롤링 배포, 헬스 체크를 구현하세요","es":"Aprende a implementar patrones de deploy efectivos con CI/CD, Docker y estrategias de rollback para aplicaciones web","fr":"Découvrez comment mettre en œuvre des modèles de déploiement efficaces avec CI/CD, Docker et des stratégies de rollback pour les applications web","de":"Erfahren Sie, wie Sie effektive Deploy-Patterns mit CI/CD, Docker und Rollback-Strategien für Webanwendungen implementieren","pt":"Aprenda a implementar padrões de implantação eficazes com workflows de CI/CD, containerização com Docker e estratégias de rollback","ru":"Узнайте, как реализовать паттерны развертывания с помощью рабочих процессов CI/CD, контейнеризации с Docker и стратегий откатов для ИИ Агентов","ar":"تعلم كيفية تنفيذ أنماط نشر فعالة باستخدام عمليات CI/CD وتصوير Docker واستراتيجيات الإرجاع للعمليات الية"},"definition":{"en":"deployment-patterns is a set of technical workflows and strategies for deploying web applications, including CI/CD pipelines, Docker containerization, and health checks.","zh":"部署模式是指一种确保web应用程序部署高效、可靠和安全的方法，包括CI/CD管道和Docker容器化","ja":"デプロイパターンは、Webアプリケーションのデプロイを効率的に、信頼性が高く、安全に保つための方法であり、CI/CDパイプラインとDockerコンテナ化が含まれます","ko":"배포 패턴은 웹 애플리케이션의 배포를 효율적이고 신뢰할 수 있고 안전하게 유지하는 방법으로 CI/CD 파이프라인과 도커 컨테이너화를 포함합니다","es":"Un patrón de implementación es una estrategia para deployar aplicaciones web de manera eficiente y segura","fr":"Un modèle de déploiement est une stratégie pour déployer des applications web de manière efficace et sécurisée","de":"Ein Deploy-Pattern ist eine Strategie für die effiziente und sichere Bereitstellung von Webanwendungen","pt":"Padrões de implantação são práticas recomendadas para implantar aplicações web de forma eficaz","ru":"Паттерны развертывания - это рекомендуемые практики для эффективного развертывания веб-приложений для ИИ Агентов","ar":"أنماط النشر هي ممارسات موصى بها لنشر التطبيقات الويب بفعالية للعمليات الية"},"features":{"en":["Implements rolling deployment strategy with simultaneous old and new version rollout","Supports Docker containerization for web applications","Includes health checks and readiness probes for production environments","Provides environment-specific settings configuration","Enables blue-green, canary, and rolling deployment planning"],"zh":["CI/CD管道支持","Docker容器化","滚动部署","健康检查和就绪探针","蓝绿部署和金丝雀部署"],"ja":["CI/CDパイプラインのサポート","Dockerコンテナ化","ローリングデプロイ","ヘルスチェックとリディネスプローブ","ブルーグリーンデプロイとカナリアデプロイ"],"ko":["CI/CD 파이프라인 지원","도커 컨테이너화","롤링 배포","헬스 체크와 리드니스 프로브","블루-그린 배포와 카나리아 배포"],"es":["Implementación de pipelines CI/CD","Contenerización con Docker","Estrategias de deploy: blue-green, canary, rolling","Chequeos de salud y sondeos de preparación","Planificación de estrategias de rollback"],"fr":["Mise en œuvre de pipelines CI/CD","Conteneurisation avec Docker","Stratégies de déploiement : blue-green, canary, rolling","Vérifications de santé et sondes de préparation","Planification de stratégies de rollback"],"de":["Implementierung von CI/CD-Pipelines","Containerisierung mit Docker","Deploy-Strategien: blue-green, canary, rolling","Gesundheitschecks und Bereitschaftssonden","Planung von Rollback-Strategien"],"pt":["Workflows de CI/CD","Containerização com Docker","Estratégias de rollback","Implantação gradual","Verificação de saúde e prontidão"],"ru":["Рабочие процессы CI/CD","Контейнеризация с Docker","Стратегии откатов","Постепенная_Implantação","Проверка здоровья и готовности для ИИ Агентов"],"ar":["عمليات CI/CD","تصوير Docker","استراتيجيات الإرجاع","نشر تدريجي","فحص الصحة والجاهزية للعمليات الية"]},"keywords":{"en":["how to use deployment-patterns","deployment-patterns setup guide","CI/CD pipeline best practices","Docker containerization tutorial","deployment-patterns vs Jenkins","what is deployment-patterns","deployment-patterns install","deployment-patterns alternative"],"zh":["AIエージェント","CI/CD管道","Docker容器化","滚动部署","健康检查","蓝绿部署","金丝雀部署","部署模式","web应用程序部署"],"ja":["AIエージェント","CI/CDパイプライン","Dockerコンテナ化","ローリングデプロイ","ヘルスチェック","ブルーグリーンデプロイ","カナリアデプロイ","デプロイパターン","Webアプリケーションのデプロイ"],"ko":["AI 에이전트","CI/CD 파이프라인","도커 컨테이너화","롤링 배포","헬스 체크","블루-그린 배포","카나리아 배포","배포 패턴","웹 애플리케이션 배포"],"es":["patrones de implementación","CI/CD","Docker","estrategias de deploy","chequeos de salud","rollback","aplicaciones web","Herramientas de desarrollo","Agente de IA","Desarrollo de software"],"fr":["modèles de déploiement","CI/CD","Docker","stratégies de déploiement","vérifications de santé","rollback","applications web","Outils de développement","Agent IA","Développement de logiciels"],"de":["Deploy-Patterns","CI/CD","Docker","Deploy-Strategien","Gesundheitschecks","Rollback","Webanwendungen","Entwicklungstools","KI-Agent","Software-Entwicklung"],"pt":["padrões de implantação","CI/CD","Docker","estratégias de rollback","implantação gradual","verificação de saúde","nublado de desenvolvimento","ferramentas de desenvolvimento"],"ru":["паттерны развертывания","CI/CD","Docker","стратегии откатов","постепенная_implantação","проверка здоровья","облачное разработка","инструменты разработки для ИИ Агентов"],"ar":["أنماط النشر","CI/CD","Docker","استراتيجيات الإرجاع","نشر تدريجي","فحص الصحة","التطوير السحابي","أدوات التطوير للعمليات الية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for DevOps Automation Agents orchestrating containerized deployments and CI/CD workflows.","zh":"非常适合编排容器化部署和CI/CD工作流程的DevOps Automation Agents。","ja":"コンテナ化されたデプロイとCI/CDワークフローを調整するDevOps Automation Agentsに最適です。","ko":"컨테이너화된 배포와 CI/CD 워크플로를 조율하는 DevOps Automation Agents에 완벽합니다.","es":"Perfecto para agentes de automatización de DevOps que orquestan despliegues contenerizados y flujos de trabajo de CI/CD.","fr":"Parfait pour les agents d''automatisation DevOps qui orchestrent des déploiements conteneurisés et des flux de travail CI/CD.","de":"Perfekt für DevOps-Automatisierungsagenten, die containerisierte Bereitstellungen und CI/CD-Workflows orchestrieren.","pt":"Perfeito para Agentes de Automação DevOps que orquestram implantações em contêineres e fluxos de trabalho de CI/CD.","ru":"Идеально подходит для агентов автоматизации DevOps, оркестрирующих контейнерные развертывания и рабочие процессы CI/CD.","ar":"مثالي لوكلاء أتمتة DevOps التي تنظم عمليات النشر المعتمدة على الحاويات وسير عمل CI/CD."},"recommendation":{"en":"Empowers agents to design and implement production-grade deployment strategies including blue-green, canary, and rolling deployments with Docker containerization. Provides expertise in configuring health checks, readiness probes, and automated rollback mechanisms for zero-downtime releases.","zh":"赋能Agent设计和实施生产级部署策略，包括使用Docker容器化的蓝绿部署、金丝雀部署和滚动部署。为零停机发布提供配置健康检查、就绪探针和自动回滚机制的专业知识。","ja":"AgentがDockerコンテナ化を使用したブルーグリーン、カナリア、ローリングデプロイを含むプロダクショングレードのデプロイ戦略を設計および実装することを可能にします。ダウンタイムゼロのリリースのために、ヘルスチェック、readiness probes、自動ロールバックメカニズムの設定に関する専門知識を提供します。","ko":"Agent가 Docker 컨테이너화를 사용한 블루-그린, 카나리아, 롤링 배포를 포함한 프로덕션 등급의 배포 전략을 설계하고 구현할 수 있도록 합니다. 제로 다운타임 릴리스를 위한 헬스 체크, 준비 상태 프로브(readiness probes), 자동 롤백 메커니즘 구성에 대한 전문성을 제공합니다.","es":"Habilita a los agentes a diseñar e implementar estrategias de implementación de producción de grado que incluyen despliegues azul-verde, canario y en rodaje con contenerización de Docker. Proporciona experiencia en la configuración de comprobaciones de salud, sondas de preparación y mecanismos de reversión automática para lanzamientos sin tiempo de inactividad.","fr":"Permet aux agents de concevoir et de mettre en œuvre des stratégies de déploiement de production de niveau supérieur, y compris les déploiements bleu-vert, canari et progressif avec la conteneurisation Docker. Fournit une expertise dans la configuration des vérifications de santé, des sondes de préparation et des mécanismes de réversibilité automatisés pour les versions sans temps d''arrêt.","de":"Ermächtigt Agenten, Produktionsgrade-Implementierungsstrategien zu entwerfen und umzusetzen, einschließlich blau-grüner, Kanarien- und Rollout-Deployments mit Docker-Containerisierung. Bietet Expertenwissen bei der Konfiguration von Gesundheitschecks, Bereitschaftssonden und automatisierten Rollback-Mechanismen für Zero-Downtime-Veröffentlichungen.","pt":"Capacita os agentes a projetar e implementar estratégias de implantação de nível de produção, incluindo implantações blue-green, canary e rolling com a containerização Docker. Fornece expertise na configuração de verificações de integridade, sondas de prontidão e mecanismos de reversão automatizada para lançamentos com tempo de inatividade zero.","ru":"Позволяет агентам проектировать и внедрять стратегии развертывания производственного уровня, включая blue-green, canary и rolling развертывания с контейнеризацией Docker. Предоставляет экспертизу в настройке проверок работоспособности, проб готовности и автоматизированных механизмов отката для выпусков с нулевым временем простоя.","ar":"يمكن الوكلاء من تصميم وتنفيذ استراتيجيات النشر على مستوى الإنتاج بما في ذلك النشر الأزرق-الأخضر، والتدرجي، والمتداول مع حاوية Docker. يوفر الخبرة في تكوين فحوصات الصحة، ومسابر الجاهزية، وآليات التراجع الآلي للإصدارات بدون توقف."},"useCases":{"en":["Automating CI/CD pipeline configuration","Implementing Docker containerization strategies","Designing blue-green deployment workflows","Configuring health checks and readiness probes","Executing automated rollback procedures"],"zh":["自动化CI/CD流水线配置","实施Docker容器化策略","设计蓝绿部署工作流程","配置健康检查和就绪探针","执行自动回滚流程"],"ja":["CI/CDパイプライン構成の自動化","Dockerコンテナ化戦略の実装","ブルーグリーンデプロイワークフローの設計","ヘルスチェックとreadiness probesの設定","自動ロールバック手順の実行"],"ko":["CI/CD 파이프라인 구성 자동화","Docker 컨테이너화 전략 구현","블루-그린 배포 워크플로 설계","헬스 체크 및 준비 상태 프로브(readiness probes) 구성","자동 롤백 절차 실행"],"es":["Automatización de la configuración de la canalización CI/CD","Implementación de estrategias de contenerización de Docker","Diseño de flujos de trabajo de despliegue azul-verde","Configuración de comprobaciones de salud y sondas de preparación","Ejecución de procedimientos de reversión automática"],"fr":["Automatisation de la configuration du pipeline CI/CD","Mise en œuvre de stratégies de conteneurisation Docker","Conception de flux de travail de déploiement bleu-vert","Configuration des vérifications de santé et des sondes de préparation","Exécution de procédures de réversibilité automatisées"],"de":["Automatisierung der CI/CD-Pipeline-Konfiguration","Implementierung von Docker-Containerisierungsstrategien","Entwurf von blau-grünen Deployment-Workflows","Konfiguration von Gesundheitschecks und Bereitschaftssonden","Ausführung von automatisierten Rollback-Verfahren"],"pt":["Automatizando a configuração do pipeline de CI/CD","Implementando estratégias de containerização Docker","Projetando fluxos de trabalho de implantação blue-green","Configurando verificações de integridade e sondas de prontidão","Executando procedimentos de reversão automatizada"],"ru":["Автоматизация настройки конвейера CI/CD","Внедрение стратегий контейнеризации Docker","Проектирование рабочих процессов blue-green развертывания","Настройка проверок работоспособности и проб готовности","Выполнение автоматизированных процедур отката"],"ar":["أتمتة تكوين خط أنابيب CI/CD","تنفيذ استراتيجيات حاوية Docker","تصميم سير عمل النشر الأزرق-الأخضر","تكوين فحوصات الصحة ومسابر الجاهزية","تنفيذ إجراءات التراجع الآلي"]},"limitations":{"en":["Requires Docker environment access","Assumes existing application infrastructure","Needs CI/CD platform integration"],"zh":["需要Docker环境访问权限","假定存在现有应用程序基础设施","需要CI/CD平台集成"],"ja":["Docker環境へのアクセスが必要","既存のアプリケーションインフラストラクチャを想定","CI/CDプラットフォームとの統合が必要"],"ko":["Docker 환경 접근 권한 필요","기존 애플리케이션 인프라가 존재한다고 가정","CI/CD 플랫폼 통합 필요"],"es":["Requiere acceso al entorno de Docker","Supone infraestructura de aplicación existente","Necesita integración con plataforma CI/CD"],"fr":["Nécessite un accès à l''environnement Docker","Suppose une infrastructure d''application existante","Nécessite une intégration avec une plate-forme CI/CD"],"de":["Benötigt Zugriff auf die Docker-Umgebung","Geht von bestehender Anwendungsinfrastruktur aus","Benötigt Integration mit CI/CD-Plattform"],"pt":["Requer acesso ao ambiente Docker","Assume uma infraestrutura de aplicação existente","Requer integração com uma plataforma de CI/CD"],"ru":["Требует доступ к среде Docker","Предполагает существующую инфраструктуру приложения","Требует интеграции с платформой CI/CD"],"ar":["يتطلب الوصول إلى بيئة Docker","يفترض وجود بنية تحتية للتطبيق","يحتاج إلى تكامل مع منصة CI/CD"]},"version":4},"contentHash":"b2d18f90ea5f5b7e6c357c3ded7353fa2d23b04464eed4b81745b0c8340e31ba","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":80}');
