INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/deployment-patterns', 'deployment-patterns', 'affaan-m', 'everything-claude-code', 'official', 'deployment-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The deployment-patterns skill provides technical workflows for CI/CD pipelines, Docker containerization, and production readiness. It benefits developers and teams deploying web applications. 部署模式提供CI/CD管道、Docker容器化和滚动部署等功能，帮助开发者实现高效的部署策略 デプロイパターンはCI/CDパイプライン、Dockerコンテナ化、ローリングデプロイなどの機能を提供し、開発者が効率的なデプロイ戦略を実現できるようにします 배포 패턴은 CI/CD 파이프라인, 도커 컨테이너화, 롤링 배포 등의 기능을 제공하여 개발자가 효율적인 배포 전략을 구현할 수 있습니다 Los patrones de implementación permiten configurar flujos de trabajo de deploy y pipelines CI/CD para aplicaciones web Les modèles de déploiement permettent de configurer des flux de travail de déploiement et des pipelines CI/CD pour les applications web Deploy-Patterns ermöglichen die Konfiguration von Deploy-Workflows und CI/CD-Pipelines für Webanwendungen Implantação de aplicações web com padrões de implantação, incluindo CI/CD e containerização com Docker Развертывание веб-приложений с помощью паттернов развертывания, включая CI/CD и контейнеризацию с Docker для ИИ Агентов نشر التطبيقات الويب باستخدام أنماط النشر، بما في ذلك عمليات CI/CD وتصوير Docker للعمليات الية how to use deployment-patterns deployment-patterns setup guide CI/CD pipeline best practices Docker containerization tutorial deployment-patterns vs Jenkins what is deployment-patterns deployment-patterns install deployment-patterns alternative AIエージェント CI/CD管道 Docker容器化 滚动部署 健康检查 蓝绿部署 金丝雀部署 部署模式 web应用程序部署 Implements rolling deployment strategy with simultaneous old and new version rollout Supports Docker containerization for web applications Includes health checks and readiness probes for production environments Provides environment-specific settings configuration Enables blue-green, canary, and rolling deployment planning deployment-patterns is a set of technical workflows and strategies for deploying web applications, including CI/CD pipelines, Docker containerization, and health checks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/golang-testing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'golang-testing', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T04:14:33.280Z', '2da1afcd9df6529392653cd450edc40eb8bbc0b073f3eda17a510f4b89411c1b', '{"id":"affaan-m/everything-claude-code/golang-testing","name":"golang-testing","description":{"en":"The golang-testing skill provides comprehensive Go testing patterns for writing reliable, maintainable tests following TDD methodology, benefiting Go developers and teams.","zh":"Go语言测试模式是使用TDD方法提高代码质量的综合解决方案，包括表驱动测试、子测试、基准测试、模糊测试和测试覆盖率等功能","ja":"Goテストパターンは、TDD方法論を使用して信頼性の高いテストを書くための包括的なソリューションです","ko":"고랭测试 패턴은 TDD 방법론을 사용하여 코드 품질을 향상시키는 통합 솔루션으로, 테이블 드라이븐 테스트, 서브테스트, 벤치마크 테스트, 퍼징 테스트 및 테스트 커버리지 등의 기능을 제공합니다","es":"El patrón de testing de Go proporciona una forma de escribir pruebas confiables y mantenibles utilizando TDD y prácticas idiomáticas de Go","fr":"Le modèle de test Go fournit un moyen d''écrire des tests fiables et maintenables en utilisant TDD et des pratiques idiomatiques de Go","de":"Das Go-Testing-Muster bietet eine Möglichkeit, zuverlässige und wartbare Tests unter Verwendung von TDD und idiomatischen Go-Praktiken zu schreiben","pt":"Este AI Agent especializado em Golang implementa padrões de teste avançados como table-driven tests, subtests e fuzzing. Segue metodologia TDD (Red-Green-Refactor) com práticas idiomáticas da linguagem Go para testes confiáveis e de alta cobertura.","ru":"Этот ИИ Агент специализируется на продвинутых паттернах тестирования в Golang, включая табличное тестирование, подтесты и фаззинг. Следует методологии TDD (Red-Green-Refactor) с идиоматическими практиками языка Go для надежных тестов с высоким покрытием.","ar":"يتخصص هذا الوكيل الذكي في أنماط الاختبار المتقدمة في Golang بما في ذلك الاختبارات المجدولة، الاختبارات الفرعية والاختبار الضبابي. يتبع منهجية TDD (Red-Green-Refactor) مع الممارسات الاصطلاحية للغة Go لاختبارات موثوقة وعالية التغطية."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"golang-testing","description":"Go testing patterns including table-driven tests, subtests, benchmarks, fuzzing, and test coverage. Follows TDD methodology with idiomatic Go practices.","bodyPreview":"# Go Testing Patterns\n\nComprehensive Go testing patterns for writing reliable, maintainable tests following TDD methodology.\n\n## When to Activate\n\n- Writing new Go functions or methods\n- Adding test coverage to existing code\n- Creating benchmarks for performance-critical code\n- Implementing fuzz tests for input validation\n- Following TDD workflow in Go projects\n\n## TDD Workflow for Go\n\n### The RED-GREEN-REFACTOR Cycle\n\n```\nRED     → Write a failing test first\nGREEN   → Write minimal code to pass","body":"# Go Testing Patterns\n\nComprehensive Go testing patterns for writing reliable, maintainable tests following TDD methodology.\n\n## When to Activate\n\n- Writing new Go functions or methods\n- Adding test coverage to existing code\n- Creating benchmarks for performance-critical code\n- Implementing fuzz tests for input validation\n- Following TDD workflow in Go projects\n\n## TDD Workflow for Go\n\n### The RED-GREEN-REFACTOR Cycle\n\n```\nRED     → Write a failing test first\nGREEN   → Write minimal code to pass the test\nREFACTOR → Improve code while keeping tests green\nREPEAT  → Continue with next requirement\n```\n\n### Step-by-Step TDD in Go\n\n```go\n// Step 1: Define the interface/signature\n// calculator.go\npackage calculator\n\nfunc Add(a, b int) int {\n    panic(\"not implemented\") // Placeholder\n}\n\n// Step 2: Write failing test (RED)\n// calculator_test.go\npackage calculator\n\nimport \"testing\"\n\nfunc TestAdd(t *testing.T) {\n    got := Add(2, 3)\n    want := 5\n    if got != want {\n        t.Errorf(\"Add(2, 3) = %d; want %d\", got, want)\n    }\n}\n\n// Step 3: Run test - verify FAIL\n// $ go test\n// --- FAIL: TestAdd (0.00s)\n// panic: not implemented\n\n// Step 4: Implement minimal code (GREEN)\nfunc Add(a, b int) int {\n    return a + b\n}\n\n// Step 5: Run test - verify PASS\n// $ go test\n// PASS\n\n// Step 6: Refactor if needed, verify tests still pass\n```\n\n## Table-Driven Tests\n\nThe standard pattern for Go tests. Enables comprehensive coverage with minimal code.\n\n```go\nfunc TestAdd(t *testing.T) {\n    tests := []struct {\n        name     string\n        a, b     int\n        expected int\n    }{\n        {\"positive numbers\", 2, 3, 5},\n        {\"negative numbers\", -1, -2, -3},\n        {\"zero values\", 0, 0, 0},\n        {\"mixed signs\", -1, 1, 0},\n        {\"large numbers\", 1000000, 2000000, 3000000},\n    }\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            got := Add(tt.a, tt.b)\n            if got != tt.expected {\n                t.Errorf(\"Add(%d, %d) = %d; want %d\",\n                    tt.a, tt.b, got, tt.expected)\n            }\n        })\n    }\n}\n```\n\n### Table-Driven Tests with Error Cases\n\n```go\nfunc TestParseConfig(t *testing.T) {\n    tests := []struct {\n        name    string\n        input   string\n        want    *Config\n        wantErr bool\n    }{\n        {\n            name:  \"valid config\",\n            input: `{\"host\": \"localhost\", \"port\": 8080}`,\n            want:  &Config{Host: \"localhost\", Port: 8080},\n        },\n        {\n            name:    \"invalid JSON\",\n            input:   `{invalid}`,\n            wantErr: true,\n        },\n        {\n            name:    \"empty input\",\n            input:   \"\",\n            wantErr: true,\n        },\n        {\n            name:  \"minimal config\",\n            input: `{}`,\n            want:  &Config{}, // Zero value config\n        },\n    }\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            got, err := ParseConfig(tt.input)\n\n            if tt.wantErr {\n                if err == nil {\n                    t.Error(\"expected error, got nil\")\n                }\n                return\n            }\n\n            if err != nil {\n                t.Fatalf(\"unexpected error: %v\", err)\n            }\n\n            if !reflect.DeepEqual(got, tt.want) {\n                t.Errorf(\"got %+v; want %+v\", got, tt.want)\n            }\n        })\n    }\n}\n```\n\n## Subtests and Sub-benchmarks\n\n### Organizing Related Tests\n\n```go\nfunc TestUser(t *testing.T) {\n    // Setup shared by all subtests\n    db := setupTestDB(t)\n\n    t.Run(\"Create\", func(t *testing.T) {\n        user := &User{Name: \"Alice\"}\n        err := db.CreateUser(user)\n        if err != nil {\n            t.Fatalf(\"CreateUser failed: %v\", err)\n        }\n        if user.ID == \"\" {\n            t.Error(\"expected user ID to be set\")\n        }\n    })\n\n    t.Run(\"Get\", func(t *testing.T) {\n        user, err := db.GetUser(\"alice-id\")\n        if err != nil {\n            t.Fatalf(\"GetUser failed: %v\", err)\n        }\n        if user.Name != \"Alice\" {\n            t.Errorf(\"got name %q; want %q\", user.Name, \"Alice\")\n        }\n    })\n\n    t.Run(\"Update\", func(t *testing.T) {\n        // ...\n    })\n\n    t.Run(\"Delete\", func(t *testing.T) {\n        // ...\n    })\n}\n```\n\n### Parallel Subtests\n\n```go\nfunc TestParallel(t *testing.T) {\n    tests := []struct {\n        name  string\n        input string\n    }{\n        {\"case1\", \"input1\"},\n        {\"case2\", \"input2\"},\n        {\"case3\", \"input3\"},\n    }\n\n    for _, tt := range tests {\n        tt := tt // Capture range variable\n        t.Run(tt.name, func(t *testing.T) {\n            t.Parallel() // Run subtests in parallel\n            result := Process(tt.input)\n            // assertions...\n            _ = result\n        })\n    }\n}\n```\n\n## Test Helpers\n\n### Helper Functions\n\n```go\nfunc setupTestDB(t *testing.T) *sql.DB {\n    t.Helper() // Marks this as a helper function\n\n    db, err := sql.Open(\"sqlite3\", \":memory:\")\n    if err != nil {\n        t.Fatalf(\"failed to open database: %v\", err)\n    }\n\n    // Cleanup when test finishes\n    t.Cleanup(func() {\n        db.Close()\n    })\n\n    // Run migrations\n    if _, err := db.Exec(schema); err != nil {\n        t.Fatalf(\"failed to create schema: %v\", err)\n    }\n\n    return db\n}\n\nfunc assertNoError(t *testing.T, err error) {\n    t.Helper()\n    if err != nil {\n        t.Fatalf(\"unexpected error: %v\", err)\n    }\n}\n\nfunc assertEqual[T comparable](t *testing.T, got, want T) {\n    t.Helper()\n    if got != want {\n        t.Errorf(\"got %v; want %v\", got, want)\n    }\n}\n```\n\n### Temporary Files and Directories\n\n```go\nfunc TestFileProcessing(t *testing.T) {\n    // Create temp directory - automatically cleaned up\n    tmpDir := t.TempDir()\n\n    // Create test file\n    testFile := filepath.Join(tmpDir, \"test.txt\")\n    err := os.WriteFile(testFile, []byte(\"test content\"), 0644)\n    if err != nil {\n        t.Fatalf(\"failed to create test file: %v\", err)\n    }\n\n    // Run test\n    result, err := ProcessFile(testFile)\n    if err != nil {\n        t.Fatalf(\"ProcessFile failed: %v\", err)\n    }\n\n    // Assert...\n    _ = result\n}\n```\n\n## Golden Files\n\nTesting against expected output files stored in `testdata/`.\n\n```go\nvar update = flag.Bool(\"update\", false, \"update golden files\")\n\nfunc TestRender(t *testing.T) {\n    tests := []struct {\n        name  string\n        input Template\n    }{\n        {\"simple\", Template{Name: \"test\"}},\n        {\"complex\", Template{Name: \"test\", Items: []string{\"a\", \"b\"}}},\n    }\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            got := Render(tt.input)\n\n            golden := filepath.Join(\"testdata\", tt.name+\".golden\")\n\n            if *update {\n                // Update golden file: go test -update\n                err := os.WriteFile(golden, got, 0644)\n                if err != nil {\n                    t.Fatalf(\"failed to update golden file: %v\", err)\n                }\n            }\n\n            want, err := os.ReadFile(golden)\n            if err != nil {\n                t.Fatalf(\"failed to read golden file: %v\", err)\n            }\n\n            if !bytes.Equal(got, want) {\n                t.Errorf(\"output mismatch:\\ngot:\\n%s\\nwant:\\n%s\", got, want)\n            }\n        })\n    }\n}\n```\n\n## Mocking with Interfaces\n\n### Interface-Based Mocking\n\n```go\n// Define interface for dependencies\ntype UserRepository interface {\n    GetUser(id string) (*User, error)\n    SaveUser(user *User) error\n}\n\n// Production implementation\ntype PostgresUserRepository struct {\n    db *sql.DB\n}\n\nfunc (r *PostgresUserRepository) GetUser(id string) (*User, error) {\n    // Real database query\n}\n\n// Mock implementation for tests\ntype MockUserRepository struct {\n    GetUserFunc  func(id string) (*User, error)\n    SaveUserFunc func(user *User) error\n}\n\nfunc (m *MockUserRepository) GetUser(id string) (*User, error) {\n    return m.GetUserFunc(id)\n}\n\nfunc (m *MockUserRepository) SaveUser(user *User) error {\n    return m.SaveUserFunc(user)\n}\n\n// Test using mock\nfunc TestUserService(t *testing.T) {\n    mock := &MockUserRepository{\n        GetUserFunc: func(id string) (*User, error) {\n            if id == \"123\" {\n                return &User{ID: \"123\", Name: \"Alice\"}, nil\n            }\n            return nil, ErrNotFound\n        },\n    }\n\n    service := NewUserService(mock)\n\n    user, err := service.GetUserProfile(\"123\")\n    if err != nil {\n        t.Fatalf(\"unexpected error: %v\", err)\n    }\n    if user.Name != \"Alice\" {\n        t.Errorf(\"got name %q; want %q\", user.Name, \"Alice\")\n    }\n}\n```\n\n## Benchmarks\n\n### Basic Benchmarks\n\n```go\nfunc BenchmarkProcess(b *testing.B) {\n    data := generateTestData(1000)\n    b.ResetTimer() // Don''t count setup time\n\n    for i := 0; i < b.N; i++ {\n        Process(data)\n    }\n}\n\n// Run: go test -bench=BenchmarkProcess -benchmem\n// Output: BenchmarkProcess-8   10000   105234 ns/op   4096 B/op   10 allocs/op\n```\n\n### Benchmark with Different Sizes\n\n```go\nfunc BenchmarkSort(b *testing.B) {\n    sizes := []int{100, 1000, 10000, 100000}\n\n    for _, size := range sizes {\n        b.Run(fmt.Sprintf(\"size=%d\", size), func(b *testing.B) {\n            data := generateRandomSlice(size)\n            b.ResetTimer()\n\n            for i := 0; i < b.N; i++ {\n                // Make a copy to avoid sorting already sorted data\n                tmp := make([]int, len(data))\n                copy(tmp, data)\n                sort.Ints(tmp)\n            }\n        })\n    }\n}\n```\n\n### Memory Allocation Benchmarks\n\n```go\nfunc BenchmarkStringConcat(b *testing.B) {\n    parts := []string{\"hello\", \"world\", \"foo\", \"bar\", \"baz\"}\n\n    b.Run(\"plus\", func(b *testing.B) {\n        for i := 0; i < b.N; i++ {\n            var s string\n            for _, p := range parts {\n                s += p\n            }\n            _ = s\n        }\n    })\n\n    b.Run(\"builder\", func(b *testing.B) {\n        for i := 0; i < b.N; i++ {\n            var sb strings.Builder\n            for _, p := range parts {\n                sb.WriteString(p)\n            }\n            _ = sb.String()\n        }\n    })\n\n    b.Run(\"join\", func(b *testing.B) {\n        for i := 0; i < b.N; i++ {\n            _ = strings.Join(parts, \"\")\n        }\n    })\n}\n```\n\n## Fuzzing (Go 1.18+)\n\n### Basic Fuzz Test\n\n```go\nfunc FuzzParseJSON(f *testing.F) {\n    // Add seed corpus\n    f.Add(`{\"name\": \"test\"}`)\n    f.Add(`{\"count\": 123}`)\n    f.Add(`[]`)\n    f.Add(`\"\"`)\n\n    f.Fuzz(func(t *testing.T, input string) {\n        var result map[string]interface{}\n        err := json.Unmarshal([]byte(input), &result)\n\n        if err != nil {\n            // Invalid JSON is expected for random input\n            return\n        }\n\n        // If parsing succeeded, re-encoding should work\n        _, err = json.Marshal(result)\n        if err != nil {\n            t.Errorf(\"Marshal failed after successful Unmarshal: %v\", err)\n        }\n    })\n}\n\n// Run: go test -fuzz=FuzzParseJSON -fuzztime=30s\n```\n\n### Fuzz Test with Multiple Inputs\n\n```go\nfunc FuzzCompare(f *testing.F) {\n    f.Add(\"hello\", \"world\")\n    f.Add(\"\", \"\")\n    f.Add(\"abc\", \"abc\")\n\n    f.Fuzz(func(t *testing.T, a, b string) {\n        result := Compare(a, b)\n\n        // Property: Compare(a, a) should always equal 0\n        if a == b && result != 0 {\n            t.Errorf(\"Compare(%q, %q) = %d; want 0\", a, b, result)\n        }\n\n        // Property: Compare(a, b) and Compare(b, a) should have opposite signs\n        reverse := Compare(b, a)\n        if (result > 0 && reverse >= 0) || (result < 0 && reverse <= 0) {\n            if result != 0 || reverse != 0 {\n                t.Errorf(\"Compare(%q, %q) = %d, Compare(%q, %q) = %d; inconsistent\",\n                    a, b, result, b, a, reverse)\n            }\n        }\n    })\n}\n```\n\n## Test Coverage\n\n### Running Coverage\n\n```bash\n# Basic coverage\ngo test -cover ./...\n\n# Generate coverage profile\ngo test -coverprofile=coverage.out ./...\n\n# View coverage in browser\ngo tool cover -html=coverage.out\n\n# View coverage by function\ngo tool cover -func=coverage.out\n\n# Coverage with race detection\ngo test -race -coverprofile=coverage.out ./...\n```\n\n### Coverage Targets\n\n| Code Type | Target |\n|-----------|--------|\n| Critical business logic | 100% |\n| Public APIs | 90%+ |\n| General code | 80%+ |\n| Generated code | Exclude |\n\n### Excluding Generated Code from Coverage\n\n```go\n//go:generate mockgen -source=interface.go -destination=mock_interface.go\n\n// In coverage profile, exclude with build tags:\n// go test -cover -tags=!generate ./...\n```\n\n## HTTP Handler Testing\n\n```go\nfunc TestHealthHandler(t *testing.T) {\n    // Create request\n    req := httptest.NewRequest(http.MethodGet, \"/health\", nil)\n    w := httptest.NewRecorder()\n\n    // Call handler\n    HealthHandler(w, req)\n\n    // Check response\n    resp := w.Result()\n    defer resp.Body.Close()\n\n    if resp.StatusCode != http.StatusOK {\n        t.Errorf(\"got status %d; want %d\", resp.StatusCode, http.StatusOK)\n    }\n\n    body, _ := io.ReadAll(resp.Body)\n    if string(body) != \"OK\" {\n        t.Errorf(\"got body %q; want %q\", body, \"OK\")\n    }\n}\n\nfunc TestAPIHandler(t *testing.T) {\n    tests := []struct {\n        name       string\n        method     string\n        path       string\n        body       string\n        wantStatus int\n        wantBody   string\n    }{\n        {\n            name:       \"get user\",\n            method:     http.MethodGet,\n            path:       \"/users/123\",\n            wantStatus: http.StatusOK,\n            wantBody:   `{\"id\":\"123\",\"name\":\"Alice\"}`,\n        },\n        {\n            name:       \"not found\",\n            method:     http.MethodGet,\n            path:       \"/users/999\",\n            wantStatus: http.StatusNotFound,\n        },\n        {\n            name:       \"create user\",\n            method:     http.MethodPost,\n            path:       \"/users\",\n            body:       `{\"name\":\"Bob\"}`,\n            wantStatus: http.StatusCreated,\n        },\n    }\n\n    handler := NewAPIHandler()\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            var body io.Reader\n            if tt.body != \"\" {\n                body = strings.NewReader(tt.body)\n            }\n\n            req := httptest.NewRequest(tt.method, tt.path, body)\n            req.Header.Set(\"Content-Type\", \"application/json\")\n            w := httptest.NewRecorder()\n\n            handler.ServeHTTP(w, req)\n\n            if w.Code != tt.wantStatus {\n                t.Errorf(\"got status %d; want %d\", w.Code, tt.wantStatus)\n            }\n\n            if tt.wantBody != \"\" && w.Body.String() != tt.wantBody {\n                t.Errorf(\"got body %q; want %q\", w.Body.String(), tt.wantBody)\n            }\n        })\n    }\n}\n```\n\n## Testing Commands\n\n```bash\n# Run all tests\ngo test ./...\n\n# Run tests with verbose output\ngo test -v ./...\n\n# Run specific test\ngo test -run TestAdd ./...\n\n# Run tests matching pattern\ngo test -run \"TestUser/Create\" ./...\n\n# Run tests with race detector\ngo test -race ./...\n\n# Run tests with coverage\ngo test -cover -coverprofile=coverage.out ./...\n\n# Run short tests only\ngo test -short ./...\n\n# Run tests with timeout\ngo test -timeout 30s ./...\n\n# Run benchmarks\ngo test -bench=. -benchmem ./...\n\n# Run fuzzing\ngo test -fuzz=FuzzParse -fuzztime=30s ./...\n\n# Count test runs (for flaky test detection)\ngo test -count=10 ./...\n```\n\n## Best Practices\n\n**DO:**\n- Write tests FIRST (TDD)\n- Use table-driven tests for comprehensive coverage\n- Test behavior, not implementation\n- Use `t.Helper()` in helper functions\n- Use `t.Parallel()` for independent tests\n- Clean up resources with `t.Cleanup()`\n- Use meaningful test names that describe the scenario\n\n**DON''T:**\n- Test private functions directly (test through public API)\n- Use `time.Sleep()` in tests (use channels or conditions)\n- Ignore flaky tests (fix or remove them)\n- Mock everything (prefer integration tests when possible)\n- Skip error path testing\n\n## Integration with CI/CD\n\n```yaml\n# GitHub Actions example\ntest:\n  runs-on: ubuntu-latest\n  steps:\n    - uses: actions/checkout@v4\n    - uses: actions/setup-go@v5\n      with:\n        go-version: ''1.22''\n\n    - name: Run tests\n      run: go test -race -coverprofile=coverage.out ./...\n\n    - name: Check coverage\n      run: |\n        go tool cover -func=coverage.out | grep total | awk ''{print $3}'' | \\\n        awk -F''%'' ''{if ($1 < 80) exit 1}''\n```\n\n**Remember**: Tests are documentation. They show how your code is meant to be used. Write them clearly and keep them up to date.\n"},"category":"official","lastSynced":"2026-03-06T04:14:33.280Z","seo":{"title":{"en":"golang-testing: Comprehensive Test Coverage Setup Guide |...","zh":"Go语言测试模式设置指南 - TDD实践","ja":"Goテストパターンのベストプラクティス - AIエージェントを使用する","ko":"고랭测试 패턴 설정 가이드 - TDD 방법론","es":"Guía de pruebas de Go: patrones y prácticas de testing","fr":"Guide de tests Go: modèles et bonnes pratiques de testing","de":"Go-Testing-Anleitung: Muster und Best Practices für zuver...","pt":"Padrões de Teste em Golang: Guia Completo com AI Agents","ru":"Паттерны тестирования в Golang: Полное руководство с ИИ А...","ar":"أنماط اختبار Golang: دليل شامل مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient Go testing patterns with table-driven tests, subtests, and benchmarks. Learn how to activate golang-testing for reliable code, and get start...","zh":"了解Go语言测试模式，包括表驱动测试、子测试、基准测试、模糊测试和测试覆盖率，使用TDD方法提高代码质量","ja":"Goテストパターンを使用して、信頼性の高いテストを書くためのベストプラクティスを学びましょう - AIエージェントとTDD方法論","ko":"고랭测试 패턴에 대해 알아보고, 테이블 드라이븐 테스트, 서브테스트, 벤치마크 테스트, 퍼징 테스트 및 테스트 커버리지와 같은 기능을 사용하여 코드 품질을 향상시키세요","es":"Aprende a escribir pruebas de Go confiables y mantenibles con patrones de testing como table-driven tests, subtests y benchmarks","fr":"Découvrez comment écrire des tests Go fiables et maintenables avec des modèles de testing tels que les tests pilotés par table, les sous-tests et les benchmarks","de":"Erfahren Sie, wie Sie zuverlässige und wartbare Go-Tests mit Testmus