INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/golang-testing', 'golang-testing', 'affaan-m', 'everything-claude-code', 'official', 'golang-testing affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The golang-testing skill provides comprehensive Go testing patterns for writing reliable, maintainable tests following TDD methodology, benefiting Go developers and teams. Go语言测试模式是使用TDD方法提高代码质量的综合解决方案，包括表驱动测试、子测试、基准测试、模糊测试和测试覆盖率等功能 Goテストパターンは、TDD方法論を使用して信頼性の高いテストを書くための包括的なソリューションです 고랭测试 패턴은 TDD 방법론을 사용하여 코드 품질을 향상시키는 통합 솔루션으로, 테이블 드라이븐 테스트, 서브테스트, 벤치마크 테스트, 퍼징 테스트 및 테스트 커버리지 등의 기능을 제공합니다 El patrón de testing de Go proporciona una forma de escribir pruebas confiables y mantenibles utilizando TDD y prácticas idiomáticas de Go Le modèle de test Go fournit un moyen d''écrire des tests fiables et maintenables en utilisant TDD et des pratiques idiomatiques de Go Das Go-Testing-Muster bietet eine Möglichkeit, zuverlässige und wartbare Tests unter Verwendung von TDD und idiomatischen Go-Praktiken zu schreiben Este AI Agent especializado em Golang implementa padrões de teste avançados como table-driven tests, subtests e fuzzing. Segue metodologia TDD (Red-Green-Refactor) com práticas idiomáticas da linguagem Go para testes confiáveis e de alta cobertura. Этот ИИ Агент специализируется на продвинутых паттернах тестирования в Golang, включая табличное тестирование, подтесты и фаззинг. Следует методологии TDD (Red-Green-Refactor) с идиоматическими практиками языка Go для надежных тестов с высоким покрытием. يتخصص هذا الوكيل الذكي في أنماط الاختبار المتقدمة في Golang بما في ذلك الاختبارات المجدولة، الاختبارات الفرعية والاختبار الضبابي. يتبع منهجية TDD (Red-Green-Refactor) مع الممارسات الاصطلاحية للغة Go لاختبارات موثوقة وعالية التغطية. how to use golang-testing golang testing patterns TDD methodology in Go golang-testing vs GoConvey golang-testing install golang testing best practices table-driven tests in Go subtests in golang-testing golang-testing setup guide Go语言测试 TDD方法论 表驱动测试 子测试 基准测试 模糊测试 测试覆盖率 AIエージェント 软件开发 Table-driven tests for efficient test case management Subtests for organizing and running related tests Benchmarks for measuring performance-critical code Fuzzing for input validation and error handling Test coverage analysis for ensuring reliable code golang-testing is a set of Go testing patterns including table-driven tests, subtests, benchmarks, fuzzing, and test coverage, following TDD methodology with idiomatic Go practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/python-testing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'python-testing', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T04:28:03.134Z', 'b304a8c503af32644f97a889c5545ee4f90e91980462ad4ce33fee3dea6f414f', '{"id":"affaan-m/everything-claude-code/python-testing","name":"python-testing","description":{"en":"The python-testing skill provides comprehensive testing strategies for Python applications using pytest, TDD methodology, and best practices, benefiting developers and AI agents alike.","zh":"Python pytest测试框架的完整TDD开发指南，涵盖fixtures依赖注入、mock对象技术、参数化测试用例设计和覆盖率报告生成。","ja":"Python pytestテストフレームワークによる包括的なTDD開発手法、fixturesによる依存性注入、mockオブジェクト技術、パラメータ化テストケース設計とカバレッジレポート生成。","ko":"Python pytest 테스트 프레임워크를 이용한 종합적인 TDD 개발 방법론, fixtures를 통한 의존성 주입, mock 객체 기술, 매개변수화 테스트 케이스 설계 및 커버리지 리포트 생성。","es":"Pruebas de Python con pytest, TDD y mejores prácticas para desarrolladores","fr":"Tests Python avec pytest, TDD et meilleures pratiques pour les développeurs","de":"Python-Tests mit pytest, TDD und Best Practices für Entwickler","pt":"Desenvolva testes em Python com pytest, TDD e boas práticas para garantir a qualidade do seu código","ru":"Разрабатывайте тесты для Python с помощью pytest, TDD и лучших практик для обеспечения качества вашего кода","ar":"قُم بتطوير الاختبارات ببايثون باستخدام pytest و TDD وأفضل الممارسات لضمان جودة كودك"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"python-testing","description":"Python testing strategies using pytest, TDD methodology, fixtures, mocking, parametrization, and coverage requirements.","bodyPreview":"# Python Testing Patterns\n\nComprehensive testing strategies for Python applications using pytest, TDD methodology, and best practices.\n\n## When to Activate\n\n- Writing new Python code (follow TDD: red, green, refactor)\n- Designing test suites for Python projects\n- Reviewing Python test coverage\n- Setting up testing infrastructure\n\n## Core Testing Philosophy\n\n### Test-Driven Development (TDD)\n\nAlways follow the TDD cycle:\n\n1. **RED**: Write a failing test for the desired behavior\n2. **GREEN**: Wri","body":"# Python Testing Patterns\n\nComprehensive testing strategies for Python applications using pytest, TDD methodology, and best practices.\n\n## When to Activate\n\n- Writing new Python code (follow TDD: red, green, refactor)\n- Designing test suites for Python projects\n- Reviewing Python test coverage\n- Setting up testing infrastructure\n\n## Core Testing Philosophy\n\n### Test-Driven Development (TDD)\n\nAlways follow the TDD cycle:\n\n1. **RED**: Write a failing test for the desired behavior\n2. **GREEN**: Write minimal code to make the test pass\n3. **REFACTOR**: Improve code while keeping tests green\n\n```python\n# Step 1: Write failing test (RED)\ndef test_add_numbers():\n    result = add(2, 3)\n    assert result == 5\n\n# Step 2: Write minimal implementation (GREEN)\ndef add(a, b):\n    return a + b\n\n# Step 3: Refactor if needed (REFACTOR)\n```\n\n### Coverage Requirements\n\n- **Target**: 80%+ code coverage\n- **Critical paths**: 100% coverage required\n- Use `pytest --cov` to measure coverage\n\n```bash\npytest --cov=mypackage --cov-report=term-missing --cov-report=html\n```\n\n## pytest Fundamentals\n\n### Basic Test Structure\n\n```python\nimport pytest\n\ndef test_addition():\n    \"\"\"Test basic addition.\"\"\"\n    assert 2 + 2 == 4\n\ndef test_string_uppercase():\n    \"\"\"Test string uppercasing.\"\"\"\n    text = \"hello\"\n    assert text.upper() == \"HELLO\"\n\ndef test_list_append():\n    \"\"\"Test list append.\"\"\"\n    items = [1, 2, 3]\n    items.append(4)\n    assert 4 in items\n    assert len(items) == 4\n```\n\n### Assertions\n\n```python\n# Equality\nassert result == expected\n\n# Inequality\nassert result != unexpected\n\n# Truthiness\nassert result  # Truthy\nassert not result  # Falsy\nassert result is True  # Exactly True\nassert result is False  # Exactly False\nassert result is None  # Exactly None\n\n# Membership\nassert item in collection\nassert item not in collection\n\n# Comparisons\nassert result > 0\nassert 0 <= result <= 100\n\n# Type checking\nassert isinstance(result, str)\n\n# Exception testing (preferred approach)\nwith pytest.raises(ValueError):\n    raise ValueError(\"error message\")\n\n# Check exception message\nwith pytest.raises(ValueError, match=\"invalid input\"):\n    raise ValueError(\"invalid input provided\")\n\n# Check exception attributes\nwith pytest.raises(ValueError) as exc_info:\n    raise ValueError(\"error message\")\nassert str(exc_info.value) == \"error message\"\n```\n\n## Fixtures\n\n### Basic Fixture Usage\n\n```python\nimport pytest\n\n@pytest.fixture\ndef sample_data():\n    \"\"\"Fixture providing sample data.\"\"\"\n    return {\"name\": \"Alice\", \"age\": 30}\n\ndef test_sample_data(sample_data):\n    \"\"\"Test using the fixture.\"\"\"\n    assert sample_data[\"name\"] == \"Alice\"\n    assert sample_data[\"age\"] == 30\n```\n\n### Fixture with Setup/Teardown\n\n```python\n@pytest.fixture\ndef database():\n    \"\"\"Fixture with setup and teardown.\"\"\"\n    # Setup\n    db = Database(\":memory:\")\n    db.create_tables()\n    db.insert_test_data()\n\n    yield db  # Provide to test\n\n    # Teardown\n    db.close()\n\ndef test_database_query(database):\n    \"\"\"Test database operations.\"\"\"\n    result = database.query(\"SELECT * FROM users\")\n    assert len(result) > 0\n```\n\n### Fixture Scopes\n\n```python\n# Function scope (default) - runs for each test\n@pytest.fixture\ndef temp_file():\n    with open(\"temp.txt\", \"w\") as f:\n        yield f\n    os.remove(\"temp.txt\")\n\n# Module scope - runs once per module\n@pytest.fixture(scope=\"module\")\ndef module_db():\n    db = Database(\":memory:\")\n    db.create_tables()\n    yield db\n    db.close()\n\n# Session scope - runs once per test session\n@pytest.fixture(scope=\"session\")\ndef shared_resource():\n    resource = ExpensiveResource()\n    yield resource\n    resource.cleanup()\n```\n\n### Fixture with Parameters\n\n```python\n@pytest.fixture(params=[1, 2, 3])\ndef number(request):\n    \"\"\"Parameterized fixture.\"\"\"\n    return request.param\n\ndef test_numbers(number):\n    \"\"\"Test runs 3 times, once for each parameter.\"\"\"\n    assert number > 0\n```\n\n### Using Multiple Fixtures\n\n```python\n@pytest.fixture\ndef user():\n    return User(id=1, name=\"Alice\")\n\n@pytest.fixture\ndef admin():\n    return User(id=2, name=\"Admin\", role=\"admin\")\n\ndef test_user_admin_interaction(user, admin):\n    \"\"\"Test using multiple fixtures.\"\"\"\n    assert admin.can_manage(user)\n```\n\n### Autouse Fixtures\n\n```python\n@pytest.fixture(autouse=True)\ndef reset_config():\n    \"\"\"Automatically runs before every test.\"\"\"\n    Config.reset()\n    yield\n    Config.cleanup()\n\ndef test_without_fixture_call():\n    # reset_config runs automatically\n    assert Config.get_setting(\"debug\") is False\n```\n\n### Conftest.py for Shared Fixtures\n\n```python\n# tests/conftest.py\nimport pytest\n\n@pytest.fixture\ndef client():\n    \"\"\"Shared fixture for all tests.\"\"\"\n    app = create_app(testing=True)\n    with app.test_client() as client:\n        yield client\n\n@pytest.fixture\ndef auth_headers(client):\n    \"\"\"Generate auth headers for API testing.\"\"\"\n    response = client.post(\"/api/login\", json={\n        \"username\": \"test\",\n        \"password\": \"test\"\n    })\n    token = response.json[\"token\"]\n    return {\"Authorization\": f\"Bearer {token}\"}\n```\n\n## Parametrization\n\n### Basic Parametrization\n\n```python\n@pytest.mark.parametrize(\"input,expected\", [\n    (\"hello\", \"HELLO\"),\n    (\"world\", \"WORLD\"),\n    (\"PyThOn\", \"PYTHON\"),\n])\ndef test_uppercase(input, expected):\n    \"\"\"Test runs 3 times with different inputs.\"\"\"\n    assert input.upper() == expected\n```\n\n### Multiple Parameters\n\n```python\n@pytest.mark.parametrize(\"a,b,expected\", [\n    (2, 3, 5),\n    (0, 0, 0),\n    (-1, 1, 0),\n    (100, 200, 300),\n])\ndef test_add(a, b, expected):\n    \"\"\"Test addition with multiple inputs.\"\"\"\n    assert add(a, b) == expected\n```\n\n### Parametrize with IDs\n\n```python\n@pytest.mark.parametrize(\"input,expected\", [\n    (\"valid@email.com\", True),\n    (\"invalid\", False),\n    (\"@no-domain.com\", False),\n], ids=[\"valid-email\", \"missing-at\", \"missing-domain\"])\ndef test_email_validation(input, expected):\n    \"\"\"Test email validation with readable test IDs.\"\"\"\n    assert is_valid_email(input) is expected\n```\n\n### Parametrized Fixtures\n\n```python\n@pytest.fixture(params=[\"sqlite\", \"postgresql\", \"mysql\"])\ndef db(request):\n    \"\"\"Test against multiple database backends.\"\"\"\n    if request.param == \"sqlite\":\n        return Database(\":memory:\")\n    elif request.param == \"postgresql\":\n        return Database(\"postgresql://localhost/test\")\n    elif request.param == \"mysql\":\n        return Database(\"mysql://localhost/test\")\n\ndef test_database_operations(db):\n    \"\"\"Test runs 3 times, once for each database.\"\"\"\n    result = db.query(\"SELECT 1\")\n    assert result is not None\n```\n\n## Markers and Test Selection\n\n### Custom Markers\n\n```python\n# Mark slow tests\n@pytest.mark.slow\ndef test_slow_operation():\n    time.sleep(5)\n\n# Mark integration tests\n@pytest.mark.integration\ndef test_api_integration():\n    response = requests.get(\"https://api.example.com\")\n    assert response.status_code == 200\n\n# Mark unit tests\n@pytest.mark.unit\ndef test_unit_logic():\n    assert calculate(2, 3) == 5\n```\n\n### Run Specific Tests\n\n```bash\n# Run only fast tests\npytest -m \"not slow\"\n\n# Run only integration tests\npytest -m integration\n\n# Run integration or slow tests\npytest -m \"integration or slow\"\n\n# Run tests marked as unit but not slow\npytest -m \"unit and not slow\"\n```\n\n### Configure Markers in pytest.ini\n\n```ini\n[pytest]\nmarkers =\n    slow: marks tests as slow\n    integration: marks tests as integration tests\n    unit: marks tests as unit tests\n    django: marks tests as requiring Django\n```\n\n## Mocking and Patching\n\n### Mocking Functions\n\n```python\nfrom unittest.mock import patch, Mock\n\n@patch(\"mypackage.external_api_call\")\ndef test_with_mock(api_call_mock):\n    \"\"\"Test with mocked external API.\"\"\"\n    api_call_mock.return_value = {\"status\": \"success\"}\n\n    result = my_function()\n\n    api_call_mock.assert_called_once()\n    assert result[\"status\"] == \"success\"\n```\n\n### Mocking Return Values\n\n```python\n@patch(\"mypackage.Database.connect\")\ndef test_database_connection(connect_mock):\n    \"\"\"Test with mocked database connection.\"\"\"\n    connect_mock.return_value = MockConnection()\n\n    db = Database()\n    db.connect()\n\n    connect_mock.assert_called_once_with(\"localhost\")\n```\n\n### Mocking Exceptions\n\n```python\n@patch(\"mypackage.api_call\")\ndef test_api_error_handling(api_call_mock):\n    \"\"\"Test error handling with mocked exception.\"\"\"\n    api_call_mock.side_effect = ConnectionError(\"Network error\")\n\n    with pytest.raises(ConnectionError):\n        api_call()\n\n    api_call_mock.assert_called_once()\n```\n\n### Mocking Context Managers\n\n```python\n@patch(\"builtins.open\", new_callable=mock_open)\ndef test_file_reading(mock_file):\n    \"\"\"Test file reading with mocked open.\"\"\"\n    mock_file.return_value.read.return_value = \"file content\"\n\n    result = read_file(\"test.txt\")\n\n    mock_file.assert_called_once_with(\"test.txt\", \"r\")\n    assert result == \"file content\"\n```\n\n### Using Autospec\n\n```python\n@patch(\"mypackage.DBConnection\", autospec=True)\ndef test_autospec(db_mock):\n    \"\"\"Test with autospec to catch API misuse.\"\"\"\n    db = db_mock.return_value\n    db.query(\"SELECT * FROM users\")\n\n    # This would fail if DBConnection doesn''t have query method\n    db_mock.assert_called_once()\n```\n\n### Mock Class Instances\n\n```python\nclass TestUserService:\n    @patch(\"mypackage.UserRepository\")\n    def test_create_user(self, repo_mock):\n        \"\"\"Test user creation with mocked repository.\"\"\"\n        repo_mock.return_value.save.return_value = User(id=1, name=\"Alice\")\n\n        service = UserService(repo_mock.return_value)\n        user = service.create_user(name=\"Alice\")\n\n        assert user.name == \"Alice\"\n        repo_mock.return_value.save.assert_called_once()\n```\n\n### Mock Property\n\n```python\n@pytest.fixture\ndef mock_config():\n    \"\"\"Create a mock with a property.\"\"\"\n    config = Mock()\n    type(config).debug = PropertyMock(return_value=True)\n    type(config).api_key = PropertyMock(return_value=\"test-key\")\n    return config\n\ndef test_with_mock_config(mock_config):\n    \"\"\"Test with mocked config properties.\"\"\"\n    assert mock_config.debug is True\n    assert mock_config.api_key == \"test-key\"\n```\n\n## Testing Async Code\n\n### Async Tests with pytest-asyncio\n\n```python\nimport pytest\n\n@pytest.mark.asyncio\nasync def test_async_function():\n    \"\"\"Test async function.\"\"\"\n    result = await async_add(2, 3)\n    assert result == 5\n\n@pytest.mark.asyncio\nasync def test_async_with_fixture(async_client):\n    \"\"\"Test async with async fixture.\"\"\"\n    response = await async_client.get(\"/api/users\")\n    assert response.status_code == 200\n```\n\n### Async Fixture\n\n```python\n@pytest.fixture\nasync def async_client():\n    \"\"\"Async fixture providing async test client.\"\"\"\n    app = create_app()\n    async with app.test_client() as client:\n        yield client\n\n@pytest.mark.asyncio\nasync def test_api_endpoint(async_client):\n    \"\"\"Test using async fixture.\"\"\"\n    response = await async_client.get(\"/api/data\")\n    assert response.status_code == 200\n```\n\n### Mocking Async Functions\n\n```python\n@pytest.mark.asyncio\n@patch(\"mypackage.async_api_call\")\nasync def test_async_mock(api_call_mock):\n    \"\"\"Test async function with mock.\"\"\"\n    api_call_mock.return_value = {\"status\": \"ok\"}\n\n    result = await my_async_function()\n\n    api_call_mock.assert_awaited_once()\n    assert result[\"status\"] == \"ok\"\n```\n\n## Testing Exceptions\n\n### Testing Expected Exceptions\n\n```python\ndef test_divide_by_zero():\n    \"\"\"Test that dividing by zero raises ZeroDivisionError.\"\"\"\n    with pytest.raises(ZeroDivisionError):\n        divide(10, 0)\n\ndef test_custom_exception():\n    \"\"\"Test custom exception with message.\"\"\"\n    with pytest.raises(ValueError, match=\"invalid input\"):\n        validate_input(\"invalid\")\n```\n\n### Testing Exception Attributes\n\n```python\ndef test_exception_with_details():\n    \"\"\"Test exception with custom attributes.\"\"\"\n    with pytest.raises(CustomError) as exc_info:\n        raise CustomError(\"error\", code=400)\n\n    assert exc_info.value.code == 400\n    assert \"error\" in str(exc_info.value)\n```\n\n## Testing Side Effects\n\n### Testing File Operations\n\n```python\nimport tempfile\nimport os\n\ndef test_file_processing():\n    \"\"\"Test file processing with temp file.\"\"\"\n    with tempfile.NamedTemporaryFile(mode=''w'', delete=False, suffix=''.txt'') as f:\n        f.write(\"test content\")\n        temp_path = f.name\n\n    try:\n        result = process_file(temp_path)\n        assert result == \"processed: test content\"\n    finally:\n        os.unlink(temp_path)\n```\n\n### Testing with pytest''s tmp_path Fixture\n\n```python\ndef test_with_tmp_path(tmp_path):\n    \"\"\"Test using pytest''s built-in temp path fixture.\"\"\"\n    test_file = tmp_path / \"test.txt\"\n    test_file.write_text(\"hello world\")\n\n    result = process_file(str(test_file))\n    assert result == \"hello world\"\n    # tmp_path automatically cleaned up\n```\n\n### Testing with tmpdir Fixture\n\n```python\ndef test_with_tmpdir(tmpdir):\n    \"\"\"Test using pytest''s tmpdir fixture.\"\"\"\n    test_file = tmpdir.join(\"test.txt\")\n    test_file.write(\"data\")\n\n    result = process_file(str(test_file))\n    assert result == \"data\"\n```\n\n## Test Organization\n\n### Directory Structure\n\n```\ntests/\n├── conftest.py                 # Shared fixtures\n├── __init__.py\n├── unit/                       # Unit tests\n│   ├── __init__.py\n│   ├── test_models.py\n│   ├── test_utils.py\n│   └── test_services.py\n├── integration/                # Integration tests\n│   ├── __init__.py\n│   ├── test_api.py\n│   └── test_database.py\n└── e2e/                        # End-to-end tests\n    ├── __init__.py\n    └── test_user_flow.py\n```\n\n### Test Classes\n\n```python\nclass TestUserService:\n    \"\"\"Group related tests in a class.\"\"\"\n\n    @pytest.fixture(autouse=True)\n    def setup(self):\n        \"\"\"Setup runs before each test in this class.\"\"\"\n        self.service = UserService()\n\n    def test_create_user(self):\n        \"\"\"Test user creation.\"\"\"\n        user = self.service.create_user(\"Alice\")\n        assert user.name == \"Alice\"\n\n    def test_delete_user(self):\n        \"\"\"Test user deletion.\"\"\"\n        user = User(id=1, name=\"Bob\")\n        self.service.delete_user(user)\n        assert not self.service.user_exists(1)\n```\n\n## Best Practices\n\n### DO\n\n- **Follow TDD**: Write tests before code (red-green-refactor)\n- **Test one thing**: Each test should verify a single behavior\n- **Use descriptive names**: `test_user_login_with_invalid_credentials_fails`\n- **Use fixtures**: Eliminate duplication with fixtures\n- **Mock external dependencies**: Don''t depend on external services\n- **Test edge cases**: Empty inputs, None values, boundary conditions\n- **Aim for 80%+ coverage**: Focus on critical paths\n- **Keep tests fast**: Use marks to separate slow tests\n\n### DON''T\n\n- **Don''t test implementation**: Test behavior, not internals\n- **Don''t use complex conditionals in tests**: Keep tests simple\n- **Don''t ignore test failures**: All tests must pass\n- **Don''t test third-party code**: Trust libraries to work\n- **Don''t share state between tests**: Tests should be independent\n- **Don''t catch exceptions in tests**: Use `pytest.raises`\n- **Don''t use print statements**: Use assertions and pytest output\n- **Don''t write tests that are too brittle**: Avoid over-specific mocks\n\n## Common Patterns\n\n### Testing API Endpoints (FastAPI/Flask)\n\n```python\n@pytest.fixture\ndef client():\n    app = create_app(testing=True)\n    return app.test_client()\n\ndef test_get_user(client):\n    response = client.get(\"/api/users/1\")\n    assert response.status_code == 200\n    assert response.json[\"id\"] == 1\n\ndef test_create_user(client):\n    response = client.post(\"/api/users\", json={\n        \"name\": \"Alice\",\n        \"email\": \"alice@example.com\"\n    })\n    assert response.status_code == 201\n    assert response.json[\"name\"] == \"Alice\"\n```\n\n### Testing Database Operations\n\n```python\n@pytest.fixture\ndef db_session():\n    \"\"\"Create a test database session.\"\"\"\n    session = Session(bind=engine)\n    session.begin_nested()\n    yield session\n    session.rollback()\n    session.close()\n\ndef test_create_user(db_session):\n    user = User(name=\"Alice\", email=\"alice@example.com\")\n    db_session.add(user)\n    db_session.commit()\n\n    retrieved = db_session.query(User).filter_by(name=\"Alice\").first()\n    assert retrieved.email == \"alice@example.com\"\n```\n\n### Testing Class Methods\n\n```python\nclass TestCalculator:\n    @pytest.fixture\n    def calculator(self):\n        return Calculator()\n\n    def test_add(self, calculator):\n        assert calculator.add(2, 3) == 5\n\n    def test_divide_by_zero(self, calculator):\n        with pytest.raises(ZeroDivisionError):\n            calculator.divide(10, 0)\n```\n\n## pytest Configuration\n\n### pytest.ini\n\n```ini\n[pytest]\ntestpaths = tests\npython_files = test_*.py\npython_classes = Test*\npython_functions = test_*\naddopts =\n    --strict-markers\n    --disable-warnings\n    --cov=mypackage\n    --cov-report=term-missing\n    --cov-report=html\nmarkers =\n    slow: marks tests as slow\n    integration: marks tests as integration tests\n    unit: marks tests as unit tests\n```\n\n### pyproject.toml\n\n```toml\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\npython_classes = [\"Test*\"]\npython_functions = [\"test_*\"]\naddopts = [\n    \"--strict-markers\",\n    \"--cov=mypackage\",\n    \"--cov-report=term-missing\",\n    \"--cov-report=html\",\n]\nmarkers = [\n    \"slow: marks tests as slow\",\n    \"integration: marks tests as integration tests\",\n    \"unit: marks tests as unit tests\",\n]\n```\n\n## Running Tests\n\n```bash\n# Run all tests\npytest\n\n# Run specific file\npytest tests/test_utils.py\n\n# Run specific test\npytest tests/test_utils.py::test_function\n\n# Run with verbose output\npytest -v\n\n# Run with coverage\npytest --cov=mypackage --cov-report=html\n\n# Run only fast tests\npytest -m \"not slow\"\n\n# Run until first failure\npytest -x\n\n# Run and stop on N failures\npytest --maxfail=3\n\n# Run last failed tests\npytest --lf\n\n# Run tests with pattern\npytest -k \"test_user\"\n\n# Run with debugger on failure\npytest --pdb\n```\n\n## Quick Reference\n\n| Pattern | Usage |\n|---------|-------|\n| `pytest.raises()` | Test expected exceptions |\n| `@pytest.fixture()` | Create reusable test fixtures |\n| `@pytest.mark.parametrize()` | Run tests with multiple inputs |\n| `@pytest.mark.slow` | Mark slow tests |\n| `pytest -m \"not slow\"` | Skip slow tests |\n| `@patch()` | Mock functions and classes |\n| `tmp_path` fixture | Automatic temp directory |\n| `pytest --cov` | Generate coverage report |\n| `assert` | Simple and readable assertions |\n\n**Remember**: Tests are code too. Keep them clean, readable, and maintainable. Good tests catch bugs; great tests prevent them.\n"},"category":"official","lastSynced":"2026-03-06T04:28:03.134Z","seo":{"title":{"en":"python-testing: Comprehensive Testing Strategies for AI A...","zh":"Python测试指南 pytest TDD方法","ja":"Pythonテスト戦略 pytest TDD手法","ko":"Python 테스트 전략 pytest TDD 방법론","es":"Guía de configuración para pruebas de Python con pytest","fr":"Guide de mise en place des tests Python avec pytest","de":"Einrichtungsanleitung für Python-Tests mit pytest","pt":"Guia de Configuração de Testes em Python com Pytest","ru":"Настройка тестирования Python с помощью pytest и ИИ Агентов","ar":"دليل إعداد الاختبارات ببايثون باستخدام pytest ووكيلات الذ..."},"description":{"en":"Unlock efficient Python testing with pytest, TDD, and best practices. Learn how to set up testing infrastructure and improve test coverage - get started now!","zh":"Python pytest测试框架的TDD开发流程，包含fixtures使用、mock技术、参数化测试和覆盖率要求的最佳实践指南。","ja":"Python pytestテストフレームワークを用いたTDD開発手法、fixturesの活用、mock技術、パラメータ化テストとカバレッジ要件の実践ガイド。","ko":"Python pytest 테스트 프레임워크의 TDD 개발 프로세스, fixtures 사용법, mock 기술, 매개변수화 테스트 및 커버리지 요구사항의 최적 실천指南。","es":"Aprende a implementar estrategias de prueba de Python con pytest, TDD y mejores prácticas para mejorar la calidad de tu código","fr":"Découvrez comment mettre en place des stratégies de test Python avec pytest, TDD et meilleures pratiques pour améliorer la qualité de votre code","de":"Erfahren Sie, wie Sie Python-Teststrategien mit pytest, TDD und Best Practices implementieren, um die Qualität Ihres Codes zu verbessern","pt":"Aprenda a configurar testes em Python com pytest, TDD e boas práticas para melhorar a qualidade do seu código","ru":"Узнайте, как настроить тестирование Python с помощью pytest, TDD и лучших практик для повышения качества вашего кода с помощью ИИ Агентов","ar":"تعلم كيفية إعداد الاختبارات ببايثون باستخدام pytest و TDD وأفضل الممارسات لتحسين جودة كودك مع وكيلات الذكاء الاصطناعي"},"definition":{"en":"python-testing is a set of testing strategies for Python applications using pytest, TDD methodology, fixtures, mocking, parametrization, and coverage requirements.","zh":"Python pytest测试框架采用测试驱动开发(TDD)方法论，通过red-green-refactor循环实现测试先行开发，支持fixtures依赖注入、mock技术和参数化测试用例设计。","ja":"Python pytestテストフレームワークはテスト駆動開発(TDD)手法を採用し、red-green-refactorサイクルを通じてテストファースト開発を実現し、fixturesによる依存性注入、mock技術、パラメータ化テストケース設計をサポートします。","ko":"Python pytest 테스트 프레임워크는 테스트 주도 개발(TDD) 방법론을 채택하여 red-green-refactor 사이클을 통해 테스트 우선 개발을 구현하며, fixtures를 통한 의존성 주입, mock 기술, 매개변수화 테스트 케이스 설계를 지원합니다。","es":"Pruebas de Python es una técnica de testing que utiliza pytest y TDD para garantizar la calidad del código","fr":"Les tests Python sont une technique de testing qui utilise pytest et TDD pour garantir la qualité du code","de":"Python-Tests sind eine Testtechnik, die pytest und TDD verwendet, um die Qualität des Codes zu gewährleisten","pt":"Testes em Python são estratégias de teste que utilizam pytest, TDD e boas práticas para garantir a qualidade do código","ru":"Тестирование Python - это стратегии тестирования, которые используют pytest, TDD и лучшие практики для обеспечения качества кода","ar":"الاختبارات ببايثون هي استراتيجيات الاختبار التي تستخدم pytest و TDD وأفضل الممارسات لضمان جودة الكود"},"features":{"en":["Implements Test-Driven Development (TDD) cycle with RED, GREEN, and refactor stages","Utilizes pytest for efficient testing","Supports fixtures, mocking, and parametrization for robust test suites","Enforces coverage requirements for thorough testing","Facilitates setting up testing infrastructure for Python projects"],"zh":["pytest fixtures依赖注入系统","unittest.mock模块的patch技术","@pytest.mark.parametrize参数化测试","pytest-cov覆盖率插件集成","TDD red-green-refactor开发循环","测试用例标记和筛选机制"],"ja":["pytest fixturesによる依存性注入システム","unittest.mockモジュールのpatch技術","@pytest.mark.parametrizeパラメータ化テスト","pytest-covカバレッジプラグイン連携","TDD red-green-refactor開発サイクル","テストケースマーキングとフィルタリング機構"],"ko":["pytest fixtures 의존성 주입 시스템","unittest.mock 모듈의 patch 기술","@pytest.mark.parametrize 매개변수화 테스트","pytest-cov 커버리지 플러그인 통합","TDD red-green-refactor 개발 사이클","테스트 케이스 마킹 및 필터링 메커니즘"],"es":["Implementación de TDD (Desarrollo guiado por pruebas)","Uso de pytest para pruebas unitarias y de integración","Configuración de fixtures y mocking para pruebas más eficientes","Parametrización de pruebas para cubrir múltiples escenarios","Análisis de cobertura de código para garantizar la calidad"],"fr":["Mise en place de la TDD (Développement guidé par les tests)","Utilisation de pytest pour les tests unitaires et d''intégration","Configuration de fixtures et de mocking pour des tests plus efficaces","Paramétrisation des tests pour couvrir plusieurs scénarios","Analyse de la couverture de code pour garantir la qualité"],"de":["Implementierung von TDD (Testgetriebene Entwicklung)","Verwendung von pytest für Einheitstests und Integrationstests","Konfiguration von Fixtures und Mocking für effizientere Tests","Parametrisierung von Tests für die Abdeckung mehrerer Szenarien","Analyse der Codeabdeckung für die Gewährleistung der Qualität"],"pt":["Utilização de pytest para testes unitários","Implementação de TDD (Test-Driven Development)","Uso de fixtures e mocking para isolamento de dependências","Parametrização de testes para cobertura de casos de uso","Análise de cobertura de código para garantia de qualidade"],"ru":["Использование pytest для модульного тестирования","Реализация TDD (Test-Driven Development)","Использование fixtures и mocking для изоляции зависимостей","Параметризация тестов для покрытия случаев использования","Анализ покрытия кода для обеспечения качества"],"ar":["استخدام pytest للاختبارات الوحدة","تنفيذ TDD (التطوير القائم على الاختبار)","استخدام fixtures و mocking لتعزيل الاعتماديات","تحديد 매개 Variables للاختبارات لتغطية حالات الاستخدام","تحليل تغطية الكود لضمان الجودة"]},"keywords":{"en":["how to use python-testing","python-testing setup guide","pytest tutorial for python-testing","TDD methodology in python-testing","python-testing vs unittest","python-testing install for AI agents","improving test coverage with python-testing","python-testing best practices for developers"],"zh":["pytest测试框架","TDD开发方法","Python单元测试","fixtures依赖注入","mock测试技术","参数化测试用例","测试覆盖率要求","red-green-refactor"],"ja":["pytestテストフレームワーク","TDD開発手法","Python単体テスト","fixtures依存性注入","mockテスト技術","パラメータ化テストケース","テストカバレッジ要件","red-green-refactor"],"ko":["pytest 테스트 프레임워크","TDD 개발 방법론","Python 단위 테스트","fixtures 의존성 주입","mock 테스트 기술","매개변수화 테스트 케이스","테스트 커버리지 요구사항","red-green-refactor"],"es":["pruebas de python","pytest","TDD","desarrollo de software","testing de software","mejores prácticas de testing","herramientas de testing","ai agents para testing","agentes de inteligencia artificial para pruebas"],"fr":["tests python","pytest","TDD","développement de logiciels","testing de logiciels","meilleures pratiques de testing","outils de testing","agents IA pour les tests","agents d''intelligence artificielle pour les tests"],"de":["python tests","pytest","TDD","softwareentwicklung","softwaretesting","best practices für testing","testingtools","künstliche intelligenz agenten für tests","ai agenten für softwaretests"],"pt":["testes em python","pytest","TDD","fixtures","mocking","parametrização de testes","cobertura de código","qualidade de código","desenvolvimento de software","testes unitários"],"ru":["тестирование python","pytest","TDD","fixtures","mocking","параметризация тестов","покрытие кода","качество кода","разработка программного обеспечения","модульное тестирование"],"ar":["الاختبارات ببايثون","pytest","TDD","fixtures","mocking","تحديد 매개 Variables للاختبارات","تغطية الكود","جودة الكود","تطوير البرمجيات","الاختبارات الوحدة"]}},"agentAnalysis":{"suitability":{"en":"Essential for Python Development Agents requiring comprehensive test automation and quality assurance capabilities.","zh":"适用于需要全面测试自动化和质量保证能力的Python开发代理。","ja":"Python開発エージェントが包括的なテスト自動化と品質保証機能を必要とする場合に不可欠です。","ko":"전체적인 테스트 자동화 및 품질 보증 기능이 필요한 Python 개발 에이전트에 적합합니다.","es":"Esencial para Agentes de Desarrollo en Python que requieren capacidades completas de automatización de pruebas y garantía de calidad.","fr":"Essentiel pour les Agents de Développement Python nécessitant des capacités complètes d''automatisation des tests et d''assurance qualité.","de":"Essenziell für Python-Entwicklungs-Agents, die umfassende Testautomatisierungs- und Qualitätssicherungsfunktionen benötigen.","pt":"Essencial para Agentes de Desenvolvimento Python que exigem capacidades abrangentes de automação de testes e garantia de qualidade.","ru":"Необходимо для Агентов Разработки на Python, требующих комплексных возможностей автоматизации тестирования и обеспечения качества.","ar":"أساسي لوكلاء تطوير Python الذين يتطلبون قدرات شاملة لأتمتة الاختبار وضمان الجودة."},"recommendation":{"en":"Enables agents to implement pytest-driven testing strategies including fixture management, mocking, parametrization, and coverage analysis. Provides TDD methodology enforcement for Python code development cycles.","zh":"使代理能够实施基于pytest的测试策略，包括fixture管理、模拟、参数化和覆盖率分析。为Python代码开发周期提供TDD方法论强制执行。","ja":"エージェントがpytestによるテスト戦略を実装できるようにし、fixture管理、モッキング、パラメータ化、カバレッジ分析を含む。Pythonコード開発サイクルにTDD方法論を強制適用する。","ko":"에이전트가 pytest 기반의 테스트 전략을 구현할 수 있게 하며, fixture 관리, 모의, 매개변수화, 커버리지 분석을 포함한다. Python 코드 개발 주기에 TDD 방법론을 강제 적용한다.","es":"Permite a los agentes implementar estrategias de testing basadas en pytest, incluyendo la gestión de fixtures, mocking, parametrización y análisis de cobertura. Proporciona la aplicación de la metodología TDD para los ciclos de desarrollo de código Python.","fr":"Permet aux agents de mettre en œuvre des stratégies de test pilotées par pytest, incluant la gestion des fixtures, le mocking, la paramétrisation et l''analyse de couverture. Fournit l''application de la méthodologie TDD pour les cycles de développement de code Python.","de":"Ermöglicht es Agents, pytest-gesteuerte Teststrategien zu implementieren, einschließlich Fixture-Management, Mocking, Parametrisierung und Coverage-Analyse. Bietet die Durchsetzung der TDD-Methodik für Python-Code-Entwicklungszyklen.","pt":"Permite que os agentes implementem estratégias de teste orientadas por pytest, incluindo gerenciamento de fixtures, mocking, parametrização e análise de cobertura. Fornece aplicação da metodologia TDD para ciclos de desenvolvimento de código Python.","ru":"Позволяет агентам реализовывать стратегии тестирования на основе pytest, включая управление фикстурами, мокирование, параметризацию и анализ покрытия. Обеспечивает соблюдение методологии TDD для циклов разработки кода на Python.","ar":"يمكن الوكلاء من تنفيذ استراتيجيات الاختبار القائمة على pytest بما في ذلك إدارة التركيبات، والمحاكاة، والتحديد البارامتري، وتحليل التغطية. يوفر فرض منهجية TDD لدورات تطوير كود Python."},"useCases":{"en":["Implementing TDD workflows (red-green-refactor)","Generating parametrized test cases for edge coverage","Creating mock objects for isolated unit testing","Analyzing test coverage metrics for quality assurance","Setting up pytest fixtures for test infrastructure"],"zh":["实现TDD工作流（红绿重构）","为边缘覆盖生成参数化测试用例","为隔离单元测试创建模拟对象","分析测试覆盖率指标以进行质量保证","设置pytest fixture以进行测试基础设施"],"ja":["TDDワークフロー（red-green-refactor）を実装する","エッジカバレッジのためのパラメータ化されたテストケースを生成する","分離されたユニットテストのためのモックオブジェクトを作成する","テストカバレッジメトリクスを分析して品質保証を行う","テストインフラストラクチャのためのpytest fixtureを設定する"],"ko":["TDD 워크플ロー(빨강-초록-리팩토링)를 구현한다","경계 커버리지에 대한 매개변수화된 테스트 케이스를 생성한다","분리된 유닛 테스트를 위한 모의 객체를 생성한다","품질 보증을 위해 테스트 커버리지 메트릭스를 분석한다","테스트 인프라를 위한 pytest fixture를 설정한다"],"es":["Implementación de flujos de trabajo TDD (red-green-refactor)","Generación de casos de prueba parametrizados para la cobertura de edge cases","Creación de mock objects para pruebas unitarias aisladas","Análisis de métricas de cobertura de pruebas para garantía de calidad","Configuración de pytest fixtures para la infraestructura de pruebas"],"fr":["Mise en œuvre des workflows TDD (red-green-refactor)","Génération de cas de test paramétrés pour la couverture des edge cases","Création de mock objects pour des tests unitaires isolés","Analyse des métriques de couverture de test pour l''assurance qualité","Configuration des pytest fixtures pour l''infrastructure de test"],"de":["Implementierung von TDD-Workflows (red-green-refactor)","Generierung parametrisierter Testfälle für Edge-Case-Abdeckung","Erstellung von Mock-Objekten für isolierte Unit-Tests","Analyse von Test-Coverage-Metriken für die Qualitätssicherung","Einrichtung von pytest-Fixtures für die Testinfrastruktur"],"pt":["Implementação de fluxos de trabalho TDD (red-green-refactor)","Geração de casos de teste parametrizados para cobertura de edge cases","Criação de objetos mock para testes de unidade isolados","Análise de métricas de cobertura de testes para garantia de qualidade","Configuração de fixtures do pytest para infraestrutura de teste"],"ru":["Реализация рабочих процессов TDD (красный-зеленый-рефакторинг)","Генерация параметризованных тестовых случаев для покрытия граничных условий","Создание mock-объектов для изолированного модульного тестирования","Анализ метрик покрытия тестов для обеспечения качества","Настройка фикстур pytest для тестовой инфраструктуры"],"ar":["تنفيح سير عمل TDD (أحمر-أخضر-إعادة الهيكلة)","إنشاء حالات اختبار محددة ببارامترات لتغطية الحالات الطرفية","إنشاء كائنات وهمية للاختبار المعزول للوحدات","تحليل مقاييس تغطية الاختبار لضمان الجودة","إعداد تركيبات pytest للبنية التحتية للاختبار"]},"limitations":{"en":["Python-specific testing framework","Requires pytest installation","Focuses on unit/integration testing patterns"],"zh":["Python特定的测试框架","需要pytest安装","关注单元/集成测试模式"],"ja":["Python特有のテストフレームワーク","pytestのインストールが必要","ユニット/統合テストパターンに焦点を当てている"],"ko":["Python 전용 테스트 프레임워크","pytest 설치가 필요하다","유닛/통합 테스트 패턴에 초점을 맞추고 있다"],"es":["Framework de testing específico para Python","Requiere la instalación de pytest","Se centra en patrones de pruebas unitarias/de integración"],"fr":["Framework de test spécifique à Python","Nécessite l''installation de pytest","Se concentre sur les patterns de tests unitaires/intégration"],"de":["Python-spezifisches Test-Framework","Erfordert eine pytest-Installation","Konzentriert sich auf Unit-/Integrationstest-Muster"],"pt":["Framework de teste específico para Python","Requer instalação do pytest","Foca em padrões de teste de unidade/integração"],"ru":["Специализированный фреймворк тестирования для Python","Требует установки pytest","Сосредоточен на шаблонах модульного/интеграционного тестирования"],"ar":["إطار عمل اختبار مخصص لـ Python","يتطلب تثبيت pytest","يركز على أنماط اختبار الوحدة / التكامل"]},"version":4},"contentHash":"b304a8c503af32644f97a889c5545ee4f90e91980462ad4ce33fee3dea6f414f","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":80}');
